def build_benchmark_materialization_status(
    *,
    raw_root: str | Path = "/mnt/storage/axio_fusion_benchmarks/raw",
    output_dir: str | Path = "/mnt/storage/axio_fusion_benchmarks/standardized",
    download_manifest_path: str | Path | None = GPQA_DEFAULT_DOWNLOAD_MANIFEST,
    suite_ids: Sequence[str] = (),
    min_cases_per_suite: int = 100,
) -> dict[str, Any]:
    """Report raw-to-standardized benchmark materialization readiness safely.

    The receipt is intentionally hash/count only.  It can point operators toward
    the next materialization step without persisting raw benchmark content or
    raw local paths in shareable artifacts.
    """

    raw_base = Path(raw_root)
    out_base = Path(output_dir)
    selected = {str(item) for item in suite_ids if str(item)}
    download_status = _benchmark_download_statuses(download_manifest_path)
    rows = []
    for suite in BENCHMARK_SUITES:
        if selected and suite.suite_id not in selected:
            continue
        rows.append(
            _materialization_status_row(
                suite,
                raw_root=raw_base,
                output_dir=out_base,
                download_status=download_status,
                min_cases_per_suite=min_cases_per_suite,
            )
        )
    ready_rows = [row for row in rows if row.get("ready") is True]
    blocked_rows = [row for row in rows if row.get("status", "").startswith("blocked")]
    materialization_required = [row for row in rows if row.get("status") == "materialization_required"]
    return {
        "schema": "axio_fusion_api.benchmark_materialization_status.v1",
        "suite_count": len(rows),
        "ready_suite_count": len(ready_rows),
        "blocked_suite_count": len(blocked_rows),
        "materialization_required_suite_count": len(materialization_required),
        "all_selected_local_materializations_ready": len(ready_rows) == len(rows) if rows else False,
        "raw_root_sha256": sha256_text(str(raw_root)),
        "output_dir_sha256": sha256_text(str(output_dir)),
        "download_manifest_path_sha256": sha256_text(str(download_manifest_path or "")),
        "min_cases_per_suite": int(min_cases_per_suite),
        "blocking_reason_counts": _count_reason_codes([row for row in rows if row.get("ready") is not True]),
        "suite_rows": rows,
        "anti_leakage_contract": {
            "raw_dataset_paths_persisted": False,
            "raw_dataset_content_persisted": False,
            "raw_labels_persisted": False,
            "raw_prompts_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        "raw_dataset_paths_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_labels_persisted": False,
        "secrets_persisted": False,
    }


def materialize_benchmark_datasets(
    *,
    raw_root: str | Path = "/mnt/storage/axio_fusion_benchmarks/raw",
    output_dir: str | Path = "/mnt/storage/axio_fusion_benchmarks/standardized",
    download_manifest_path: str | Path | None = GPQA_DEFAULT_DOWNLOAD_MANIFEST,
    suite_ids: Sequence[str] = (),
    limit_per_suite: int | None = None,
    min_cases_per_suite: int = 100,
    overwrite: bool = False,
) -> dict[str, Any]:
    """Materialize supported raw benchmark assets into private standardized JSONL.

    The JSONL files intentionally contain benchmark prompts and references and
    therefore belong in the mechanical-disk/private benchmark cache, not in
    shareable repository artifacts.  The returned receipt remains hash/count
    only.
    """

    raw_base = Path(raw_root)
    out_base = Path(output_dir)
    out_base.mkdir(parents=True, exist_ok=True)
    selected = {str(item) for item in suite_ids if str(item)}
    download_status = _benchmark_download_statuses(download_manifest_path)
    rows = []
    for suite in BENCHMARK_SUITES:
        if selected and suite.suite_id not in selected:
            continue
        rows.append(
            _materialize_one_benchmark_suite(
                suite,
                raw_root=raw_base,
                output_dir=out_base,
                download_status=download_status,
                limit_per_suite=limit_per_suite,
                min_cases_per_suite=min_cases_per_suite,
                overwrite=overwrite,
            )
        )
    materialized_rows = [row for row in rows if row.get("status") in {"materialized", "already_materialized"}]
    blocked_rows = [row for row in rows if str(row.get("status") or "").startswith("blocked")]
    failed_rows = [row for row in rows if row.get("status") == "failed"]
    return {
        "schema": "axio_fusion_api.benchmark_materialization_run.v1",
        "suite_count": len(rows),
        "materialized_or_existing_suite_count": len(materialized_rows),
        "blocked_suite_count": len(blocked_rows),
        "failed_suite_count": len(failed_rows),
        "limit_per_suite": None if limit_per_suite is None else int(limit_per_suite),
        "min_cases_per_suite": int(min_cases_per_suite),
        "raw_root_sha256": sha256_text(str(raw_root)),
        "output_dir_sha256": sha256_text(str(output_dir)),
        "download_manifest_path_sha256": sha256_text(str(download_manifest_path or "")),
        "suite_rows": rows,
        "blocking_reason_counts": _count_reason_codes([row for row in rows if row.get("ready") is not True]),
        "anti_leakage_contract": {
            "standardized_jsonl_is_private_benchmark_cache": True,
            "receipt_raw_dataset_paths_persisted": False,
            "receipt_raw_dataset_content_persisted": False,
            "receipt_raw_labels_persisted": False,
            "receipt_raw_prompts_persisted": False,
            "receipt_raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        "raw_dataset_paths_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_labels_persisted": False,
        "secrets_persisted": False,
    }


def run_multiple_choice_benchmark(
    *,
    suite_id: str,
    dataset_path: str | Path,
    candidate_id: str,
    api_format: str = "",
    registry_path: str | Path | None = None,
    limit: int | None = None,
    live: bool = False,
    client: HTTPProviderClient | None = None,
    axio_gateway_url: str | None = None,
    engine: FusionEngine | None = None,
    profiles: Sequence[ModelProfile] | None = None,
    provider_profiles: Sequence[ModelProfile] | None = None,
    max_latency_ms: int | None = None,
) -> dict[str, Any]:
    active_engine, active_profiles, active_client = _resolve_benchmark_runtime(
        registry_path=registry_path,
        client=client,
        engine=engine,
        profiles=profiles,
    )
    surface = _split_axio_api_surface_id(candidate_id)
    safe_candidate_id = surface[0] if surface else _canonical_campaign_candidate_id(active_profiles, candidate_id)
    selected_api_format = _selected_benchmark_api_format(safe_candidate_id, api_format or (surface[1] if surface else ""))
    cases = _load_multiple_choice_cases(dataset_path, limit=limit)
    case_results = []
    started = time.monotonic()
    for index, case in enumerate(cases):
        result = _run_one_multiple_choice_case(
            case=case,
            index=index,
            suite_id=suite_id,
            candidate_id=safe_candidate_id,
            api_format=selected_api_format,
            profiles=active_profiles,
            engine=active_engine,
            live=live,
            client=active_client,
            provider_profiles=provider_profiles,
            axio_gateway_url=axio_gateway_url,
            max_latency_ms=max_latency_ms,
        )
        case_results.append(result)
    correct_count = sum(1 for row in case_results if row.get("correct") is True)
    attempted_count = sum(1 for row in case_results if row.get("status") == "completed")
    cost_summary = _benchmark_cost_summary(case_results)
    latency_summary = _benchmark_latency_summary(case_results)
    return {
        "schema": "axio_fusion_api.multiple_choice_benchmark_run.v1",
        "suite_id": suite_id,
        "candidate_id": safe_candidate_id,
        "candidate_id_policy": _candidate_id_alias_policy(candidate_id, safe_candidate_id),
        **_benchmark_api_surface_fields(safe_candidate_id, selected_api_format),
        "prompt_protocol_sha256": _prompt_protocol_sha256_for_suite(suite_id, "multiple_choice"),
        "decoding_config_sha256": _decoding_config_sha256_for_suite(suite_id, "multiple_choice"),
        "reasoning_receipt": _benchmark_reasoning_run_receipt(
            {"case_results": case_results},
            suite_id=suite_id,
            task_format="multiple_choice",
        ),
        "mode": "live" if live else "dry_run",
        "case_count": len(cases),
        "attempted_count": attempted_count,
        "correct_count": correct_count,
        "accuracy": None if not cases else round(correct_count / len(cases), 6),
        "latency_ms": round((time.monotonic() - started) * 1000, 3),
        **latency_summary,
        **cost_summary,
        "case_results": case_results,
        "harness_receipt": _local_harness_receipt(suite_id, "multiple_choice"),
        "cost_contract": _benchmark_cost_contract(),
        "anti_leakage_contract": {
            "raw_questions_persisted": False,
            "raw_options_persisted": False,
            "raw_labels_persisted": False,
            "benchmark_labels_used_for_training": False,
            "raw_provider_model_ids_persisted": False,
            "prompt_input_projection_enforced": True,
            "prompt_contract_required_for_final_claim": True,
            "prompt_contract_schema": BENCHMARK_PROMPT_CONTRACT_SCHEMA,
            "scoring_fields_structurally_excluded_from_prompts": all(
                _benchmark_prompt_contract_is_clean(row.get("prompt_contract"))
                for row in case_results
            ),
        },
        "raw_prompt_persisted": False,
        "raw_label_persisted": False,
        "raw_provider_output_persisted": False,
        "secrets_persisted": False,
    }


def run_benchmark_dataset(
    *,
    suite_id: str,
    dataset_path: str | Path,
    candidate_id: str,
    api_format: str = "",
    task_format: str = "auto",
    registry_path: str | Path | None = None,
    limit: int | None = None,
    live: bool = False,
    client: HTTPProviderClient | None = None,
    code_timeout_seconds: float = 5.0,
    axio_gateway_url: str | None = None,
    engine: FusionEngine | None = None,
    profiles: Sequence[ModelProfile] | None = None,
    provider_profiles: Sequence[ModelProfile] | None = None,
    max_latency_ms: int | None = None,
) -> dict[str, Any]:
    selected_format = _suite_task_format(suite_id) if task_format == "auto" else str(task_format or "multiple_choice")
    if selected_format == "multiple_choice":
        return run_multiple_choice_benchmark(
            suite_id=suite_id,
            dataset_path=dataset_path,
            candidate_id=candidate_id,
            api_format=api_format,
            registry_path=registry_path,
            limit=limit,
            live=live,
            client=client,
            axio_gateway_url=axio_gateway_url,
            engine=engine,
            profiles=profiles,
            provider_profiles=provider_profiles,
            max_latency_ms=max_latency_ms,
        )
    active_engine, active_profiles, active_client = _resolve_benchmark_runtime(
        registry_path=registry_path,
        client=client,
        engine=engine,
        profiles=profiles,
    )
    surface = _split_axio_api_surface_id(candidate_id)
    safe_candidate_id = surface[0] if surface else _canonical_campaign_candidate_id(active_profiles, candidate_id)
    selected_api_format = _selected_benchmark_api_format(safe_candidate_id, api_format or (surface[1] if surface else ""))
    cases = _load_generic_cases(dataset_path, limit=limit)
    started = time.monotonic()
    case_results = [
        _run_one_generic_case(
            case=case,
            index=index,
            suite_id=suite_id,
            candidate_id=safe_candidate_id,
            api_format=selected_api_format,
            task_format=selected_format,
            profiles=active_profiles,
            engine=active_engine,
            live=live,
            client=active_client,
            provider_profiles=provider_profiles,
            code_timeout_seconds=code_timeout_seconds,
            axio_gateway_url=axio_gateway_url,
            max_latency_ms=max_latency_ms,
        )
        for index, case in enumerate(cases)
    ]
    completed = [row for row in case_results if row.get("status") == "completed"]
    correct_count = sum(1 for row in case_results if row.get("correct") is True)
    scores = [float(row["score"]) for row in case_results if row.get("score") is not None]
    secondary_metrics = _official_import_secondary_metrics(case_results)
    cost_summary = _benchmark_cost_summary(case_results)
    latency_summary = _benchmark_latency_summary(case_results)
    return {
        "schema": "axio_fusion_api.benchmark_run.v2",
        "suite_id": suite_id,
        "candidate_id": safe_candidate_id,
        "candidate_id_policy": _candidate_id_alias_policy(candidate_id, safe_candidate_id),
        **_benchmark_api_surface_fields(safe_candidate_id, selected_api_format),
        "task_format": selected_format,
        "prompt_protocol_sha256": _prompt_protocol_sha256_for_suite(suite_id, selected_format),
        "decoding_config_sha256": _decoding_config_sha256_for_suite(suite_id, selected_format),
        "reasoning_receipt": _benchmark_reasoning_run_receipt(
            {"case_results": case_results},
            suite_id=suite_id,
            task_format=selected_format,
        ),
        "mode": "live" if live else "dry_run",
        "case_count": len(cases),
        "attempted_count": len(completed),
        "correct_count": correct_count,
        "accuracy": None if not cases else round(correct_count / len(cases), 6),
        "mean_score": None if not scores else round(sum(scores) / len(scores), 6),
        "primary_metric": _primary_metric_for_official_import(suite_id, selected_format),
        "secondary_metrics": secondary_metrics,
        "latency_ms": round((time.monotonic() - started) * 1000, 3),
        **latency_summary,
        **cost_summary,
        "case_results": case_results,
        "harness_receipt": _local_harness_receipt(suite_id, selected_format),
        "cost_contract": _benchmark_cost_contract(),
        "execution_contract": {
            "python_code_execution_enabled": _code_execution_enabled() if selected_format == "python_code" else False,
            "python_code_timeout_seconds": float(code_timeout_seconds) if selected_format == "python_code" else None,
            "external_pairwise_judge_runs_must_be_imported": selected_format == "external_pairwise_judge",
            "raw_dataset_content_persisted": False,
        },
        "anti_leakage_contract": {
            "raw_inputs_persisted": False,
            "raw_references_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "benchmark_labels_used_for_training": False,
            "prompt_input_projection_enforced": True,
            "prompt_contract_required_for_final_claim": True,
            "prompt_contract_schema": BENCHMARK_PROMPT_CONTRACT_SCHEMA,
            "scoring_fields_structurally_excluded_from_prompts": all(
                _benchmark_prompt_contract_is_clean(row.get("prompt_contract"))
                for row in case_results
            ),
        },
        "raw_prompt_persisted": False,
        "raw_label_persisted": False,
        "raw_provider_output_persisted": False,
        "secrets_persisted": False,
    }


def _resolve_benchmark_runtime(
    *,
    registry_path: str | Path | None,
    client: HTTPProviderClient | None,
    engine: FusionEngine | None,
    profiles: Sequence[ModelProfile] | None,
) -> tuple[FusionEngine, list[ModelProfile], HTTPProviderClient]:
    """Resolve one benchmark runtime without crossing the credential boundary.

    A live runtime engine is authoritative when supplied.  This is the path
    used by process-local secret managers and dynamic channel discovery; it
    keeps endpoint/key material in the engine's in-memory profiles instead of
    forcing benchmark execution through a persisted registry.  The historical
    registry path remains the default for reproducible provider-baseline runs.
    """

    if engine is not None:
        active_profiles = list(engine.profiles)
        active_client = ensure_strict_streaming_client(client or engine.client)
        return engine, active_profiles, active_client
    active_profiles = list(profiles) if profiles is not None else load_registry(registry_path)
    active_client = ensure_strict_streaming_client(client)
    return FusionEngine(active_profiles, client=active_client), active_profiles, active_client


def run_runtime_benchmark_campaign(
    *,
    dataset_manifest_path: str | Path,
    output_dir: str | Path,
    engine: FusionEngine,
    suite_ids: Sequence[str] = (),
    candidate_ids: Sequence[str] = AXIO_BENCHMARK_PUBLIC_MODELS,
    api_formats: Sequence[str] = AXIO_BENCHMARK_API_FORMATS,
    limit: int | None = None,
    live: bool = True,
    resume: bool = True,
    code_timeout_seconds: float = 5.0,
    axio_gateway_url: str | None = None,
    max_latency_ms: int | None = None,
    client: HTTPProviderClient | None = None,
) -> dict[str, Any]:
    """Run a safe diagnostic campaign against an in-memory channel portfolio.

    This path is intentionally separate from :func:`run_benchmark_campaign`.
    Runtime credentials and discovered model profiles are often supplied by a
    secret manager and therefore cannot be reconstructed from a persisted
    registry.  The campaign records the same case/prediction/latency hashes as
    the formal runner, exercises all requested Axio public API surfaces, and
    is explicitly ineligible for provider-superiority claims.  Formal claims
    still require the pinned registry, externally pre-registered baselines, and
    official harness imports handled by ``run_benchmark_campaign``.
    """

    if not isinstance(engine, FusionEngine):
        raise TypeError("engine must be a FusionEngine")
    selected_suite_ids = {str(value).strip() for value in suite_ids if str(value).strip()}
    manifest = _load_dataset_manifest(dataset_manifest_path)
    suite_specs = _campaign_suite_specs(manifest)
    specs_by_suite = {
        str(spec.get("suite_id") or ""): spec
        for spec in suite_specs
        if isinstance(spec, Mapping)
    }
    selected_suites = [
        suite
        for suite in BENCHMARK_SUITES
        if not selected_suite_ids or suite.suite_id in selected_suite_ids
    ]
    unknown_suites = sorted(selected_suite_ids.difference({suite.suite_id for suite in BENCHMARK_SUITES}))
    if unknown_suites:
        raise ValueError("unknown benchmark suite id")

    selected_candidates = _runtime_campaign_candidates(candidate_ids)
    selected_formats = _runtime_campaign_api_formats(api_formats)
    active_client = client or engine.client
    output = Path(output_dir)
    runs_dir = output / "runs"
    runs_dir.mkdir(parents=True, exist_ok=True)
    runs: list[dict[str, Any]] = []
    artifacts: list[dict[str, Any]] = []
    blocked_suites: list[dict[str, Any]] = []

    for suite in selected_suites:
        spec = specs_by_suite.get(suite.suite_id, {})
        dataset_path = _suite_dataset_path(spec)
        if not dataset_path:
            blocked_suites.append(
                _runtime_campaign_blocked_suite_row(
                    suite,
                    reason="dataset_path_missing_or_official_import_required",
                )
            )
            continue
        dataset = Path(dataset_path)
        if not dataset.is_file():
            blocked_suites.append(
                _runtime_campaign_blocked_suite_row(
                    suite,
                    reason="dataset_file_missing",
                )
            )
            continue
        task_format = str(spec.get("task_format") or suite.task_format)
        for candidate_id in selected_candidates:
            for api_format in selected_formats:
                run_unit_id = _axio_api_surface_id(candidate_id, api_format)
                run_path = runs_dir / (
                    f"{_safe_filename(suite.suite_id)}__{_safe_filename(run_unit_id)}.json"
                )
                if resume and run_path.is_file() and _runtime_run_resume_allowed(
                    run_path,
                    suite=suite,
                    dataset_path=dataset,
                    task_format=task_format,
                    candidate_id=candidate_id,
                    api_format=api_format,
                    limit=limit,
                    live=live,
                    axio_gateway_url=axio_gateway_url,
                    max_latency_ms=max_latency_ms,
                ):
                    try:
                        run = _normalize_imported_run_for_campaign(
                            json.loads(run_path.read_text(encoding="utf-8")),
                            suite_id=suite.suite_id,
                            candidate_id=run_unit_id,
                        )
                        status = "resumed"
                    except (OSError, json.JSONDecodeError, ValueError, TypeError):
                        run = _run_runtime_benchmark_unit(
                            suite=suite,
                            dataset_path=dataset,
                            task_format=task_format,
                            candidate_id=candidate_id,
                            api_format=api_format,
                            engine=engine,
                            client=active_client,
                            limit=limit,
                            live=live,
                            code_timeout_seconds=code_timeout_seconds,
                            axio_gateway_url=axio_gateway_url,
                            max_latency_ms=max_latency_ms,
                        )
                        status = "completed"
                else:
                    run = _run_runtime_benchmark_unit(
                        suite=suite,
                        dataset_path=dataset,
                        task_format=task_format,
                        candidate_id=candidate_id,
                        api_format=api_format,
                        engine=engine,
                        client=active_client,
                        limit=limit,
                        live=live,
                        code_timeout_seconds=code_timeout_seconds,
                        axio_gateway_url=axio_gateway_url,
                        max_latency_ms=max_latency_ms,
                    )
                    status = "completed"
                run = _annotate_benchmark_run_identity(
                    run,
                    benchmark_slot_id=suite.suite_id,
                    spec=spec,
                )
                write_json(run_path, run)
                runs.append(run)
                artifacts.append(
                    {
                        "suite_id": suite.suite_id,
                        "candidate_id": candidate_id,
                        "run_unit_id": run_unit_id,
                        "api_format": api_format,
                        "api_surface_id": run.get("api_surface_id") or run_unit_id,
                        "status": status,
                        "task_format": task_format,
                        "case_count": run.get("case_count"),
                        "attempted_count": run.get("attempted_count"),
                        "accuracy": run.get("accuracy"),
                        "mean_score": run.get("mean_score"),
                        "estimated_cost_usd": run.get("estimated_cost_usd"),
                        "provider_call_count": run.get("provider_call_count"),
                        "dataset_path_sha256": sha256_text(str(dataset)),
                        "raw_dataset_path_persisted": False,
                        "raw_prompt_persisted": False,
                    }
                )

    parity = build_benchmark_api_surface_parity_report(
        runs,
        require_http_gateway=bool(live and axio_gateway_url),
        suite_ids=[suite.suite_id for suite in selected_suites],
        model_ids=selected_candidates,
    )
    run_set = build_benchmark_runs_payload(runs)
    runtime_summary = _runtime_campaign_summary(engine)
    output_files = {
        "runs": "runs.json",
        "api_surface_parity": "api_surface_parity.json",
        "campaign": "campaign.json",
    }
    write_json(output / output_files["runs"], run_set)
    write_json(output / output_files["api_surface_parity"], parity)
    campaign = {
        "schema": "axio_fusion_api.runtime_benchmark_campaign.v1",
        "mode": "live" if live else "dry_run",
        "diagnostic_only": True,
        "final_claims_allowed": False,
        "superiority_claim_allowed": False,
        "dataset_manifest_sha256": sha256_text(Path(dataset_manifest_path).read_text(encoding="utf-8")),
        "selected_suite_count": len(selected_suites),
        "selected_candidate_count": len(selected_candidates),
        "selected_api_format_count": len(selected_formats),
        "expected_run_count": len(selected_suites) * len(selected_candidates) * len(selected_formats),
        "completed_or_resumed_run_count": len(runs),
        "blocked_suite_count": len(blocked_suites),
        "blocked_suites": blocked_suites,
        "candidate_ids": list(selected_candidates),
        "api_formats": list(selected_formats),
        "api_surface_contract": _api_surface_contract(),
        "api_surface_parity": parity,
        "runtime_channel_summary": runtime_summary,
        "artifacts": artifacts,
        "output_files": output_files,
        "resume": bool(resume),
        "max_latency_ms": max(1, int(max_latency_ms)) if max_latency_ms is not None else None,
        "gateway": {
            "configured": bool(axio_gateway_url),
            "url_sha256": sha256_text(str(axio_gateway_url).rstrip("/")) if axio_gateway_url else "",
            "transport_policy": "http_gateway_when_configured_else_in_process_public_endpoint",
            "raw_gateway_url_persisted": False,
        },
        "anti_leakage_contract": {
            "raw_dataset_content_persisted": False,
            "raw_dataset_paths_persisted": False,
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_provider_urls_persisted": False,
            "raw_api_keys_persisted": False,
            "secrets_persisted": False,
        },
    }
    write_json(output / output_files["campaign"], campaign)
    return campaign


def _runtime_campaign_candidates(candidate_ids: Sequence[str]) -> tuple[str, ...]:
    selected = tuple(
        dict.fromkeys(
            str(candidate).strip()
            for candidate in candidate_ids
            if str(candidate).strip()
        )
    )
    invalid = [candidate for candidate in selected if not _is_axio_public_candidate(candidate)]
    if invalid:
        raise ValueError("runtime diagnostic campaign accepts Axio public models only")
    if not selected:
        raise ValueError("runtime diagnostic campaign requires at least one Axio model")
    return selected


def _runtime_campaign_api_formats(api_formats: Sequence[str]) -> tuple[str, ...]:
    selected: list[str] = []
    for value in api_formats:
        normalized = normalize_api_format(str(value or ""))
        if normalized not in AXIO_BENCHMARK_API_FORMATS:
            raise ValueError("runtime diagnostic campaign received an unsupported API surface")
        if normalized not in selected:
            selected.append(normalized)
    if not selected:
        raise ValueError("runtime diagnostic campaign requires at least one API surface")
    return tuple(selected)


def _run_runtime_benchmark_unit(
    *,
    suite: BenchmarkSuite,
    dataset_path: Path,
    task_format: str,
    candidate_id: str,
    api_format: str,
    engine: FusionEngine,
    client: HTTPProviderClient,
    limit: int | None,
    live: bool,
    code_timeout_seconds: float,
    axio_gateway_url: str | None,
    max_latency_ms: int | None,
) -> dict[str, Any]:
    run = run_benchmark_dataset(
        suite_id=suite.suite_id,
        dataset_path=dataset_path,
        candidate_id=candidate_id,
        api_format=api_format,
        task_format=task_format,
        limit=limit,
        live=live,
        client=client,
        code_timeout_seconds=code_timeout_seconds,
        axio_gateway_url=axio_gateway_url,
        engine=engine,
        profiles=engine.profiles,
        max_latency_ms=max_latency_ms,
    )
    return {
        **run,
        "runtime_diagnostic_contract": {
            "schema": "axio_fusion_api.runtime_diagnostic_execution_contract.v1",
            "suite_id": suite.suite_id,
            "candidate_id": candidate_id,
            "api_format": api_format,
            "task_format": task_format,
            "case_count": _runtime_expected_case_count(dataset_path, task_format, limit),
            "mode": "live" if live else "dry_run",
            "gateway_required": bool(live and axio_gateway_url),
            "max_latency_ms": max(1, int(max_latency_ms)) if max_latency_ms is not None else None,
            "raw_gateway_url_persisted": False,
            "raw_prompts_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
    }


def _runtime_run_resume_allowed(
    path: Path,
    *,
    suite: BenchmarkSuite,
    dataset_path: Path,
    task_format: str,
    candidate_id: str,
    api_format: str,
    limit: int | None,
    live: bool,
    axio_gateway_url: str | None,
    max_latency_ms: int | None,
) -> bool:
    """Reuse only a completed run made under the same diagnostic contract."""

    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, TypeError):
        return False
    if not isinstance(payload, Mapping):
        return False
    contract = payload.get("runtime_diagnostic_contract")
    if not isinstance(contract, Mapping):
        return False
    expected_case_count = _runtime_expected_case_count(dataset_path, task_format, limit)
    expected_latency = max(1, int(max_latency_ms)) if max_latency_ms is not None else None
    if {
        str(contract.get("suite_id") or ""),
        str(contract.get("candidate_id") or ""),
        str(contract.get("api_format") or ""),
        str(contract.get("task_format") or ""),
    } != {suite.suite_id, candidate_id, api_format, task_format}:
        return False
    if _optional_int(contract.get("case_count")) != expected_case_count:
        return False
    if str(contract.get("mode") or "") != ("live" if live else "dry_run"):
        return False
    if bool(contract.get("gateway_required")) != bool(live and axio_gateway_url):
        return False
    if contract.get("max_latency_ms") != expected_latency:
        return False
    case_results = payload.get("case_results") if isinstance(payload.get("case_results"), list) else []
    return bool(case_results) and all(
        isinstance(case, Mapping) and str(case.get("status") or "") == "completed"
        for case in case_results
    )


def _runtime_expected_case_count(dataset_path: Path, task_format: str, limit: int | None) -> int:
    if task_format == "multiple_choice":
        return len(_load_multiple_choice_cases(dataset_path, limit=limit))
    return len(_load_generic_cases(dataset_path, limit=limit))


def _runtime_campaign_blocked_suite_row(
    suite: BenchmarkSuite,
    *,
    reason: str,
) -> dict[str, Any]:
    return {
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": suite.task_format,
        "ready": False,
        "reason_codes": [str(reason)],
        "raw_dataset_path_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_labels_persisted": False,
        "secrets_persisted": False,
    }


def _runtime_campaign_summary(engine: FusionEngine) -> dict[str, Any]:
    from .channel_config import runtime_channel_summary

    summary = runtime_channel_summary(engine.profiles)
    return {
        **summary,
        "engine_profile_count": len(engine.profiles),
        "engine_client_type": type(engine.client).__name__,
        "raw_runtime_credentials_persisted": False,
        "secrets_persisted": False,
    }


def import_official_benchmark_run(
    *,
    suite_id: str,
    candidate_id: str,
    source_path: str | Path,
    task_format: str = "auto",
    harness_name: str,
    harness_version: str,
    dataset_snapshot: str,
    evaluator_config: str,
    position_balanced: bool = False,
    prompt_protocol: str = "",
    decoding_config: str = "",
    api_format: str = "",
) -> dict[str, Any]:
    selected_format = _suite_task_format(suite_id) if task_format == "auto" else str(task_format or "multiple_choice")
    surface = _split_axio_api_surface_id(candidate_id)
    surface_api_format = normalize_api_format(api_format or (surface[1] if surface else ""))
    safe_candidate_id = surface[0] if surface else _canonical_safe_candidate_id(candidate_id)
    if _is_axio_public_candidate(safe_candidate_id) and not api_format and not surface:
        surface_api_format = AXIO_BENCHMARK_PRIMARY_API_FORMAT
    prompt_protocol_sha256 = _prompt_protocol_sha256_for_suite(
        suite_id,
        selected_format,
        prompt_protocol=prompt_protocol,
    )
    decoding_config_sha256 = _decoding_config_sha256_for_suite(
        suite_id,
        selected_format,
        decoding_config=decoding_config,
    )
    source = _load_official_import_source(source_path)
    rows = source["rows"]
    case_results = [
        _official_import_case_result(row, suite_id=suite_id, task_format=selected_format, index=index)
        for index, row in enumerate(rows)
    ]
    completed = [row for row in case_results if row.get("status") == "completed"]
    correct_count = sum(1 for row in case_results if row.get("correct") is True)
    scores = [float(row["score"]) for row in case_results if row.get("score") is not None]
    secondary_metrics = _official_import_secondary_metrics(case_results)
    cost_summary = _benchmark_cost_summary(case_results)
    latency_summary = _benchmark_latency_summary(case_results)
    return {
        "schema": "axio_fusion_api.benchmark_run.v2",
        "suite_id": suite_id,
        "candidate_id": safe_candidate_id,
        "candidate_id_policy": _candidate_id_alias_policy(candidate_id, safe_candidate_id),
        "api_format": surface_api_format
        if _is_axio_public_candidate(safe_candidate_id)
        else "provider_native"
        if str(safe_candidate_id).startswith("provider::")
        else "internal",
        "api_surface_id": _axio_api_surface_id(safe_candidate_id, surface_api_format)
        if _is_axio_public_candidate(safe_candidate_id)
        else safe_candidate_id,
        "api_surface_group": safe_candidate_id,
        "api_surface_role": "primary_claim"
        if _is_axio_public_candidate(safe_candidate_id) and _is_primary_axio_api_surface(surface_api_format)
        else "compatibility_check"
        if _is_axio_public_candidate(safe_candidate_id)
        else "native_or_internal",
        "api_surface_is_primary_claim": (
            _is_primary_axio_api_surface(surface_api_format)
            if _is_axio_public_candidate(safe_candidate_id)
            else True
        ),
        "task_format": selected_format,
        "prompt_protocol_sha256": prompt_protocol_sha256,
        "decoding_config_sha256": decoding_config_sha256,
        "mode": "official_import",
        "case_count": len(case_results),
        "attempted_count": len(completed),
        "correct_count": correct_count,
        "accuracy": None if not case_results else round(correct_count / len(case_results), 6),
        "mean_score": None if not scores else round(sum(scores) / len(scores), 6),
        "primary_metric": _primary_metric_for_official_import(suite_id, selected_format),
        "secondary_metrics": secondary_metrics,
        "latency_ms": round(sum(float(row.get("latency_ms") or 0.0) for row in case_results), 3),
        **latency_summary,
        **cost_summary,
        "case_results": case_results,
        "harness_receipt": _official_harness_receipt(
            suite_id=suite_id,
            task_format=selected_format,
            harness_name=harness_name,
            harness_version=harness_version,
            dataset_snapshot=dataset_snapshot,
            evaluator_config=evaluator_config,
            position_balanced=position_balanced,
            prompt_protocol_sha256=prompt_protocol_sha256,
            decoding_config_sha256=decoding_config_sha256,
        ),
        "cost_contract": {
            **_benchmark_cost_contract(),
            "cost_values_imported_from_official_or_audited_harness_receipts": True,
        },
        "import_receipt": {
            "schema": "axio_fusion_api.official_run_import_receipt.v1",
            "source_path_sha256": sha256_text(str(source_path)),
            "source_kind": source["kind"],
            "input_row_count": source["input_row_count"],
            "imported_case_count": len(case_results),
            "candidate_id_policy": _candidate_id_alias_policy(candidate_id, safe_candidate_id),
            "raw_source_path_persisted": False,
            "raw_source_content_persisted": False,
            "raw_provider_outputs_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_labels_persisted": False,
            "secrets_persisted": False,
        },
        "anti_leakage_contract": {
            "raw_inputs_persisted": False,
            "raw_references_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "benchmark_labels_used_for_training": False,
            "official_harness_receipt_required_for_final_claim": _suite_requires_official_harness(suite_id, selected_format),
        },
        "raw_prompt_persisted": False,
        "raw_label_persisted": False,
        "raw_provider_output_persisted": False,
        "secrets_persisted": False,
    }


def import_official_benchmark_run_batch(
    *,
    batch_path: str | Path,
    output_dir: str | Path,
    default_harness_name: str = "",
    default_harness_version: str = "",
    default_dataset_snapshot: str = "",
    default_evaluator_config: str = "",
    default_prompt_protocol: str = "",
    default_decoding_config: str = "",
) -> dict[str, Any]:
    """Import many official/audited benchmark outputs into safe run artifacts."""

    batch = _load_official_import_batch(batch_path)
    entries = _official_import_batch_entries(batch)
    defaults = _official_import_batch_defaults(
        batch,
        default_harness_name=default_harness_name,
        default_harness_version=default_harness_version,
        default_dataset_snapshot=default_dataset_snapshot,
        default_evaluator_config=default_evaluator_config,
        default_prompt_protocol=default_prompt_protocol,
        default_decoding_config=default_decoding_config,
    )
    output_root = Path(output_dir)
    output_root.mkdir(parents=True, exist_ok=True)
    receipts = []
    for index, entry in enumerate(entries):
        receipt = _import_official_batch_entry(
            entry,
            index=index,
            output_root=output_root,
            defaults=defaults,
        )
        receipts.append(receipt)
    imported = [row for row in receipts if row.get("status") == "imported"]
    failed = [row for row in receipts if row.get("status") != "imported"]
    return {
        "schema": "axio_fusion_api.official_run_import_batch.v1",
        "batch_path_sha256": sha256_text(str(batch_path)),
        "output_dir_sha256": sha256_text(str(output_dir)),
        "input_entry_count": len(entries),
        "imported_run_count": len(imported),
        "failed_import_count": len(failed),
        "suite_count": len({str(row.get("suite_id") or "") for row in imported if row.get("suite_id")}),
        "candidate_hash_count": len({str(row.get("candidate_id_hash") or "") for row in imported if row.get("candidate_id_hash")}),
        "position_balanced_import_count": sum(1 for row in imported if row.get("position_balanced") is True),
        "receipts": receipts,
        "summary_by_suite": _official_import_batch_summary_by_suite(receipts),
        "usage": {
            "next_step": "run benchmark-assemble-manifest with this output directory as --import-dir",
            "assemble_manifest_template": (
                "axio-fusion-api-standalone benchmark-assemble-manifest "
                "--dataset-dir <PINNED_DATASET_DIR> "
                f"--import-dir <SAFE_IMPORT_DIR_HASH_{sha256_text(str(output_dir))[:12]}> "
                "--output <WORK_DIR>/dataset_manifest.json"
            ),
        },
        "anti_leakage_contract": {
            "raw_batch_path_persisted": False,
            "raw_output_dir_persisted": False,
            "raw_source_paths_persisted": False,
            "raw_source_content_persisted": False,
            "raw_candidate_ids_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        "raw_batch_path_persisted": False,
        "raw_output_dir_persisted": False,
        "raw_source_paths_persisted": False,
        "raw_source_content_persisted": False,
        "raw_candidate_ids_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def build_benchmark_runs_payload(runs: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    normalized_runs = [_normalize_safe_run_candidate_alias(run) for run in runs if isinstance(run, Mapping)]
    run_set_receipt = _benchmark_run_set_receipt(normalized_runs)
    return {
        "schema": "axio_fusion_api.benchmark_campaign_runs.v1",
        "run_count": len(normalized_runs),
        "run_set_digest_sha256": run_set_receipt["run_set_digest_sha256"],
        "run_set_receipt": run_set_receipt,
        "runs": normalized_runs,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _benchmark_run_set_receipt(runs: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    rows = [
        _benchmark_run_set_receipt_row(run)
        for run in runs
        if isinstance(run, Mapping)
    ]
    rows.sort(
        key=lambda row: (
            row["suite_id"],
            row["candidate_id_sha256"],
            row["api_surface_id_sha256"],
            row["task_format"],
            row["mode"],
        )
    )
    digest_input = {
        "schema": "axio_fusion_api.benchmark_run_set_digest_input.v1",
        "rows": rows,
    }
    suite_ids = {row["suite_id"] for row in rows if row["suite_id"]}
    candidate_hashes = {row["candidate_id_sha256"] for row in rows if row["candidate_id_sha256"]}
    surface_hashes = {row["api_surface_id_sha256"] for row in rows if row["api_surface_id_sha256"]}
    return {
        "schema": "axio_fusion_api.benchmark_run_set_receipt.v1",
        "run_count": len(rows),
        "suite_count": len(suite_ids),
        "candidate_hash_count": len(candidate_hashes),
        "api_surface_hash_count": len(surface_hashes),
        "digest_input_schema": digest_input["schema"],
        "run_set_digest_sha256": sha256_text(stable_json(digest_input)),
        "run_set_rows_sha256": sha256_text(stable_json(rows)),
        "row_preview": rows[:8],
        "raw_candidate_ids_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _benchmark_methodology_receipt(methodology: Mapping[str, Any]) -> dict[str, Any]:
    suites = methodology.get("suites") if isinstance(methodology.get("suites"), list) else []
    suite_rows = [
        {
            "suite_id": str(row.get("suite_id") or ""),
            "category": str(row.get("category") or ""),
            "task_format": str(row.get("task_format") or ""),
            "primary_metric": str(row.get("primary_metric") or ""),
            "requires_official_harness": row.get("requires_official_harness") is True,
            "requires_external_judge_imports": row.get("requires_external_judge_imports") is True,
        }
        for row in suites
        if isinstance(row, Mapping)
    ]
    suite_rows.sort(key=lambda row: row["suite_id"])
    categories = sorted({row["category"] for row in suite_rows if row["category"]})
    return {
        "schema": "axio_fusion_api.benchmark_methodology_receipt.v1",
        "methodology_schema": str(methodology.get("schema") or ""),
        "methodology_digest_sha256": sha256_text(stable_json(methodology)),
        "suite_count": len(suite_rows),
        "required_category_count": len(categories),
        "suite_set_sha256": sha256_text(stable_json([row["suite_id"] for row in suite_rows])),
        "suite_contract_set_sha256": sha256_text(stable_json(suite_rows)),
        "global_controls_sha256": sha256_text(stable_json(methodology.get("global_controls") or {})),
        "raw_benchmark_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _benchmark_readiness_preflight_receipt(readiness: Mapping[str, Any]) -> dict[str, Any]:
    rows = readiness.get("rows") if isinstance(readiness.get("rows"), list) else []
    suite_rows = [
        {
            "suite_id": str(row.get("suite_id") or ""),
            "task_format": str(row.get("task_format") or ""),
            "ready": row.get("ready") is True,
            "reason_codes": sorted(str(reason) for reason in row.get("reason_codes", []) if reason),
            "case_count": _optional_int(row.get("case_count")) or 0,
            "requires_official_harness": row.get("requires_official_harness") is True,
            "run_unit_count": _optional_int(row.get("run_unit_count")) or 0,
            "expected_imported_run_count": _optional_int(row.get("expected_imported_run_count")) or 0,
            "valid_imported_run_count": _optional_int(row.get("valid_imported_run_count")) or 0,
            "missing_imported_run_count": _optional_int(row.get("missing_imported_run_count")) or 0,
            "invalid_imported_run_count": _optional_int(row.get("invalid_imported_run_count")) or 0,
        }
        for row in rows
        if isinstance(row, Mapping)
    ]
    suite_rows.sort(key=lambda row: row["suite_id"])
    digest_input = {
        "schema": "axio_fusion_api.benchmark_readiness_preflight_digest_input.v1",
        "dataset_manifest_sha256": str(readiness.get("dataset_manifest_sha256") or ""),
        "required_suite_count": _optional_int(readiness.get("required_suite_count")) or 0,
        "ready_suite_count": _optional_int(readiness.get("ready_suite_count")) or 0,
        "candidate_count": _optional_int(readiness.get("candidate_count")) or 0,
        "run_unit_count": _optional_int(readiness.get("run_unit_count")) or 0,
        "provider_baseline_count": _optional_int(readiness.get("provider_baseline_count")) or 0,
        "provider_baseline_selection": str(readiness.get("provider_baseline_selection") or ""),
        "available_provider_baseline_count": _optional_int(readiness.get("available_provider_baseline_count")) or 0,
        "registry_final_claim_ready": readiness.get("registry_final_claim_ready") is True,
        "registry_live_probe_proven": readiness.get("registry_live_probe_proven") is True,
        "registry_live_available_model_count": _optional_int(readiness.get("registry_live_available_model_count")) or 0,
        "final_claim_provider_baselines_exhaustive": readiness.get("final_claim_provider_baselines_exhaustive") is True,
        "final_claim_provider_baselines_pre_registered": readiness.get("final_claim_provider_baselines_pre_registered") is True,
        "final_claim_blocking_reasons": sorted(
            str(reason)
            for reason in readiness.get("final_claim_blocking_reasons", [])
            if reason
        ),
        "min_cases_per_suite": _optional_int(readiness.get("min_cases_per_suite")) or 0,
        "all_required_suites_ready": readiness.get("all_required_suites_ready") is True,
        "will_claim_audit_be_possible": readiness.get("will_claim_audit_be_possible") is True,
        "suite_rows": suite_rows,
    }
    return {
        "schema": "axio_fusion_api.benchmark_readiness_preflight_receipt.v1",
        "digest_input_schema": digest_input["schema"],
        "readiness_digest_sha256": sha256_text(stable_json(digest_input)),
        "dataset_manifest_sha256": digest_input["dataset_manifest_sha256"],
        "required_suite_count": digest_input["required_suite_count"],
        "ready_suite_count": digest_input["ready_suite_count"],
        "candidate_count": digest_input["candidate_count"],
        "run_unit_count": digest_input["run_unit_count"],
        "provider_baseline_count": digest_input["provider_baseline_count"],
        "provider_baseline_selection": digest_input["provider_baseline_selection"],
        "available_provider_baseline_count": digest_input["available_provider_baseline_count"],
        "registry_final_claim_ready": digest_input["registry_final_claim_ready"],
        "registry_live_probe_proven": digest_input["registry_live_probe_proven"],
        "registry_live_available_model_count": digest_input["registry_live_available_model_count"],
        "final_claim_provider_baselines_exhaustive": digest_input["final_claim_provider_baselines_exhaustive"],
        "final_claim_provider_baselines_pre_registered": digest_input["final_claim_provider_baselines_pre_registered"],
        "final_claim_blocking_reasons": digest_input["final_claim_blocking_reasons"],
        "min_cases_per_suite": digest_input["min_cases_per_suite"],
        "all_required_suites_ready": digest_input["all_required_suites_ready"],
        "will_claim_audit_be_possible": digest_input["will_claim_audit_be_possible"],
        "suite_readiness_set_sha256": sha256_text(stable_json(suite_rows)),
        "blocking_reason_counts": _count_reason_codes(_evidence_readiness_missing(readiness)),
        "raw_candidate_ids_persisted": False,
        "raw_dataset_paths_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _registry_claim_readiness_receipt(registry_path: str | Path | None) -> dict[str, Any]:
    selected = Path(registry_path) if registry_path else None
    artifact = _load_json_artifact(selected)
    payload = artifact["payload"] if artifact["valid_json_object"] else {}
    readiness = payload.get("readiness") if isinstance(payload.get("readiness"), Mapping) else {}
    portfolio_summary = _registry_provider_portfolio_claim_summary(registry_path, artifact_valid=artifact["valid_json_object"])
    generated_from_probe = payload.get("generated_from_probe") is True
    generated_from_prefusion = payload.get("generated_from_prefusion_screening") is True
    prefusion_validation: dict[str, Any] = {}
    if artifact["valid_json_object"] and generated_from_prefusion:
        try:
            prefusion_validation = validate_prefusion_registry_handoff(
                payload,
                require_ready=True,
            )
        except Exception:  # noqa: BLE001 - readiness must fail closed
            prefusion_validation = {
                "valid": False,
                "reason_codes": ["prefusion_registry_handoff_validation_failed"],
            }
    prefusion_handoff_valid = prefusion_validation.get("valid") is True
    probe_backed_registry = generated_from_probe or prefusion_handoff_valid
    final_ready = (
        readiness.get("final_claim_registry_ready") is True
        if generated_from_probe
        else prefusion_handoff_valid and readiness.get("ready") is True
    )
    live_proven = (
        readiness.get("live_probe_proven") is True
        if generated_from_probe
        else prefusion_handoff_valid
    )
    blockers: list[str] = []
    if registry_path is None:
        blockers.append("registry_path_missing_for_final_claim")
    elif not artifact["exists"] or not artifact["valid_json_object"]:
        blockers.append("registry_artifact_unavailable_for_final_claim")
    if artifact["valid_json_object"] and not probe_backed_registry:
        blockers.append("registry_not_generated_from_probe")
    if artifact["valid_json_object"] and generated_from_prefusion and not prefusion_handoff_valid:
        blockers.append("registry_prefusion_handoff_invalid")
        blockers.extend(
            f"registry_prefusion_{str(reason)}"
            for reason in prefusion_validation.get("reason_codes", [])
            if str(reason)
        )
    if artifact["valid_json_object"] and probe_backed_registry and not live_proven:
        blockers.append("registry_live_probe_evidence_missing")
    if artifact["valid_json_object"] and probe_backed_registry and not final_ready:
        blockers.append("registry_final_claim_readiness_false")
    for reason in readiness.get("blockers", []) if isinstance(readiness.get("blockers"), list) else []:
        blockers.append(f"registry_readiness_{str(reason)}")
    if portfolio_summary.get("final_claim_portfolio_ready") is not True:
        blockers.append("provider_portfolio_final_claim_not_ready")
    for reason in portfolio_summary.get("blockers", []) if isinstance(portfolio_summary.get("blockers"), list) else []:
        blockers.append(f"provider_portfolio_{str(reason)}")
    for reason in portfolio_summary.get("warnings", []) if isinstance(portfolio_summary.get("warnings"), list) else []:
        if str(reason) in {
            "answer_claim_verifier_new_profile_capacity_below_target",
            "answer_claim_verifier_cross_provider_capacity_below_target",
            "answer_claim_verifier_live_probe_evidence_below_final_claim_target",
            "provider_diversity_below_target",
        }:
            blockers.append(f"provider_portfolio_{str(reason)}")
    blockers = sorted(set(blockers))
    return {
        "schema": "axio_fusion_api.registry_claim_readiness_receipt.v1",
        "registry_path_provided": registry_path is not None,
        "registry_path_sha256": sha256_text(str(registry_path)) if registry_path is not None else "",
        "registry_artifact_exists": artifact["exists"],
        "registry_artifact_valid_json": artifact["valid_json_object"],
        "registry_schema": artifact["schema"],
        "generated_from_probe": generated_from_probe,
        "generated_from_prefusion_screening": generated_from_prefusion,
        "prefusion_handoff_valid": prefusion_handoff_valid,
        "probe_backed_registry": probe_backed_registry,
        "readiness_status": str(readiness.get("status") or ""),
        "final_claim_registry_ready": final_ready and not blockers,
        "live_probe_proven": live_proven,
        "available_model_count": _optional_int(payload.get("available_model_count", readiness.get("available_model_count"))) or 0,
        "live_available_model_count": _optional_int(payload.get("live_available_model_count", readiness.get("live_available_model_count"))) or 0,
        "min_available_models": _optional_int(readiness.get("min_available_models")) or 0,
        "probe_mode_counts": dict(readiness.get("probe_mode_counts")) if isinstance(readiness.get("probe_mode_counts"), Mapping) else {},
        "provider_portfolio_summary": portfolio_summary,
        "final_claim_blocking_reasons": blockers,
        "raw_registry_path_persisted": False,
        "raw_provider_names_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_provider_urls_persisted": False,
        "raw_api_keys_persisted": False,
        "secrets_persisted": False,
    }


def _registry_provider_portfolio_claim_summary(
    registry_path: str | Path | None,
    *,
    artifact_valid: bool,
) -> dict[str, Any]:
    if registry_path is None:
        return {
            "available": False,
            "reason_codes": ["registry_path_missing"],
            "final_claim_portfolio_ready": False,
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
        }
    if not artifact_valid:
        return {
            "available": False,
            "reason_codes": ["registry_artifact_invalid_or_missing"],
            "registry_path_sha256": sha256_text(str(registry_path)),
            "final_claim_portfolio_ready": False,
            "raw_path_persisted": False,
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
        }
    try:
        audit = build_provider_portfolio_audit(load_registry(registry_path))
    except Exception:  # noqa: BLE001 - readiness must remain safe and diagnostic
        return {
            "available": False,
            "reason_codes": ["provider_portfolio_audit_failed"],
            "registry_path_sha256": sha256_text(str(registry_path)),
            "final_claim_portfolio_ready": False,
            "raw_path_persisted": False,
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
        }
    capacity = audit.get("independent_verification_capacity") if isinstance(audit.get("independent_verification_capacity"), Mapping) else {}
    return {
        "available": True,
        "schema": str(audit.get("schema") or ""),
        "status": str(audit.get("status") or ""),
        "ready_for_serving": audit.get("ready_for_serving") is True,
        "ready_for_diverse_fusion": audit.get("ready_for_diverse_fusion") is True,
        "final_claim_portfolio_ready": audit.get("ready_for_final_claim_registry_profile") is True,
        "blockers": list(audit.get("blockers") or []),
        "warnings": list(audit.get("warnings") or []),
        "independent_verification_capacity": {
            "schema": str(capacity.get("schema") or ""),
            "serving_independent_verification_ready": capacity.get("serving_independent_verification_ready") is True,
            "cross_provider_verifier_ready": capacity.get("cross_provider_verifier_ready") is True,
            "new_profile_verifier_ready": capacity.get("new_profile_verifier_ready") is True,
            "final_claim_independent_verification_ready": capacity.get("final_claim_independent_verification_ready") is True,
            "ready_verifier_count": _optional_int(capacity.get("ready_verifier_count")) or 0,
            "ready_provider_hash_count": _optional_int(capacity.get("ready_provider_hash_count")) or 0,
            "live_probe_evidence_ready_verifier_count": _optional_int(capacity.get("live_probe_evidence_ready_verifier_count")) or 0,
            "reason_codes": list(capacity.get("reason_codes") or []),
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
        },
        "recommendation_ids": [
            str(row.get("recommendation_id") or "")
            for row in audit.get("recommendations", [])
            if isinstance(row, Mapping)
        ],
        "raw_path_persisted": False,
        "raw_provider_names_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "secrets_persisted": False,
    }


def _benchmark_run_set_receipt_row(run: Mapping[str, Any]) -> dict[str, Any]:
    suite_id = str(run.get("suite_id") or "")
    task_format = str(run.get("task_format") or _suite_task_format(suite_id))
    candidate_id = str(run.get("candidate_id") or "")
    api_format = _run_api_format(run)
    api_surface_id = _run_api_surface_id(run)
    case_receipt = _run_case_hash_receipt(run)
    prompt_receipt = _run_prompt_protocol_receipt(run)
    decoding_receipt = _run_decoding_config_receipt(run)
    reasoning_receipt = _benchmark_reasoning_run_receipt(
        run,
        suite_id=suite_id,
        task_format=task_format,
    )
    harness_receipt = _run_official_harness_binding_receipt(
        run,
        suite_id=suite_id,
        task_format=task_format,
    )
    harness_binding = {
        "harness_receipt_required": harness_receipt["harness_receipt_required"],
        "harness_receipt_present": harness_receipt["harness_receipt_present"],
        "harness_receipt_valid": harness_receipt["harness_receipt_valid"],
        "official_harness_binding_hashes": harness_receipt["official_harness_binding_hashes"],
        "official_harness_binding_missing_fields": harness_receipt["official_harness_binding_missing_fields"],
    }
    case_hashes = case_receipt.get("case_hashes") if isinstance(case_receipt.get("case_hashes"), list) else []
    return {
        "suite_id": suite_id,
        "candidate_id_sha256": sha256_text(candidate_id),
        "api_format": api_format,
        "api_surface_id_sha256": sha256_text(api_surface_id),
        "api_surface_role": str(run.get("api_surface_role") or ""),
        "api_surface_is_primary_claim": run.get("api_surface_is_primary_claim") is True
        or (_is_axio_public_candidate(candidate_id) and _is_primary_axio_api_surface(api_format)),
        "candidate_type": "provider" if candidate_id.startswith("provider::") else "axio" if candidate_id.startswith("axio-") else "baseline",
        "task_format": task_format,
        "mode": str(run.get("mode") or ""),
        "primary_metric": _scorecard_primary_metric(run),
        "primary_score": _run_primary_score(run),
        "accuracy": _optional_float(run.get("accuracy")),
        "mean_score": _optional_float(run.get("mean_score")),
        "case_count": _optional_int(run.get("case_count")) or 0,
        "attempted_count": _optional_int(run.get("attempted_count")) or 0,
        "correct_count": _optional_int(run.get("correct_count")) or 0,
        "case_hash_count": _optional_int(case_receipt.get("case_hash_count")) or 0,
        "case_hash_set_sha256": sha256_text(stable_json(sorted(str(item) for item in case_hashes))),
        "missing_case_hash_count": _optional_int(case_receipt.get("missing_case_hash_count")) or 0,
        "duplicate_case_hash_count": _optional_int(case_receipt.get("duplicate_case_hash_count")) or 0,
        "prompt_protocol_sha256": str(prompt_receipt.get("prompt_protocol_sha256") or ""),
        "prompt_protocol_hash_count": _optional_int(prompt_receipt.get("prompt_protocol_hash_count")) or 0,
        "prompt_protocol_hash_conflict": prompt_receipt.get("prompt_protocol_hash_conflict") is True,
        "decoding_config_sha256": str(decoding_receipt.get("decoding_config_sha256") or ""),
        "decoding_config_hash_count": _optional_int(decoding_receipt.get("decoding_config_hash_count")) or 0,
        "decoding_config_hash_conflict": decoding_receipt.get("decoding_config_hash_conflict") is True,
        "requested_reasoning_effort": str(reasoning_receipt.get("requested_reasoning_effort") or ""),
        "effective_reasoning_effort": str(reasoning_receipt.get("effective_reasoning_effort") or ""),
        "reasoning_transport": str(reasoning_receipt.get("reasoning_transport") or ""),
        "native_reasoning_effort_verified": reasoning_receipt.get("native_reasoning_effort_verified"),
        "reasoning_config_sha256": str(reasoning_receipt.get("reasoning_config_sha256") or ""),
        "reasoning_status": str(reasoning_receipt.get("status") or ""),
        "harness_binding_sha256": sha256_text(stable_json(harness_binding)),
        "harness_receipt_required": harness_receipt["harness_receipt_required"],
        "harness_receipt_present": harness_receipt["harness_receipt_present"],
        "harness_receipt_valid": harness_receipt["harness_receipt_valid"],
        "estimated_cost_usd": _run_estimated_cost_usd(run),
        "latency_ms": _optional_float(run.get("latency_ms")),
        "average_case_latency_ms": _optional_float(run.get("average_case_latency_ms")),
        "p50_case_latency_ms": _optional_float(run.get("p50_case_latency_ms")),
        "p95_case_latency_ms": _optional_float(run.get("p95_case_latency_ms")),
        "pricing_known_case_count": _optional_int(run.get("pricing_known_case_count")) or 0,
        "pricing_unknown_case_count": _optional_int(run.get("pricing_unknown_case_count")) or 0,
        "provider_call_count": _optional_int(run.get("provider_call_count")) or 0,
    }


def _primary_claim_scoring_runs(runs: Sequence[Mapping[str, Any]]) -> list[Mapping[str, Any]]:
    selected = []
    for run in runs:
        candidate_id = str(run.get("candidate_id") or "")
        if not _is_axio_public_candidate(candidate_id):
            selected.append(run)
            continue
        if _run_api_surface_is_primary_claim(run):
            selected.append(run)
    return selected


def _run_api_surface_is_primary_claim(run: Mapping[str, Any]) -> bool:
    candidate_id = str(run.get("candidate_id") or "")
    if not _is_axio_public_candidate(candidate_id):
        return True
    if "api_surface_is_primary_claim" in run:
        return run.get("api_surface_is_primary_claim") is True
    return _is_primary_axio_api_surface(_run_api_format(run))


def _api_surface_run_transport_receipt(
    run: Mapping[str, Any],
    *,
    expected_api_format: str,
) -> dict[str, Any]:
    """Summarize only safe public-API transport facts for one Axio run.

    A final benchmark claim needs stronger evidence than a compatible response
    shape: every scored Axio case must have crossed the public HTTP gateway in
    the selected protocol.  The run artifact retains only counts and boolean
    facts here, never a gateway URL, benchmark prompt, response text, tool
    schema, or provider identity.
    """

    rows = run.get("case_results") if isinstance(run.get("case_results"), list) else []
    expected = normalize_api_format(expected_api_format)
    missing_invocation_count = 0
    public_api_not_used_count = 0
    api_format_mismatch_count = 0
    non_http_gateway_count = 0
    network_not_performed_count = 0
    unsafe_invocation_count = 0
    http_gateway_count = 0
    network_call_count = 0

    if not rows:
        missing_invocation_count = 1
    for row in rows:
        if not isinstance(row, Mapping):
            missing_invocation_count += 1
            continue
        invocation = row.get("public_api_invocation")
        if not isinstance(invocation, Mapping):
            missing_invocation_count += 1
            continue
        if _contains_true_raw_persisted_flag(invocation) or _contains_forbidden_persistence_flag(invocation):
            unsafe_invocation_count += 1
        if invocation.get("public_api_surface_used") is not True:
            public_api_not_used_count += 1
        actual_raw = str(invocation.get("api_format") or "").strip()
        actual = normalize_api_format(actual_raw) if actual_raw else ""
        if actual != expected:
            api_format_mismatch_count += 1
        transport = str(invocation.get("transport") or "")
        agent_turn_count = _optional_int(invocation.get("agent_turn_count")) or 0
        agent_http_gateway_call_count = _optional_int(invocation.get("http_gateway_call_count")) or 0
        agent_network_call_count = _optional_int(invocation.get("network_call_count")) or 0
        if transport == "http_gateway":
            http_gateway_count += 1
        else:
            non_http_gateway_count += 1
        if invocation.get("network_calls_performed") is True:
            network_call_count += 1
        else:
            network_not_performed_count += 1
        if agent_turn_count and agent_http_gateway_call_count < agent_turn_count:
            non_http_gateway_count += 1
        if agent_turn_count and agent_network_call_count < agent_turn_count:
            network_not_performed_count += 1

    all_http_gateway = bool(rows) and not any(
        (
            missing_invocation_count,
            public_api_not_used_count,
            api_format_mismatch_count,
            non_http_gateway_count,
            network_not_performed_count,
            unsafe_invocation_count,
        )
    )
    reason_codes = []
    if missing_invocation_count:
        reason_codes.append("api_surface_public_api_invocation_missing")
    if public_api_not_used_count:
        reason_codes.append("api_surface_public_api_surface_not_used")
    if api_format_mismatch_count:
        reason_codes.append("api_surface_invocation_api_format_mismatch")
    if non_http_gateway_count:
        reason_codes.append("api_surface_http_gateway_transport_required")
    if network_not_performed_count:
        reason_codes.append("api_surface_network_call_receipt_required")
    if unsafe_invocation_count:
        reason_codes.append("api_surface_public_api_invocation_unsafe")
    return {
        "schema": "axio_fusion_api.api_surface_http_transport_receipt.v1",
        "expected_api_format": expected,
        "case_result_count": len(rows),
        "missing_public_api_invocation_case_count": missing_invocation_count,
        "public_api_surface_not_used_case_count": public_api_not_used_count,
        "api_format_mismatch_case_count": api_format_mismatch_count,
        "http_gateway_case_count": http_gateway_count,
        "non_http_gateway_case_count": non_http_gateway_count,
        "network_call_case_count": network_call_count,
        "network_not_performed_case_count": network_not_performed_count,
        "unsafe_invocation_case_count": unsafe_invocation_count,
        "all_case_invocations_use_http_gateway": all_http_gateway,
        "reason_codes": reason_codes,
        "raw_gateway_urls_persisted": False,
        "raw_prompts_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def build_benchmark_api_surface_audit(
    runs: Sequence[Mapping[str, Any]],
    *,
    score_tolerance: float = AXIO_BENCHMARK_API_SURFACE_SCORE_TOLERANCE,
    require_http_gateway: bool = False,
    suite_ids: Sequence[str] | None = None,
    model_ids: Sequence[str] | None = None,
) -> dict[str, Any]:
    normalized_runs = [_normalize_safe_run_candidate_alias(run) for run in runs if isinstance(run, Mapping)]
    by_suite_model: dict[tuple[str, str], list[Mapping[str, Any]]] = {}
    for run in normalized_runs:
        candidate_id = str(run.get("candidate_id") or "")
        suite_id = str(run.get("suite_id") or "")
        if suite_id and _is_axio_public_candidate(candidate_id):
            by_suite_model.setdefault((suite_id, candidate_id), []).append(run)
    selected_suite_ids = {str(value).strip() for value in (suite_ids or ()) if str(value).strip()}
    selected_suites = [
        suite
        for suite in BENCHMARK_SUITES
        if not selected_suite_ids or suite.suite_id in selected_suite_ids
    ]
    selected_model_ids = tuple(
        dict.fromkeys(
            str(value).strip()
            for value in (model_ids or AXIO_BENCHMARK_PUBLIC_MODELS)
            if str(value).strip() in AXIO_BENCHMARK_PUBLIC_MODELS
        )
    )
    rows = []
    for suite in selected_suites:
        for model in selected_model_ids:
            rows.append(
                _api_surface_audit_row(
                    suite_id=suite.suite_id,
                    category=suite.category,
                    model=model,
                    runs=by_suite_model.get((suite.suite_id, model), []),
                    score_tolerance=float(score_tolerance),
                    require_http_gateway=bool(require_http_gateway),
                )
            )
    failed = [row for row in rows if row.get("ready") is not True]
    reason_counts = _count_reason_codes(failed)
    return {
        "schema": "axio_fusion_api.benchmark_api_surface_audit.v1",
        "required_suite_count": len(BENCHMARK_SUITES),
        "scoped_suite_count": len(selected_suites),
        "scoped_suite_ids": [suite.suite_id for suite in selected_suites],
        "scoped_model_count": len(selected_model_ids),
        "scoped_model_ids": list(selected_model_ids),
        "required_model_count": len(AXIO_BENCHMARK_PUBLIC_MODELS),
        "required_api_format_count": len(AXIO_BENCHMARK_API_FORMATS),
        "required_surface_row_count": len(rows),
        "ready_surface_row_count": sum(1 for row in rows if row.get("ready") is True),
        "all_required_api_surfaces_ready": not failed,
        "score_tolerance": float(score_tolerance),
        "http_gateway_required": bool(require_http_gateway),
        "api_surface_contract": _api_surface_contract(),
        "blocking_reason_counts": reason_counts,
        "suite_model_rows": rows,
        "anti_leakage_contract": {
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def build_benchmark_api_surface_parity_report(
    runs: Sequence[Mapping[str, Any]],
    *,
    score_tolerance: float = AXIO_BENCHMARK_API_SURFACE_SCORE_TOLERANCE,
    require_http_gateway: bool = False,
    suite_ids: Sequence[str] | None = None,
    model_ids: Sequence[str] | None = None,
) -> dict[str, Any]:
    """Build an operator-facing, hash-only report for Axio API surface parity."""

    audit = build_benchmark_api_surface_audit(
        runs,
        score_tolerance=score_tolerance,
        require_http_gateway=bool(require_http_gateway),
        suite_ids=suite_ids,
        model_ids=model_ids,
    )
    run_set_receipt = _benchmark_run_set_receipt([run for run in runs if isinstance(run, Mapping)])
    rows = audit.get("suite_model_rows") if isinstance(audit.get("suite_model_rows"), list) else []
    safe_rows = [row for row in rows if isinstance(row, Mapping)]
    failed = [row for row in safe_rows if row.get("ready") is not True]
    reason_counts = dict(audit.get("blocking_reason_counts") or {})
    missing_format_counts = _api_surface_format_counts(failed, "missing_api_formats")
    duplicate_format_counts = _api_surface_format_counts(failed, "duplicate_api_formats")
    score_delta_rows = sorted(
        [
            {
                "suite_id": str(row.get("suite_id") or ""),
                "category": str(row.get("category") or ""),
                "axio_model": str(row.get("axio_model") or ""),
                "max_primary_score_delta": _optional_float(row.get("max_primary_score_delta")),
                "ready": row.get("ready") is True,
                "reason_codes": list(row.get("reason_codes") or []),
            }
            for row in safe_rows
            if _optional_float(row.get("max_primary_score_delta")) is not None
        ],
        key=lambda item: _optional_float(item.get("max_primary_score_delta")) or 0.0,
        reverse=True,
    )
    return {
        "schema": "axio_fusion_api.benchmark_api_surface_parity_report.v1",
        "run_count": len([run for run in runs if isinstance(run, Mapping)]),
        "source_run_set_digest_sha256": run_set_receipt["run_set_digest_sha256"],
        "run_set_receipt": run_set_receipt,
        "required_suite_count": audit.get("required_suite_count"),
        "scoped_suite_count": audit.get("scoped_suite_count"),
        "scoped_suite_ids": list(audit.get("scoped_suite_ids") or []),
        "scoped_model_count": audit.get("scoped_model_count"),
        "scoped_model_ids": list(audit.get("scoped_model_ids") or []),
        "required_model_count": audit.get("required_model_count"),
        "required_api_formats": list(AXIO_BENCHMARK_API_FORMATS),
        "primary_claim_api_surface": AXIO_BENCHMARK_PRIMARY_API_FORMAT,
        "score_tolerance": float(score_tolerance),
        "http_gateway_required": bool(require_http_gateway),
        "surface_row_count": len(safe_rows),
        "ready_surface_row_count": _optional_int(audit.get("ready_surface_row_count")) or 0,
        "failed_surface_row_count": len(failed),
        "all_required_api_surfaces_ready": audit.get("all_required_api_surfaces_ready") is True,
        "surface_audit_digest_sha256": sha256_text(stable_json(audit)),
        "blocking_reason_counts": reason_counts,
        "missing_api_format_counts": missing_format_counts,
        "duplicate_api_format_counts": duplicate_format_counts,
        "by_model": _api_surface_parity_model_summary(safe_rows, model_ids=model_ids),
        "by_category": _api_surface_parity_category_summary(safe_rows),
        "score_delta_extremes": score_delta_rows[:24],
        "repair_queue": [_api_surface_repair_receipt(row) for row in failed[:96]],
        "recommendations": _api_surface_parity_recommendations(reason_counts),
        "next_command_templates": {
            "rerun_missing_surface": (
                "axio-fusion-api-standalone --registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "benchmark-run --suite-id <SUITE_ID> --dataset <PRIVATE_DATASET_JSONL> "
                "--candidate-id <AXIO_MODEL> --api-format <MISSING_API_FORMAT> "
                "--live --output <PRIVATE_CAMPAIGN_DIR>/runs/<SAFE_RUN_FILE>.json"
            ),
            "campaign_progress": (
                "axio-fusion-api-standalone --registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "benchmark-campaign-progress-plan --dataset-manifest <PINNED_DATASET_MANIFEST> "
                "--output-dir <PRIVATE_CAMPAIGN_DIR> --provider-baseline-freeze <SAFE_WORK_DIR>/provider_baseline_freeze.safe.json "
                "--output <SAFE_WORK_DIR>/campaign_progress.safe.json"
            ),
            "parity_report": (
                "axio-fusion-api-standalone benchmark-api-surface-parity "
                "--run-file <PRIVATE_CAMPAIGN_DIR>/runs.json --require-http-gateway "
                "--output <SAFE_WORK_DIR>/api_surface_parity.safe.json"
            ),
        },
        "claim_contract": {
            "four_public_api_surfaces_required_for_each_axio_model_suite": True,
            "only_primary_surface_participates_in_superiority_claim": True,
            "non_primary_surfaces_are_engineering_stability_gates": True,
            "case_hash_sets_must_match_across_surfaces": True,
            "prompt_protocol_hash_must_match_across_surfaces": True,
            "decoding_config_hash_must_match_across_surfaces": True,
            "score_delta_must_not_exceed_tolerance": True,
            "formal_live_benchmark_requires_http_gateway_per_public_api_case": True,
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
        },
        "anti_leakage_contract": {
            "raw_run_paths_persisted": False,
            "raw_dataset_paths_persisted": False,
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "secrets_persisted": False,
        },
        "raw_run_paths_persisted": False,
        "raw_dataset_paths_persisted": False,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "secrets_persisted": False,
    }


def _api_surface_format_counts(rows: Sequence[Mapping[str, Any]], field: str) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        values = row.get(field) if isinstance(row.get(field), list) else []
        for value in values:
            api_format = str(value or "")
            if api_format:
                counts[api_format] = counts.get(api_format, 0) + 1
    return dict(sorted(counts.items()))


def _api_surface_parity_model_summary(
    rows: Sequence[Mapping[str, Any]],
    *,
    model_ids: Sequence[str] | None = None,
) -> list[dict[str, Any]]:
    result = []
    selected_models = tuple(
        dict.fromkeys(
            str(value).strip()
            for value in (model_ids or AXIO_BENCHMARK_PUBLIC_MODELS)
            if str(value).strip() in AXIO_BENCHMARK_PUBLIC_MODELS
        )
    )
    for model in selected_models:
        model_rows = [row for row in rows if str(row.get("axio_model") or "") == model]
        failed = [row for row in model_rows if row.get("ready") is not True]
        deltas = [
            _optional_float(row.get("max_primary_score_delta"))
            for row in model_rows
            if _optional_float(row.get("max_primary_score_delta")) is not None
        ]
        result.append(
            {
                "axio_model": model,
                "surface_row_count": len(model_rows),
                "ready_surface_row_count": sum(1 for row in model_rows if row.get("ready") is True),
                "failed_surface_row_count": len(failed),
                "max_primary_score_delta": None if not deltas else round(max(float(value) for value in deltas if value is not None), 6),
                "reason_counts": _count_reason_codes(failed),
            }
        )
    return result


def _api_surface_parity_category_summary(rows: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    result = []
    for category in sorted(BENCHMARK_CATEGORY_REQUIRED_SUITE_COUNTS):
        category_rows = [row for row in rows if str(row.get("category") or "") == category]
        failed = [row for row in category_rows if row.get("ready") is not True]
        result.append(
            {
                "category": category,
                "surface_row_count": len(category_rows),
                "ready_surface_row_count": sum(1 for row in category_rows if row.get("ready") is True),
                "failed_surface_row_count": len(failed),
                "reason_counts": _count_reason_codes(failed),
            }
        )
    return result


def _api_surface_repair_receipt(row: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "suite_id": str(row.get("suite_id") or ""),
        "category": str(row.get("category") or ""),
        "axio_model": str(row.get("axio_model") or ""),
        "present_api_formats": [str(item) for item in row.get("present_api_formats", []) if str(item)]
        if isinstance(row.get("present_api_formats"), list)
        else [],
        "missing_api_formats": [str(item) for item in row.get("missing_api_formats", []) if str(item)]
        if isinstance(row.get("missing_api_formats"), list)
        else [],
        "duplicate_api_formats": [str(item) for item in row.get("duplicate_api_formats", []) if str(item)]
        if isinstance(row.get("duplicate_api_formats"), list)
        else [],
        "case_hash_sets_identical": row.get("case_hash_sets_identical") is True,
        "reference_case_hash_count": _optional_int(row.get("reference_case_hash_count")) or 0,
        "prompt_protocol_hashes_identical": row.get("prompt_protocol_hashes_identical") is True,
        "decoding_config_hashes_identical": row.get("decoding_config_hashes_identical") is True,
        "max_primary_score_delta": _optional_float(row.get("max_primary_score_delta")),
        "score_tolerance": _optional_float(row.get("score_tolerance")),
        "http_gateway_required": row.get("http_gateway_required") is True,
        "http_gateway_case_count": _optional_int(row.get("http_gateway_case_count")) or 0,
        "in_process_or_missing_transport_case_count": (
            (_optional_int(row.get("missing_public_api_invocation_case_count")) or 0)
            + (_optional_int(row.get("non_http_gateway_case_count")) or 0)
        ),
        "all_case_invocations_use_http_gateway": row.get("all_case_invocations_use_http_gateway") is True,
        "reason_codes": list(row.get("reason_codes") or []),
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _api_surface_parity_recommendations(reason_counts: Mapping[str, int]) -> list[dict[str, Any]]:
    recommendations = []
    if int(reason_counts.get("missing_required_api_surface_runs") or 0) > 0:
        recommendations.append(
            _api_surface_parity_recommendation(
                recommendation_id="complete_missing_api_surface_runs",
                priority="P0",
                reason="one_or_more_axio_suite_model_cells_are_missing_required_public_api_formats",
                validation_gate="all axio suite/model cells have chat, responses, anthropic, and gemini runs",
            )
        )
    if int(reason_counts.get("duplicate_api_surface_runs") or 0) > 0:
        recommendations.append(
            _api_surface_parity_recommendation(
                recommendation_id="deduplicate_api_surface_runs",
                priority="P1",
                reason="duplicate_api_surface_runs_make_surface_equivalence_ambiguous",
                validation_gate="exactly one run per suite, axio model, and public API format",
            )
        )
    if (
        int(reason_counts.get("api_surface_case_hash_sets_misaligned") or 0) > 0
        or int(reason_counts.get("api_surface_prompt_protocol_misaligned") or 0) > 0
        or int(reason_counts.get("api_surface_decoding_config_misaligned") or 0) > 0
    ):
        recommendations.append(
            _api_surface_parity_recommendation(
                recommendation_id="rebind_case_prompt_and_decoding_protocols",
                priority="P0",
                reason="surface_runs_must_share_case_hashes_prompt_protocol_and_decoding_config",
                validation_gate="case hash sets, prompt protocol hash, and decoding config hash match across surfaces",
            )
        )
    if int(reason_counts.get("api_surface_score_delta_above_tolerance") or 0) > 0:
        recommendations.append(
            _api_surface_parity_recommendation(
                recommendation_id="investigate_surface_adapter_score_drift",
                priority="P1",
                reason="same_axio_model_scores_differ_across_public_api_surfaces",
                validation_gate="max primary score delta stays within the registered tolerance",
            )
        )
    if int(reason_counts.get("api_surface_scores_missing") or 0) > 0:
        recommendations.append(
            _api_surface_parity_recommendation(
                recommendation_id="repair_missing_surface_scores",
                priority="P0",
                reason="surface_runs_without_primary_scores_cannot_support_equivalence",
                validation_gate="every surface run has a primary score",
            )
        )
    transport_issue_count = sum(
        int(reason_counts.get(reason) or 0)
        for reason in (
            "api_surface_public_api_invocation_missing",
            "api_surface_public_api_surface_not_used",
            "api_surface_invocation_api_format_mismatch",
            "api_surface_http_gateway_transport_required",
            "api_surface_network_call_receipt_required",
            "api_surface_public_api_invocation_unsafe",
        )
    )
    if transport_issue_count:
        recommendations.append(
            _api_surface_parity_recommendation(
                recommendation_id="repair_public_http_gateway_evidence",
                priority="P0",
                reason="formal_live_benchmark_requires_each_axio_case_to_cross_the_matching_public_http_api_surface",
                validation_gate="every Axio case has a safe matching-format http_gateway receipt with network_calls_performed=true",
            )
        )
    if not recommendations:
        recommendations.append(
            _api_surface_parity_recommendation(
                recommendation_id="surface_parity_clean_keep_protocol_frozen",
                priority="P3",
                reason="all_required_api_surfaces_are_ready",
                validation_gate="keep case, prompt, and decoding protocol hashes frozen for final audit",
            )
        )
    return recommendations


def _api_surface_parity_recommendation(
    *,
    recommendation_id: str,
    priority: str,
    reason: str,
    validation_gate: str,
) -> dict[str, Any]:
    return {
        "recommendation_id": recommendation_id,
        "priority": priority,
        "reason": reason,
        "validation_gate": validation_gate,
        "shadow_only": True,
        "auto_applied_to_serving_policy": False,
        "raw_prompts_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _api_surface_audit_row(
    *,
    suite_id: str,
    category: str,
    model: str,
    runs: Sequence[Mapping[str, Any]],
    score_tolerance: float,
    require_http_gateway: bool,
) -> dict[str, Any]:
    by_format: dict[str, list[Mapping[str, Any]]] = {}
    for run in runs:
        by_format.setdefault(_run_api_format(run), []).append(run)
    missing_formats = [
        api_format
        for api_format in AXIO_BENCHMARK_API_FORMATS
        if api_format not in by_format
    ]
    duplicate_formats = [
        api_format
        for api_format, rows in by_format.items()
        if api_format in AXIO_BENCHMARK_API_FORMATS and len(rows) > 1
    ]
    selected_runs = [
        by_format[api_format][0]
        for api_format in AXIO_BENCHMARK_API_FORMATS
        if api_format in by_format and by_format[api_format]
    ]
    case_sets = [_run_case_hash_set(run) for run in selected_runs]
    case_reference = case_sets[0] if case_sets else set()
    case_hash_sets_identical = (
        bool(selected_runs)
        and not missing_formats
        and all(case_set == case_reference for case_set in case_sets)
        and bool(case_reference)
    )
    prompt_hashes = sorted({str(run.get("prompt_protocol_sha256") or "") for run in selected_runs if str(run.get("prompt_protocol_sha256") or "")})
    decoding_hashes = sorted({str(run.get("decoding_config_sha256") or "") for run in selected_runs if str(run.get("decoding_config_sha256") or "")})
    reasoning_receipts = {
        api_format: _benchmark_reasoning_run_receipt(
            by_format[api_format][0],
            suite_id=suite_id,
            task_format=str(by_format[api_format][0].get("task_format") or _suite_task_format(suite_id)),
        )
        for api_format in AXIO_BENCHMARK_API_FORMATS
        if api_format in by_format
        and by_format[api_format]
        and _run_has_benchmark_reasoning_receipt(by_format[api_format][0])
    }
    reasoning_hashes = sorted(
        {
            str(receipt.get("reasoning_config_sha256") or "")
            for receipt in reasoning_receipts.values()
            if str(receipt.get("reasoning_config_sha256") or "")
        }
    )
    reasoning_requested_values = sorted(
        {
            str(receipt.get("requested_reasoning_effort") or "")
            for receipt in reasoning_receipts.values()
            if str(receipt.get("requested_reasoning_effort") or "")
        }
    )
    scores = [_run_primary_score(run) for run in selected_runs]
    scored = [float(score) for score in scores if score is not None]
    score_delta = None if not scored else round(max(scored) - min(scored), 6)
    transport_receipts = {
        api_format: _api_surface_run_transport_receipt(
            by_format[api_format][0],
            expected_api_format=api_format,
        )
        for api_format in AXIO_BENCHMARK_API_FORMATS
        if api_format in by_format and by_format[api_format]
    }
    transport_reason_codes = sorted(
        {
            str(reason)
            for receipt in transport_receipts.values()
            if isinstance(receipt, Mapping)
            for reason in (receipt.get("reason_codes") if isinstance(receipt.get("reason_codes"), list) else [])
            if str(reason)
        }
    )
    transport_counts = {
        "missing_public_api_invocation_case_count": sum(
            _optional_int(receipt.get("missing_public_api_invocation_case_count")) or 0
            for receipt in transport_receipts.values()
        ),
        "public_api_surface_not_used_case_count": sum(
            _optional_int(receipt.get("public_api_surface_not_used_case_count")) or 0
            for receipt in transport_receipts.values()
        ),
        "api_format_mismatch_case_count": sum(
            _optional_int(receipt.get("api_format_mismatch_case_count")) or 0
            for receipt in transport_receipts.values()
        ),
        "http_gateway_case_count": sum(
            _optional_int(receipt.get("http_gateway_case_count")) or 0
            for receipt in transport_receipts.values()
        ),
        "non_http_gateway_case_count": sum(
            _optional_int(receipt.get("non_http_gateway_case_count")) or 0
            for receipt in transport_receipts.values()
        ),
        "network_call_case_count": sum(
            _optional_int(receipt.get("network_call_case_count")) or 0
            for receipt in transport_receipts.values()
        ),
        "network_not_performed_case_count": sum(
            _optional_int(receipt.get("network_not_performed_case_count")) or 0
            for receipt in transport_receipts.values()
        ),
        "unsafe_invocation_case_count": sum(
            _optional_int(receipt.get("unsafe_invocation_case_count")) or 0
            for receipt in transport_receipts.values()
        ),
    }
    all_case_invocations_use_http_gateway = (
        not missing_formats
        and len(transport_receipts) == len(AXIO_BENCHMARK_API_FORMATS)
        and all(
            receipt.get("all_case_invocations_use_http_gateway") is True
            for receipt in transport_receipts.values()
        )
    )
    reasons = []
    if missing_formats:
        reasons.append("missing_required_api_surface_runs")
    if duplicate_formats:
        reasons.append("duplicate_api_surface_runs")
    if selected_runs and not case_hash_sets_identical:
        reasons.append("api_surface_case_hash_sets_misaligned")
    if len(prompt_hashes) != 1 or len(prompt_hashes) != len({str(run.get("prompt_protocol_sha256") or "") for run in selected_runs}):
        reasons.append("api_surface_prompt_protocol_misaligned")
    if len(decoding_hashes) != 1 or len(decoding_hashes) != len({str(run.get("decoding_config_sha256") or "") for run in selected_runs}):
        reasons.append("api_surface_decoding_config_misaligned")
    if reasoning_receipts and (
        len(reasoning_receipts) != len(AXIO_BENCHMARK_API_FORMATS)
        or len(reasoning_hashes) != 1
        or len(reasoning_requested_values) != 1
    ):
        reasons.append("api_surface_reasoning_config_misaligned")
    if len(scored) != len(selected_runs):
        reasons.append("api_surface_scores_missing")
    elif score_delta is not None and score_delta > float(score_tolerance):
        reasons.append("api_surface_score_delta_above_tolerance")
    if require_http_gateway:
        reasons.extend(transport_reason_codes)
    return {
        "suite_id": suite_id,
        "category": category,
        "axio_model": model,
        "required_api_formats": list(AXIO_BENCHMARK_API_FORMATS),
        "present_api_formats": sorted(api_format for api_format in by_format if api_format in AXIO_BENCHMARK_API_FORMATS),
        "missing_api_formats": missing_formats,
        "duplicate_api_formats": duplicate_formats,
        "run_count": len(selected_runs),
        "case_hash_sets_identical": case_hash_sets_identical,
        "reference_case_hash_count": len(case_reference),
        "prompt_protocol_hashes_identical": len(prompt_hashes) == 1 and bool(selected_runs),
        "decoding_config_hashes_identical": len(decoding_hashes) == 1 and bool(selected_runs),
        "reasoning_config_hashes_identical": bool(reasoning_receipts)
        and len(reasoning_receipts) == len(AXIO_BENCHMARK_API_FORMATS)
        and len(reasoning_hashes) == 1,
        "reasoning_requested_efforts_identical": bool(reasoning_receipts)
        and len(reasoning_receipts) == len(AXIO_BENCHMARK_API_FORMATS)
        and len(reasoning_requested_values) == 1,
        "reasoning_by_api_format": reasoning_receipts,
        "primary_scores_by_api_format": {
            api_format: _run_primary_score(by_format[api_format][0])
            for api_format in AXIO_BENCHMARK_API_FORMATS
            if api_format in by_format and by_format[api_format]
        },
        "max_primary_score_delta": score_delta,
        "score_tolerance": float(score_tolerance),
        "http_gateway_required": bool(require_http_gateway),
        "transport_by_api_format": transport_receipts,
        **transport_counts,
        "all_case_invocations_use_http_gateway": all_case_invocations_use_http_gateway,
        "ready": not reasons,
        "reason_codes": sorted(set(reasons)),
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def build_benchmark_scorecard(
    runs: Sequence[Mapping[str, Any]],
    *,
    provider_baseline_freeze: Mapping[str, Any] | None = None,
    provider_baseline_freeze_path: str | Path | None = None,
    require_http_gateway: bool = False,
) -> dict[str, Any]:
    if provider_baseline_freeze_path is not None:
        artifact = _load_json_artifact(Path(provider_baseline_freeze_path))
        provider_baseline_freeze = (
            artifact.get("payload")
            if isinstance(artifact.get("payload"), Mapping)
            else {}
        )
    normalized_runs = [_normalize_safe_run_candidate_alias(run) for run in runs if isinstance(run, Mapping)]
    pre_registered_baselines = _claim_pre_registered_provider_rank_map(provider_baseline_freeze)
    use_pre_registered_baselines = provider_baseline_freeze is not None
    run_set_receipt = _benchmark_run_set_receipt(normalized_runs)
    scoring_runs = _primary_claim_scoring_runs(normalized_runs)
    api_surface_summary = build_benchmark_api_surface_audit(
        normalized_runs,
        require_http_gateway=bool(require_http_gateway),
    )
    by_candidate: dict[str, list[Mapping[str, Any]]] = {}
    for run in scoring_runs:
        by_candidate.setdefault(str(run.get("candidate_id") or ""), []).append(run)
    candidates = []
    for candidate_id, rows in by_candidate.items():
        total_cases = sum(int(row.get("case_count") or 0) for row in rows)
        total_correct = sum(int(row.get("correct_count") or 0) for row in rows)
        attempted = sum(int(row.get("attempted_count") or 0) for row in rows)
        latency = sum(float(row.get("latency_ms") or 0.0) for row in rows)
        estimated_cost = sum(_optional_float(row.get("estimated_cost_usd")) or 0.0 for row in rows)
        pricing_known_cases = sum(_optional_int(row.get("pricing_known_case_count")) or 0 for row in rows)
        provider_call_count = sum(_optional_int(row.get("provider_call_count")) or 0 for row in rows)
        case_latencies = [latency for run in rows for latency in _run_case_latencies(run)]
        accuracy = None if total_cases <= 0 else round(total_correct / total_cases, 6)
        primary_numerator = 0.0
        primary_denominator = 0
        for run in rows:
            primary_score = _run_primary_score(run)
            case_count = _optional_int(run.get("case_count")) or 0
            if primary_score is None or case_count <= 0:
                continue
            primary_numerator += float(primary_score) * case_count
            primary_denominator += case_count
        mean_primary_score = None if primary_denominator <= 0 else round(primary_numerator / primary_denominator, 6)
        candidates.append(
            {
                "candidate_id": candidate_id,
                "run_count": len(rows),
                "case_count": total_cases,
                "attempted_count": attempted,
                "correct_count": total_correct,
                "accuracy": accuracy,
                "total_latency_ms": round(latency, 3),
                "average_latency_ms": _average_float(case_latencies),
                "p50_latency_ms": _percentile_float(case_latencies, 0.50),
                "p95_latency_ms": _percentile_float(case_latencies, 0.95),
                "total_estimated_cost_usd": round(max(0.0, estimated_cost), 8),
                "cost_per_case_usd": None if total_cases <= 0 else round(max(0.0, estimated_cost) / total_cases, 8),
                "mean_primary_score": mean_primary_score,
                "accuracy_per_dollar": _score_per_dollar(accuracy, estimated_cost),
                "primary_score_per_dollar": _score_per_dollar(mean_primary_score, estimated_cost),
                "pricing_known_case_count": pricing_known_cases,
                "pricing_unknown_case_count": max(0, total_cases - pricing_known_cases),
                "provider_call_count": provider_call_count,
            }
        )
    candidates.sort(
        key=lambda row: (
            row["accuracy"] if row["accuracy"] is not None else -1.0,
            -row["total_latency_ms"],
        ),
        reverse=True,
    )
    by_id = {row["candidate_id"]: row for row in candidates}
    suite_observed_best_provider = _best_of(
        row for row in candidates if str(row["candidate_id"]).startswith("provider::")
    )
    frozen_rank_one_provider = None
    if use_pre_registered_baselines:
        rank_one_candidate_hash = str(
            pre_registered_baselines.get("rank_to_candidate_id_sha256", {}).get(1) or ""
        )
        frozen_rank_one_provider = next(
            (
                row
                for row in candidates
                if sha256_text(str(row.get("candidate_id") or "")) == rank_one_candidate_hash
            ),
            None,
        )
    comparison_provider = (
        frozen_rank_one_provider if use_pre_registered_baselines else suite_observed_best_provider
    )
    axio_rows = [row for row in candidates if str(row["candidate_id"]).startswith("axio-")]
    per_suite = _scorecard_per_suite(
        scoring_runs,
        pre_registered_provider_rank_map=(
            pre_registered_baselines.get("rank_to_candidate_id_sha256", {})
            if use_pre_registered_baselines
            else {}
        ),
        baseline_pre_registered=use_pre_registered_baselines,
    )
    tier_target_summary = _scorecard_tier_target_summary(per_suite)
    return {
        "schema": "axio_fusion_api.benchmark_scorecard.v1",
        "run_count": len(normalized_runs),
        "scoring_run_count": len(scoring_runs),
        "source_run_set_digest_sha256": run_set_receipt["run_set_digest_sha256"],
        "source_run_set_receipt": run_set_receipt,
        "candidate_count": len(candidates),
        "candidates": candidates,
        "per_suite": per_suite,
        "api_surface_summary": api_surface_summary,
        "provider_tier_contract": {
            "strongest_provider": (
                "externally pre-registered configured-provider-pool rank 1 provider baseline"
                if use_pre_registered_baselines
                else "legacy rank 1 provider baseline by the suite primary metric"
            ),
            "second_strongest_provider": (
                "externally pre-registered configured-provider-pool rank 2 provider baseline"
                if use_pre_registered_baselines
                else "legacy rank 2 provider baseline by the suite primary metric"
            ),
            "third_strongest_provider": (
                "externally pre-registered configured-provider-pool rank 3 provider baseline"
                if use_pre_registered_baselines
                else "legacy rank 3 provider baseline by the suite primary metric"
            ),
            "axio-pro": "must beat strongest_provider on every required suite",
            "axio-terra": "must beat second_strongest_provider on every required suite",
            "axio-fast": "must beat third_strongest_provider on every required suite",
            "ranking_source": (
                EXTERNAL_PROVIDER_RANKING_RANK_SOURCE
                if use_pre_registered_baselines
                else "legacy_same_suite_primary_metric"
            ),
            "ranking_tie_breakers": (
                ["pre_registered_external_tie_break_policy"]
                if use_pre_registered_baselines
                else ["correct_count", "lower_latency_ms", "candidate_id"]
            ),
            "raw_provider_outputs_persisted": False,
        },
        "leader": candidates[0] if candidates else {},
        "comparison": {
            "best_provider_baseline": comparison_provider,
            "best_provider_baseline_source": (
                EXTERNAL_PROVIDER_RANKING_RANK_SOURCE
                if use_pre_registered_baselines
                else "legacy_same_suite_primary_metric"
            ),
            "suite_observed_best_provider_diagnostic": suite_observed_best_provider,
            "suite_observed_best_provider_is_diagnostic_only": bool(use_pre_registered_baselines),
            "axio_candidates": axio_rows,
            "axio_pro_beats_best_provider": _beats(by_id.get("axio-pro"), comparison_provider),
            "axio_terra_beats_best_provider": _beats(by_id.get("axio-terra"), comparison_provider),
            "tier_target_summary": tier_target_summary,
            "superiority_claim_allowed": bool(
                _beats(by_id.get("axio-pro"), comparison_provider)
                and by_id.get("axio-pro", {}).get("case_count", 0) >= 20
            ),
            "requires_more_cases_before_marketing_claim": True,
        },
        "provider_baseline_freeze_binding": pre_registered_baselines,
        "raw_prompt_persisted": False,
        "raw_label_persisted": False,
        "secrets_persisted": False,
    }


_AXIO_TIER_TARGETS: tuple[tuple[str, str, int], ...] = (
    ("axio-pro", "strongest_provider", 0),
    ("axio-terra", "second_strongest_provider", 1),
    ("axio-fast", "third_strongest_provider", 2),
)


def _scorecard_per_suite(
    runs: Sequence[Mapping[str, Any]],
    *,
    pre_registered_provider_rank_map: Mapping[int, str] | None = None,
    baseline_pre_registered: bool = False,
) -> list[dict[str, Any]]:
    by_suite: dict[str, list[Mapping[str, Any]]] = {}
    for run in runs:
        suite_id = str(run.get("suite_id") or "")
        if suite_id:
            by_suite.setdefault(suite_id, []).append(run)
    ordered_suite_ids = [suite.suite_id for suite in BENCHMARK_SUITES if suite.suite_id in by_suite]
    ordered_suite_ids.extend(sorted(suite_id for suite_id in by_suite if suite_id not in ordered_suite_ids))
    rows = []
    for suite_id in ordered_suite_ids:
        suite = _suite_by_id(suite_id)
        suite_runs = by_suite.get(suite_id, [])
        candidates = sorted(
            [_scorecard_run_receipt(run) for run in suite_runs],
            key=_scorecard_candidate_sort_key,
            reverse=True,
        )
        provider_runs = _rank_provider_runs(suite_runs)
        provider_runs_by_hash = {
            sha256_text(str(run.get("candidate_id") or "")): run
            for run in provider_runs
        }
        if baseline_pre_registered:
            ranked_provider_runs = [
                provider_runs_by_hash.get(str((pre_registered_provider_rank_map or {}).get(rank) or ""))
                for rank in EXTERNAL_PROVIDER_RANKING_REQUIRED_RANKS
            ]
        else:
            ranked_provider_runs = provider_runs[:3]
        provider_tiers = [
            _scorecard_provider_tier_receipt(run, rank=index + 1, tier=tier)
            for index, (tier, run) in enumerate(
                zip(
                    ("strongest_provider", "second_strongest_provider", "third_strongest_provider"),
                    ranked_provider_runs,
                )
            )
            if isinstance(run, Mapping)
        ]
        run_by_candidate = {str(run.get("candidate_id") or ""): run for run in suite_runs}
        rows.append(
            {
                "suite_id": suite_id,
                "category": suite.category if suite else "",
                "task_format": str(suite.task_format if suite else (suite_runs[0].get("task_format") if suite_runs else "")),
                "primary_metric": _scorecard_primary_metric(suite_runs[0]) if suite_runs else _primary_metric_for_format(_suite_task_format(suite_id)),
                "run_count": len(suite_runs),
                "candidate_count": len(candidates),
                "provider_baseline_count": len(provider_runs),
                "provider_baseline_tiers": provider_tiers,
                "provider_baseline_pre_registered": bool(baseline_pre_registered),
                "candidates": candidates,
                "axio_target_comparisons": [
                    _scorecard_axio_target_receipt(
                        suite_id=suite_id,
                        axio_model=axio_model,
                        target_tier=target_tier,
                        axio_run=run_by_candidate.get(axio_model),
                        baseline_run=(
                            ranked_provider_runs[baseline_index]
                            if len(ranked_provider_runs) > baseline_index
                            else None
                        ),
                    )
                    for axio_model, target_tier, baseline_index in _AXIO_TIER_TARGETS
                ],
                "raw_prompt_persisted": False,
                "raw_labels_persisted": False,
                "raw_provider_outputs_persisted": False,
                "secrets_persisted": False,
            }
        )
    return rows


def _scorecard_tier_target_summary(per_suite: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    summary = {}
    required_suite_count = len(BENCHMARK_SUITES)
    required_suite_ids = {suite.suite_id for suite in BENCHMARK_SUITES}
    for axio_model, target_tier, _ in _AXIO_TIER_TARGETS:
        rows = []
        for suite_row in per_suite:
            comparisons = suite_row.get("axio_target_comparisons") if isinstance(suite_row.get("axio_target_comparisons"), list) else []
            rows.extend(
                row
                for row in comparisons
                if isinstance(row, Mapping) and str(row.get("axio_model") or "") == axio_model
            )
        required_rows = [
            row
            for row in rows
            if str(row.get("suite_id") or "") in required_suite_ids
        ]
        required_by_suite = {
            str(row.get("suite_id") or ""): row
            for row in required_rows
        }
        missing_required_suite_ids = sorted(required_suite_ids.difference(required_by_suite))
        scored = [
            row
            for row in required_rows
            if row.get("axio_primary_score") is not None and row.get("baseline_primary_score") is not None
        ]
        missing = [
            {
                "suite_id": str(row.get("suite_id") or ""),
                "reason_codes": list(row.get("reason_codes") or []),
            }
            for row in required_rows
            if row.get("beats_target") is not True
        ]
        missing.extend(
            {
                "suite_id": suite_id,
                "reason_codes": ["missing_required_suite_comparison"],
            }
            for suite_id in missing_required_suite_ids[:24]
        )
        passed_required_suite_count = sum(1 for row in required_rows if row.get("beats_target") is True)
        all_required_suites_present = len(required_by_suite) == required_suite_count
        summary[axio_model] = {
            "target_tier": target_tier,
            "required_suite_count": required_suite_count,
            "suite_comparison_count": len(rows),
            "required_suite_comparison_count": len(required_by_suite),
            "scored_suite_count": len(scored),
            "passed_suite_count": passed_required_suite_count,
            "all_required_suites_present": all_required_suites_present,
            "all_required_suites_passed": all_required_suites_present
            and passed_required_suite_count == required_suite_count,
            "all_scored_suites_passed": bool(scored) and all(row.get("beats_target") is True for row in scored),
            "missing_required_suite_count": len(missing_required_suite_ids),
            "failed_or_missing_suites": missing[:24],
            "raw_provider_outputs_persisted": False,
        }
    return summary


def build_benchmark_fusion_failure_analysis(
    *,
    scorecard: Mapping[str, Any] | None = None,
    claim_audit: Mapping[str, Any] | None = None,
    readiness: Mapping[str, Any] | None = None,
    trace_report: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a safe, shadow-only optimization plan from benchmark evidence."""

    scorecard_map = scorecard if isinstance(scorecard, Mapping) else {}
    claim_audit_map = claim_audit if isinstance(claim_audit, Mapping) else {}
    readiness_map = readiness if isinstance(readiness, Mapping) else {}
    trace_report_map = trace_report if isinstance(trace_report, Mapping) else {}

    claim_rows = _fusion_claim_comparison_rows(claim_audit_map)
    scorecard_rows = _fusion_scorecard_target_rows(scorecard_map)
    comparison_rows = claim_rows if claim_rows else scorecard_rows
    api_surface_failures = _fusion_api_surface_failure_rows(scorecard_map)
    readiness_reason_counts = _fusion_readiness_blocking_counts(readiness_map)
    trace_summary = _fusion_trace_summary(trace_report_map)
    model_summaries = [
        _fusion_model_failure_summary(model, comparison_rows, api_surface_failures)
        for model in AXIO_BENCHMARK_PUBLIC_MODELS
    ]
    reason_counts = _fusion_all_reason_counts(
        comparison_rows=comparison_rows,
        api_surface_failures=api_surface_failures,
        readiness_reason_counts=readiness_reason_counts,
    )
    recommendations = _fusion_failure_recommendations(
        reason_counts=reason_counts,
        model_summaries=model_summaries,
        readiness_reason_counts=readiness_reason_counts,
        trace_summary=trace_summary,
    )
    status = _fusion_failure_status(
        scorecard=scorecard_map,
        claim_audit=claim_audit_map,
        comparison_rows=comparison_rows,
        api_surface_failures=api_surface_failures,
        readiness_reason_counts=readiness_reason_counts,
    )
    failed_rows = [
        row
        for row in comparison_rows
        if row.get("passed") is not True
    ]
    return {
        "schema": "axio_fusion_api.benchmark_fusion_failure_analysis.v1",
        "status": status,
        "analysis_scope": {
            "benchmark_suite_count": len(BENCHMARK_SUITES),
            "benchmark_category_count": len(BENCHMARK_CATEGORY_REQUIRED_SUITE_COUNTS),
            "public_axio_models": list(AXIO_BENCHMARK_PUBLIC_MODELS),
            "required_api_formats": list(AXIO_BENCHMARK_API_FORMATS),
            "latency_gate_max_multiplier": CLAIM_LATENCY_MAX_MULTIPLIER,
        },
        "input_artifact_receipts": {
            "scorecard": _fusion_input_artifact_receipt("scorecard", scorecard_map),
            "claim_audit": _fusion_input_artifact_receipt("claim_audit", claim_audit_map),
            "readiness": _fusion_input_artifact_receipt("readiness", readiness_map),
            "trace_report": _fusion_input_artifact_receipt("trace_report", trace_report_map),
        },
        "claim_status": {
            "claim_audit_present": bool(claim_audit_map),
            "all_final_claims_allowed": claim_audit_map.get("all_final_claims_allowed") is True,
            "all_required_suites_present": claim_audit_map.get("all_required_suites_present") is True,
            "comparison_count": len(comparison_rows),
            "failed_comparison_count": len(failed_rows),
            "api_surface_failure_count": len(api_surface_failures),
            "readiness_blocker_count": sum(readiness_reason_counts.values()),
            "reason_counts": reason_counts,
        },
        "model_failure_summaries": model_summaries,
        "failed_comparison_rows": failed_rows[:96],
        "api_surface_failures": api_surface_failures[:96],
        "trace_summary": trace_summary,
        "recommendations": recommendations,
        "ablation_plan": _fusion_ablation_plan(recommendations, model_summaries, trace_summary),
        "success_criteria": _fusion_success_criteria(),
        "no_cheat_contract": {
            "shadow_only": True,
            "automatic_policy_application_allowed": False,
            "do_not_train_or_tune_on_benchmark_labels": True,
            "future_claim_requires_fresh_campaign_replay": True,
            "paired_case_hashes_and_official_harness_receipts_required": True,
            "multiple_comparison_correction_required": True,
            "latency_gate_required_for_claims": True,
            "latency_gate_requires_p50_and_p95": True,
            "latency_gate_max_multiplier": CLAIM_LATENCY_MAX_MULTIPLIER,
        },
        "anti_leakage_contract": {
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "raw_provider_urls_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "secrets_persisted": False,
        },
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_provider_urls_persisted": False,
        "secrets_persisted": False,
    }


def _fusion_input_artifact_receipt(name: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    if not isinstance(payload, Mapping) or not payload:
        return {
            "artifact": str(name),
            "present": False,
            "schema": "",
            "artifact_sha256": "",
            "raw_payload_persisted": False,
        }
    return {
        "artifact": str(name),
        "present": True,
        "schema": str(payload.get("schema") or ""),
        "artifact_sha256": sha256_text(stable_json(payload)),
        "raw_payload_persisted": False,
    }


def _fusion_claim_comparison_rows(claim_audit: Mapping[str, Any]) -> list[dict[str, Any]]:
    rows = claim_audit.get("comparisons") if isinstance(claim_audit.get("comparisons"), list) else []
    return [
        _fusion_safe_comparison_row(row, source="claim_audit")
        for row in rows
        if isinstance(row, Mapping)
    ]


def _fusion_scorecard_target_rows(scorecard: Mapping[str, Any]) -> list[dict[str, Any]]:
    result = []
    suites = scorecard.get("per_suite") if isinstance(scorecard.get("per_suite"), list) else []
    for suite in suites:
        if not isinstance(suite, Mapping):
            continue
        comparisons = suite.get("axio_target_comparisons") if isinstance(suite.get("axio_target_comparisons"), list) else []
        for row in comparisons:
            if isinstance(row, Mapping):
                merged = dict(row)
                merged.setdefault("suite_id", str(suite.get("suite_id") or ""))
                merged.setdefault("category", str(suite.get("category") or ""))
                result.append(_fusion_safe_comparison_row(merged, source="scorecard"))
    return result


def _fusion_safe_comparison_row(row: Mapping[str, Any], *, source: str) -> dict[str, Any]:
    reason_codes = sorted({str(reason) for reason in row.get("reason_codes") or [] if str(reason)})
    if source == "claim_audit":
        passed = row.get("claim_allowed") is True
    else:
        passed = row.get("beats_target") is True
    baseline_id = str(row.get("baseline_candidate_id") or "")
    paired = row.get("paired_case_stats") if isinstance(row.get("paired_case_stats"), Mapping) else {}
    correction = row.get("multiple_comparison_correction") if isinstance(row.get("multiple_comparison_correction"), Mapping) else {}
    return {
        "source": source,
        "suite_id": str(row.get("suite_id") or ""),
        "category": str(row.get("category") or ""),
        "axio_model": str(row.get("axio_model") or ""),
        "baseline_tier": str(row.get("baseline_tier") or row.get("target_tier") or ""),
        "baseline_candidate_id_sha256": sha256_text(baseline_id) if baseline_id else "",
        "provider_baseline_count": _optional_int(row.get("provider_baseline_count")) or 0,
        "axio_primary_score": _optional_float(row.get("axio_primary_score")),
        "baseline_primary_score": _optional_float(row.get("baseline_primary_score")),
        "primary_score_delta": _optional_float(row.get("primary_score_delta")),
        "latency_multiplier_vs_baseline": _optional_float(row.get("latency_multiplier_vs_baseline")),
        "latency_within_3x_baseline": row.get("latency_within_3x_baseline") is True,
        "paired_common_case_count": _optional_int(paired.get("common_case_count")) or 0,
        "paired_axio_unique_correct_count": _optional_int(paired.get("axio_unique_correct_count")) or 0,
        "paired_baseline_unique_correct_count": _optional_int(paired.get("baseline_unique_correct_count")) or 0,
        "p_value_one_sided": _optional_float(paired.get("p_value_one_sided")),
        "multiple_comparison_passed": row.get("multiple_comparison_passed") is True
        or correction.get("passed") is True,
        "passed": passed,
        "reason_codes": reason_codes,
        "raw_questions_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "raw_provider_model_ids_persisted": False,
    }


def _fusion_api_surface_failure_rows(scorecard: Mapping[str, Any]) -> list[dict[str, Any]]:
    api_summary = scorecard.get("api_surface_summary") if isinstance(scorecard.get("api_surface_summary"), Mapping) else {}
    rows = api_summary.get("suite_model_rows") if isinstance(api_summary.get("suite_model_rows"), list) else []
    failures = []
    for row in rows:
        if not isinstance(row, Mapping) or row.get("ready") is True:
            continue
        failures.append(
            {
                "suite_id": str(row.get("suite_id") or ""),
                "category": str(row.get("category") or ""),
                "axio_model": str(row.get("axio_model") or ""),
                "present_api_formats": [str(item) for item in row.get("present_api_formats") or [] if str(item)],
                "missing_api_formats": [str(item) for item in row.get("missing_api_formats") or [] if str(item)],
                "duplicate_api_formats": [str(item) for item in row.get("duplicate_api_formats") or [] if str(item)],
                "max_primary_score_delta": _optional_float(row.get("max_primary_score_delta")),
                "reason_codes": sorted({str(reason) for reason in row.get("reason_codes") or [] if str(reason)}),
                "raw_prompts_persisted": False,
                "raw_labels_persisted": False,
                "raw_provider_outputs_persisted": False,
            }
        )
    return failures


def _fusion_model_failure_summary(
    model: str,
    comparison_rows: Sequence[Mapping[str, Any]],
    api_surface_failures: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    model_rows = [row for row in comparison_rows if str(row.get("axio_model") or "") == model]
    failed_rows = [row for row in model_rows if row.get("passed") is not True]
    model_api_failures = [row for row in api_surface_failures if str(row.get("axio_model") or "") == model]
    reason_counts = _count_reason_codes([*failed_rows, *model_api_failures])
    deltas = [_optional_float(row.get("primary_score_delta")) for row in failed_rows]
    clean_deltas = [float(value) for value in deltas if value is not None]
    latency_multipliers = [
        float(value)
        for value in (_optional_float(row.get("latency_multiplier_vs_baseline")) for row in failed_rows)
        if value is not None
    ]
    failed_categories = sorted({str(row.get("category") or "") for row in failed_rows if str(row.get("category") or "")})
    return {
        "axio_model": model,
        "suite_comparison_count": len(model_rows),
        "failed_suite_comparison_count": len(failed_rows),
        "api_surface_failure_count": len(model_api_failures),
        "failure_reason_counts": reason_counts,
        "score_failure_count": _fusion_reason_total(reason_counts, FUSION_FAILURE_SCORE_REASONS),
        "latency_failure_count": _fusion_reason_total(reason_counts, FUSION_FAILURE_LATENCY_REASONS),
        "evidence_gap_count": _fusion_reason_total(reason_counts, FUSION_FAILURE_EVIDENCE_REASONS),
        "api_surface_issue_count": _fusion_reason_total(reason_counts, FUSION_FAILURE_API_SURFACE_REASONS),
        "worst_primary_score_delta": None if not clean_deltas else round(min(clean_deltas), 6),
        "max_latency_multiplier_vs_baseline": None if not latency_multipliers else round(max(latency_multipliers), 6),
        "failed_categories": failed_categories,
        "failed_or_unproven_suites": [
            {
                "suite_id": str(row.get("suite_id") or ""),
                "category": str(row.get("category") or ""),
                "reason_codes": list(row.get("reason_codes") or []),
                "primary_score_delta": row.get("primary_score_delta"),
                "latency_multiplier_vs_baseline": row.get("latency_multiplier_vs_baseline"),
            }
            for row in failed_rows[:24]
        ],
        "recommended_focus": _fusion_recommended_focus(reason_counts),
        "raw_provider_outputs_persisted": False,
    }


def _fusion_recommended_focus(reason_counts: Mapping[str, int]) -> str:
    if _fusion_reason_total(reason_counts, FUSION_FAILURE_EVIDENCE_REASONS) > 0:
        return "evidence_completion_before_algorithm_claims"
    if _fusion_reason_total(reason_counts, FUSION_FAILURE_API_SURFACE_REASONS) > 0:
        return "api_surface_equivalence_repair"
    if _fusion_reason_total(reason_counts, FUSION_FAILURE_LATENCY_REASONS) > 0:
        return "latency_guarded_adaptive_panel"
    if _fusion_reason_total(reason_counts, FUSION_FAILURE_SCORE_REASONS) > 0:
        return "score_diversity_judge_escalation"
    return "maintain_and_replay"


def _fusion_all_reason_counts(
    *,
    comparison_rows: Sequence[Mapping[str, Any]],
    api_surface_failures: Sequence[Mapping[str, Any]],
    readiness_reason_counts: Mapping[str, int],
) -> dict[str, int]:
    failed_rows = [row for row in comparison_rows if row.get("passed") is not True]
    counts = _count_reason_codes([*failed_rows, *api_surface_failures])
    for reason, count in readiness_reason_counts.items():
        key = str(reason or "")
        if key:
            counts[key] = counts.get(key, 0) + int(count or 0)
    return dict(sorted(counts.items()))


def _fusion_readiness_blocking_counts(readiness: Mapping[str, Any]) -> dict[str, int]:
    if not isinstance(readiness, Mapping) or not readiness:
        return {}
    counts: dict[str, int] = {}

    def add(reason: Any, count: int = 1) -> None:
        key = str(reason or "")
        if key:
            counts[key] = counts.get(key, 0) + max(1, int(count or 1))

    for field in ("next_blockers", "final_claim_blocking_reasons", "reason_codes"):
        values = readiness.get(field)
        if isinstance(values, list):
            for reason in values:
                add(reason)
    for field in ("blocking_reason_counts", "final_audit_blocking_kind_counts"):
        mapping = readiness.get(field)
        if isinstance(mapping, Mapping):
            for reason, count in mapping.items():
                add(reason, _optional_int(count) or 1)
    for nested_field in (
        "benchmark_artifact_readiness",
        "live_registry_readiness",
        "provider_env_readiness",
        "readiness_snapshot",
    ):
        nested = readiness.get(nested_field)
        if not isinstance(nested, Mapping):
            continue
        nested_counts = nested.get("blocking_reason_counts")
        if isinstance(nested_counts, Mapping):
            for reason, count in nested_counts.items():
                add(reason, _optional_int(count) or 1)
        for field in ("blockers", "next_blockers", "final_claim_blocking_reasons"):
            values = nested.get(field)
            if isinstance(values, list):
                for reason in values:
                    add(reason)
    for row in _evidence_readiness_missing(readiness):
        for reason in row.get("reason_codes") or []:
            add(reason)
    if readiness.get("status") == "blocked" and not counts:
        add("readiness_blocked_without_reason")
    return dict(sorted(counts.items()))


def _fusion_trace_summary(trace_report: Mapping[str, Any]) -> dict[str, Any]:
    if not isinstance(trace_report, Mapping) or not trace_report:
        return {
            "present": False,
            "trace_count": 0,
            "average_latency_ms": None,
            "average_provider_call_count": None,
            "average_cost_usd": None,
            "by_strategy": {},
            "by_public_model": {},
            "provider_routing_summary": _fusion_trace_provider_routing_summary({}),
            "raw_prompt_persisted": False,
            "raw_provider_output_persisted": False,
        }
    provider_routing = trace_report.get("provider_routing_summary") if isinstance(trace_report.get("provider_routing_summary"), Mapping) else {}
    return {
        "present": True,
        "schema": str(trace_report.get("schema") or ""),
        "trace_count": _optional_int(trace_report.get("trace_count")) or 0,
        "average_latency_ms": _optional_float(trace_report.get("average_latency_ms")),
        "average_provider_call_count": _optional_float(trace_report.get("average_provider_call_count")),
        "average_cost_usd": _optional_float(trace_report.get("average_cost_usd")),
        "by_strategy": dict(trace_report.get("by_strategy")) if isinstance(trace_report.get("by_strategy"), Mapping) else {},
        "by_public_model": dict(trace_report.get("by_public_model")) if isinstance(trace_report.get("by_public_model"), Mapping) else {},
        "provider_routing_summary": _fusion_trace_provider_routing_summary(provider_routing),
        "raw_prompt_persisted": False,
        "raw_provider_output_persisted": False,
    }


def _fusion_trace_provider_routing_summary(value: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "schema": str(value.get("schema") or "axio_fusion_api.trace_provider_routing_summary.v1"),
        "policy_count": _optional_int(value.get("policy_count")) or 0,
        "fallback_enabled_rate": _optional_float(value.get("fallback_enabled_rate")),
        "average_fallback_pool_count": _optional_float(value.get("average_fallback_pool_count")),
        "average_top_routing_score": _optional_float(value.get("average_top_routing_score")),
        "average_top_availability_score": _optional_float(value.get("average_top_availability_score")),
        "average_top_latency_score": _optional_float(value.get("average_top_latency_score")),
        "average_top_cost_score": _optional_float(value.get("average_top_cost_score")),
        "average_selected_panel_count": _optional_float(value.get("average_selected_panel_count")),
        "average_nonpanel_count": _optional_float(value.get("average_nonpanel_count")),
        "average_api_format_count": _optional_float(value.get("average_api_format_count")),
        "average_provider_hash_count": _optional_float(value.get("average_provider_hash_count")),
        "nonpanel_available_rate": _optional_float(value.get("nonpanel_available_rate")),
        "low_top_availability_rate": _optional_float(value.get("low_top_availability_rate")),
        "low_top_routing_rate": _optional_float(value.get("low_top_routing_rate")),
        "raw_provider_names_persisted": False,
        "raw_model_names_persisted": False,
        "raw_provider_urls_persisted": False,
        "secrets_persisted": False,
    }


def _fusion_failure_status(
    *,
    scorecard: Mapping[str, Any],
    claim_audit: Mapping[str, Any],
    comparison_rows: Sequence[Mapping[str, Any]],
    api_surface_failures: Sequence[Mapping[str, Any]],
    readiness_reason_counts: Mapping[str, int],
) -> str:
    if not scorecard and not claim_audit and not readiness_reason_counts:
        return "insufficient_evidence"
    if readiness_reason_counts and not comparison_rows:
        return "evidence_incomplete"
    if claim_audit.get("all_final_claims_allowed") is True and not api_surface_failures and not readiness_reason_counts:
        return "passing"
    if any(row.get("passed") is not True for row in comparison_rows) or api_surface_failures:
        return "optimization_needed"
    if readiness_reason_counts:
        return "evidence_incomplete"
    return "needs_replay_confirmation"


def _fusion_failure_recommendations(
    *,
    reason_counts: Mapping[str, int],
    model_summaries: Sequence[Mapping[str, Any]],
    readiness_reason_counts: Mapping[str, int],
    trace_summary: Mapping[str, Any],
) -> list[dict[str, Any]]:
    recommendations = []
    evidence_count = _fusion_reason_total(reason_counts, FUSION_FAILURE_EVIDENCE_REASONS)
    api_count = _fusion_reason_total(reason_counts, FUSION_FAILURE_API_SURFACE_REASONS)
    latency_count = _fusion_reason_total(reason_counts, FUSION_FAILURE_LATENCY_REASONS)
    score_count = _fusion_reason_total(reason_counts, FUSION_FAILURE_SCORE_REASONS)
    fallback_issue_count = _fusion_provider_fallback_issue_count(trace_summary)
    provider_count = sum(
        int(readiness_reason_counts.get(reason, 0))
        for reason in ("provider_credentials_missing", "live_probe_registry_missing", "fewer_than_three_provider_baselines")
    )
    official_count = sum(
        int(readiness_reason_counts.get(reason, 0))
        for reason in (
            "official_harness_model_outputs_missing",
            "official_import_receipts_missing",
            "missing_official_harness_receipt",
        )
    )
    gated_count = int(readiness_reason_counts.get("gated_dataset_access_missing", 0))

    if evidence_count > 0 or provider_count > 0 or official_count > 0 or gated_count > 0:
        recommendations.append(
            _fusion_recommendation(
                recommendation_id="complete_evidence_before_algorithm_claims",
                priority="P0",
                trigger_count=evidence_count + provider_count + official_count + gated_count,
                target_models=list(AXIO_BENCHMARK_PUBLIC_MODELS),
                target_categories=list(BENCHMARK_CATEGORY_REQUIRED_SUITE_COUNTS),
                action_type="readiness_and_evidence",
                triggered_by=_fusion_matching_reasons(reason_counts, FUSION_FAILURE_EVIDENCE_REASONS),
                algorithm_changes=[
                    "run live provider discovery only from environment-supplied arbitrary provider configs",
                    "import official or audited harness outputs before final claims",
                    "obtain authorized gated dataset access instead of substituting labels",
                    "include all usable provider single-model baselines before ranking tiers",
                ],
                validation_gate="fusion-live-readiness and benchmark-final-audit must be clean before ability claims",
            )
        )
    if api_count > 0:
        recommendations.append(
            _fusion_recommendation(
                recommendation_id="repair_api_surface_equivalence",
                priority="P0",
                trigger_count=api_count,
                target_models=_fusion_models_with_family(model_summaries, FUSION_FAILURE_API_SURFACE_REASONS),
                target_categories=_fusion_categories_with_family(model_summaries, FUSION_FAILURE_API_SURFACE_REASONS),
                action_type="api_compatibility",
                triggered_by=_fusion_matching_reasons(reason_counts, FUSION_FAILURE_API_SURFACE_REASONS),
                algorithm_changes=[
                    "canonicalize one internal FusionRequest for chat, responses, anthropic, and gemini surfaces",
                    "bind the same prompt protocol, decoding config, and case-hash set across surfaces",
                    "treat non-primary surfaces as engineering equivalence gates, not separate intelligence claims",
                ],
                validation_gate="api surface audit must pass with score deltas within tolerance",
            )
        )
    if latency_count > 0:
        recommendations.append(
            _fusion_recommendation(
                recommendation_id="latency_guarded_adaptive_panel",
                priority="P0",
                trigger_count=latency_count,
                target_models=_fusion_models_with_family(model_summaries, FUSION_FAILURE_LATENCY_REASONS),
                target_categories=_fusion_categories_with_family(model_summaries, FUSION_FAILURE_LATENCY_REASONS),
                action_type="routing_and_orchestration",
                triggered_by=_fusion_matching_reasons(reason_counts, FUSION_FAILURE_LATENCY_REASONS),
                algorithm_changes=[
                    "lower max_models and max_depth for latency-failing tier/category cells",
                    "prefer parallel experts over serial refinement under the 3x latency gate",
                    "raise early-exit use when judge confidence is high and disagreement is low",
                    "run targeted escalation only for contested or missing subtasks",
                    "cap synthesis candidates with diversity-aware compression",
                ],
                validation_gate="p50 and p95 case latency must stay at or below 3x the matched baseline",
            )
        )
    if score_count > 0:
        recommendations.append(
            _fusion_recommendation(
                recommendation_id="score_diversity_judge_escalation",
                priority="P1",
                trigger_count=score_count,
                target_models=_fusion_models_with_family(model_summaries, FUSION_FAILURE_SCORE_REASONS),
                target_categories=_fusion_categories_with_family(model_summaries, FUSION_FAILURE_SCORE_REASONS),
                action_type="fusion_quality",
                triggered_by=_fusion_matching_reasons(reason_counts, FUSION_FAILURE_SCORE_REASONS),
                algorithm_changes=[
                    "increase provider and API-format diversity weight when panel correlation is high",
                    "promote domain specialist and critic roles for failed categories",
                    "use the quality-diversity archive to preserve minority evidence-backed candidates",
                    "strengthen judge prompts around contradiction, coverage, and benchmark output-format discipline",
                    "route math, code, and tool-call tasks through verifier or execution-aware roles when allowed",
                ],
                validation_gate="improvement must hold on paired case hashes after Holm-Bonferroni correction",
            )
        )
    if fallback_issue_count > 0 and (score_count > 0 or latency_count > 0 or provider_count > 0):
        fallback_target_models = sorted(
            set(
                _fusion_models_with_family(model_summaries, FUSION_FAILURE_SCORE_REASONS)
                + _fusion_models_with_family(model_summaries, FUSION_FAILURE_LATENCY_REASONS)
            )
        ) or list(AXIO_BENCHMARK_PUBLIC_MODELS)
        fallback_target_categories = sorted(
            set(
                _fusion_categories_with_family(model_summaries, FUSION_FAILURE_SCORE_REASONS)
                + _fusion_categories_with_family(model_summaries, FUSION_FAILURE_LATENCY_REASONS)
            )
        )
        recommendations.append(
            _fusion_recommendation(
                recommendation_id="provider_fallback_pool_refresh",
                priority="P1",
                trigger_count=fallback_issue_count,
                target_models=fallback_target_models,
                target_categories=fallback_target_categories,
                action_type="provider_routing",
                triggered_by=["weak_provider_fallback_pool_from_safe_trace_summary"],
                algorithm_changes=[
                    "refresh live probe registry before expensive benchmark replay",
                    "expand non-primary-panel fallback candidates across providers",
                    "prefer API-format diversity when fallback pool coverage is narrow",
                    "weight recent availability and circuit-breaker health ahead of raw capability priors",
                    "feed safe fallback receipts into router shadow replay before changing production defaults",
                ],
                validation_gate="fresh holdout traces must improve fallback availability without exceeding 3x latency",
            )
        )
    if trace_summary.get("present") is True and (_optional_float(trace_summary.get("average_provider_call_count")) or 0.0) > 3.0:
        recommendations.append(
            _fusion_recommendation(
                recommendation_id="trace_budget_calibration",
                priority="P2",
                trigger_count=1,
                target_models=list(AXIO_BENCHMARK_PUBLIC_MODELS),
                target_categories=[],
                action_type="runtime_budgeting",
                triggered_by=["high_average_provider_call_count"],
                algorithm_changes=[
                    "fit shadow budget ceilings from safe trace aggregates",
                    "audit skipped-call and early-exit receipts before changing production defaults",
                    "validate cost and latency changes on holdout traffic before benchmark replay",
                ],
                validation_gate="trace-derived knobs remain shadow-only until fresh non-benchmark validation passes",
            )
        )
    if not recommendations:
        recommendations.append(
            _fusion_recommendation(
                recommendation_id="maintain_frozen_policy_and_replay",
                priority="P3",
                trigger_count=0,
                target_models=list(AXIO_BENCHMARK_PUBLIC_MODELS),
                target_categories=[],
                action_type="confirmation",
                triggered_by=[],
                algorithm_changes=[
                    "keep routing and orchestration policy frozen",
                    "rerun deterministic final audit when new provider or benchmark evidence arrives",
                ],
                validation_gate="no policy change is needed without a failed claim, API surface, or readiness gate",
            )
        )
    return recommendations


def _fusion_provider_fallback_issue_count(trace_summary: Mapping[str, Any]) -> int:
    provider_routing = trace_summary.get("provider_routing_summary") if isinstance(trace_summary.get("provider_routing_summary"), Mapping) else {}
    if (_optional_int(provider_routing.get("policy_count")) or 0) <= 0:
        return 0
    checks = [
        (_optional_float(provider_routing.get("fallback_enabled_rate")), 1.0, "lt"),
        (_optional_float(provider_routing.get("average_top_availability_score")), 0.65, "lt"),
        (_optional_float(provider_routing.get("average_top_routing_score")), 0.5, "lt"),
        (_optional_float(provider_routing.get("low_top_availability_rate")), 0.3, "ge"),
        (_optional_float(provider_routing.get("low_top_routing_rate")), 0.3, "ge"),
        (_optional_float(provider_routing.get("average_nonpanel_count")), 1.0, "lt"),
        (_optional_float(provider_routing.get("average_api_format_count")), 2.0, "lt"),
    ]
    issue_count = 0
    for value, threshold, op in checks:
        if value is None:
            continue
        if op == "lt" and value < threshold:
            issue_count += 1
        elif op == "ge" and value >= threshold:
            issue_count += 1
    return issue_count


def _fusion_recommendation(
    *,
    recommendation_id: str,
    priority: str,
    trigger_count: int,
    target_models: Sequence[str],
    target_categories: Sequence[str],
    action_type: str,
    triggered_by: Sequence[str],
    algorithm_changes: Sequence[str],
    validation_gate: str,
) -> dict[str, Any]:
    return {
        "recommendation_id": recommendation_id,
        "priority": priority,
        "trigger_count": int(trigger_count),
        "target_models": sorted({str(model) for model in target_models if str(model)}),
        "target_categories": sorted({str(category) for category in target_categories if str(category)}),
        "action_type": action_type,
        "triggered_by_reason_codes": sorted({str(reason) for reason in triggered_by if str(reason)}),
        "algorithm_changes": [str(change) for change in algorithm_changes],
        "validation_gate": validation_gate,
        "shadow_only": True,
        "auto_applied_to_serving_policy": False,
        "raw_prompts_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _fusion_ablation_plan(
    recommendations: Sequence[Mapping[str, Any]],
    model_summaries: Sequence[Mapping[str, Any]],
    trace_summary: Mapping[str, Any],
) -> dict[str, Any]:
    recommendation_ids = {str(row.get("recommendation_id") or "") for row in recommendations}
    variants = []
    if "complete_evidence_before_algorithm_claims" in recommendation_ids:
        variants.append(
            _fusion_ablation_variant(
                variant_id="evidence_first_replay",
                purpose="complete missing benchmark and provider evidence before algorithm changes",
                target_models=list(AXIO_BENCHMARK_PUBLIC_MODELS),
                knobs={
                    "provider_probe": "environment_configured_arbitrary_providers_only",
                    "official_harness_imports": "required_for_official_or_audited_suites",
                    "provider_baselines": "all_usable_single_models",
                },
                measurement_gate="readiness must become ready without storing secrets or raw provider outputs",
            )
        )
    if "latency_guarded_adaptive_panel" in recommendation_ids:
        variants.append(
            _fusion_ablation_variant(
                variant_id="latency_trim_adaptive_panel",
                purpose="reduce 3x latency gate failures while preserving paired-case score",
                target_models=_fusion_models_with_family(model_summaries, FUSION_FAILURE_LATENCY_REASONS),
                knobs={
                    "router.max_models": "decrease for failing tier/category cells",
                    "router.max_depth": "decrease or zero when disagreement is low",
                    "router.max_parallel_experts": "prefer parallel experts over serial depth",
                    "runtime.early_exit_enabled": "increase usage for high-confidence judge records",
                    "synthesis.max_synthesis_candidates": "keep diversity-aware compression tight",
                },
                measurement_gate="score must not regress materially and p50/p95 latency must stay within 3x baseline",
            )
        )
    if "score_diversity_judge_escalation" in recommendation_ids:
        variants.append(
            _fusion_ablation_variant(
                variant_id="diversity_judge_quality_lift",
                purpose="improve failed score comparisons without benchmark-label tuning",
                target_models=_fusion_models_with_family(model_summaries, FUSION_FAILURE_SCORE_REASONS),
                knobs={
                    "router.provider_diversity_weight": "increase when provider overlap is high",
                    "router.api_format_diversity_weight": "increase when formats are available",
                    "router.role_blueprint": "promote domain_specialist and critic roles for failed categories",
                    "orchestrator.targeted_escalation": "focus only on judge-reported gaps",
                    "synthesis.selection_kernel": "rank_first_diversity_aware_synthesis",
                },
                measurement_gate="paired sign-test, Holm-Bonferroni, and practical effect-size gates must pass on fresh replay",
            )
        )
    if "provider_fallback_pool_refresh" in recommendation_ids:
        provider_routing = trace_summary.get("provider_routing_summary") if isinstance(trace_summary.get("provider_routing_summary"), Mapping) else {}
        variants.append(
            _fusion_ablation_variant(
                variant_id="provider_fallback_pool_refresh",
                purpose="improve fallback availability and independence before rerunning failed Axio tiers",
                target_models=list(AXIO_BENCHMARK_PUBLIC_MODELS),
                knobs={
                    "provider_probe": "refresh_environment_configured_live_registry",
                    "router.fallback_min_nonpanel_candidates": "increase in shadow only",
                    "router.fallback_prefer_api_format_diversity": True,
                    "router.fallback_recent_availability_weight": "increase before raw capability priors",
                    "trace.average_top_availability_score": provider_routing.get("average_top_availability_score"),
                    "trace.average_nonpanel_count": provider_routing.get("average_nonpanel_count"),
                    "trace.average_api_format_count": provider_routing.get("average_api_format_count"),
                },
                measurement_gate="fallback pool health improves on holdout traces and benchmark replay remains no-cheat",
            )
        )
    if "repair_api_surface_equivalence" in recommendation_ids:
        variants.append(
            _fusion_ablation_variant(
                variant_id="api_surface_parity_replay",
                purpose="prove four public API formats do not change model intelligence",
                target_models=list(AXIO_BENCHMARK_PUBLIC_MODELS),
                knobs={
                    "compat.canonical_payload": "same FusionRequest across all surfaces",
                    "benchmark.prompt_protocol_sha256": "identical across public surfaces",
                    "benchmark.decoding_config_sha256": "identical across public surfaces",
                    "benchmark.case_hash_set": "identical across public surfaces",
                },
                measurement_gate="all four surface runs must pass score tolerance and hash alignment checks",
            )
        )
    if "trace_budget_calibration" in recommendation_ids:
        variants.append(
            _fusion_ablation_variant(
                variant_id="trace_budget_shadow_patch",
                purpose="use safe aggregate traces to reduce unnecessary provider calls",
                target_models=list(AXIO_BENCHMARK_PUBLIC_MODELS),
                knobs={
                    "runtime.average_provider_call_count": trace_summary.get("average_provider_call_count"),
                    "router.max_total_model_calls": "calibrate in shadow only",
                    "runtime.deadline_budget": "tighten only after holdout validation",
                },
                measurement_gate="holdout trace quality and latency improve before any benchmark replay",
            )
        )
    if not variants:
        variants.append(
            _fusion_ablation_variant(
                variant_id="frozen_policy_replay",
                purpose="confirm current policy with deterministic replay",
                target_models=list(AXIO_BENCHMARK_PUBLIC_MODELS),
                knobs={"policy": "frozen"},
                measurement_gate="final audit remains clean after artifact replay",
            )
        )
    return {
        "schema": "axio_fusion_api.fusion_ablation_plan.v1",
        "variant_count": len(variants),
        "variants": variants,
        "policy_patch_auto_applied": False,
        "requires_holdout_or_fresh_replay_before_claim": True,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _fusion_ablation_variant(
    *,
    variant_id: str,
    purpose: str,
    target_models: Sequence[str],
    knobs: Mapping[str, Any],
    measurement_gate: str,
) -> dict[str, Any]:
    return {
        "variant_id": variant_id,
        "purpose": purpose,
        "target_models": sorted({str(model) for model in target_models if str(model)}),
        "knobs": dict(knobs),
        "measurement_gate": measurement_gate,
        "shadow_only": True,
        "auto_applied_to_serving_policy": False,
        "raw_prompts_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _fusion_success_criteria() -> dict[str, Any]:
    return {
        "schema": "axio_fusion_api.fusion_optimization_success_criteria.v1",
        "axio_pro": "beats strongest usable provider baseline on every required suite",
        "axio_terra": "beats second strongest usable provider baseline on every required suite",
        "axio_fast": "beats third strongest usable provider baseline on every required suite",
        "suite_count": len(BENCHMARK_SUITES),
        "category_counts": dict(BENCHMARK_CATEGORY_REQUIRED_SUITE_COUNTS),
        "api_surfaces": list(AXIO_BENCHMARK_API_FORMATS),
        "primary_claim_api_surface": AXIO_BENCHMARK_PRIMARY_API_FORMAT,
        "latency_p50_and_p95_max_multiplier": CLAIM_LATENCY_MAX_MULTIPLIER,
        "requires_paired_case_level_tests": True,
        "requires_holm_bonferroni_correction": True,
        "requires_practical_effect_size_gate": True,
        "minimum_primary_score_delta": CLAIM_MIN_PRIMARY_SCORE_DELTA,
        "minimum_paired_net_win_rate_delta": CLAIM_MIN_PAIRED_NET_WIN_RATE_DELTA,
        "requires_final_audit_replay": True,
        "requires_training_contamination_audit": True,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _fusion_reason_total(reason_counts: Mapping[str, int], family: set[str] | frozenset[str]) -> int:
    return sum(int(reason_counts.get(reason, 0) or 0) for reason in family)


def _fusion_matching_reasons(reason_counts: Mapping[str, int], family: set[str] | frozenset[str]) -> list[str]:
    return sorted(reason for reason in family if int(reason_counts.get(reason, 0) or 0) > 0)


def _fusion_models_with_family(
    model_summaries: Sequence[Mapping[str, Any]],
    family: set[str] | frozenset[str],
) -> list[str]:
    models = [
        str(summary.get("axio_model") or "")
        for summary in model_summaries
        if _fusion_reason_total(
            summary.get("failure_reason_counts") if isinstance(summary.get("failure_reason_counts"), Mapping) else {},
            family,
        )
        > 0
    ]
    return models or list(AXIO_BENCHMARK_PUBLIC_MODELS)


def _fusion_categories_with_family(
    model_summaries: Sequence[Mapping[str, Any]],
    family: set[str] | frozenset[str],
) -> list[str]:
    categories: set[str] = set()
    for summary in model_summaries:
        reason_counts = summary.get("failure_reason_counts") if isinstance(summary.get("failure_reason_counts"), Mapping) else {}
        if _fusion_reason_total(reason_counts, family) <= 0:
            continue
        for category in summary.get("failed_categories") or []:
            if str(category):
                categories.add(str(category))
    return sorted(categories)


def _scorecard_run_receipt(run: Mapping[str, Any]) -> dict[str, Any]:
    candidate_id = str(run.get("candidate_id") or "")
    score = _run_primary_score(run)
    task_format = str(run.get("task_format") or _suite_task_format(str(run.get("suite_id") or "")))
    reasoning_receipt = _benchmark_reasoning_run_receipt(
        run,
        suite_id=str(run.get("suite_id") or ""),
        task_format=task_format,
    )
    return {
        "suite_id": str(run.get("suite_id") or ""),
        "candidate_id": candidate_id,
        "candidate_id_sha256": sha256_text(candidate_id),
        "candidate_type": "provider" if candidate_id.startswith("provider::") else "axio" if candidate_id.startswith("axio-") else "baseline",
        "primary_metric": _scorecard_primary_metric(run),
        "primary_score": score,
        "accuracy": _optional_float(run.get("accuracy")),
        "mean_score": _optional_float(run.get("mean_score")),
        "case_count": _optional_int(run.get("case_count")) or 0,
        "attempted_count": _optional_int(run.get("attempted_count")) or 0,
        "correct_count": _optional_int(run.get("correct_count")) or 0,
        "latency_ms": _optional_float(run.get("latency_ms")) or 0.0,
        "average_case_latency_ms": _optional_float(run.get("average_case_latency_ms")),
        "p50_case_latency_ms": _optional_float(run.get("p50_case_latency_ms")),
        "p95_case_latency_ms": _optional_float(run.get("p95_case_latency_ms")),
        "estimated_cost_usd": _run_estimated_cost_usd(run),
        "cost_per_case_usd": _run_cost_per_case_usd(run),
        "primary_score_per_dollar": _score_per_dollar(score, _run_estimated_cost_usd(run)),
        "pricing_known_case_count": _optional_int(run.get("pricing_known_case_count")) or 0,
        "pricing_unknown_case_count": _optional_int(run.get("pricing_unknown_case_count")) or 0,
        "provider_call_count": _optional_int(run.get("provider_call_count")) or 0,
        "mode": str(run.get("mode") or ""),
        "task_format": task_format,
        "requested_reasoning_effort": str(reasoning_receipt.get("requested_reasoning_effort") or ""),
        "effective_reasoning_effort": str(reasoning_receipt.get("effective_reasoning_effort") or ""),
        "reasoning_transport": str(reasoning_receipt.get("reasoning_transport") or ""),
        "native_reasoning_effort_verified": reasoning_receipt.get("native_reasoning_effort_verified"),
        "reasoning_config_sha256": str(reasoning_receipt.get("reasoning_config_sha256") or ""),
        "raw_prompt_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _scorecard_provider_tier_receipt(run: Mapping[str, Any], *, rank: int, tier: str) -> dict[str, Any]:
    receipt = _scorecard_run_receipt(run)
    return {
        "tier": tier,
        "rank": int(rank),
        "candidate_id": receipt["candidate_id"],
        "candidate_id_sha256": receipt["candidate_id_sha256"],
        "primary_metric": receipt["primary_metric"],
        "primary_score": receipt["primary_score"],
        "case_count": receipt["case_count"],
        "correct_count": receipt["correct_count"],
        "latency_ms": receipt["latency_ms"],
        "average_case_latency_ms": receipt["average_case_latency_ms"],
        "p50_case_latency_ms": receipt["p50_case_latency_ms"],
        "p95_case_latency_ms": receipt["p95_case_latency_ms"],
        "estimated_cost_usd": receipt["estimated_cost_usd"],
        "cost_per_case_usd": receipt["cost_per_case_usd"],
        "primary_score_per_dollar": receipt["primary_score_per_dollar"],
        "provider_call_count": receipt["provider_call_count"],
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _scorecard_axio_target_receipt(
    *,
    suite_id: str,
    axio_model: str,
    target_tier: str,
    axio_run: Mapping[str, Any] | None,
    baseline_run: Mapping[str, Any] | None,
) -> dict[str, Any]:
    axio_score = _run_primary_score(axio_run)
    baseline_score = _run_primary_score(baseline_run)
    axio_cost = _run_estimated_cost_usd(axio_run)
    baseline_cost = _run_estimated_cost_usd(baseline_run)
    axio_p50 = _optional_float(axio_run.get("p50_case_latency_ms")) if isinstance(axio_run, Mapping) else None
    baseline_p50 = _optional_float(baseline_run.get("p50_case_latency_ms")) if isinstance(baseline_run, Mapping) else None
    axio_p95 = _optional_float(axio_run.get("p95_case_latency_ms")) if isinstance(axio_run, Mapping) else None
    baseline_p95 = _optional_float(baseline_run.get("p95_case_latency_ms")) if isinstance(baseline_run, Mapping) else None
    latency_gate = _claim_latency_gate(axio_run, baseline_run)
    paired = _paired_case_stats(axio_run, baseline_run)
    reason_codes = []
    if not isinstance(axio_run, Mapping):
        reason_codes.append("missing_axio_run")
    if not isinstance(baseline_run, Mapping):
        reason_codes.append(f"missing_{target_tier}")
    if axio_score is None or baseline_score is None:
        reason_codes.append("missing_primary_score")
    elif axio_score <= baseline_score:
        reason_codes.append("axio_primary_score_not_higher")
    if latency_gate["latency_gate_passed"] is not True:
        reason_codes.extend(str(reason) for reason in latency_gate.get("reason_codes") or [] if str(reason))
    return {
        "suite_id": suite_id,
        "axio_model": axio_model,
        "target_tier": target_tier,
        "baseline_candidate_id": str(baseline_run.get("candidate_id") or "") if isinstance(baseline_run, Mapping) else "",
        "baseline_candidate_id_sha256": sha256_text(str(baseline_run.get("candidate_id") or "")) if isinstance(baseline_run, Mapping) else "",
        "primary_metric": _scorecard_primary_metric(axio_run or baseline_run or {"suite_id": suite_id}),
        "axio_primary_score": axio_score,
        "baseline_primary_score": baseline_score,
        "primary_score_delta": None if axio_score is None or baseline_score is None else round(axio_score - baseline_score, 6),
        "axio_estimated_cost_usd": axio_cost,
        "baseline_estimated_cost_usd": baseline_cost,
        "estimated_cost_delta_usd": None if axio_cost is None or baseline_cost is None else round(axio_cost - baseline_cost, 8),
        "cost_ratio_vs_baseline": None if axio_cost is None or baseline_cost in (None, 0.0) else round(axio_cost / baseline_cost, 6),
        "axio_cost_per_case_usd": _run_cost_per_case_usd(axio_run),
        "baseline_cost_per_case_usd": _run_cost_per_case_usd(baseline_run),
        "axio_p50_latency_ms": axio_p50,
        "baseline_p50_latency_ms": baseline_p50,
        "p50_latency_delta_ms": None if axio_p50 is None or baseline_p50 is None else round(axio_p50 - baseline_p50, 3),
        "axio_p95_latency_ms": axio_p95,
        "baseline_p95_latency_ms": baseline_p95,
        "p95_latency_delta_ms": None if axio_p95 is None or baseline_p95 is None else round(axio_p95 - baseline_p95, 3),
        "latency_gate": latency_gate,
        "latency_multiplier_vs_baseline": latency_gate["latency_multiplier_vs_baseline"],
        "latency_within_3x_baseline": latency_gate["latency_gate_passed"],
        "paired_case_overlap_count": _optional_int(paired.get("common_case_count")) or 0,
        "beats_target": None
        if axio_score is None or baseline_score is None
        else axio_score > baseline_score and latency_gate["latency_gate_passed"] is True,
        "reason_codes": sorted(set(reason_codes)),
        "raw_questions_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _claim_reasoning_gate(
    run: Mapping[str, Any] | None,
    *,
    required_reasoning_effort: str,
    native_max_required: bool,
    suite_id: str,
    task_format: str,
) -> dict[str, Any]:
    required = normalize_reasoning_effort(required_reasoning_effort)
    if not native_max_required or not required:
        return {
            "required": False,
            "passed": True,
            "required_reasoning_effort": required,
            "native_reasoning_effort_verified": None,
            "reason_codes": [],
        }
    receipt = (
        _benchmark_reasoning_run_receipt(run, suite_id=suite_id, task_format=task_format)
        if isinstance(run, Mapping)
        else {}
    )
    requested = normalize_reasoning_effort(receipt.get("requested_reasoning_effort"))
    effective = normalize_reasoning_effort(receipt.get("effective_reasoning_effort"))
    native_verified = receipt.get("native_reasoning_effort_verified") is True
    reasons: list[str] = []
    if not receipt or receipt.get("status") == "missing":
        reasons.append("provider_baseline_reasoning_receipt_missing")
    if requested != required:
        reasons.append("provider_baseline_requested_reasoning_effort_mismatch")
    if effective != required:
        reasons.append("provider_baseline_effective_reasoning_effort_mismatch")
    if not native_verified:
        reasons.append("provider_baseline_native_max_unverified")
    return {
        "required": True,
        "passed": not reasons,
        "required_reasoning_effort": required,
        "requested_reasoning_effort": requested,
        "effective_reasoning_effort": effective,
        "reasoning_transport": str(receipt.get("reasoning_transport") or ""),
        "native_reasoning_effort_verified": native_verified,
        "reasoning_status": str(receipt.get("status") or ""),
        "reason_codes": sorted(set(reasons)),
    }


def _scorecard_candidate_sort_key(row: Mapping[str, Any]) -> tuple[float, int, float, str]:
    score = _optional_float(row.get("primary_score"))
    return (
        score if score is not None else -1.0,
        _optional_int(row.get("correct_count")) or 0,
        -(_optional_float(row.get("latency_ms")) or 0.0),
        str(row.get("candidate_id") or ""),
    )


def _scorecard_primary_metric(run: Mapping[str, Any]) -> str:
    suite_id = str(run.get("suite_id") or "")
    return str(run.get("primary_metric") or _primary_metric_for_format(str(run.get("task_format") or _suite_task_format(suite_id))))


def _run_primary_score(run: Mapping[str, Any] | None) -> float | None:
    if not isinstance(run, Mapping):
        return None
    metric = _scorecard_primary_metric(run).strip().lower()
    accuracy = _optional_float(run.get("accuracy"))
    mean_score = _optional_float(run.get("mean_score"))
    if metric in {"chrf", "judge_score", "win_rate", "strict_instruction_pass", "instruction_level_accuracy"} and mean_score is not None:
        return mean_score
    if accuracy is not None:
        return accuracy
    return mean_score


def _run_estimated_cost_usd(run: Mapping[str, Any] | None) -> float | None:
    if not isinstance(run, Mapping):
        return None
    value = _optional_float(run.get("estimated_cost_usd"))
    return None if value is None else round(max(0.0, value), 8)


def _run_cost_per_case_usd(run: Mapping[str, Any] | None) -> float | None:
    if not isinstance(run, Mapping):
        return None
    direct = _optional_float(run.get("cost_per_case_usd"))
    if direct is not None:
        return round(max(0.0, direct), 8)
    cost = _run_estimated_cost_usd(run)
    cases = _optional_int(run.get("case_count")) or 0
    if cost is None or cases <= 0:
        return None
    return round(cost / cases, 8)


def _score_per_dollar(score: float | None, estimated_cost_usd: float | None) -> float | None:
    if score is None or estimated_cost_usd is None:
        return None
    try:
        cost = float(estimated_cost_usd)
    except (TypeError, ValueError):
        return None
    if cost <= 0.0:
        return None
    return round(float(score) / cost, 6)


def _run_case_latencies(run: Mapping[str, Any]) -> list[float]:
    rows = run.get("case_results") if isinstance(run.get("case_results"), list) else []
    latencies = [
        float(value)
        for value in (_optional_float(row.get("latency_ms")) for row in rows if isinstance(row, Mapping))
        if value is not None
    ]
    if latencies:
        return latencies
    p50 = _optional_float(run.get("p50_case_latency_ms"))
    p95 = _optional_float(run.get("p95_case_latency_ms"))
    average = _optional_float(run.get("average_case_latency_ms"))
    total = _optional_float(run.get("latency_ms"))
    return [value for value in (p50, p95, average, total) if value is not None]


def _average_float(values: Sequence[Any]) -> float | None:
    clean = [float(value) for value in values if _optional_float(value) is not None]
    if not clean:
        return None
    return round(sum(clean) / len(clean), 3)


def _percentile_float(values: Sequence[Any], q: float) -> float | None:
    clean = sorted(float(value) for value in values if _optional_float(value) is not None)
    if not clean:
        return None
    if len(clean) == 1:
        return round(clean[0], 3)
    position = (len(clean) - 1) * max(0.0, min(1.0, float(q)))
    lower = int(math.floor(position))
    upper = int(math.ceil(position))
    if lower == upper:
        return round(clean[lower], 3)
    weight = position - lower
    return round(clean[lower] * (1.0 - weight) + clean[upper] * weight, 3)


def _claim_pre_registered_provider_rank_map(
    provider_baseline_freeze: Mapping[str, Any] | None,
) -> dict[str, Any]:
    manifest = provider_baseline_freeze if isinstance(provider_baseline_freeze, Mapping) else {}
    freeze_receipt = _provider_baseline_freeze_receipt(manifest) if manifest else {}
    external_receipt = (
        manifest.get("external_ranking_receipt")
        if isinstance(manifest.get("external_ranking_receipt"), Mapping)
        else {}
    )
    registry_receipt = (
        manifest.get("provider_registry_receipt")
        if isinstance(manifest.get("provider_registry_receipt"), Mapping)
        else {}
    )
    blockers: list[str] = []
    rank_to_candidate_hash: dict[int, str] = {}
    if not manifest:
        blockers.append("provider_baseline_freeze_missing_for_claim_audit")
    elif str(manifest.get("provider_baseline_selection") or "") != EXTERNAL_PROVIDER_RANKING_SELECTION_MODE:
        blockers.append("provider_baseline_freeze_not_externally_ranked_for_claim_audit")
    if freeze_receipt and freeze_receipt.get("freeze_digest_matches") is not True:
        blockers.append("provider_baseline_freeze_digest_mismatch_for_claim_audit")
    if external_receipt.get("schema") != EXTERNAL_PROVIDER_RANKING_RECEIPT_SCHEMA:
        blockers.append("provider_baseline_external_ranking_receipt_missing_for_claim_audit")
    if external_receipt.get("ready") is not True:
        blockers.append("provider_baseline_external_ranking_not_ready_for_claim_audit")
    if external_receipt.get("pre_registered_before_campaign") is not True:
        blockers.append("provider_baseline_external_ranking_not_pre_registered_for_claim_audit")
    if external_receipt.get("registry_file_matches_current_registry") is not True:
        blockers.append("provider_baseline_external_ranking_registry_mismatch_for_claim_audit")
    if external_receipt.get("target_benchmark_material_detected") is True:
        blockers.append("provider_baseline_external_ranking_contains_target_benchmark_material")
    external_validation_errors = _external_provider_rank_mapping_validation_errors(
        manifest,
        expected_registry_file_sha256=str(registry_receipt.get("registry_file_sha256") or ""),
    )
    blockers.extend(
        f"provider_baseline_{reason}_for_claim_audit"
        for reason in external_validation_errors
    )
    rows = manifest.get("frozen_candidate_rows") if isinstance(manifest.get("frozen_candidate_rows"), list) else []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        rank = _optional_int(row.get("pre_campaign_external_rank"))
        candidate_hash = str(row.get("candidate_id_sha256") or "")
        if rank not in EXTERNAL_PROVIDER_RANKING_REQUIRED_RANKS or not _looks_like_sha256(candidate_hash):
            continue
        if rank in rank_to_candidate_hash:
            blockers.append("provider_baseline_external_rank_duplicate_for_claim_audit")
            continue
        rank_to_candidate_hash[rank] = candidate_hash
    if set(rank_to_candidate_hash) != set(EXTERNAL_PROVIDER_RANKING_REQUIRED_RANKS):
        blockers.append("provider_baseline_external_top_three_incomplete_for_claim_audit")
    return {
        "selection_mode": str(manifest.get("provider_baseline_selection") or ""),
        "freeze_digest_sha256": str(manifest.get("freeze_digest_sha256") or ""),
        "freeze_receipt_digest_sha256": str(freeze_receipt.get("freeze_digest_sha256") or ""),
        "external_ranking_receipt_digest_sha256": str(external_receipt.get("receipt_digest_sha256") or ""),
        "external_ranking_validation_errors": external_validation_errors,
        "rank_to_candidate_id_sha256": rank_to_candidate_hash,
        "ready": not blockers,
        "blockers": sorted(set(blockers)),
        "raw_provider_model_ids_persisted": False,
        "secrets_persisted": False,
    }


def build_benchmark_claim_audit(
    runs: Sequence[Mapping[str, Any]],
    *,
    min_cases_per_suite: int = 100,
    alpha: float = 0.05,
    provider_baseline_freeze: Mapping[str, Any] | None = None,
    provider_baseline_freeze_path: str | Path | None = None,
    require_http_gateway: bool = False,
    native_max_required: bool = False,
    required_reasoning_effort: str = "",
) -> dict[str, Any]:
    if provider_baseline_freeze_path is not None:
        artifact = _load_json_artifact(Path(provider_baseline_freeze_path))
        provider_baseline_freeze = (
            artifact.get("payload")
            if isinstance(artifact.get("payload"), Mapping)
            else {}
        )
    pre_registered_baselines = _claim_pre_registered_provider_rank_map(provider_baseline_freeze)
    use_pre_registered_baselines = provider_baseline_freeze is not None
    normalized_runs = [_normalize_safe_run_candidate_alias(run) for run in runs if isinstance(run, Mapping)]
    run_set_receipt = _benchmark_run_set_receipt(normalized_runs)
    api_surface_audit = build_benchmark_api_surface_audit(
        normalized_runs,
        require_http_gateway=bool(require_http_gateway),
    )
    scoring_runs = _primary_claim_scoring_runs(normalized_runs)
    suite_ids = [suite.suite_id for suite in BENCHMARK_SUITES]
    suite_categories = {suite.suite_id: suite.category for suite in BENCHMARK_SUITES}
    runs_by_suite: dict[str, dict[str, Mapping[str, Any]]] = {}
    for run in scoring_runs:
        suite_id = str(run.get("suite_id") or "")
        candidate_id = str(run.get("candidate_id") or "")
        if not suite_id or not candidate_id:
            continue
        runs_by_suite.setdefault(suite_id, {})[candidate_id] = run
    comparisons = []
    model_contract = {
        "axio-pro": ("strongest_provider", 0),
        "axio-terra": ("second_strongest_provider", 1),
        "axio-fast": ("third_strongest_provider", 2),
    }
    for suite_id in suite_ids:
        suite_runs = runs_by_suite.get(suite_id, {})
        provider_runs = _rank_provider_runs(suite_runs.values())
        provider_runs_by_hash = {
            sha256_text(str(run.get("candidate_id") or "")): run
            for run in provider_runs
        }
        for axio_model, (baseline_tier, baseline_index) in model_contract.items():
            axio_run = suite_runs.get(axio_model)
            expected_candidate_hash = ""
            if use_pre_registered_baselines:
                expected_candidate_hash = str(
                    pre_registered_baselines.get("rank_to_candidate_id_sha256", {}).get(baseline_index + 1)
                    or ""
                )
                baseline_run = provider_runs_by_hash.get(expected_candidate_hash)
            else:
                baseline_run = provider_runs[baseline_index] if len(provider_runs) > baseline_index else None
            comparisons.append(
                _claim_comparison_row(
                    suite_id=suite_id,
                    category=suite_categories.get(suite_id, ""),
                    axio_model=axio_model,
                    baseline_tier=baseline_tier,
                    axio_run=axio_run,
                    baseline_run=baseline_run,
                    provider_baseline_count=len(provider_runs),
                    min_cases_per_suite=min_cases_per_suite,
                    alpha=alpha,
                    baseline_rank=baseline_index + 1,
                    baseline_pre_registered=use_pre_registered_baselines,
                    expected_baseline_candidate_id_sha256=expected_candidate_hash,
                    native_max_required=native_max_required,
                    required_reasoning_effort=required_reasoning_effort,
                )
            )
    comparisons, multiple_correction = _apply_claim_multiple_comparison_correction(comparisons, alpha=float(alpha))
    by_model = {}
    for axio_model in model_contract:
        rows = [row for row in comparisons if row["axio_model"] == axio_model]
        by_model[axio_model] = {
            "suite_comparison_count": len(rows),
            "passed_suite_count": sum(1 for row in rows if row["claim_allowed"] is True),
            "failed_suite_count": sum(1 for row in rows if row["claim_allowed"] is not True),
            "all_required_suites_passed": bool(rows) and all(row["claim_allowed"] is True for row in rows),
            "failed_suites": [
                {
                    "suite_id": row["suite_id"],
                    "category": row["category"],
                    "reason_codes": row["reason_codes"],
                }
                for row in rows
                if row["claim_allowed"] is not True
            ],
        }
    category_coverage = _claim_category_coverage(comparisons)
    missing_requirements = _claim_missing_requirements(
        comparisons=comparisons,
        by_model=by_model,
        category_coverage=category_coverage,
        runs_by_suite=runs_by_suite,
    )
    if api_surface_audit.get("all_required_api_surfaces_ready") is not True:
        missing_requirements.append(
            {
                "kind": "api_surface_audit_not_ready",
                "blocking_reason_counts": dict(api_surface_audit.get("blocking_reason_counts") or {}),
            }
        )
    if use_pre_registered_baselines and pre_registered_baselines.get("ready") is not True:
        missing_requirements.append(
            {
                "kind": "pre_registered_provider_baseline_freeze_not_ready",
                "reason_codes": list(pre_registered_baselines.get("blockers") or []),
            }
        )
    if native_max_required:
        unverified_comparisons = [
            row
            for row in comparisons
            if "provider_baseline_native_max_unverified" in (row.get("reason_codes") or [])
        ]
        if unverified_comparisons:
            missing_requirements.append(
                {
                    "kind": "provider_baseline_native_max_unverified",
                    "comparison_count": len(unverified_comparisons),
                    "required_reasoning_effort": normalize_reasoning_effort(required_reasoning_effort),
                }
            )
    final_claims = {
        "axio_pro_beats_strongest_single_model_on_all_required_benchmarks": by_model["axio-pro"]["all_required_suites_passed"],
        "axio_terra_beats_second_strongest_single_model_on_all_required_benchmarks": by_model["axio-terra"]["all_required_suites_passed"],
        "axio_fast_beats_third_strongest_single_model_on_all_required_benchmarks": by_model["axio-fast"]["all_required_suites_passed"],
    }
    return {
        "schema": "axio_fusion_api.benchmark_claim_audit.v1",
        "run_count": len(normalized_runs),
        "scoring_run_count": len(scoring_runs),
        "source_run_set_digest_sha256": run_set_receipt["run_set_digest_sha256"],
        "source_run_set_receipt": run_set_receipt,
        "required_suite_count": len(suite_ids),
        "covered_required_suite_count": sum(1 for suite_id in suite_ids if suite_id in runs_by_suite),
        "all_required_suites_present": all(suite_id in runs_by_suite for suite_id in suite_ids),
        "required_suite_counts_by_category": dict(BENCHMARK_CATEGORY_REQUIRED_SUITE_COUNTS),
        "required_two_suites_per_category": False,
        "category_contract": "first eight categories require two suites; vertical_domain requires five suites",
        "category_coverage": category_coverage,
        "baseline_contract": {
            "axio-pro": "must beat externally pre-registered configured-provider-pool rank-one provider baseline on every suite",
            "axio-terra": "must beat externally pre-registered configured-provider-pool rank-two provider baseline on every suite",
            "axio-fast": "must beat externally pre-registered configured-provider-pool rank-three provider baseline on every suite",
            "provider_strength_source": (
                EXTERNAL_PROVIDER_RANKING_RANK_SOURCE
                if use_pre_registered_baselines
                else "legacy_same_suite_observed_provider_primary_metric"
            ),
            "pre_registered_rank_mapping_required_for_final_claim": True,
            "latency_gate": "each Axio tier must keep both p50 and p95 latency within 3x the corresponding same-suite provider baseline latency",
            "native_max_reasoning_gate_enabled": bool(native_max_required),
            "required_reasoning_effort": normalize_reasoning_effort(required_reasoning_effort),
        },
        "reasoning_contract": {
            "native_max_required": bool(native_max_required),
            "required_reasoning_effort": normalize_reasoning_effort(required_reasoning_effort),
            "fail_closed": bool(native_max_required),
            "provider_baseline_receipts_are_claim_input": bool(native_max_required),
        },
        "provider_baseline_freeze_binding": pre_registered_baselines,
        "statistical_contract": {
            "paired_case_comparison_required": True,
            "one_sided_exact_sign_test": True,
            "multiple_comparison_correction_required": True,
            "multiple_comparison_correction_method": CLAIM_MULTIPLE_COMPARISON_METHOD,
            "familywise_error_rate_control": True,
            "correction_family": CLAIM_MULTIPLE_COMPARISON_FAMILY,
            "correction_family_size": len(comparisons),
            "alpha": float(alpha),
            "practical_significance_required": True,
            "minimum_primary_score_delta": CLAIM_MIN_PRIMARY_SCORE_DELTA,
            "minimum_paired_net_win_rate_delta": CLAIM_MIN_PAIRED_NET_WIN_RATE_DELTA,
            "wilson_score_interval_confidence": 0.95,
            "min_cases_per_suite": int(min_cases_per_suite),
            "aggregate_only_scores_can_not_support_claim": True,
            "latency_gate_required_for_claims": True,
            "latency_gate_max_multiplier": CLAIM_LATENCY_MAX_MULTIPLIER,
        },
        "multiple_comparison_correction": multiple_correction,
        "api_surface_audit": api_surface_audit,
        "comparisons": comparisons,
        "by_model": by_model,
        "final_claims": final_claims,
        "all_final_claims_allowed": all(final_claims.values())
        and api_surface_audit.get("all_required_api_surfaces_ready") is True
        and not missing_requirements,
        "missing_requirements": missing_requirements,
        "anti_leakage_contract": {
            "raw_questions_persisted": False,
            "raw_options_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "benchmark_labels_used_for_training": False,
            "claim_gate_uses_case_hashes_only": True,
        },
        "raw_prompt_persisted": False,
        "raw_label_persisted": False,
        "raw_provider_output_persisted": False,
        "secrets_persisted": False,
    }


def run_benchmark_campaign(
    *,
    dataset_manifest_path: str | Path,
    output_dir: str | Path,
    registry_path: str | Path | None = None,
    candidate_ids: Sequence[str] = (),
    include_provider_baselines: bool = True,
    max_provider_baselines: int | None = 3,
    provider_baseline_freeze_path: str | Path | None = None,
    provider_probe_evidence_audit_path: str | Path | None = None,
    source_manifest_path: str | Path | None = None,
    case_hash_manifest_path: str | Path | None = None,
    official_import_audit_path: str | Path | None = None,
    api_surface_protocol_path: str | Path | None = None,
    provider_input_adapter_path: str | Path | None = None,
    system_development_readiness_path: str | Path | None = None,
    limit: int | None = None,
    live: bool = False,
    resume: bool = True,
    code_timeout_seconds: float = 5.0,
    min_cases_per_suite: int = 100,
    alpha: float = 0.05,
    strict_live_preflight: bool = False,
    client: HTTPProviderClient | None = None,
    axio_gateway_url: str | None = None,
    benchmark_policy_path: str | Path | None = None,
) -> dict[str, Any]:
    benchmark_policy = load_benchmark_evaluation_policy(benchmark_policy_path)
    benchmark_policy_safe_receipt = benchmark_policy_receipt(benchmark_policy)
    benchmark_reasoning = benchmark_policy.get("reasoning") if isinstance(benchmark_policy.get("reasoning"), Mapping) else {}
    readiness_preflight = audit_benchmark_campaign_readiness(
        dataset_manifest_path=dataset_manifest_path,
        registry_path=registry_path,
        candidate_ids=candidate_ids,
        include_provider_baselines=include_provider_baselines,
        max_provider_baselines=max_provider_baselines,
        provider_baseline_freeze_path=provider_baseline_freeze_path,
        min_cases_per_suite=min_cases_per_suite,
    )
    readiness_preflight_receipt = _benchmark_readiness_preflight_receipt(readiness_preflight)
    manifest = _load_dataset_manifest(dataset_manifest_path)
    suite_specs = _campaign_suite_specs(manifest)
    profiles = load_registry(registry_path)
    selection_context = _provider_baseline_selection_context(
        profiles,
        include_provider_baselines=include_provider_baselines,
        max_provider_baselines=max_provider_baselines,
        provider_baseline_freeze_path=provider_baseline_freeze_path,
        registry_path=registry_path,
    )
    candidates = _campaign_candidate_ids(
        profiles,
        candidate_ids=candidate_ids,
        include_provider_baselines=include_provider_baselines,
        max_provider_baselines=max_provider_baselines,
        provider_baseline_freeze_path=provider_baseline_freeze_path,
        registry_path=registry_path,
    )
    run_units = _run_units_from_candidate_ids(profiles, candidates)
    selected_provider_baselines = list(selection_context.get("profiles") or [])
    output = Path(output_dir)
    runs_dir = output / "runs"
    runs_dir.mkdir(parents=True, exist_ok=True)
    selected_provider_probe_evidence_audit = _campaign_provider_probe_evidence_audit_path(
        provider_probe_evidence_audit_path,
        output_dir=output,
    )
    provider_probe_evidence_artifact = _load_json_artifact(selected_provider_probe_evidence_audit)
    if (
        provider_probe_evidence_artifact.get("valid_json_object") is True
        and _provider_probe_evidence_audit_copy_allowed(provider_probe_evidence_artifact.get("payload"))
    ):
        copied_probe_evidence = output / "provider_probe_evidence_audit.safe.json"
        write_json(copied_probe_evidence, provider_probe_evidence_artifact["payload"])
        selected_provider_probe_evidence_audit = copied_probe_evidence
        provider_probe_evidence_artifact = _load_json_artifact(selected_provider_probe_evidence_audit)
    provider_registry_receipt = _provider_registry_receipt(
        profiles,
        registry_path=registry_path,
    )
    provider_probe_evidence_audit_receipt = _provider_probe_evidence_audit_receipt_for_freeze(
        selected_provider_probe_evidence_audit,
        registry_receipt=provider_registry_receipt,
    )
    if provider_baseline_freeze_path is not None:
        provided_freeze_artifact = _load_json_artifact(Path(provider_baseline_freeze_path))
        provided_freeze = (
            provided_freeze_artifact.get("payload")
            if isinstance(provided_freeze_artifact.get("payload"), Mapping)
            else {}
        )
        if _provider_baseline_freeze_copy_allowed(provided_freeze):
            provider_baseline_freeze = dict(provided_freeze)
        else:
            provider_baseline_freeze = build_provider_baseline_freeze_manifest(
                registry_path=registry_path,
                include_provider_baselines=include_provider_baselines,
                max_provider_baselines=max_provider_baselines,
                provider_probe_evidence_audit_path=selected_provider_probe_evidence_audit,
            )
            provider_baseline_freeze["final_claim_freeze_ready"] = False
            provider_baseline_freeze["blockers"] = sorted(
                set(
                    [
                        *provider_baseline_freeze.get("blockers", []),
                        "provider_baseline_freeze_input_invalid_or_unsafe",
                    ]
                )
            )
            provider_baseline_freeze["freeze_digest_sha256"] = sha256_text(
                stable_json(_provider_baseline_freeze_digest_input(provider_baseline_freeze))
            )
            provider_baseline_freeze["freeze_receipt"] = _provider_baseline_freeze_receipt(
                provider_baseline_freeze
            )
    else:
        provider_baseline_freeze = build_provider_baseline_freeze_manifest(
            registry_path=registry_path,
            include_provider_baselines=include_provider_baselines,
            max_provider_baselines=max_provider_baselines,
            provider_probe_evidence_audit_path=selected_provider_probe_evidence_audit,
        )
    provider_baseline_freeze_receipt = _provider_baseline_freeze_receipt(provider_baseline_freeze)
    strict_source_manifest_receipt = _strict_live_source_manifest_preflight_receipt(
        source_manifest_path=source_manifest_path,
        min_cases_per_suite=min_cases_per_suite,
    )
    strict_case_hash_manifest_receipt = _strict_live_case_hash_manifest_preflight_receipt(
        case_hash_manifest_path=case_hash_manifest_path,
        source_manifest_path=source_manifest_path,
        min_cases_per_suite=min_cases_per_suite,
    )
    strict_official_import_audit_receipt = _strict_live_official_import_audit_preflight_receipt(
        official_import_audit_path=official_import_audit_path,
    )
    strict_api_surface_protocol_receipt = _strict_live_api_surface_protocol_preflight_receipt(
        api_surface_protocol_path=api_surface_protocol_path,
    )
    strict_provider_input_adapter_receipt = _strict_live_provider_input_adapter_preflight_receipt(
        provider_input_adapter_path=provider_input_adapter_path,
    )
    strict_system_development_readiness_receipt = _strict_live_system_development_readiness_preflight_receipt(
        system_development_readiness_path=system_development_readiness_path,
    )
    strict_axio_http_gateway_receipt = _strict_live_axio_http_gateway_preflight_receipt(
        axio_gateway_url=axio_gateway_url,
        run_units=run_units,
    )
    if live and strict_live_preflight:
        strict_live_blockers = _strict_live_preflight_blockers(
            readiness_preflight_receipt=readiness_preflight_receipt,
            provider_probe_evidence_audit_receipt=provider_probe_evidence_audit_receipt,
            provider_baseline_freeze_receipt=provider_baseline_freeze_receipt,
            source_manifest_receipt=strict_source_manifest_receipt,
            case_hash_manifest_receipt=strict_case_hash_manifest_receipt,
            official_import_audit_receipt=strict_official_import_audit_receipt,
            api_surface_protocol_receipt=strict_api_surface_protocol_receipt,
            provider_input_adapter_receipt=strict_provider_input_adapter_receipt,
            system_development_readiness_receipt=strict_system_development_readiness_receipt,
            axio_http_gateway_receipt=strict_axio_http_gateway_receipt,
        )
        if strict_live_blockers:
            return _write_strict_live_preflight_blocked_campaign(
                dataset_manifest_path=dataset_manifest_path,
                output=output,
                suite_specs=suite_specs,
                candidates=candidates,
                run_units=run_units,
                profiles=profiles,
                selected_provider_baselines=selected_provider_baselines,
                selection_context=selection_context,
                include_provider_baselines=include_provider_baselines,
                max_provider_baselines=max_provider_baselines,
                min_cases_per_suite=min_cases_per_suite,
                alpha=alpha,
                resume=resume,
                blockers=strict_live_blockers,
                readiness_preflight_receipt=readiness_preflight_receipt,
                provider_registry_receipt=provider_registry_receipt,
                provider_probe_evidence_audit_receipt=provider_probe_evidence_audit_receipt,
                provider_baseline_freeze=provider_baseline_freeze,
                provider_baseline_freeze_receipt=provider_baseline_freeze_receipt,
                source_manifest_receipt=strict_source_manifest_receipt,
                case_hash_manifest_receipt=strict_case_hash_manifest_receipt,
                official_import_audit_receipt=strict_official_import_audit_receipt,
                api_surface_protocol_receipt=strict_api_surface_protocol_receipt,
                provider_input_adapter_receipt=strict_provider_input_adapter_receipt,
                system_development_readiness_receipt=strict_system_development_readiness_receipt,
                axio_http_gateway_receipt=strict_axio_http_gateway_receipt,
                benchmark_policy_safe_receipt=benchmark_policy_safe_receipt,
                benchmark_policy=benchmark_policy,
                native_max_required=benchmark_reasoning.get("native_max_required") is True,
                required_reasoning_effort=str(benchmark_reasoning.get("target_effort") or ""),
            )
    started = time.monotonic()
    runs = []
    artifacts = []
    missing_suites = []
    for spec in suite_specs:
        suite_id = str(spec.get("suite_id") or "")
        dataset_path = _suite_dataset_path(spec)
        has_imports = isinstance(spec.get("imported_runs"), Mapping) and bool(spec.get("imported_runs"))
        if not suite_id:
            missing_suites.append({"suite_id": suite_id, "reason": "missing_suite_id"})
            continue
        if not dataset_path and not has_imports:
            missing_suites.append({"suite_id": suite_id, "reason": "missing_dataset_path"})
            continue
        selected_limit = _optional_int(spec.get("limit"))
        if selected_limit is None:
            selected_limit = limit
        task_format = str(spec.get("task_format") or "auto")
        for unit in run_units:
            candidate_id = _candidate_id_for_run_unit(unit)
            api_format = _api_format_for_run_unit(unit)
            api_surface_id = _api_surface_id_for_run_unit(unit)
            run_unit_id = str(unit.get("run_unit_id") or api_surface_id)
            run_path = runs_dir / f"{_safe_filename(suite_id)}__{_safe_filename(run_unit_id)}.json"
            imported_path = _imported_run_path_for_unit(spec, unit)
            if imported_path:
                run = _normalize_imported_run_for_campaign(
                    _load_imported_run(imported_path),
                    suite_id=suite_id,
                    candidate_id=run_unit_id,
                )
                write_json(run_path, run)
                status = "imported"
            elif resume and run_path.exists():
                run = _normalize_imported_run_for_campaign(
                    json.loads(run_path.read_text(encoding="utf-8")),
                    suite_id=suite_id,
                    candidate_id=run_unit_id,
                )
                write_json(run_path, run)
                status = "resumed"
            else:
                run = run_benchmark_dataset(
                    suite_id=suite_id,
                    dataset_path=dataset_path,
                    candidate_id=candidate_id,
                    api_format=api_format,
                    task_format=task_format,
                    registry_path=registry_path,
                    limit=selected_limit,
                    live=live,
                    client=client,
                    code_timeout_seconds=code_timeout_seconds,
                    axio_gateway_url=axio_gateway_url,
                    provider_profiles=selection_context.get("provider_profiles"),
                )
                write_json(run_path, run)
                status = "completed"
            run = _annotate_benchmark_run_identity(
                run,
                benchmark_slot_id=suite_id,
                spec=spec,
            )
            write_json(run_path, run)
            runs.append(run)
            artifacts.append(
                {
                    "suite_id": suite_id,
                    "candidate_id": candidate_id,
                    "run_unit_id": run_unit_id,
                    "api_format": run.get("api_format") or api_format,
                    "api_surface_id": run.get("api_surface_id") or api_surface_id,
                    "api_surface_role": run.get("api_surface_role") or unit.get("api_surface_role"),
                    "api_surface_is_primary_claim": run.get("api_surface_is_primary_claim"),
                    "run_path": str(run_path.relative_to(output)),
                    "status": status,
                    "task_format": run.get("task_format") or task_format,
                    "case_count": run.get("case_count"),
                    "attempted_count": run.get("attempted_count"),
                    "accuracy": run.get("accuracy"),
                    "mean_score": run.get("mean_score"),
                    "estimated_cost_usd": run.get("estimated_cost_usd"),
                    "provider_call_count": run.get("provider_call_count"),
                    "dataset_path_sha256": sha256_text(str(dataset_path)),
                    "raw_dataset_path_persisted": False,
                    "raw_prompt_persisted": False,
                }
            )
    scorecard = build_benchmark_scorecard(
        runs,
        provider_baseline_freeze=provider_baseline_freeze,
        require_http_gateway=bool(live),
    )
    claim_audit = build_benchmark_claim_audit(
        runs,
        min_cases_per_suite=min_cases_per_suite,
        alpha=alpha,
        provider_baseline_freeze=provider_baseline_freeze,
        require_http_gateway=bool(live),
        native_max_required=benchmark_reasoning.get("native_max_required") is True,
        required_reasoning_effort=str(benchmark_reasoning.get("target_effort") or ""),
    )
    methodology = build_benchmark_methodology_manifest(
        dataset_manifest_path=dataset_manifest_path,
        benchmark_policy=benchmark_policy,
    )
    methodology_receipt = _benchmark_methodology_receipt(methodology)
    runs_payload = build_benchmark_runs_payload(runs)
    write_json(output / "runs.json", runs_payload)
    write_json(output / "scorecard.json", scorecard)
    write_json(output / "claim_audit.json", claim_audit)
    write_json(output / "methodology.json", methodology)
    write_json(output / "provider_baseline_freeze.safe.json", provider_baseline_freeze)
    training_contamination_audit = _default_training_contamination_audit_for_campaign(runs_payload)
    write_json(output / "training_contamination_audit.json", training_contamination_audit)
    campaign = {
        "schema": "axio_fusion_api.benchmark_campaign.v1",
        "mode": "live" if live else "dry_run",
        "dataset_manifest_sha256": sha256_text(Path(dataset_manifest_path).read_text(encoding="utf-8")),
        "suite_spec_count": len(suite_specs),
        "candidate_count": len(candidates),
        "run_unit_count": len(run_units),
        "expected_run_count": len(suite_specs) * len(run_units),
        "completed_or_resumed_run_count": len(runs),
        "missing_suite_count": len(missing_suites),
        "missing_suites": missing_suites,
        "candidate_ids": list(candidates),
        "run_unit_ids": [str(unit.get("run_unit_id") or "") for unit in run_units],
        "api_surface_ids": [
            _api_surface_id_for_run_unit(unit)
            for unit in run_units
            if _is_axio_public_candidate(_candidate_id_for_run_unit(unit))
        ],
        "api_surface_contract": _api_surface_contract(),
        "artifacts": artifacts,
        "output_files": {
            "runs": "runs.json",
            "scorecard": "scorecard.json",
            "claim_audit": "claim_audit.json",
            "methodology": "methodology.json",
            "provider_probe_evidence_audit": "provider_probe_evidence_audit.safe.json",
            "provider_baseline_freeze": "provider_baseline_freeze.safe.json",
            "training_contamination_audit": "training_contamination_audit.json",
        },
        "claim_summary": {
            "all_required_suites_present": claim_audit.get("all_required_suites_present"),
            "all_final_claims_allowed": claim_audit.get("all_final_claims_allowed"),
            "final_claims": claim_audit.get("final_claims"),
            "missing_requirement_count": len(claim_audit.get("missing_requirements", [])) if isinstance(claim_audit.get("missing_requirements"), list) else None,
        },
        "benchmark_policy": benchmark_policy_safe_receipt,
        "policy": {
            "include_provider_baselines": bool(include_provider_baselines),
            "max_provider_baselines": max_provider_baselines if max_provider_baselines is None else int(max_provider_baselines),
            "provider_baseline_selection": str(selection_context.get("selection_mode") or ""),
            "available_provider_baseline_count": len(_provider_baseline_profiles(profiles)) if include_provider_baselines else 0,
            "provider_baseline_freeze_supplied": provider_baseline_freeze_path is not None,
            "provider_baseline_pre_registration_ready": selection_context.get("external_ranking_pre_registered") is True,
            "min_cases_per_suite": int(min_cases_per_suite),
            "alpha": float(alpha),
            "resume": bool(resume),
            "code_execution_enabled": _code_execution_enabled(),
            "benchmark_policy_sha256": str(benchmark_policy_safe_receipt.get("policy_sha256") or ""),
            "benchmark_target_reasoning_effort": str(benchmark_reasoning.get("target_effort") or ""),
            "native_max_reasoning_required": benchmark_reasoning.get("native_max_required") is True,
        },
        "provider_candidate_alias_policy": {
            "schema": "axio_fusion_api.provider_candidate_alias_policy.v1",
            "provider_candidate_hash_alias_required": True,
            "generated_provider_candidate_ids_use_profile_sha256": True,
            "legacy_provider_profile_ids_accepted_only_as_input": True,
            "raw_provider_candidate_ids_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "secrets_persisted": False,
        },
        "provider_baseline_census": _provider_baseline_census(
            profiles,
            selected_provider_baselines=selected_provider_baselines,
            max_provider_baselines=max_provider_baselines,
            include_provider_baselines=include_provider_baselines,
            source="registry_campaign",
            selection_context=selection_context,
        ),
        "provider_registry_receipt": provider_registry_receipt,
        "provider_probe_evidence_audit_receipt": provider_probe_evidence_audit_receipt,
        "provider_baseline_freeze_receipt": provider_baseline_freeze_receipt,
        "readiness_preflight_receipt": readiness_preflight_receipt,
        "strict_live_preflight": {
            "enabled": bool(live and strict_live_preflight),
            "status": "passed" if live and strict_live_preflight else "not_requested",
            "blocked_before_run_loop": False,
            "source_manifest_receipt": strict_source_manifest_receipt,
            "case_hash_manifest_receipt": strict_case_hash_manifest_receipt,
            "official_import_audit_receipt": strict_official_import_audit_receipt,
            "api_surface_protocol_receipt": strict_api_surface_protocol_receipt,
            "provider_input_adapter_receipt": strict_provider_input_adapter_receipt,
            "system_development_readiness_receipt": strict_system_development_readiness_receipt,
            "axio_http_gateway_receipt": strict_axio_http_gateway_receipt,
            "raw_paths_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        "methodology_receipt": methodology_receipt,
        "total_estimated_cost_usd": round(
            sum(_optional_float(run.get("estimated_cost_usd")) or 0.0 for run in runs),
            8,
        ),
        "cost_contract": _benchmark_cost_contract(),
        "latency_ms": round((time.monotonic() - started) * 1000, 3),
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }
    write_json(output / "campaign.json", campaign)
    return campaign


def _strict_live_preflight_blockers(
    *,
    readiness_preflight_receipt: Mapping[str, Any],
    provider_probe_evidence_audit_receipt: Mapping[str, Any],
    provider_baseline_freeze_receipt: Mapping[str, Any],
    source_manifest_receipt: Mapping[str, Any],
    case_hash_manifest_receipt: Mapping[str, Any],
    official_import_audit_receipt: Mapping[str, Any],
    api_surface_protocol_receipt: Mapping[str, Any],
    provider_input_adapter_receipt: Mapping[str, Any],
    system_development_readiness_receipt: Mapping[str, Any],
    axio_http_gateway_receipt: Mapping[str, Any],
) -> list[str]:
    blockers: list[str] = []
    if readiness_preflight_receipt.get("all_required_suites_ready") is not True:
        blockers.append("readiness_all_required_suites_not_ready")
    if readiness_preflight_receipt.get("will_claim_audit_be_possible") is not True:
        blockers.append("readiness_claim_audit_not_possible")
    if readiness_preflight_receipt.get("registry_final_claim_ready") is not True:
        blockers.append("readiness_registry_final_claim_not_ready")
    if readiness_preflight_receipt.get("registry_live_probe_proven") is not True:
        blockers.append("readiness_registry_live_probe_not_proven")
    if readiness_preflight_receipt.get("final_claim_provider_baselines_pre_registered") is not True:
        blockers.append("readiness_provider_baselines_not_pre_registered")
    if (_optional_int(readiness_preflight_receipt.get("provider_baseline_count")) or 0) < 3:
        blockers.append("readiness_fewer_than_three_provider_baselines")

    if provider_probe_evidence_audit_receipt.get("present") is not True:
        blockers.append("provider_probe_evidence_audit_missing")
    if provider_probe_evidence_audit_receipt.get("valid_json_object") is not True:
        blockers.append("provider_probe_evidence_audit_invalid_json")
    if provider_probe_evidence_audit_receipt.get("audit_ready") is not True:
        blockers.append("provider_probe_evidence_audit_not_ready")
    if provider_probe_evidence_audit_receipt.get("all_bindings_ready") is not True:
        blockers.append("provider_probe_evidence_bindings_not_ready")
    if provider_probe_evidence_audit_receipt.get("safe_artifacts_clean") is not True:
        blockers.append("provider_probe_evidence_safe_artifacts_not_clean")
    if provider_probe_evidence_audit_receipt.get("registry_file_matches_current_registry") is not True:
        blockers.append("provider_probe_evidence_registry_mismatch")
    if (_optional_int(provider_probe_evidence_audit_receipt.get("blocker_count")) or 0) > 0:
        blockers.append("provider_probe_evidence_audit_has_blockers")
    if provider_probe_evidence_audit_receipt.get("ready_for_baseline_freeze") is not True:
        blockers.append("provider_probe_evidence_not_ready_for_baseline_freeze")
    if provider_probe_evidence_audit_receipt.get("private_registry_live_probe_proven") is not True:
        blockers.append("provider_probe_evidence_private_registry_live_probe_not_proven")
    if provider_probe_evidence_audit_receipt.get("private_registry_final_claim_ready") is not True:
        blockers.append("provider_probe_evidence_private_registry_not_final_claim_ready")
    if (
        _optional_int(provider_probe_evidence_audit_receipt.get("private_probe_live_available_count")) or 0
    ) < max(3, _optional_int(provider_probe_evidence_audit_receipt.get("min_live_available_models")) or 3):
        blockers.append("provider_probe_evidence_live_available_model_count_too_small")

    if provider_baseline_freeze_receipt.get("present") is not True:
        blockers.append("provider_baseline_freeze_missing")
    if provider_baseline_freeze_receipt.get("freeze_digest_matches") is not True:
        blockers.append("provider_baseline_freeze_digest_mismatch")
    if provider_baseline_freeze_receipt.get("final_claim_freeze_ready") is not True:
        blockers.append("provider_baseline_freeze_not_ready")
    if provider_baseline_freeze_receipt.get("provider_probe_evidence_audit_bound") is not True:
        blockers.append("provider_baseline_freeze_probe_evidence_unbound")
    if provider_baseline_freeze_receipt.get("provider_probe_evidence_private_registry_live_probe_proven") is not True:
        blockers.append("provider_baseline_freeze_probe_evidence_registry_live_probe_not_proven")
    if provider_baseline_freeze_receipt.get("provider_probe_evidence_private_registry_final_claim_ready") is not True:
        blockers.append("provider_baseline_freeze_probe_evidence_registry_not_final_claim_ready")
    if (
        _optional_int(provider_baseline_freeze_receipt.get("provider_probe_evidence_private_probe_live_available_count"))
        or 0
    ) < max(3, _optional_int(provider_baseline_freeze_receipt.get("provider_probe_evidence_min_live_available_models")) or 3):
        blockers.append("provider_baseline_freeze_probe_evidence_live_available_model_count_too_small")
    if provider_baseline_freeze_receipt.get("provider_portfolio_summary_bound") is not True:
        blockers.append("provider_baseline_freeze_provider_portfolio_unbound")
    if provider_baseline_freeze_receipt.get("provider_portfolio_final_claim_ready") is not True:
        blockers.append("provider_baseline_freeze_provider_portfolio_not_final_claim_ready")
    if provider_baseline_freeze_receipt.get("provider_portfolio_independent_verification_ready") is not True:
        blockers.append("provider_baseline_freeze_provider_portfolio_independent_verification_not_ready")
    if provider_baseline_freeze_receipt.get("provider_portfolio_cross_provider_verifier_ready") is not True:
        blockers.append("provider_baseline_freeze_provider_portfolio_cross_provider_verifier_missing")
    if (_optional_int(provider_baseline_freeze_receipt.get("provider_portfolio_ready_verifier_count")) or 0) < 2:
        blockers.append("provider_baseline_freeze_provider_portfolio_insufficient_verifiers")
    if (_optional_int(provider_baseline_freeze_receipt.get("provider_portfolio_ready_provider_hash_count")) or 0) < 2:
        blockers.append("provider_baseline_freeze_provider_portfolio_insufficient_provider_diversity")
    if str(provider_baseline_freeze_receipt.get("provider_baseline_selection") or "") != EXTERNAL_PROVIDER_RANKING_SELECTION_MODE:
        blockers.append("provider_baseline_freeze_not_externally_ranked_top_three")
    if provider_baseline_freeze_receipt.get("external_ranking_ready") is not True:
        blockers.append("provider_baseline_freeze_external_ranking_not_ready")
    if provider_baseline_freeze_receipt.get("external_ranking_receipt_digest_matches") is not True:
        blockers.append("provider_baseline_freeze_external_ranking_receipt_digest_mismatch")
    if provider_baseline_freeze_receipt.get("external_ranking_mapping_valid") is not True:
        blockers.append("provider_baseline_freeze_external_ranking_mapping_invalid")
    for reason in provider_baseline_freeze_receipt.get("external_ranking_validation_errors", []):
        blockers.append(f"provider_baseline_freeze_{str(reason)}")
    if provider_baseline_freeze_receipt.get("external_ranking_pre_registered_before_campaign") is not True:
        blockers.append("provider_baseline_freeze_external_ranking_not_pre_registered")
    if provider_baseline_freeze_receipt.get("external_ranking_registry_file_matches_current_registry") is not True:
        blockers.append("provider_baseline_freeze_external_ranking_registry_mismatch")
    if provider_baseline_freeze_receipt.get("external_ranking_target_benchmark_material_detected") is True:
        blockers.append("provider_baseline_freeze_external_ranking_contains_target_benchmark_material")
    if sorted(provider_baseline_freeze_receipt.get("external_ranking_rank_values") or []) != list(EXTERNAL_PROVIDER_RANKING_REQUIRED_RANKS):
        blockers.append("provider_baseline_freeze_external_ranking_top_three_incomplete")
    if (_optional_int(provider_baseline_freeze_receipt.get("selected_provider_baseline_count")) or 0) < 3:
        blockers.append("provider_baseline_freeze_fewer_than_three_baselines")
    if (_optional_int(provider_baseline_freeze_receipt.get("selected_live_probe_evidence_count")) or 0) < 3:
        blockers.append("provider_baseline_freeze_insufficient_live_probe_evidence")

    if source_manifest_receipt.get("final_claim_eligible") is not True:
        blockers.append("source_manifest_not_final_claim_eligible")
    source_reason_codes = source_manifest_receipt.get("reason_codes") if isinstance(source_manifest_receipt.get("reason_codes"), list) else []
    for reason in source_reason_codes:
        blockers.append(f"source_manifest_{str(reason)}")

    if case_hash_manifest_receipt.get("all_required_case_manifests_ready") is not True:
        blockers.append("case_hash_manifest_not_ready")
    if case_hash_manifest_receipt.get("source_digest_match") is not True:
        blockers.append("case_hash_manifest_source_digest_mismatch")
    if case_hash_manifest_receipt.get("binding_receipt_valid_for_current_inputs") is not True:
        blockers.append("source_manifest_case_hash_binding_receipt_invalid")
    case_reason_codes = case_hash_manifest_receipt.get("reason_codes") if isinstance(case_hash_manifest_receipt.get("reason_codes"), list) else []
    for reason in case_reason_codes:
        blockers.append(f"case_hash_manifest_{str(reason)}")

    if official_import_audit_receipt.get("ready_for_campaign_preflight") is not True:
        blockers.append("official_import_audit_not_ready_for_campaign_preflight")
    official_reason_codes = official_import_audit_receipt.get("reason_codes") if isinstance(official_import_audit_receipt.get("reason_codes"), list) else []
    for reason in official_reason_codes:
        blockers.append(f"official_import_audit_{str(reason)}")

    if api_surface_protocol_receipt.get("ready_for_campaign_preflight") is not True:
        blockers.append("api_surface_protocol_self_test_not_ready_for_campaign_preflight")
    api_reason_codes = api_surface_protocol_receipt.get("reason_codes") if isinstance(api_surface_protocol_receipt.get("reason_codes"), list) else []
    for reason in api_reason_codes:
        blockers.append(f"api_surface_protocol_{str(reason)}")

    if provider_input_adapter_receipt.get("ready_for_campaign_preflight") is not True:
        blockers.append("provider_input_adapter_self_test_not_ready_for_campaign_preflight")
    adapter_reason_codes = provider_input_adapter_receipt.get("reason_codes") if isinstance(provider_input_adapter_receipt.get("reason_codes"), list) else []
    for reason in adapter_reason_codes:
        blockers.append(f"provider_input_adapter_{str(reason)}")

    if system_development_readiness_receipt.get("provided") is not True:
        blockers.append("system_development_readiness_missing")
    if system_development_readiness_receipt.get("exists") is not True:
        blockers.append("system_development_readiness_path_not_found")
    if system_development_readiness_receipt.get("valid_json_object") is not True:
        blockers.append("system_development_readiness_invalid_json")
    if system_development_readiness_receipt.get("ready_for_campaign_preflight") is not True:
        blockers.append("system_development_readiness_not_ready_for_campaign_preflight")
    system_reason_codes = (
        system_development_readiness_receipt.get("reason_codes")
        if isinstance(system_development_readiness_receipt.get("reason_codes"), list)
        else []
    )
    for reason in system_reason_codes:
        blockers.append(f"system_development_readiness_{str(reason)}")
    if axio_http_gateway_receipt.get("required") is True:
        if axio_http_gateway_receipt.get("configured") is not True:
            blockers.append("axio_http_gateway_missing")
        if axio_http_gateway_receipt.get("valid") is not True:
            blockers.append("axio_http_gateway_invalid")
        if axio_http_gateway_receipt.get("ready_for_campaign_preflight") is not True:
            blockers.append("axio_http_gateway_not_ready_for_campaign_preflight")
        gateway_reason_codes = (
            axio_http_gateway_receipt.get("reason_codes")
            if isinstance(axio_http_gateway_receipt.get("reason_codes"), list)
            else []
        )
        for reason in gateway_reason_codes:
            blockers.append(f"axio_http_gateway_{str(reason)}")
    return sorted(set(blockers))


def _strict_live_axio_http_gateway_preflight_receipt(
    *,
    axio_gateway_url: str | None,
    run_units: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Validate only the shape of the public Axio gateway before live work.

    This is deliberately non-networked.  It prevents a strict campaign from
    silently falling back to the in-process handler while ensuring no raw URL,
    credentials, prompts, or provider metadata enter the campaign artifact.
    """

    requires_gateway = any(
        _is_axio_public_candidate(_candidate_id_for_run_unit(unit))
        for unit in run_units
        if isinstance(unit, Mapping)
    )
    raw_value = str(axio_gateway_url or os.getenv("AXIO_FUSION_BENCHMARK_GATEWAY_URL") or "").strip()
    reason_codes: list[str] = []
    normalized = ""
    if requires_gateway:
        if not raw_value:
            reason_codes.append("missing")
        else:
            try:
                normalized = _benchmark_gateway_url(raw_value)
            except BenchmarkPublicApiInvocationError as exc:
                code = str(exc) or "invalid"
                if code == "public_api_gateway_url_must_not_embed_credentials":
                    reason_codes.append("embedded_credentials_or_query")
                else:
                    reason_codes.append("invalid")
    valid = bool(normalized) and not reason_codes if requires_gateway else True
    return {
        "schema": "axio_fusion_api.strict_live_axio_http_gateway_preflight_receipt.v1",
        "required": requires_gateway,
        "configured": bool(raw_value),
        "valid": valid,
        "ready_for_campaign_preflight": (not requires_gateway) or valid,
        "gateway_url_sha256": sha256_text(normalized) if normalized else "",
        "scheme": "https" if normalized.startswith("https://") else "http" if normalized.startswith("http://") else "",
        "reason_codes": sorted(set(reason_codes)),
        "network_calls_performed": False,
        "raw_gateway_url_persisted": False,
        "raw_paths_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _strict_live_source_manifest_preflight_receipt(
    *,
    source_manifest_path: str | Path | None,
    min_cases_per_suite: int,
) -> dict[str, Any]:
    summary, missing = _final_source_manifest_summary(
        source_manifest_path=source_manifest_path,
        min_cases_per_suite=min_cases_per_suite,
    )
    reason_codes = sorted({str(row.get("kind") or "") for row in missing if isinstance(row, Mapping) and str(row.get("kind") or "")})
    return {
        "schema": "axio_fusion_api.strict_live_source_manifest_preflight_receipt.v1",
        "provided": source_manifest_path is not None,
        "path_sha256": sha256_text(str(source_manifest_path)) if source_manifest_path else "",
        "source_manifest_schema": str(summary.get("source_manifest_schema") or ""),
        "required_suite_count": _optional_int(summary.get("required_suite_count")) or len(BENCHMARK_SUITES),
        "ready_suite_count": _optional_int(summary.get("ready_suite_count")) or 0,
        "all_required_sources_ready": summary.get("all_required_sources_ready") is True,
        "final_claim_eligible": summary.get("final_claim_eligible") is True,
        "reason_codes": reason_codes,
        "missing_kind_count": len(reason_codes),
        "missing_kind_digest_sha256": sha256_text(stable_json(reason_codes)),
        "blocking_reason_counts": dict(summary.get("blocking_reason_counts") or {}),
        "raw_source_manifest_path_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _strict_live_case_hash_manifest_preflight_receipt(
    *,
    case_hash_manifest_path: str | Path | None,
    source_manifest_path: str | Path | None,
    min_cases_per_suite: int,
) -> dict[str, Any]:
    summary, missing = _final_case_hash_manifest_summary(
        case_hash_manifest_path=case_hash_manifest_path,
        source_manifest_path=source_manifest_path,
        min_cases_per_suite=min_cases_per_suite,
    )
    binding = summary.get("binding_receipt_summary") if isinstance(summary.get("binding_receipt_summary"), Mapping) else {}
    reason_codes = sorted({str(row.get("kind") or "") for row in missing if isinstance(row, Mapping) and str(row.get("kind") or "")})
    return {
        "schema": "axio_fusion_api.strict_live_case_hash_manifest_preflight_receipt.v1",
        "provided": case_hash_manifest_path is not None,
        "path_sha256": sha256_text(str(case_hash_manifest_path)) if case_hash_manifest_path else "",
        "case_hash_manifest_schema": str(summary.get("schema") or ""),
        "required_suite_count": _optional_int(summary.get("required_suite_count")) or len(BENCHMARK_SUITES),
        "ready_suite_count": _optional_int(summary.get("ready_suite_count")) or 0,
        "all_required_case_manifests_ready": summary.get("all_required_case_manifests_ready") is True,
        "source_digest_match": summary.get("source_digest_match") is True,
        "binding_receipt_valid_for_current_inputs": binding.get("binding_receipt_valid_for_current_inputs") is True,
        "case_hash_manifest_sha256_matches_current": binding.get("case_hash_manifest_sha256_matches_current") is True,
        "reason_codes": reason_codes,
        "missing_kind_count": len(reason_codes),
        "missing_kind_digest_sha256": sha256_text(stable_json(reason_codes)),
        "blocking_reason_counts": dict(summary.get("blocking_reason_counts") or {}),
        "raw_case_hash_manifest_path_persisted": False,
        "raw_source_manifest_path_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _strict_live_official_import_audit_preflight_receipt(
    *,
    official_import_audit_path: str | Path | None,
) -> dict[str, Any]:
    artifact = _load_json_artifact(Path(official_import_audit_path) if official_import_audit_path else None)
    payload = artifact["payload"] if artifact.get("valid_json_object") is True else {}
    reason_codes: list[str] = []
    if official_import_audit_path is None:
        reason_codes.append("missing_official_import_audit_path")
    elif artifact.get("exists") is not True:
        reason_codes.append("official_import_audit_path_not_found")
    if artifact.get("valid_json_object") is not True:
        reason_codes.append("official_import_audit_invalid_json")
    if str(payload.get("schema") or "") != "axio_fusion_api.official_import_audit.v1":
        reason_codes.append("official_import_audit_schema_unrecognized")
    if payload.get("ready_for_campaign_import_stage") is not True:
        reason_codes.append("official_import_audit_not_ready")
    official_suite_count = _optional_int(payload.get("official_suite_count")) or 0
    ready_suite_count = _optional_int(payload.get("ready_official_suite_count")) or 0
    blocked_suite_count = _optional_int(payload.get("blocked_official_suite_count")) or 0
    expected_official_suite_count = sum(
        1 for suite in BENCHMARK_SUITES if _suite_requires_official_harness(suite.suite_id, suite.task_format)
    )
    if official_suite_count != expected_official_suite_count:
        reason_codes.append("official_suite_count_mismatch")
    if ready_suite_count != official_suite_count:
        reason_codes.append("ready_official_suite_count_incomplete")
    if blocked_suite_count:
        reason_codes.append("blocked_official_suites_present")
    blocking_reason_counts = dict(payload.get("blocking_reason_counts") or {}) if isinstance(payload.get("blocking_reason_counts"), Mapping) else {}
    if blocking_reason_counts:
        reason_codes.append("blocking_reason_counts_present")
    alignment = payload.get("run_alignment_summary") if isinstance(payload.get("run_alignment_summary"), Mapping) else {}
    run_set_receipt = alignment.get("run_set_receipt") if isinstance(alignment.get("run_set_receipt"), Mapping) else {}
    audit_run_set_digest = str(run_set_receipt.get("run_set_digest_sha256") or "")
    if not run_set_receipt:
        reason_codes.append("run_set_receipt_missing")
    elif not _looks_like_sha256(audit_run_set_digest):
        reason_codes.append("run_set_digest_missing")
    raw_persistence = bool(payload) and _contains_true_raw_persisted_flag(payload)
    forbidden_persistence = bool(payload) and _contains_forbidden_persistence_flag(payload)
    if raw_persistence:
        reason_codes.append("raw_persistence_flag_detected")
    if forbidden_persistence:
        reason_codes.append("forbidden_persistence_flag_detected")
    clean_reasons = sorted(set(reason_codes))
    return {
        "schema": "axio_fusion_api.strict_live_official_import_audit_preflight_receipt.v1",
        "provided": official_import_audit_path is not None,
        "exists": artifact.get("exists") is True,
        "valid_json_object": artifact.get("valid_json_object") is True,
        "path_sha256": sha256_text(str(official_import_audit_path)) if official_import_audit_path else "",
        "official_import_audit_schema": str(payload.get("schema") or ""),
        "ready_for_campaign_preflight": not clean_reasons,
        "ready_for_campaign_import_stage": payload.get("ready_for_campaign_import_stage") is True,
        "official_suite_count": official_suite_count,
        "expected_official_suite_count": expected_official_suite_count,
        "ready_official_suite_count": ready_suite_count,
        "blocked_official_suite_count": blocked_suite_count,
        "audit_run_count": _optional_int(run_set_receipt.get("run_count")) or 0,
        "audit_run_set_digest_sha256": audit_run_set_digest if _looks_like_sha256(audit_run_set_digest) else "",
        "blocking_reason_counts": blocking_reason_counts,
        "reason_codes": clean_reasons,
        "reason_digest_sha256": sha256_text(stable_json(clean_reasons)),
        "raw_candidate_ids_persisted": False,
        "raw_import_paths_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _strict_live_api_surface_protocol_preflight_receipt(
    *,
    api_surface_protocol_path: str | Path | None,
) -> dict[str, Any]:
    artifact = _load_json_artifact(Path(api_surface_protocol_path) if api_surface_protocol_path else None)
    payload = artifact["payload"] if artifact.get("valid_json_object") is True else {}
    reason_codes: list[str] = []
    if api_surface_protocol_path is None:
        reason_codes.append("missing_api_surface_protocol_path")
    elif artifact.get("exists") is not True:
        reason_codes.append("api_surface_protocol_path_not_found")
    if artifact.get("valid_json_object") is not True:
        reason_codes.append("api_surface_protocol_invalid_json")
    if str(payload.get("schema") or "") != "axio_fusion_api.api_surface_protocol_self_test.v1":
        reason_codes.append("api_surface_protocol_schema_unrecognized")
    if payload.get("all_required_protocols_ready") is not True:
        reason_codes.append("api_surface_protocol_not_ready")
    if payload.get("all_models_route_consistent_across_surfaces") is not True:
        reason_codes.append("api_surface_protocol_route_consistency_not_ready")
    if (_optional_int(payload.get("public_model_count")) or 0) != len(AXIO_BENCHMARK_PUBLIC_MODELS):
        reason_codes.append("api_surface_protocol_public_model_count_mismatch")
    if (_optional_int(payload.get("api_surface_count")) or 0) != len(AXIO_BENCHMARK_API_FORMATS):
        reason_codes.append("api_surface_protocol_surface_count_mismatch")
    missing_surfaces = payload.get("missing_api_surfaces") if isinstance(payload.get("missing_api_surfaces"), list) else []
    if missing_surfaces:
        reason_codes.append("api_surface_protocol_missing_surfaces")
    if _contains_true_raw_persisted_flag(payload) or _contains_forbidden_persistence_flag(payload):
        reason_codes.append("api_surface_protocol_forbidden_persistence_flag")
    clean_reasons = sorted(set(reason_codes))
    return {
        "schema": "axio_fusion_api.strict_live_api_surface_protocol_preflight_receipt.v1",
        "provided": api_surface_protocol_path is not None,
        "exists": artifact.get("exists") is True,
        "valid_json_object": artifact.get("valid_json_object") is True,
        "path_sha256": sha256_text(str(api_surface_protocol_path)) if api_surface_protocol_path else "",
        "api_surface_protocol_schema": str(payload.get("schema") or ""),
        "ready_for_campaign_preflight": not clean_reasons,
        "all_required_protocols_ready": payload.get("all_required_protocols_ready") is True,
        "all_models_route_consistent_across_surfaces": payload.get("all_models_route_consistent_across_surfaces") is True,
        "public_model_count": _optional_int(payload.get("public_model_count")) or 0,
        "api_surface_count": _optional_int(payload.get("api_surface_count")) or 0,
        "reason_codes": clean_reasons,
        "reason_digest_sha256": sha256_text(stable_json(clean_reasons)),
        "raw_paths_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


