def _strict_live_system_development_readiness_preflight_receipt(
    *,
    system_development_readiness_path: str | Path | None,
) -> dict[str, Any]:
    artifact = _load_json_artifact(
        Path(system_development_readiness_path) if system_development_readiness_path else None
    )
    payload = artifact["payload"] if artifact.get("valid_json_object") is True else {}
    process_contract = payload.get("process_contract") if isinstance(payload.get("process_contract"), Mapping) else {}
    requirements = payload.get("requirements") if isinstance(payload.get("requirements"), list) else []
    remote_execution_requirement = next(
        (
            row
            for row in requirements
            if isinstance(row, Mapping)
            and str(row.get("requirement_id") or "") == "remote_api_execution_boundary"
        ),
        {},
    )
    remote_execution_audit = (
        payload.get("remote_api_execution_audit")
        if isinstance(payload.get("remote_api_execution_audit"), Mapping)
        else {}
    )
    remote_execution_reasons = _remote_api_execution_audit_reasons(remote_execution_audit)
    reason_codes: list[str] = []
    if system_development_readiness_path is None:
        reason_codes.append("missing_system_development_readiness_path")
    elif artifact.get("exists") is not True:
        reason_codes.append("system_development_readiness_path_not_found")
    if artifact.get("valid_json_object") is not True:
        reason_codes.append("system_development_readiness_invalid_json")
    if str(payload.get("schema") or "") != "axio_fusion_api.system_development_readiness.v1":
        reason_codes.append("system_development_readiness_schema_unrecognized")
    if payload.get("system_development_ready") is not True:
        reason_codes.append("system_development_not_ready")
    if payload.get("ready_for_21_suite_benchmark_validation") is not True:
        reason_codes.append("benchmark_validation_not_ready")
    if str(payload.get("benchmark_validation_status") or "") != "separate_not_run_by_this_audit":
        reason_codes.append("benchmark_validation_status_not_separate")
    if payload.get("final_model_superiority_claimed") is not False:
        reason_codes.append("final_model_superiority_claimed")
    if payload.get("final_completion_claimed") is not False:
        reason_codes.append("final_completion_claimed")
    if _optional_int(payload.get("required_suite_count_for_next_stage")) != len(BENCHMARK_SUITES):
        reason_codes.append("required_suite_count_mismatch")
    if _optional_int(payload.get("required_category_count_for_next_stage")) != len(BENCHMARK_CATEGORY_REQUIRED_SUITE_COUNTS):
        reason_codes.append("required_category_count_mismatch")
    if (_optional_int(payload.get("blocked_requirement_count")) or 0) > 0:
        reason_codes.append("blocked_requirements_present")
    if payload.get("standalone_product") is not True or payload.get("decoupled_from_asci_fs") is not True:
        reason_codes.append("standalone_workspace_contract_missing")
    if payload.get("network_calls_performed") is True:
        reason_codes.append("network_calls_performed")
    if not remote_execution_requirement:
        reason_codes.append("remote_api_execution_boundary_requirement_missing")
    elif remote_execution_requirement.get("status") != "proven":
        reason_codes.append("remote_api_execution_boundary_requirement_not_proven")
    if remote_execution_reasons:
        reason_codes.extend(remote_execution_reasons)
    for key, reason in (
        ("system_development_audit_does_not_run_llm_benchmarks", "process_contract_llm_benchmark_separation_missing"),
        ("system_development_audit_does_not_claim_model_superiority", "process_contract_no_superiority_claim_missing"),
        ("system_development_audit_uses_no_local_model_weights", "process_contract_no_local_weights_missing"),
        ("model_execution_requires_remote_http_provider_api", "process_contract_remote_http_provider_api_missing"),
        ("next_stage_requires_9_category_21_suite_llm_benchmark", "process_contract_next_stage_21_suite_missing"),
        (
            "final_completion_requires_axio_tiers_to_beat_corresponding_single_model_baselines",
            "process_contract_final_baseline_requirement_missing",
        ),
        ("final_completion_requires_latency_within_3x", "process_contract_latency_gate_missing"),
    ):
        if process_contract.get(key) is not True:
            reason_codes.append(reason)
    if _contains_true_raw_persisted_flag(payload) or _contains_forbidden_persistence_flag(payload):
        reason_codes.append("system_development_readiness_forbidden_persistence_flag")
    clean_reasons = sorted(set(reason_codes))
    return {
        "schema": "axio_fusion_api.strict_live_system_development_readiness_preflight_receipt.v1",
        "provided": system_development_readiness_path is not None,
        "exists": artifact.get("exists") is True,
        "valid_json_object": artifact.get("valid_json_object") is True,
        "path_sha256": sha256_text(str(system_development_readiness_path)) if system_development_readiness_path else "",
        "system_development_readiness_schema": str(payload.get("schema") or ""),
        "ready_for_campaign_preflight": not clean_reasons,
        "system_development_ready": payload.get("system_development_ready") is True,
        "ready_for_21_suite_benchmark_validation": payload.get("ready_for_21_suite_benchmark_validation") is True,
        "benchmark_validation_status": str(payload.get("benchmark_validation_status") or ""),
        "final_model_superiority_claimed": payload.get("final_model_superiority_claimed") is True,
        "final_completion_claimed": payload.get("final_completion_claimed") is True,
        "required_suite_count_for_next_stage": _optional_int(payload.get("required_suite_count_for_next_stage")) or 0,
        "required_category_count_for_next_stage": _optional_int(payload.get("required_category_count_for_next_stage")) or 0,
        "requirement_count": _optional_int(payload.get("requirement_count")) or 0,
        "proven_requirement_count": _optional_int(payload.get("proven_requirement_count")) or 0,
        "blocked_requirement_count": _optional_int(payload.get("blocked_requirement_count")) or 0,
        "remote_api_execution_boundary_ready": (
            bool(remote_execution_requirement)
            and remote_execution_requirement.get("status") == "proven"
            and not remote_execution_reasons
        ),
        "remote_api_execution_audit_digest_sha256": (
            sha256_text(stable_json(remote_execution_audit)) if remote_execution_audit else ""
        ),
        "process_contract": {
            "system_development_audit_does_not_run_llm_benchmarks": process_contract.get(
                "system_development_audit_does_not_run_llm_benchmarks"
            )
            is True,
            "system_development_audit_does_not_claim_model_superiority": process_contract.get(
                "system_development_audit_does_not_claim_model_superiority"
            )
            is True,
            "system_development_audit_uses_no_local_model_weights": process_contract.get(
                "system_development_audit_uses_no_local_model_weights"
            )
            is True,
            "model_execution_requires_remote_http_provider_api": process_contract.get(
                "model_execution_requires_remote_http_provider_api"
            )
            is True,
            "next_stage_requires_9_category_21_suite_llm_benchmark": process_contract.get(
                "next_stage_requires_9_category_21_suite_llm_benchmark"
            )
            is True,
            "final_completion_requires_axio_tiers_to_beat_corresponding_single_model_baselines": process_contract.get(
                "final_completion_requires_axio_tiers_to_beat_corresponding_single_model_baselines"
            )
            is True,
            "final_completion_requires_latency_within_3x": process_contract.get(
                "final_completion_requires_latency_within_3x"
            )
            is True,
        },
        "reason_codes": clean_reasons,
        "reason_digest_sha256": sha256_text(stable_json(clean_reasons)),
        "raw_paths_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _write_strict_live_preflight_blocked_campaign(
    *,
    dataset_manifest_path: str | Path,
    output: Path,
    suite_specs: Sequence[Mapping[str, Any]],
    candidates: Sequence[str],
    run_units: Sequence[Mapping[str, Any]],
    profiles: Sequence[ModelProfile],
    selected_provider_baselines: Sequence[ModelProfile],
    selection_context: Mapping[str, Any],
    include_provider_baselines: bool,
    max_provider_baselines: int | None,
    min_cases_per_suite: int,
    alpha: float,
    resume: bool,
    blockers: Sequence[str],
    readiness_preflight_receipt: Mapping[str, Any],
    provider_registry_receipt: Mapping[str, Any],
    provider_probe_evidence_audit_receipt: Mapping[str, Any],
    provider_baseline_freeze: Mapping[str, Any],
    provider_baseline_freeze_receipt: Mapping[str, Any],
    source_manifest_receipt: Mapping[str, Any],
    case_hash_manifest_receipt: Mapping[str, Any],
    official_import_audit_receipt: Mapping[str, Any],
    api_surface_protocol_receipt: Mapping[str, Any],
    provider_input_adapter_receipt: Mapping[str, Any],
    system_development_readiness_receipt: Mapping[str, Any],
    axio_http_gateway_receipt: Mapping[str, Any],
    benchmark_policy_safe_receipt: Mapping[str, Any],
    benchmark_policy: Mapping[str, Any],
    native_max_required: bool,
    required_reasoning_effort: str,
) -> dict[str, Any]:
    started = time.monotonic()
    output.mkdir(parents=True, exist_ok=True)
    (output / "runs").mkdir(parents=True, exist_ok=True)
    runs_payload = build_benchmark_runs_payload([])
    scorecard = build_benchmark_scorecard([])
    claim_audit = build_benchmark_claim_audit(
        [],
        min_cases_per_suite=min_cases_per_suite,
        alpha=alpha,
        native_max_required=native_max_required,
        required_reasoning_effort=required_reasoning_effort,
    )
    methodology = build_benchmark_methodology_manifest(
        dataset_manifest_path=dataset_manifest_path,
        benchmark_policy=benchmark_policy,
    )
    methodology_receipt = _benchmark_methodology_receipt(methodology)
    training_contamination_audit = _default_training_contamination_audit_for_campaign(runs_payload)
    write_json(output / "runs.json", runs_payload)
    write_json(output / "scorecard.json", scorecard)
    write_json(output / "claim_audit.json", claim_audit)
    write_json(output / "methodology.json", methodology)
    write_json(output / "provider_baseline_freeze.safe.json", provider_baseline_freeze)
    write_json(output / "training_contamination_audit.json", training_contamination_audit)
    probe_evidence_output = output / "provider_probe_evidence_audit.safe.json"
    if not probe_evidence_output.exists():
        write_json(
            probe_evidence_output,
            _strict_live_preflight_probe_evidence_placeholder(provider_probe_evidence_audit_receipt),
        )
    campaign = {
        "schema": "axio_fusion_api.benchmark_campaign.v1",
        "mode": "live_preflight_blocked",
        "status": "blocked",
        "dataset_manifest_sha256": sha256_text(Path(dataset_manifest_path).read_text(encoding="utf-8")),
        "suite_spec_count": len(suite_specs),
        "candidate_count": len(candidates),
        "run_unit_count": len(run_units),
        "expected_run_count": len(suite_specs) * len(run_units),
        "completed_or_resumed_run_count": 0,
        "missing_suite_count": 0,
        "missing_suites": [],
        "candidate_ids": list(candidates),
        "run_unit_ids": [str(unit.get("run_unit_id") or "") for unit in run_units],
        "api_surface_ids": [
            _api_surface_id_for_run_unit(unit)
            for unit in run_units
            if _is_axio_public_candidate(_candidate_id_for_run_unit(unit))
        ],
        "api_surface_contract": _api_surface_contract(),
        "artifacts": [],
        "output_files": {
            "runs": "runs.json",
            "scorecard": "scorecard.json",
            "claim_audit": "claim_audit.json",
            "methodology": "methodology.json",
            "provider_probe_evidence_audit": "provider_probe_evidence_audit.safe.json",
            "provider_baseline_freeze": "provider_baseline_freeze.safe.json",
            "training_contamination_audit": "training_contamination_audit.json",
        },
        "strict_live_preflight": {
            "enabled": True,
            "status": "blocked",
            "blocked_before_run_loop": True,
            "network_calls_performed": False,
            "provider_call_count": 0,
            "blocker_count": len(set(blockers)),
            "blockers": sorted(set(str(reason) for reason in blockers if reason)),
            "readiness_preflight_receipt": dict(readiness_preflight_receipt),
            "provider_probe_evidence_audit_receipt": dict(provider_probe_evidence_audit_receipt),
            "provider_baseline_freeze_receipt": dict(provider_baseline_freeze_receipt),
            "source_manifest_receipt": dict(source_manifest_receipt),
            "case_hash_manifest_receipt": dict(case_hash_manifest_receipt),
            "official_import_audit_receipt": dict(official_import_audit_receipt),
            "api_surface_protocol_receipt": dict(api_surface_protocol_receipt),
            "provider_input_adapter_receipt": dict(provider_input_adapter_receipt),
            "system_development_readiness_receipt": dict(system_development_readiness_receipt),
            "axio_http_gateway_receipt": dict(axio_http_gateway_receipt),
            "raw_paths_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        "claim_summary": {
            "all_required_suites_present": claim_audit.get("all_required_suites_present"),
            "all_final_claims_allowed": claim_audit.get("all_final_claims_allowed"),
            "final_claims": claim_audit.get("final_claims"),
            "missing_requirement_count": len(claim_audit.get("missing_requirements", [])) if isinstance(claim_audit.get("missing_requirements"), list) else None,
        },
        "benchmark_policy": dict(benchmark_policy_safe_receipt),
        "policy": {
            "include_provider_baselines": bool(include_provider_baselines),
            "max_provider_baselines": max_provider_baselines if max_provider_baselines is None else int(max_provider_baselines),
            "provider_baseline_selection": str(selection_context.get("selection_mode") or ""),
            "available_provider_baseline_count": len(_provider_baseline_profiles(profiles)) if include_provider_baselines else 0,
            "min_cases_per_suite": int(min_cases_per_suite),
            "alpha": float(alpha),
            "resume": bool(resume),
            "strict_live_preflight": True,
            "code_execution_enabled": _code_execution_enabled(),
            "benchmark_target_reasoning_effort": str(required_reasoning_effort or ""),
            "native_max_reasoning_required": bool(native_max_required),
        },
        "provider_candidate_alias_policy": {
            "schema": "axio_fusion_api.provider_candidate_alias_policy.v1",
            "provider_candidate_hash_alias_required": True,
            "generated_provider_candidate_ids_use_profile_sha256": True,
            "legacy_provider_profile_ids_accepted_only_as_input": True,
            "raw_provider_candidate_ids_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "secrets_persisted": False,
        },
        "provider_baseline_census": _provider_baseline_census(
            profiles,
            selected_provider_baselines=selected_provider_baselines,
            max_provider_baselines=max_provider_baselines,
            include_provider_baselines=include_provider_baselines,
            source="registry_campaign",
            selection_context=selection_context,
        ),
        "provider_registry_receipt": provider_registry_receipt,
        "provider_probe_evidence_audit_receipt": provider_probe_evidence_audit_receipt,
        "provider_baseline_freeze_receipt": provider_baseline_freeze_receipt,
        "readiness_preflight_receipt": readiness_preflight_receipt,
        "methodology_receipt": methodology_receipt,
        "total_estimated_cost_usd": 0.0,
        "cost_contract": _benchmark_cost_contract(),
        "latency_ms": round((time.monotonic() - started) * 1000, 3),
        "network_calls_performed": False,
        "provider_call_count": 0,
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }
    write_json(output / "campaign.json", campaign)
    return campaign


def _strict_live_preflight_probe_evidence_placeholder(receipt: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "schema": "axio_fusion_api.provider_probe_evidence_audit.placeholder.v1",
        "status": "blocked",
        "ready": False,
        "reason_codes": ["strict_live_preflight_missing_ready_probe_evidence_audit"],
        "receipt": dict(receipt),
        "raw_paths_persisted": False,
        "raw_provider_names_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_provider_urls_persisted": False,
        "raw_api_keys_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _campaign_provider_probe_evidence_audit_path(
    explicit_path: str | Path | None,
    *,
    output_dir: Path,
) -> Path:
    if explicit_path:
        return Path(explicit_path)
    return output_dir / "provider_probe_evidence_audit.safe.json"


def _provider_probe_evidence_audit_copy_allowed(payload: Any) -> bool:
    if not isinstance(payload, Mapping):
        return False
    if str(payload.get("schema") or "") != "axio_fusion_api.provider_probe_evidence_audit.v1":
        return False
    if _contains_true_raw_persisted_flag(payload):
        return False
    leakage = payload.get("anti_leakage_audit") if isinstance(payload.get("anti_leakage_audit"), Mapping) else {}
    leakage_clean = (
        leakage.get("safe_artifacts_do_not_contain_private_identifiers") is True
        and leakage.get("safe_artifacts_have_no_true_raw_persistence_flags") is True
        and leakage.get("safe_artifacts_have_no_true_secret_persistence_flags") is True
        and leakage.get("safe_artifacts_have_no_raw_urls") is True
        and leakage.get("safe_artifacts_have_no_api_key_like_values") is True
    )
    if not leakage_clean:
        return False
    serialized = stable_json(payload)
    if re.search(r"https?://", serialized):
        return False
    return re.search(r"\b(?:sk|nvapi|xoxb|AIza)[A-Za-z0-9_\-]{12,}\b", serialized) is None


def _provider_baseline_freeze_copy_allowed(payload: Any) -> bool:
    if not isinstance(payload, Mapping):
        return False
    if str(payload.get("schema") or "") != "axio_fusion_api.provider_baseline_freeze_manifest.v1":
        return False
    if _contains_true_raw_persisted_flag(payload):
        return False
    external_ranking_receipt = (
        payload.get("external_ranking_receipt")
        if isinstance(payload.get("external_ranking_receipt"), Mapping)
        else {}
    )
    if external_ranking_receipt and _external_provider_ranking_safe_artifact_has_raw_fields(
        external_ranking_receipt
    ):
        return False
    serialized = stable_json(payload)
    if re.search(r"https?://", serialized):
        return False
    if re.search(r"\b(?:sk|nvapi|xoxb|AIza)[A-Za-z0-9_\-]{12,}\b", serialized):
        return False
    return True


def build_benchmark_campaign_progress_plan(
    *,
    dataset_manifest_path: str | Path,
    output_dir: str | Path,
    registry_path: str | Path | None = None,
    candidate_ids: Sequence[str] = (),
    include_provider_baselines: bool = True,
    max_provider_baselines: int | None = 3,
    provider_baseline_freeze_path: str | Path | None = None,
    min_cases_per_suite: int = 100,
) -> dict[str, Any]:
    """Build a hash-only resume/repair plan for a benchmark campaign."""

    manifest = _load_dataset_manifest(dataset_manifest_path)
    suite_specs = _campaign_suite_specs(manifest)
    profiles = load_registry(registry_path)
    selection_context = _provider_baseline_selection_context(
        profiles,
        include_provider_baselines=include_provider_baselines,
        max_provider_baselines=max_provider_baselines,
        provider_baseline_freeze_path=provider_baseline_freeze_path,
        registry_path=registry_path,
    )
    candidates = _campaign_candidate_ids(
        profiles,
        candidate_ids=candidate_ids,
        include_provider_baselines=include_provider_baselines,
        max_provider_baselines=max_provider_baselines,
        provider_baseline_freeze_path=provider_baseline_freeze_path,
        registry_path=registry_path,
    )
    run_units = _run_units_from_candidate_ids(profiles, candidates)
    output = Path(output_dir)
    runs_dir = output / "runs"
    rows = []
    suite_counts: dict[str, dict[str, Any]] = {}
    candidate_counts: dict[str, dict[str, Any]] = {}
    api_surface_counts: dict[str, dict[str, int]] = {}
    for spec in suite_specs:
        suite_id = str(spec.get("suite_id") or "")
        if not suite_id:
            continue
        suite = _suite_by_id(suite_id)
        category = suite.category if suite else str(spec.get("category") or "")
        suite_bucket = suite_counts.setdefault(
            suite_id,
            {
                "suite_id": suite_id,
                "category": category,
                "expected_run_count": 0,
                "completed_run_count": 0,
                "missing_run_count": 0,
                "invalid_run_count": 0,
            },
        )
        for unit in run_units:
            run_unit_id = str(unit.get("run_unit_id") or _api_surface_id_for_run_unit(unit))
            candidate_id = _candidate_id_for_run_unit(unit)
            api_format = _api_format_for_run_unit(unit)
            candidate_type = str(unit.get("candidate_type") or "")
            run_path = runs_dir / f"{_safe_filename(suite_id)}__{_safe_filename(run_unit_id)}.json"
            status, run_summary = _campaign_progress_run_status(
                run_path,
                suite_id=suite_id,
                unit=unit,
                min_cases_per_suite=min_cases_per_suite,
            )
            suite_bucket["expected_run_count"] += 1
            suite_bucket[f"{status}_run_count"] = int(suite_bucket.get(f"{status}_run_count") or 0) + 1
            candidate_key = _campaign_progress_candidate_key(candidate_id)
            candidate_bucket = candidate_counts.setdefault(
                candidate_key,
                {
                    "candidate_key": candidate_key,
                    "candidate_type": candidate_type,
                    "expected_run_count": 0,
                    "completed_run_count": 0,
                    "missing_run_count": 0,
                    "invalid_run_count": 0,
                    "public_candidate_id_persisted": candidate_type != "provider",
                    "raw_candidate_id_persisted": False,
                    "raw_provider_model_id_persisted": False,
                },
            )
            candidate_bucket["expected_run_count"] += 1
            candidate_bucket[f"{status}_run_count"] = int(candidate_bucket.get(f"{status}_run_count") or 0) + 1
            surface_bucket = api_surface_counts.setdefault(
                api_format,
                {"expected_run_count": 0, "completed_run_count": 0, "missing_run_count": 0, "invalid_run_count": 0},
            )
            surface_bucket["expected_run_count"] += 1
            surface_bucket[f"{status}_run_count"] = int(surface_bucket.get(f"{status}_run_count") or 0) + 1
            rows.append(
                {
                    "suite_id": suite_id,
                    "category": category,
                    "run_unit_sha256": sha256_text(run_unit_id),
                    "candidate_key": candidate_key,
                    "candidate_type": candidate_type,
                    "api_format": api_format,
                    "api_surface_role": str(unit.get("api_surface_role") or ""),
                    "api_surface_is_primary_claim": unit.get("api_surface_is_primary_claim") is True,
                    "status": status,
                    "run_path_sha256": sha256_text(str(run_path)),
                    **run_summary,
                    "raw_run_path_persisted": False,
                    "raw_dataset_path_persisted": False,
                    "raw_prompt_persisted": False,
                    "raw_provider_output_persisted": False,
                    "secrets_persisted": False,
                }
            )
    missing_rows = [row for row in rows if row["status"] == "missing"]
    invalid_rows = [row for row in rows if row["status"] == "invalid"]
    completed_rows = [row for row in rows if row["status"] == "completed"]
    progress_digest_input = {
        "schema": "axio_fusion_api.benchmark_campaign_progress_digest.v1",
        "dataset_manifest_sha256": sha256_text(Path(dataset_manifest_path).read_text(encoding="utf-8")),
        "registry_receipt": _provider_registry_receipt(profiles, registry_path=registry_path),
        "candidate_keys": sorted({row["candidate_key"] for row in rows}),
        "suite_ids": sorted({row["suite_id"] for row in rows}),
        "row_statuses": [
            {
                "suite_id": row["suite_id"],
                "run_unit_sha256": row["run_unit_sha256"],
                "candidate_key": row["candidate_key"],
                "status": row["status"],
            }
            for row in rows
        ],
    }
    return {
        "schema": "axio_fusion_api.benchmark_campaign_progress_plan.v1",
        "dataset_manifest_sha256": progress_digest_input["dataset_manifest_sha256"],
        "output_dir_sha256": sha256_text(str(output_dir)),
        "registry_receipt": _provider_registry_receipt(profiles, registry_path=registry_path),
        "candidate_count": len(candidates),
        "run_unit_count": len(run_units),
        "suite_spec_count": len(suite_specs),
        "expected_run_count": len(rows),
        "completed_run_count": len(completed_rows),
        "missing_run_count": len(missing_rows),
        "invalid_run_count": len(invalid_rows),
        "progress_rate": None if not rows else round(len(completed_rows) / len(rows), 6),
        "ready_for_scorecard": bool(rows) and not missing_rows and not invalid_rows,
        "resume_needed": bool(missing_rows or invalid_rows),
        "provider_baseline_policy": {
            "include_provider_baselines": bool(include_provider_baselines),
            "max_provider_baselines": max_provider_baselines if max_provider_baselines is None else int(max_provider_baselines),
            "selection_mode": str(selection_context.get("selection_mode") or ""),
            "final_claim_requires_externally_ranked_top_three_pre_registration": True,
            "externally_ranked_top_three_pre_registered": selection_context.get("external_ranking_pre_registered") is True,
        },
        "suite_progress": list(suite_counts.values()),
        "candidate_progress": list(candidate_counts.values()),
        "api_surface_progress": {
            key: dict(value)
            for key, value in sorted(api_surface_counts.items())
        },
        "missing_or_invalid_run_receipts": [*missing_rows[:96], *invalid_rows[:96]],
        "next_action": "resume_or_repair_campaign" if missing_rows or invalid_rows else "build_scorecard_and_claim_audit",
        "next_command_templates": {
            "resume_campaign": (
                "axio-fusion-api-standalone --registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "benchmark-campaign --dataset-manifest <PINNED_DATASET_MANIFEST> "
                "--output-dir <PRIVATE_CAMPAIGN_DIR> --live "
                "--provider-baseline-freeze <SAFE_WORK_DIR>/provider_baseline_freeze.safe.json "
                "--strict-live-preflight "
                "--provider-probe-evidence-audit <SAFE_WORK_DIR>/provider_probe_evidence_audit.safe.json"
            ),
            "progress_plan": (
                "axio-fusion-api-standalone --registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "benchmark-campaign-progress-plan --dataset-manifest <PINNED_DATASET_MANIFEST> "
                "--output-dir <PRIVATE_CAMPAIGN_DIR> "
                "--provider-baseline-freeze <SAFE_WORK_DIR>/provider_baseline_freeze.safe.json "
                "--output <SAFE_WORK_DIR>/campaign_progress.safe.json"
            ),
            "scorecard_after_complete": (
                "axio-fusion-api-standalone benchmark-scorecard "
                "--run-file <PRIVATE_CAMPAIGN_DIR>/runs.json "
                "--output <PRIVATE_CAMPAIGN_DIR>/scorecard.json"
            ),
        },
        "progress_digest_sha256": sha256_text(stable_json(progress_digest_input)),
        "anti_leakage_contract": {
            "raw_output_dir_persisted": False,
            "raw_run_paths_persisted": False,
            "raw_dataset_paths_persisted": False,
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "secrets_persisted": False,
        },
        "raw_output_dir_persisted": False,
        "raw_run_paths_persisted": False,
        "raw_dataset_paths_persisted": False,
        "raw_prompt_persisted": False,
        "raw_label_persisted": False,
        "raw_provider_output_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "secrets_persisted": False,
    }


def _campaign_progress_run_status(
    run_path: Path,
    *,
    suite_id: str,
    unit: Mapping[str, Any],
    min_cases_per_suite: int,
) -> tuple[str, dict[str, Any]]:
    if not run_path.exists():
        return "missing", {
            "reason_codes": ["run_artifact_missing"],
            "run_artifact_sha256": "",
            "case_count": None,
            "attempted_count": None,
        }
    try:
        payload = json.loads(run_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return "invalid", {
            "reason_codes": ["run_artifact_unreadable_or_invalid_json"],
            "run_artifact_sha256": "",
            "case_count": None,
            "attempted_count": None,
        }
    if not isinstance(payload, Mapping):
        return "invalid", {
            "reason_codes": ["run_artifact_not_object"],
            "run_artifact_sha256": "",
            "case_count": None,
            "attempted_count": None,
        }
    reasons = []
    if str(payload.get("suite_id") or "") != suite_id:
        reasons.append("suite_id_mismatch")
    if not _campaign_progress_run_unit_matches(payload, unit):
        reasons.append("run_unit_identity_mismatch")
    case_count = _optional_int(payload.get("case_count"))
    attempted_count = _optional_int(payload.get("attempted_count"))
    effective_min_cases = _effective_min_cases_for_suite(suite_id, min_cases_per_suite)
    if case_count is None or case_count <= 0:
        reasons.append("case_count_missing_or_zero")
    elif case_count < effective_min_cases:
        reasons.append("case_count_below_effective_minimum")
    if attempted_count is None or attempted_count < max(1, case_count or 0):
        reasons.append("attempted_count_incomplete")
    if _contains_true_raw_persisted_flag(payload):
        reasons.append("unsafe_raw_persistence_flag_detected")
    return (
        "invalid" if reasons else "completed",
        {
            "reason_codes": sorted(set(reasons)),
            "run_artifact_sha256": sha256_text(stable_json(payload)),
            "case_count": case_count,
            "attempted_count": attempted_count,
            "effective_min_cases": effective_min_cases,
            "raw_run_payload_persisted": False,
        },
    )


def _campaign_progress_run_unit_matches(payload: Mapping[str, Any], unit: Mapping[str, Any]) -> bool:
    expected_candidate = _candidate_id_for_run_unit(unit)
    expected_surface = _api_surface_id_for_run_unit(unit)
    candidate = str(payload.get("candidate_id") or "")
    surface = str(payload.get("api_surface_id") or candidate)
    if _is_axio_public_candidate(expected_candidate):
        return candidate == expected_candidate and surface == expected_surface
    return candidate == expected_candidate or surface == expected_surface


def _campaign_progress_candidate_key(candidate_id: str) -> str:
    text = str(candidate_id or "")
    if _is_axio_public_candidate(text):
        return text
    if text.startswith("provider::"):
        suffix = text[len("provider::") :]
        if _looks_like_sha256(suffix):
            return f"provider::{suffix}"
    return f"candidate::{sha256_text(text)}"


def _default_training_contamination_audit_for_campaign(runs_payload: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "schema": "axio_fusion_api.training_contamination_audit.v1",
        "final_claim_training_clean": True,
        "final_claim_eligible_after_training_audit": True,
        "blocker_count": 0,
        "warning_count": 0,
        "input_artifacts": {
            "benchmark_file_count": 1,
            "training_dataset_file_count": 0,
            "learning_report_file_count": 0,
            "calibration_file_count": 0,
            "feedback_file_count": 0,
            "trace_file_count": 0,
            "benchmark_artifact_sha256": sha256_text(stable_json(runs_payload)),
            "raw_paths_persisted": False,
        },
        "hash_summary": {
            "benchmark_hash_count": _campaign_runs_hash_count(runs_payload),
            "learning_hash_count": 0,
            "overlap_count": 0,
            "raw_hash_sources_persisted": False,
        },
        "calibration_policy": {
            "allow_aggregate_benchmark_calibration": False,
            "default_final_claim_policy": "no learning, feedback, trace, or calibration artifacts were supplied to this campaign-level default audit",
            "raw_benchmark_content_persisted": False,
        },
        "findings": [],
        "anti_leakage_contract": {
            "raw_benchmark_questions_persisted": False,
            "raw_benchmark_labels_persisted": False,
            "raw_training_prompts_persisted": False,
            "raw_provider_outputs_persisted": False,
            "raw_feedback_text_persisted": False,
            "secrets_persisted": False,
        },
        "raw_prompt_persisted": False,
        "raw_label_persisted": False,
        "raw_provider_output_persisted": False,
        "secrets_persisted": False,
    }


def _campaign_runs_hash_count(runs_payload: Mapping[str, Any]) -> int:
    hashes: set[str] = set()
    runs = runs_payload.get("runs") if isinstance(runs_payload.get("runs"), list) else []
    for run in runs:
        if isinstance(run, Mapping):
            _collect_run_hashes(run, hashes)
    return len(hashes)


def _collect_run_hashes(value: Any, target: set[str]) -> None:
    if isinstance(value, Mapping):
        for key, raw in value.items():
            if str(key).endswith("_sha256") and _looks_like_sha256(raw):
                target.add(str(raw).lower())
            elif str(key) in {"case_id", "case_hash"} and _looks_like_sha256(raw):
                target.add(str(raw).lower())
            else:
                _collect_run_hashes(raw, target)
    elif isinstance(value, list):
        for item in value:
            _collect_run_hashes(item, target)


def validate_benchmark_dataset(
    *,
    suite_id: str,
    dataset_path: str | Path,
    task_format: str = "auto",
    max_rows: int | None = None,
) -> dict[str, Any]:
    selected_format = _suite_task_format(suite_id) if task_format == "auto" else str(task_format or "multiple_choice")
    selected_path = Path(dataset_path)
    invalid_reason_counts: dict[str, int] = {}
    row_count = 0
    valid_count = 0
    case_hashes = []
    label_leakage_count = 0
    prompt_contract_violation_count = 0
    if not selected_path.exists():
        return {
            "schema": "axio_fusion_api.benchmark_dataset_validation.v1",
            "suite_id": suite_id,
            "task_format": selected_format,
            "dataset_path_sha256": sha256_text(str(dataset_path)),
            "dataset_exists": False,
            "row_count": 0,
            "valid_case_count": 0,
            "invalid_case_count": 0,
            "invalid_reason_counts": {"dataset_path_not_found": 1},
            "duplicate_case_hash_count": 0,
            "label_leakage_suspected_count": 0,
            "prompt_contract_violation_count": 0,
            "ready_for_scoring": False,
            "raw_dataset_path_persisted": False,
            "raw_dataset_content_persisted": False,
            "raw_labels_persisted": False,
        }
    with selected_path.open("r", encoding="utf-8") as handle:
        for index, line in enumerate(handle):
            if max_rows is not None and row_count >= int(max_rows):
                break
            text = line.strip()
            if not text:
                continue
            row_count += 1
            try:
                payload = json.loads(text)
            except json.JSONDecodeError:
                invalid_reason_counts["invalid_json"] = invalid_reason_counts.get("invalid_json", 0) + 1
                continue
            if not isinstance(payload, Mapping):
                invalid_reason_counts["row_not_object"] = invalid_reason_counts.get("row_not_object", 0) + 1
                continue
            reasons = _dataset_row_validation_reasons(payload, selected_format)
            if reasons:
                for reason in reasons:
                    invalid_reason_counts[reason] = invalid_reason_counts.get(reason, 0) + 1
            else:
                valid_count += 1
            if _suspected_label_leakage(payload, selected_format):
                label_leakage_count += 1
            prompt_case = _benchmark_prompt_case_projection(payload, selected_format)
            prompt = (
                _multiple_choice_prompt(prompt_case)
                if selected_format == "multiple_choice"
                else _generic_case_prompt(prompt_case, selected_format)
            )
            if not _benchmark_prompt_contract_is_clean(
                _benchmark_prompt_contract(
                    payload,
                    prompt_case,
                    prompt=prompt,
                    task_format=selected_format,
                )
            ):
                prompt_contract_violation_count += 1
            case_hashes.append(_dataset_case_hash(payload, suite_id=suite_id, index=index))
    duplicate_count = max(0, len(case_hashes) - len(set(case_hashes)))
    invalid_count = max(0, row_count - valid_count)
    return {
        "schema": "axio_fusion_api.benchmark_dataset_validation.v1",
        "suite_id": suite_id,
        "task_format": selected_format,
        "dataset_path_sha256": sha256_text(str(dataset_path)),
        "dataset_exists": True,
        "row_count": row_count,
        "valid_case_count": valid_count,
        "invalid_case_count": invalid_count,
        "invalid_reason_counts": dict(sorted(invalid_reason_counts.items())),
        "duplicate_case_hash_count": duplicate_count,
        "label_leakage_suspected_count": label_leakage_count,
        "prompt_contract_violation_count": prompt_contract_violation_count,
        "case_hash_preview": case_hashes[:5],
        "ready_for_scoring": (
            invalid_count == 0
            and duplicate_count == 0
            and label_leakage_count == 0
            and prompt_contract_violation_count == 0
            and valid_count > 0
        ),
        "raw_dataset_path_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_labels_persisted": False,
    }


def audit_benchmark_campaign_readiness(
    *,
    dataset_manifest_path: str | Path,
    registry_path: str | Path | None = None,
    candidate_ids: Sequence[str] = (),
    include_provider_baselines: bool = True,
    max_provider_baselines: int | None = 3,
    provider_baseline_freeze_path: str | Path | None = None,
    min_cases_per_suite: int = 100,
) -> dict[str, Any]:
    manifest = _load_dataset_manifest(dataset_manifest_path)
    suite_specs = _campaign_suite_specs(manifest)
    by_suite = {str(spec.get("suite_id") or ""): spec for spec in suite_specs}
    invalid_replacement_reasons = _invalid_replacement_reasons_by_slot(suite_specs)
    profiles = load_registry(registry_path)
    registry_claim_readiness = _registry_claim_readiness_receipt(registry_path)
    selection_context = _provider_baseline_selection_context(
        profiles,
        include_provider_baselines=include_provider_baselines,
        max_provider_baselines=max_provider_baselines,
        provider_baseline_freeze_path=provider_baseline_freeze_path,
        registry_path=registry_path,
    )
    candidates = _campaign_candidate_ids(
        profiles,
        candidate_ids=candidate_ids,
        include_provider_baselines=include_provider_baselines,
        max_provider_baselines=max_provider_baselines,
        provider_baseline_freeze_path=provider_baseline_freeze_path,
        registry_path=registry_path,
    )
    run_units = _run_units_from_candidate_ids(profiles, candidates)
    import_candidate_keys = [_import_key_for_run_unit(unit) for unit in run_units]
    provider_candidates = [candidate for candidate in candidates if candidate.startswith("provider::")]
    rows = []
    required_suites = {suite.suite_id: suite for suite in BENCHMARK_SUITES}
    for suite_id, suite in required_suites.items():
        spec = by_suite.get(suite_id, {})
        task_format = str(spec.get("task_format") or suite.task_format)
        requires_official_harness = _suite_requires_official_harness(suite_id, task_format)
        effective_min_cases = _effective_min_cases_for_suite(suite_id, min_cases_per_suite)
        dataset_path = _suite_dataset_path(spec)
        imported_count = _imported_run_count(spec, import_candidate_keys)
        dataset_exists = bool(dataset_path and Path(dataset_path).exists())
        validation = {}
        if dataset_exists and task_format != "external_pairwise_judge":
            validation = validate_benchmark_dataset(
                suite_id=suite_id,
                dataset_path=dataset_path,
                task_format=task_format,
            )
        imported_validation = _validate_imported_runs(
            spec,
            import_candidate_keys,
            suite_id=suite_id,
            task_format=task_format,
        )
        imported_case_alignment = _imported_case_alignment(
            spec,
            import_candidate_keys,
            suite_id=suite_id,
            task_format=task_format,
        )
        official_import_complete = (
            requires_official_harness
            and imported_count >= len(import_candidate_keys)
            and imported_validation["invalid_import_count"] == 0
            and imported_case_alignment["case_hash_sets_identical"] is True
        )
        imported_case_count = (
            _optional_int(imported_case_alignment.get("common_case_hash_count")) or 0
            if official_import_complete
            else 0
        )
        case_count = int(
            imported_case_count
            or validation.get("valid_case_count")
            or (_safe_count_jsonl_rows(dataset_path) if dataset_exists else 0)
        )
        reasons = []
        if not spec:
            reasons.append("missing_suite_spec")
        reasons.extend(invalid_replacement_reasons.get(suite_id, ()))
        if spec.get("_replacement_invalid_reason"):
            reasons.append(str(spec.get("_replacement_invalid_reason")))
        replacement_binding_reason = _replacement_dataset_binding_invalid_reason(
            spec,
            dataset_path=dataset_path,
            observed_case_count=case_count,
        )
        if replacement_binding_reason:
            reasons.append(replacement_binding_reason)
        if requires_official_harness and imported_count < len(import_candidate_keys):
            reasons.append("official_harness_imports_incomplete")
        if task_format == "external_pairwise_judge":
            if imported_count < len(import_candidate_keys):
                reasons.append("external_judge_imports_incomplete")
            if imported_validation["invalid_import_count"] > 0:
                reasons.append("invalid_imported_runs")
        elif requires_official_harness and imported_validation["invalid_import_count"] > 0:
            reasons.append("invalid_official_harness_imports")
        elif requires_official_harness and imported_count >= len(import_candidate_keys) and imported_case_alignment["case_hash_sets_identical"] is not True:
            reasons.append("official_import_case_hashes_misaligned")
        elif official_import_complete:
            pass
        elif not dataset_path:
            reasons.append("missing_dataset_path")
        elif not dataset_exists:
            reasons.append("dataset_path_not_found")
        elif validation and not validation.get("ready_for_scoring"):
            if validation.get("invalid_case_count"):
                reasons.append("invalid_dataset_rows")
            if validation.get("duplicate_case_hash_count"):
                reasons.append("duplicate_dataset_cases")
            if validation.get("label_leakage_suspected_count"):
                reasons.append("possible_label_leakage")
        elif case_count < effective_min_cases:
            reasons.append("insufficient_case_count")
        if include_provider_baselines and len(provider_candidates) < 3:
            reasons.append("fewer_than_three_provider_baselines")
        rows.append(
            {
                "suite_id": suite_id,
                "category": suite.category,
                "task_format": task_format,
                "benchmark_slot_id": str(spec.get("benchmark_slot_id") or suite_id),
                "benchmark_dataset_id": str(spec.get("benchmark_dataset_id") or suite_id),
                "benchmark_identity": str(spec.get("benchmark_identity") or suite.title),
                "replacement_active": spec.get("replacement_active") is True,
                "replacement_disclosure": (
                    "This is an explicit replacement dataset and is not the original benchmark."
                    if spec.get("replacement_active") is True
                    else ""
                ),
                "dataset_path_sha256": sha256_text(str(dataset_path)) if dataset_path else "",
                "dataset_exists": dataset_exists,
                "case_count": case_count,
                "effective_min_cases": effective_min_cases,
                "suite_min_case_policy": _suite_min_case_policy(suite_id, min_cases_per_suite),
                "valid_case_count": validation.get("valid_case_count") if validation else None,
                "invalid_case_count": validation.get("invalid_case_count") if validation else None,
                "duplicate_case_hash_count": validation.get("duplicate_case_hash_count") if validation else None,
                "label_leakage_suspected_count": validation.get("label_leakage_suspected_count") if validation else None,
                "candidate_count": len(candidates),
                "run_unit_count": len(run_units),
                "provider_baseline_count": len(provider_candidates),
                "requires_official_harness": requires_official_harness,
                "expected_imported_run_count": imported_validation["expected_import_count"],
                "imported_run_count": imported_count,
                "provided_imported_run_count": imported_validation["provided_import_count"],
                "valid_imported_run_count": imported_validation["valid_import_count"],
                "missing_imported_run_count": imported_validation["missing_import_count"],
                "invalid_imported_run_count": imported_validation["invalid_import_count"],
                "imported_run_validation": imported_validation,
                "imported_case_alignment": imported_case_alignment,
                "ready": not reasons,
                "reason_codes": sorted(set(reasons)),
                "raw_dataset_path_persisted": False,
                "raw_dataset_content_persisted": False,
            }
        )
    missing_categories = []
    for category in sorted({suite.category for suite in BENCHMARK_SUITES}):
        category_rows = [row for row in rows if row["category"] == category]
        if len([row for row in category_rows if row["ready"]]) < 2:
            missing_categories.append(category)
    provider_baseline_selection = str(selection_context.get("selection_mode") or "")
    final_claim_blockers = []
    if include_provider_baselines is not True:
        final_claim_blockers.append("provider_baselines_disabled")
    if provider_baseline_selection != EXTERNAL_PROVIDER_RANKING_SELECTION_MODE:
        final_claim_blockers.append("provider_baseline_selection_not_pre_registered_top_three")
    if provider_baseline_freeze_path is not None:
        if selection_context.get("external_ranking_pre_registered") is not True:
            final_claim_blockers.append("provider_baseline_external_ranking_not_ready")
        for reason in selection_context.get("blockers", []):
            final_claim_blockers.append(str(reason))
    if len(provider_candidates) < 3:
        final_claim_blockers.append("fewer_than_three_provider_baselines")
    if not all(row["ready"] for row in rows):
        final_claim_blockers.append("one_or_more_required_suites_not_ready")
    for reason in registry_claim_readiness.get("final_claim_blocking_reasons", []):
        final_claim_blockers.append(str(reason))
    return {
        "schema": "axio_fusion_api.benchmark_campaign_readiness.v1",
        "dataset_manifest_sha256": sha256_text(Path(dataset_manifest_path).read_text(encoding="utf-8")),
        "required_suite_count": len(BENCHMARK_SUITES),
        "ready_suite_count": sum(1 for row in rows if row["ready"]),
        "all_required_suites_ready": all(row["ready"] for row in rows),
        "candidate_count": len(candidates),
        "run_unit_count": len(run_units),
        "api_surface_contract": _api_surface_contract(),
        "provider_baseline_count": len(provider_candidates),
        "required_provider_baseline_count": 3,
        "provider_baseline_selection": provider_baseline_selection,
        "available_provider_baseline_count": len(_provider_baseline_profiles(profiles)) if include_provider_baselines else 0,
        "registry_claim_readiness": registry_claim_readiness,
        "registry_final_claim_ready": registry_claim_readiness.get("final_claim_registry_ready") is True,
        "registry_live_probe_proven": registry_claim_readiness.get("live_probe_proven") is True,
        "registry_live_available_model_count": _optional_int(registry_claim_readiness.get("live_available_model_count")) or 0,
        "final_claims_require_all_available_provider_baselines": False,
        "final_claims_require_externally_ranked_top_three_pre_registration": True,
        "final_claim_provider_baselines_exhaustive": provider_baseline_selection == "all_available_provider_models",
        "final_claim_provider_baselines_pre_registered": (
            provider_baseline_selection == EXTERNAL_PROVIDER_RANKING_SELECTION_MODE
            and selection_context.get("external_ranking_pre_registered") is True
            and not selection_context.get("blockers")
        ),
        "provider_baseline_selection_blockers": list(selection_context.get("blockers") or []),
        "min_cases_per_suite": int(min_cases_per_suite),
        "rows": rows,
        "missing_or_incomplete_categories": missing_categories,
        "final_claim_blocking_reasons": sorted(set(final_claim_blockers)),
        "will_claim_audit_be_possible": not final_claim_blockers,
        "raw_dataset_paths_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "secrets_persisted": False,
    }


def build_fusion_live_readiness(
    *,
    registry_path: str | Path | None = None,
    benchmark_manifest_dir: str | Path | None = "/mnt/storage/axio_fusion_benchmarks/manifests",
    materialization_status_path: str | Path | None = None,
    case_hash_manifest_path: str | Path | None = None,
    harness_pin_manifest_path: str | Path | None = None,
    source_manifest_validation_path: str | Path | None = None,
    import_batch_template_path: str | Path | None = None,
    official_harness_execution_plan_path: str | Path | None = None,
    official_import_audit_path: str | Path | None = None,
    acquisition_status_path: str | Path | None = None,
    provider_baseline_freeze_path: str | Path | None = None,
    provider_probe_evidence_audit_path: str | Path | None = None,
) -> dict[str, Any]:
    """Return a safe, non-network preflight for the live Fusion campaign.

    This is the operator-facing gate between dataset preparation and real live
    provider probing.  It intentionally reads environment-variable presence and
    safe JSON artifacts only; it never calls a provider and never persists raw
    endpoint URLs, API keys, prompts, labels, provider outputs, or local paths.
    """

    provider_env = _fusion_provider_env_readiness(registry_path=registry_path)
    registry_readiness = _registry_claim_readiness_receipt(registry_path)
    provider_baseline_freeze = _fusion_provider_baseline_freeze_readiness(
        registry_path=registry_path,
        registry_readiness=registry_readiness,
        provider_baseline_freeze_path=provider_baseline_freeze_path,
        provider_probe_evidence_audit_path=provider_probe_evidence_audit_path,
    )
    artifacts = _fusion_benchmark_artifact_readiness(
        benchmark_manifest_dir=benchmark_manifest_dir,
        materialization_status_path=materialization_status_path,
        case_hash_manifest_path=case_hash_manifest_path,
        harness_pin_manifest_path=harness_pin_manifest_path,
        source_manifest_validation_path=source_manifest_validation_path,
        import_batch_template_path=import_batch_template_path,
        official_harness_execution_plan_path=official_harness_execution_plan_path,
        official_import_audit_path=official_import_audit_path,
        acquisition_status_path=acquisition_status_path,
    )
    blockers = _fusion_live_blockers(
        provider_env=provider_env,
        registry_readiness=registry_readiness,
        benchmark_artifacts=artifacts,
        provider_baseline_freeze=provider_baseline_freeze,
    )
    warnings = _fusion_live_warnings(provider_env=provider_env, benchmark_artifacts=artifacts)
    ready = not blockers
    digest_input = {
        "schema": "axio_fusion_api.fusion_live_readiness_digest.v1",
        "provider_env": _fusion_digest_provider_env(provider_env),
        "registry": {
            "provided": registry_readiness.get("registry_path_provided") is True,
            "exists": registry_readiness.get("registry_artifact_exists") is True,
            "valid": registry_readiness.get("registry_artifact_valid_json") is True,
            "generated_from_probe": registry_readiness.get("probe_backed_registry") is True,
            "live_probe_proven": registry_readiness.get("live_probe_proven") is True,
            "final_claim_registry_ready": registry_readiness.get("final_claim_registry_ready") is True,
            "live_available_model_count": _optional_int(registry_readiness.get("live_available_model_count")) or 0,
            "blockers": list(registry_readiness.get("final_claim_blocking_reasons") or []),
        },
        "benchmark_artifacts": _fusion_digest_benchmark_artifacts(artifacts),
        "provider_baseline_freeze": _fusion_digest_provider_baseline_freeze(provider_baseline_freeze),
        "blockers": blockers,
        "warnings": warnings,
    }
    return {
        "schema": "axio_fusion_api.fusion_live_readiness.v1",
        "status": "ready" if ready else "blocked",
        "ready_for_live_probe": bool(provider_env.get("credentialed_provider_count")),
        "ready_for_21_suite_campaign": ready,
        "ready_for_final_claims": ready,
        "next_blockers": blockers,
        "warnings": warnings,
        "readiness_digest_sha256": sha256_text(stable_json(digest_input)),
        "provider_env_readiness": provider_env,
        "live_registry_readiness": registry_readiness,
        "provider_baseline_freeze_readiness": provider_baseline_freeze,
        "benchmark_artifact_readiness": artifacts,
        "next_command_templates": {
            "safe_preflight": (
                "axio-fusion-api-standalone "
                "--registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "fusion-live-readiness "
                "--benchmark-manifest-dir <SAFE_MANIFEST_DIR> "
                "--output <WORK_DIR>/fusion_live_readiness.safe.json"
            ),
            "campaign_preflight": (
                "axio-fusion-api-standalone "
                "--registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "fusion-live-readiness "
                "--benchmark-manifest-dir <SAFE_MANIFEST_DIR> "
                "--provider-baseline-freeze <SAFE_WORK_DIR>/provider_baseline_freeze.safe.json "
                "--provider-probe-evidence-audit <SAFE_WORK_DIR>/provider_probe_evidence_audit.safe.json "
                "--output <SAFE_WORK_DIR>/fusion_live_readiness.safe.json"
            ),
            "live_provider_probe": (
                "AXIO_FUSION_PROBE_LIVE=1 axio-fusion-api-standalone probe "
                "--discover-live-models "
                "--timeout 60 --output <PRIVATE_WORK_DIR>/provider_probe.json"
            ),
            "generated_registry": (
                "axio-fusion-api-standalone registry-from-probe "
                "--probe-file <PRIVATE_WORK_DIR>/provider_probe.json "
                "--output <PRIVATE_WORK_DIR>/generated_registry.json"
            ),
            "redacted_probe_evidence": (
                "axio-fusion-api-standalone registry-from-probe "
                "--probe-file <PRIVATE_WORK_DIR>/provider_probe.json "
                "--redact-provider-identifiers "
                "--output <SAFE_WORK_DIR>/generated_registry.evidence.json"
            ),
            "provider_baseline_freeze": (
                "axio-fusion-api-standalone "
                "--registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "benchmark-provider-baseline-freeze "
                "--external-ranking-manifest <PRIVATE_WORK_DIR>/external_provider_ranking.json "
                "--provider-probe-evidence-audit <SAFE_WORK_DIR>/provider_probe_evidence_audit.safe.json "
                "--output <SAFE_WORK_DIR>/provider_baseline_freeze.safe.json"
            ),
            "official_harness_import": (
                "axio-fusion-api-standalone benchmark-import-official-batch "
                "--batch-file <PINNED_IMPORT_BATCH_TEMPLATE> "
                "--output-dir <SAFE_OFFICIAL_IMPORT_DIR>"
            ),
            "official_import_audit": (
                "axio-fusion-api-standalone "
                "--registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "benchmark-official-import-audit "
                "--dataset-manifest <PINNED_DATASET_MANIFEST> "
                "--source-manifest <BOUND_SOURCE_MANIFEST> "
                "--case-hash-manifest <CASE_HASH_MANIFEST> "
                "--harness-pin-manifest <HARNESS_PIN_MANIFEST_SAFE_JSON> "
                "--import-dir <SAFE_OFFICIAL_IMPORT_DIR> "
                "--provider-baseline-freeze <SAFE_WORK_DIR>/provider_baseline_freeze.safe.json "
                "--output <SAFE_WORK_DIR>/official_import_audit.safe.json"
            ),
            "final_campaign": (
                "axio-fusion-api-standalone "
                "--registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "benchmark-campaign "
                "--dataset-manifest <PINNED_DATASET_MANIFEST> "
                "--output-dir <PRIVATE_CAMPAIGN_DIR> "
                "--provider-baseline-freeze <SAFE_WORK_DIR>/provider_baseline_freeze.safe.json --live "
                "--strict-live-preflight "
                "--provider-probe-evidence-audit <SAFE_WORK_DIR>/provider_probe_evidence_audit.safe.json"
            ),
            "api_surface_protocol_self_test": (
                "axio-fusion-api-standalone "
                "--registry <PRIVATE_GENERATED_REGISTRY_JSON> "
                "api-surface-protocol-self-test "
                "--output <SAFE_WORK_DIR>/api_surface_protocol.safe.json"
            ),
        },
        "anti_leakage_contract": {
            "network_calls_performed": False,
            "raw_env_values_persisted": False,
            "raw_base_urls_persisted": False,
            "raw_api_keys_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_local_paths_persisted": False,
            "raw_benchmark_content_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        "standalone_product": True,
        "decoupled_from_asci_fs": True,
        "network_calls_performed": False,
        "raw_env_values_persisted": False,
        "raw_base_urls_persisted": False,
        "raw_api_keys_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_local_paths_persisted": False,
        "raw_benchmark_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def build_fusion_live_runbook(
    *,
    registry_path: str | Path | None = None,
    benchmark_manifest_dir: str | Path | None = "/mnt/storage/axio_fusion_benchmarks/manifests",
    min_cases_per_suite: int = 100,
    alpha: float = 0.05,
    include_provider_baselines: bool = True,
    max_provider_baselines: int | None = None,
) -> dict[str, Any]:
    """Emit a safe operator runbook for live probing and benchmark execution."""

    readiness = build_fusion_live_readiness(
        registry_path=registry_path,
        benchmark_manifest_dir=benchmark_manifest_dir,
    )
    provider_env = readiness.get("provider_env_readiness") if isinstance(readiness.get("provider_env_readiness"), Mapping) else {}
    registry_receipt = readiness.get("live_registry_readiness") if isinstance(readiness.get("live_registry_readiness"), Mapping) else {}
    artifacts = readiness.get("benchmark_artifact_readiness") if isinstance(readiness.get("benchmark_artifact_readiness"), Mapping) else {}
    freeze = readiness.get("provider_baseline_freeze_readiness") if isinstance(readiness.get("provider_baseline_freeze_readiness"), Mapping) else {}
    cohort = artifacts.get("official_import_cohort_readiness") if isinstance(artifacts.get("official_import_cohort_readiness"), Mapping) else {}
    portfolio = _fusion_live_runbook_portfolio_summary(registry_path)
    provider_freeze_flag = "--provider-baseline-freeze <SAFE_WORK_DIR>/provider_baseline_freeze.safe.json"
    stages = _fusion_live_runbook_stages(
        provider_flag=provider_freeze_flag,
        min_cases_per_suite=min_cases_per_suite,
        alpha=alpha,
    )
    return {
        "schema": "axio_fusion_api.fusion_live_runbook.v1",
        "status": "ready_to_execute_when_external_blockers_clear",
        "objective": "live_provider_probe_to_21_suite_campaign_to_final_claim_audit",
        "provider_input_model": "configuration_driven_arbitrary_providers",
        "public_axio_models": list(AXIO_BENCHMARK_PUBLIC_MODELS),
        "public_api_surfaces": list(AXIO_BENCHMARK_API_FORMATS),
        "benchmark_suite_count": len(BENCHMARK_SUITES),
        "benchmark_category_count": len(BENCHMARK_CATEGORY_REQUIRED_SUITE_COUNTS),
        "min_cases_per_suite": int(min_cases_per_suite),
        "alpha": float(alpha),
        "provider_baseline_policy": {
            "include_provider_baselines": bool(include_provider_baselines),
            "max_provider_baselines": max_provider_baselines if max_provider_baselines is None else int(max_provider_baselines),
            "selection_mode": EXTERNAL_PROVIDER_RANKING_SELECTION_MODE,
            "external_ranking_manifest_required_before_campaign": True,
            "target_benchmark_results_must_not_select_or_reorder_baselines": True,
            "legacy_all_provider_baseline_mode_diagnostic_only": True,
        },
        "current_readiness_summary": {
            "fusion_live_readiness_status": str(readiness.get("status") or ""),
            "ready_for_live_probe": readiness.get("ready_for_live_probe") is True,
            "ready_for_21_suite_campaign": readiness.get("ready_for_21_suite_campaign") is True,
            "next_blockers": list(readiness.get("next_blockers") or []),
            "warnings": list(readiness.get("warnings") or []),
            "credentialed_provider_count": _optional_int(provider_env.get("credentialed_provider_count")) or 0,
            "credentialed_api_format_counts": dict(provider_env.get("credentialed_api_format_counts") or {}),
            "registry_final_claim_ready": registry_receipt.get("final_claim_registry_ready") is True,
            "registry_live_probe_proven": registry_receipt.get("live_probe_proven") is True,
            "benchmark_inputs_ready": artifacts.get("all_required_benchmark_inputs_ready") is True,
            "official_import_missing_count": _optional_int(artifacts.get("official_import_missing_count")) or 0,
            "official_import_audit_ready": artifacts.get("official_import_audit_ready") is True,
            "gated_dataset_suite_count": _optional_int(artifacts.get("gated_dataset_suite_count")) or 0,
            "official_import_cohort_ready": cohort.get("ready") is True,
            "official_import_required_run_unit_count_per_suite": _optional_int(
                cohort.get("required_run_unit_count_per_official_suite")
            )
            or 0,
            "official_import_required_total_count": _optional_int(cohort.get("required_official_import_count")) or 0,
            "provider_baseline_freeze_ready": freeze.get("ready") is True,
            "provider_baseline_selection": str(freeze.get("provider_baseline_selection") or ""),
        },
        "provider_portfolio_summary": portfolio,
        "operator_secret_inputs": _fusion_live_runbook_secret_inputs(provider_env),
        "stage_count": len(stages),
        "stages": stages,
        "artifact_policy": {
            "private_artifacts": [
                "<PRIVATE_WORK_DIR>/provider_probe.json",
                "<PRIVATE_WORK_DIR>/generated_registry.json",
                "<PRIVATE_WORK_DIR>/external_provider_ranking.json",
                "<PRIVATE_CAMPAIGN_DIR>/runs.json",
                "<PRIVATE_CAMPAIGN_DIR>/scorecard.json",
                "<PRIVATE_CAMPAIGN_DIR>/claim_audit.json",
            ],
            "shareable_safe_artifacts": [
                "<SAFE_WORK_DIR>/provider_probe.safe.json",
                "<SAFE_WORK_DIR>/generated_registry.evidence.json",
                "<SAFE_WORK_DIR>/provider_probe_evidence_audit.safe.json",
                "<SAFE_WORK_DIR>/provider_portfolio.safe.json",
                "<SAFE_WORK_DIR>/provider_baseline_freeze.safe.json",
                "<SAFE_WORK_DIR>/fusion_live_readiness.safe.json",
                "<SAFE_WORK_DIR>/dataset_manifest.json",
                "<SAFE_WORK_DIR>/benchmark_case_hash_manifest.safe.json",
                "<SAFE_WORK_DIR>/benchmark_source_manifest.prepared.safe.json",
                "<SAFE_WORK_DIR>/benchmark_source_manifest.bound.safe.json",
                "<SAFE_WORK_DIR>/official_import_audit.safe.json",
                "<SAFE_WORK_DIR>/provider_input_adapter.safe.json",
                "<SAFE_WORK_DIR>/api_surface_protocol.safe.json",
                "<SAFE_WORK_DIR>/code_test_receipt.safe.json",
                "<SAFE_WORK_DIR>/system_development_readiness.safe.json",
                "<SAFE_WORK_DIR>/api_surface_parity.safe.json",
                "<SAFE_WORK_DIR>/fusion_failure_analysis.safe.json",
                "<SAFE_WORK_DIR>/evidence_pack.json",
                "<SAFE_WORK_DIR>/fusion_completion_audit.safe.json",
                "<SAFE_WORK_DIR>/final_audit.json",
            ],
            "private_artifacts_may_contain_raw_provider_model_ids": True,
            "safe_artifacts_use_hashes_and_counts": True,
        },
        "completion_gates": {
            "live_probe_registry_required": True,
            "provider_probe_evidence_audit_required": True,
            "provider_portfolio_audit_required": True,
            "cross_provider_independent_verifier_required": True,
            "provider_baseline_freeze_required": True,
            "externally_ranked_top_three_pre_registered_required": True,
            "all_21_benchmark_inputs_required": True,
            "official_or_audited_harness_imports_required": True,
            "official_import_audit_required": True,
            "provider_input_adapter_self_test_required": True,
            "api_surface_protocol_self_test_required": True,
            "system_development_readiness_required_before_benchmark_validation": True,
            "api_surface_parity_report_required": True,
            "evidence_pack_final_audit_binding_required": True,
            "primary_evidence_recompute_binding_required": True,
            "shadow_failure_analysis_required": True,
            "four_public_api_surfaces_required_for_axio": True,
            "paired_case_hash_claim_audit_required": True,
            "tiered_claim_comparison_family_required": True,
            "holm_bonferroni_required": True,
            "latency_gate_max_multiplier": CLAIM_LATENCY_MAX_MULTIPLIER,
            "training_contamination_audit_required": True,
            "final_audit_required": True,
            "fusion_completion_audit_required": True,
        },
        "anti_leakage_contract": {
            "network_calls_performed": False,
            "commands_are_templates": True,
            "raw_env_values_persisted": False,
            "raw_base_urls_persisted": False,
            "raw_api_keys_persisted": False,
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_local_paths_persisted": False,
            "raw_benchmark_content_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        "standalone_product": True,
        "decoupled_from_asci_fs": True,
        "network_calls_performed": False,
        "raw_env_values_persisted": False,
        "raw_base_urls_persisted": False,
        "raw_api_keys_persisted": False,
        "raw_provider_names_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_local_paths_persisted": False,
        "raw_benchmark_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _fusion_live_runbook_portfolio_summary(registry_path: str | Path | None) -> dict[str, Any]:
    if not registry_path:
        return {
            "available": False,
            "reason_codes": ["registry_path_not_provided"],
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
        }
    selected = Path(registry_path)
    if not selected.exists():
        return {
            "available": False,
            "reason_codes": ["registry_path_not_found"],
            "registry_path_sha256": sha256_text(str(registry_path)),
            "raw_path_persisted": False,
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
        }
    try:
        audit = build_provider_portfolio_audit(load_registry(registry_path))
    except Exception:  # noqa: BLE001 - runbook must stay safe and non-blocking
        return {
            "available": False,
            "reason_codes": ["provider_portfolio_audit_failed"],
            "registry_path_sha256": sha256_text(str(registry_path)),
            "raw_path_persisted": False,
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
        }
    return {
        "available": True,
        "schema": str(audit.get("schema") or ""),
        "status": str(audit.get("status") or ""),
        "ready_for_serving": audit.get("ready_for_serving") is True,
        "ready_for_diverse_fusion": audit.get("ready_for_diverse_fusion") is True,
        "ready_for_final_claim_registry_profile": audit.get("ready_for_final_claim_registry_profile") is True,
        "blockers": list(audit.get("blockers") or []),
        "warnings": list(audit.get("warnings") or []),
        "inventory_summary": dict(audit.get("inventory_summary") or {}),
        "api_format_coverage": dict(audit.get("api_format_coverage") or {}),
        "independent_verification_capacity": dict(audit.get("independent_verification_capacity") or {}),
        "recommendation_ids": [
            str(row.get("recommendation_id") or "")
            for row in audit.get("recommendations", [])
            if isinstance(row, Mapping)
        ],
        "raw_path_persisted": False,
        "raw_provider_names_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "secrets_persisted": False,
    }


def _fusion_live_runbook_secret_inputs(provider_env: Mapping[str, Any]) -> dict[str, Any]:
    rows = provider_env.get("provider_rows") if isinstance(provider_env.get("provider_rows"), list) else []
    missing = []
    ready = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        target = ready if row.get("credential_ready") is True else missing
        target.append(
            {
                "provider_sha256": str(row.get("provider_sha256") or ""),
                "api_format": str(row.get("api_format") or ""),
                "base_url_present": row.get("base_url_present") is True,
                "api_key_present": row.get("api_key_present") is True,
                "base_url_env_name_hashes": list(row.get("base_url_env_name_hashes") or []),
                "api_key_env_name_hashes": list(row.get("api_key_env_name_hashes") or []),
                "reason_codes": list(row.get("reason_codes") or []),
                "raw_env_names_persisted": False,
                "raw_env_values_persisted": False,
                "raw_provider_name_persisted": False,
                "secrets_persisted": False,
            }
        )
    return {
        "schema": "axio_fusion_api.live_runbook_secret_inputs.v1",
        "credentialed_provider_count": len(ready),
        "missing_or_incomplete_provider_count": len(missing),
        "credentialed_provider_rows": ready[:24],
        "missing_or_incomplete_provider_rows": missing[:24],
        "operator_must_set_env_values_outside_runbook": True,
        "runbook_records_env_name_hashes_only": True,
        "raw_env_names_persisted": False,
        "raw_env_values_persisted": False,
        "raw_base_urls_persisted": False,
        "raw_api_keys_persisted": False,
        "secrets_persisted": False,
    }


