def _load_json_artifact(path: Path | None) -> dict[str, Any]:
    if path is None:
        return {
            "path_sha256": "",
            "content_sha256": "",
            "exists": False,
            "valid_json_object": False,
            "schema": "",
            "payload": {},
        }
    receipt = {
        "path_sha256": sha256_text(str(path)),
        "content_sha256": "",
        "exists": path.exists(),
        "valid_json_object": False,
        "schema": "",
        "payload": {},
    }
    if not path.exists():
        return receipt
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return receipt
    receipt["content_sha256"] = sha256_text(text)
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        return receipt
    if not isinstance(payload, Mapping):
        return receipt
    receipt["valid_json_object"] = True
    receipt["schema"] = str(payload.get("schema") or "")
    receipt["payload"] = dict(payload)
    return receipt


def _final_campaign_summary(campaign: Mapping[str, Any]) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing = []
    mode = str(campaign.get("mode") or "")
    expected = _optional_int(campaign.get("expected_run_count"))
    completed = _optional_int(campaign.get("completed_or_resumed_run_count"))
    missing_suite_count = _optional_int(campaign.get("missing_suite_count")) or 0
    claim = campaign.get("claim_summary") if isinstance(campaign.get("claim_summary"), Mapping) else {}
    policy = campaign.get("policy") if isinstance(campaign.get("policy"), Mapping) else {}
    preflight = (
        campaign.get("readiness_preflight_receipt")
        if isinstance(campaign.get("readiness_preflight_receipt"), Mapping)
        else {}
    )
    provider_selection = str(policy.get("provider_baseline_selection") or "")
    campaign_candidate_count = _optional_int(campaign.get("candidate_count"))
    campaign_run_unit_count = _optional_int(campaign.get("run_unit_count"))
    policy_min_cases = _optional_int(policy.get("min_cases_per_suite")) if policy else None
    policy_available_provider_count = _optional_int(policy.get("available_provider_baseline_count")) if policy else None
    if not campaign:
        missing.append({"kind": "campaign_artifact_unavailable"})
    elif mode != "live":
        missing.append({"kind": "campaign_not_live", "mode": mode or "missing"})
    if campaign and provider_selection != EXTERNAL_PROVIDER_RANKING_SELECTION_MODE:
        missing.append(
            {
                "kind": "provider_baseline_selection_not_pre_registered_top_three",
                "provider_baseline_selection": provider_selection or "missing",
            }
        )
    available_provider_count = _optional_int(policy.get("available_provider_baseline_count")) if policy else None
    if campaign and (available_provider_count or 0) < 3:
        missing.append(
            {
                "kind": "available_provider_baseline_count_too_small",
                "available_provider_baseline_count": available_provider_count,
            }
        )
    if expected is not None and completed is not None and completed < expected:
        missing.append(
            {
                "kind": "campaign_runs_incomplete",
                "expected_run_count": expected,
                "completed_or_resumed_run_count": completed,
            }
        )
    if missing_suite_count > 0:
        missing.append({"kind": "campaign_missing_suites", "missing_suite_count": missing_suite_count})
    if claim and claim.get("all_final_claims_allowed") is not True:
        missing.append({"kind": "campaign_claim_summary_not_approved"})
    if campaign and not preflight:
        missing.append({"kind": "readiness_preflight_receipt_missing"})
    elif preflight:
        if preflight.get("schema") != "axio_fusion_api.benchmark_readiness_preflight_receipt.v1":
            missing.append(
                {
                    "kind": "readiness_preflight_receipt_schema_unrecognized",
                    "schema": str(preflight.get("schema") or ""),
                }
            )
        if not _looks_like_sha256(preflight.get("readiness_digest_sha256")):
            missing.append({"kind": "readiness_preflight_digest_missing"})
        if preflight.get("all_required_suites_ready") is not True:
            missing.append({"kind": "readiness_preflight_not_all_suites_ready"})
        if preflight.get("will_claim_audit_be_possible") is not True:
            missing.append({"kind": "readiness_preflight_claim_audit_not_possible"})
        if preflight.get("registry_final_claim_ready") is not True:
            missing.append({"kind": "readiness_preflight_registry_not_final_ready"})
        if preflight.get("registry_live_probe_proven") is not True:
            missing.append({"kind": "readiness_preflight_registry_live_probe_not_proven"})
        if preflight.get("final_claim_provider_baselines_pre_registered") is not True:
            missing.append({"kind": "readiness_preflight_provider_baselines_not_pre_registered"})
        preflight_dataset_sha = str(preflight.get("dataset_manifest_sha256") or "")
        campaign_dataset_sha = str(campaign.get("dataset_manifest_sha256") or "")
        if campaign_dataset_sha and preflight_dataset_sha != campaign_dataset_sha:
            missing.append({"kind": "readiness_preflight_dataset_manifest_digest_mismatch"})
        preflight_candidate_count = _optional_int(preflight.get("candidate_count"))
        if campaign_candidate_count is not None and preflight_candidate_count is not None and preflight_candidate_count != campaign_candidate_count:
            missing.append(
                {
                    "kind": "readiness_preflight_candidate_count_mismatch",
                    "campaign_candidate_count": campaign_candidate_count,
                    "preflight_candidate_count": preflight_candidate_count,
                }
            )
        preflight_run_unit_count = _optional_int(preflight.get("run_unit_count"))
        if campaign_run_unit_count is not None and preflight_run_unit_count is not None and preflight_run_unit_count != campaign_run_unit_count:
            missing.append(
                {
                    "kind": "readiness_preflight_run_unit_count_mismatch",
                    "campaign_run_unit_count": campaign_run_unit_count,
                    "preflight_run_unit_count": preflight_run_unit_count,
                }
            )
        preflight_min_cases = _optional_int(preflight.get("min_cases_per_suite"))
        if policy_min_cases is not None and preflight_min_cases is not None and preflight_min_cases != policy_min_cases:
            missing.append(
                {
                    "kind": "readiness_preflight_min_cases_mismatch",
                    "policy_min_cases_per_suite": policy_min_cases,
                    "preflight_min_cases_per_suite": preflight_min_cases,
                }
            )
        preflight_provider_selection = str(preflight.get("provider_baseline_selection") or "")
        if provider_selection and preflight_provider_selection != provider_selection:
            missing.append({"kind": "readiness_preflight_provider_selection_mismatch"})
        preflight_available_provider_count = _optional_int(preflight.get("available_provider_baseline_count"))
        if (
            policy_available_provider_count is not None
            and preflight_available_provider_count is not None
            and preflight_available_provider_count != policy_available_provider_count
        ):
            missing.append({"kind": "readiness_preflight_available_provider_count_mismatch"})
    return (
        {
            "mode": mode,
            "expected_run_count": expected,
            "completed_or_resumed_run_count": completed,
            "candidate_count": campaign_candidate_count,
            "run_unit_count": campaign_run_unit_count,
            "missing_suite_count": missing_suite_count,
            "readiness_preflight_present": bool(preflight),
            "readiness_preflight_digest_sha256": str(preflight.get("readiness_digest_sha256") or "") if preflight else "",
            "readiness_preflight_all_required_suites_ready": preflight.get("all_required_suites_ready") if preflight else None,
            "readiness_preflight_claim_audit_possible": preflight.get("will_claim_audit_be_possible") if preflight else None,
            "readiness_preflight_registry_final_claim_ready": preflight.get("registry_final_claim_ready") if preflight else None,
            "readiness_preflight_registry_live_probe_proven": preflight.get("registry_live_probe_proven") if preflight else None,
            "readiness_preflight_registry_live_available_model_count": _optional_int(preflight.get("registry_live_available_model_count")) if preflight else None,
            "readiness_preflight_provider_baselines_pre_registered": preflight.get("final_claim_provider_baselines_pre_registered") if preflight else None,
            "readiness_preflight_blocking_reasons": list(preflight.get("final_claim_blocking_reasons", [])) if preflight and isinstance(preflight.get("final_claim_blocking_reasons"), list) else [],
            "readiness_preflight_ready_suite_count": _optional_int(preflight.get("ready_suite_count")) if preflight else None,
            "provider_baseline_selection": provider_selection or None,
            "available_provider_baseline_count": available_provider_count,
            "all_required_suites_present": claim.get("all_required_suites_present") if claim else None,
            "all_final_claims_allowed": claim.get("all_final_claims_allowed") if claim else None,
        },
        missing,
    )


def _final_provider_baseline_census_summary(
    *,
    campaign: Mapping[str, Any],
    runs: Sequence[Mapping[str, Any]],
    scorecard: Mapping[str, Any],
    claim_audit: Mapping[str, Any],
    expected_provider_baseline_count: int,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing = []
    census = campaign.get("provider_baseline_census") if isinstance(campaign.get("provider_baseline_census"), Mapping) else {}
    registry_receipt = (
        campaign.get("provider_registry_receipt")
        if isinstance(campaign.get("provider_registry_receipt"), Mapping)
        else {}
    )
    campaign_candidate_ids = campaign.get("candidate_ids") if isinstance(campaign.get("candidate_ids"), list) else []
    campaign_provider_hashes = _provider_candidate_hashes_from_ids(campaign_candidate_ids)
    run_provider_hashes = _provider_candidate_hashes_from_runs(runs)
    scorecard_provider_hashes = _provider_candidate_hashes_from_scorecard(scorecard)
    claim_provider_hashes = _provider_candidate_hashes_from_claim_audit(claim_audit)
    census_provider_hashes = [
        str(item)
        for item in census.get("selected_provider_candidate_id_hashes", [])
        if _looks_like_sha256(item)
    ] if isinstance(census.get("selected_provider_candidate_id_hashes"), list) else []
    census_available_profile_hashes = [
        str(item)
        for item in census.get("available_provider_profile_hashes", [])
        if _looks_like_sha256(item)
    ] if isinstance(census.get("available_provider_profile_hashes"), list) else []
    registry_provider_profile_hashes = [
        str(item)
        for item in registry_receipt.get("provider_baseline_profile_hashes", [])
        if _looks_like_sha256(item)
    ] if isinstance(registry_receipt.get("provider_baseline_profile_hashes"), list) else []
    available_count = _optional_int(census.get("available_provider_baseline_count")) if census else None
    selected_count = _optional_int(census.get("selected_provider_baseline_count")) if census else None
    registry_provider_count = _optional_int(registry_receipt.get("provider_baseline_profile_count")) if registry_receipt else None
    expected_count = max(3, int(expected_provider_baseline_count))
    if not census:
        missing.append({"kind": "provider_baseline_census_missing"})
    elif census.get("schema") != "axio_fusion_api.provider_baseline_census.v1":
        missing.append(
            {
                "kind": "provider_baseline_census_schema_unrecognized",
                "schema": str(census.get("schema") or ""),
            }
        )
    if census and str(census.get("source") or "") != "registry_campaign":
        missing.append(
            {
                "kind": "provider_baseline_census_not_from_registry_campaign",
                "source": str(census.get("source") or ""),
            }
        )
    if not registry_receipt:
        missing.append({"kind": "provider_registry_receipt_missing"})
    elif registry_receipt.get("schema") != "axio_fusion_api.provider_registry_receipt.v1":
        missing.append(
            {
                "kind": "provider_registry_receipt_schema_unrecognized",
                "schema": str(registry_receipt.get("schema") or ""),
            }
        )
    if census and census.get("include_provider_baselines") is not True:
        missing.append({"kind": "provider_baseline_census_provider_baselines_disabled"})
    if census and str(census.get("provider_baseline_selection") or "") != EXTERNAL_PROVIDER_RANKING_SELECTION_MODE:
        missing.append(
            {
                "kind": "provider_baseline_census_not_externally_ranked_top_three",
                "provider_baseline_selection": str(census.get("provider_baseline_selection") or ""),
            }
        )
    if census and census.get("external_ranking_pre_registered") is not True:
        missing.append({"kind": "provider_baseline_census_external_ranking_not_pre_registered"})
    if census and (available_count or 0) < expected_count:
        missing.append(
            {
                "kind": "provider_baseline_census_available_count_too_small",
                "available_provider_baseline_count": available_count,
                "expected_provider_baseline_count": expected_count,
            }
        )
    if census and selected_count != expected_count:
        missing.append(
            {
                "kind": "provider_baseline_census_selected_count_not_top_three",
                "selected_provider_baseline_count": selected_count,
                "expected_provider_baseline_count": expected_count,
            }
        )
    if census and len(set(census_provider_hashes)) != (selected_count or 0):
        missing.append(
            {
                "kind": "provider_baseline_census_hash_count_mismatch",
                "selected_provider_baseline_count": selected_count,
                "selected_provider_hash_count": len(set(census_provider_hashes)),
            }
        )
    registry_profile_set = set(registry_provider_profile_hashes)
    census_available_profile_set = set(census_available_profile_hashes)
    registry_profile_set_digest = sha256_text(stable_json(sorted(registry_profile_set)))
    census_available_profile_set_digest = sha256_text(stable_json(sorted(census_available_profile_set)))
    if registry_receipt and registry_provider_count != available_count:
        missing.append(
            {
                "kind": "provider_registry_receipt_count_mismatch",
                "registry_provider_baseline_count": registry_provider_count,
                "census_available_provider_baseline_count": available_count,
            }
        )
    if registry_receipt and census and registry_profile_set != census_available_profile_set:
        missing.append(
            {
                "kind": "provider_registry_receipt_census_mismatch",
                "registry_provider_hash_count": len(registry_profile_set),
                "census_available_provider_hash_count": len(census_available_profile_set),
            }
        )
    if registry_receipt and str(registry_receipt.get("provider_baseline_profile_set_sha256") or "") != registry_profile_set_digest:
        missing.append({"kind": "provider_registry_receipt_profile_set_digest_mismatch"})
    if census and str(census.get("available_provider_profile_set_sha256") or "") != census_available_profile_set_digest:
        missing.append({"kind": "provider_baseline_census_available_profile_set_digest_mismatch"})
    if (
        registry_receipt
        and census
        and str(registry_receipt.get("provider_baseline_profile_set_sha256") or "")
        != str(census.get("available_provider_profile_set_sha256") or "")
    ):
        missing.append({"kind": "provider_registry_receipt_census_digest_mismatch"})
    expected_set = set(census_provider_hashes)
    run_set = set(run_provider_hashes)
    campaign_set = set(campaign_provider_hashes)
    scorecard_set = set(scorecard_provider_hashes)
    claim_set = set(claim_provider_hashes)
    if census and campaign_set != expected_set:
        missing.append(
            {
                "kind": "provider_baseline_campaign_candidate_set_mismatch",
                "expected_hash_count": len(expected_set),
                "campaign_hash_count": len(campaign_set),
            }
        )
    if census and run_set != expected_set:
        missing.append(
            {
                "kind": "provider_baseline_run_candidate_set_mismatch",
                "expected_hash_count": len(expected_set),
                "run_hash_count": len(run_set),
            }
        )
    if census and scorecard_set != expected_set:
        missing.append(
            {
                "kind": "provider_baseline_scorecard_candidate_set_mismatch",
                "expected_hash_count": len(expected_set),
                "scorecard_hash_count": len(scorecard_set),
            }
        )
    if census and claim_set and not claim_set.issubset(expected_set):
        missing.append(
            {
                "kind": "provider_baseline_claim_candidate_set_mismatch",
                "expected_hash_count": len(expected_set),
                "claim_hash_count": len(claim_set),
            }
        )
    selected_set_digest = sha256_text(stable_json(sorted(expected_set)))
    if census and str(census.get("selected_provider_candidate_id_set_sha256") or "") != selected_set_digest:
        missing.append({"kind": "provider_baseline_census_candidate_set_digest_mismatch"})
    return (
        {
            "available": bool(census),
            "schema": str(census.get("schema") or "") if census else "",
            "census_source": str(census.get("source") or "") if census else "",
            "registry_receipt_available": bool(registry_receipt),
            "registry_receipt_schema": str(registry_receipt.get("schema") or "") if registry_receipt else "",
            "provider_baseline_selection": str(census.get("provider_baseline_selection") or "") if census else "",
            "available_provider_baseline_count": available_count,
            "selected_provider_baseline_count": selected_count,
            "registry_provider_baseline_count": registry_provider_count,
            "expected_provider_baseline_count": expected_count,
            "selected_all_available_provider_baselines": census.get("selected_all_available_provider_baselines") if census else None,
            "external_ranking_pre_registered": census.get("external_ranking_pre_registered") is True if census else False,
            "external_ranking_receipt_digest_sha256": str(census.get("external_ranking_receipt_digest_sha256") or "") if census else "",
            "registry_profile_hash_count": len(registry_profile_set),
            "census_available_profile_hash_count": len(census_available_profile_set),
            "census_provider_hash_count": len(expected_set),
            "campaign_provider_hash_count": len(campaign_set),
            "run_provider_hash_count": len(run_set),
            "scorecard_provider_hash_count": len(scorecard_set),
            "claim_provider_hash_count": len(claim_set),
            "registry_receipt_matches_census": bool(registry_receipt)
            and bool(census)
            and registry_provider_count == available_count
            and registry_profile_set == census_available_profile_set
            and str(registry_receipt.get("provider_baseline_profile_set_sha256") or "")
            == str(census.get("available_provider_profile_set_sha256") or ""),
            "campaign_set_matches_census": bool(census) and campaign_set == expected_set,
            "run_set_matches_census": bool(census) and run_set == expected_set,
            "scorecard_set_matches_census": bool(census) and scorecard_set == expected_set,
            "claim_set_subset_of_census": bool(census) and (not claim_set or claim_set.issubset(expected_set)),
            "selected_provider_candidate_id_set_sha256": selected_set_digest if census else "",
            "ready": not missing,
            "raw_provider_model_ids_persisted": False,
            "raw_provider_urls_persisted": False,
            "raw_api_keys_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _provider_candidate_hashes_from_ids(candidate_ids: Sequence[Any]) -> list[str]:
    return sorted(
        {
            sha256_text(str(candidate_id))
            for candidate_id in candidate_ids
            if str(candidate_id or "").startswith("provider::")
        }
    )


def _provider_candidate_hashes_from_runs(runs: Sequence[Mapping[str, Any]]) -> list[str]:
    return _provider_candidate_hashes_from_ids(
        [
            run.get("candidate_id")
            for run in runs
            if isinstance(run, Mapping)
        ]
    )


def _provider_candidate_hashes_from_scorecard(scorecard: Mapping[str, Any]) -> list[str]:
    candidates = scorecard.get("candidates") if isinstance(scorecard.get("candidates"), list) else []
    return _provider_candidate_hashes_from_ids(
        [
            row.get("candidate_id")
            for row in candidates
            if isinstance(row, Mapping)
        ]
    )


def _provider_candidate_hashes_from_claim_audit(claim_audit: Mapping[str, Any]) -> list[str]:
    comparisons = claim_audit.get("comparisons") if isinstance(claim_audit.get("comparisons"), list) else []
    return _provider_candidate_hashes_from_ids(
        [
            row.get("baseline_candidate_id")
            for row in comparisons
            if isinstance(row, Mapping)
        ]
    )


def _expected_provider_baseline_count_for_final(campaign: Mapping[str, Any]) -> int:
    # Formal claims are always paired with the externally pre-registered
    # configured-provider-pool rank 1/2/3 baselines. Legacy exhaustive
    # inventories remain diagnostic artifacts and cannot expand this claim family.
    del campaign
    return len(EXTERNAL_PROVIDER_RANKING_REQUIRED_RANKS)


def _final_provider_baseline_freeze_summary(
    *,
    campaign: Mapping[str, Any],
    freeze_manifest: Mapping[str, Any],
    runs: Sequence[Mapping[str, Any]],
    scorecard: Mapping[str, Any],
    claim_audit: Mapping[str, Any],
    expected_provider_baseline_count: int,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing = []
    manifest = freeze_manifest if isinstance(freeze_manifest, Mapping) else {}
    freeze_receipt = manifest.get("freeze_receipt") if isinstance(manifest.get("freeze_receipt"), Mapping) else {}
    campaign_freeze_receipt = (
        campaign.get("provider_baseline_freeze_receipt")
        if isinstance(campaign.get("provider_baseline_freeze_receipt"), Mapping)
        else {}
    )
    registry_receipt = (
        manifest.get("provider_registry_receipt")
        if isinstance(manifest.get("provider_registry_receipt"), Mapping)
        else {}
    )
    probe_evidence_receipt = (
        manifest.get("provider_probe_evidence_audit_receipt")
        if isinstance(manifest.get("provider_probe_evidence_audit_receipt"), Mapping)
        else {}
    )
    provider_portfolio_summary = (
        manifest.get("provider_portfolio_summary")
        if isinstance(manifest.get("provider_portfolio_summary"), Mapping)
        else {}
    )
    provider_portfolio_capacity = (
        provider_portfolio_summary.get("independent_verification_capacity")
        if isinstance(provider_portfolio_summary.get("independent_verification_capacity"), Mapping)
        else {}
    )
    selected_candidate_hashes = [
        str(item)
        for item in manifest.get("selected_provider_candidate_id_hashes", [])
        if _looks_like_sha256(item)
    ] if isinstance(manifest.get("selected_provider_candidate_id_hashes"), list) else []
    campaign_candidate_hashes = _provider_candidate_hashes_from_ids(
        campaign.get("candidate_ids") if isinstance(campaign.get("candidate_ids"), list) else []
    )
    run_candidate_hashes = _provider_candidate_hashes_from_runs(runs)
    scorecard_candidate_hashes = _provider_candidate_hashes_from_scorecard(scorecard)
    claim_candidate_hashes = _provider_candidate_hashes_from_claim_audit(claim_audit)
    claim_freeze_binding = (
        claim_audit.get("provider_baseline_freeze_binding")
        if isinstance(claim_audit.get("provider_baseline_freeze_binding"), Mapping)
        else {}
    )
    selected_set = set(selected_candidate_hashes)
    campaign_set = set(campaign_candidate_hashes)
    run_set = set(run_candidate_hashes)
    scorecard_set = set(scorecard_candidate_hashes)
    claim_set = set(claim_candidate_hashes)
    computed_digest = sha256_text(stable_json(_provider_baseline_freeze_digest_input(manifest))) if manifest else ""
    declared_digest = str(manifest.get("freeze_digest_sha256") or "") if manifest else ""
    receipt_digest = str(freeze_receipt.get("freeze_digest_sha256") or "") if freeze_receipt else ""
    campaign_receipt_digest = str(campaign_freeze_receipt.get("freeze_digest_sha256") or "") if campaign_freeze_receipt else ""
    available_count = _optional_int(manifest.get("available_provider_baseline_count")) if manifest else None
    selected_count = _optional_int(manifest.get("selected_provider_baseline_count")) if manifest else None
    selected_live_count = _optional_int(manifest.get("selected_live_probe_evidence_count")) if manifest else None
    selected_all_available = manifest.get("selected_all_available_provider_baselines") is True if manifest else False
    selection_mode = str(manifest.get("provider_baseline_selection") or "") if manifest else ""
    external_ranking_receipt = (
        manifest.get("external_ranking_receipt")
        if isinstance(manifest.get("external_ranking_receipt"), Mapping)
        else {}
    )
    external_ranking_validation_errors = _external_provider_rank_mapping_validation_errors(
        manifest,
        expected_registry_file_sha256=str(registry_receipt.get("registry_file_sha256") or ""),
    ) if manifest else ["external_ranking_freeze_manifest_missing"]
    external_rank_values = [
        _optional_int(value) or 0
        for value in external_ranking_receipt.get("rank_values", [])
        if _optional_int(value) is not None
    ]
    frozen_external_ranks = [
        _optional_int(row.get("pre_campaign_external_rank")) or 0
        for row in manifest.get("frozen_candidate_rows", [])
        if isinstance(row, Mapping)
    ]
    probe_min_live_count = max(
        3,
        _optional_int(probe_evidence_receipt.get("min_live_available_models")) or 3,
    )
    probe_available_count = _optional_int(probe_evidence_receipt.get("private_probe_available_count")) or 0
    probe_live_available_count = (
        _optional_int(probe_evidence_receipt.get("private_probe_live_available_count")) or 0
    )
    probe_mode_counts = (
        dict(probe_evidence_receipt.get("private_probe_mode_counts") or {})
        if isinstance(probe_evidence_receipt.get("private_probe_mode_counts"), Mapping)
        else {}
    )
    probe_live_mode_count = _optional_int(probe_mode_counts.get("live")) or 0
    probe_live_profile_set_sha256 = str(
        probe_evidence_receipt.get("private_probe_live_available_profile_set_sha256") or ""
    )

    if not manifest:
        missing.append({"kind": "provider_baseline_freeze_missing"})
    elif manifest.get("schema") != "axio_fusion_api.provider_baseline_freeze_manifest.v1":
        missing.append(
            {
                "kind": "provider_baseline_freeze_schema_unrecognized",
                "schema": str(manifest.get("schema") or ""),
            }
        )
    if manifest and not freeze_receipt:
        missing.append({"kind": "provider_baseline_freeze_receipt_missing"})
    elif freeze_receipt:
        if freeze_receipt.get("schema") != "axio_fusion_api.provider_baseline_freeze_receipt.v1":
            missing.append({"kind": "provider_baseline_freeze_receipt_schema_unrecognized"})
        if not _looks_like_sha256(declared_digest):
            missing.append({"kind": "provider_baseline_freeze_digest_missing"})
        elif computed_digest != declared_digest:
            missing.append({"kind": "provider_baseline_freeze_digest_mismatch"})
        if not _looks_like_sha256(receipt_digest):
            missing.append({"kind": "provider_baseline_freeze_receipt_digest_missing"})
        elif receipt_digest != computed_digest:
            missing.append({"kind": "provider_baseline_freeze_receipt_digest_mismatch"})
        if freeze_receipt.get("freeze_digest_matches") is not True:
            missing.append({"kind": "provider_baseline_freeze_receipt_not_bound"})
        if freeze_receipt.get("final_claim_freeze_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_not_final_ready"})
    if campaign and not campaign_freeze_receipt:
        missing.append({"kind": "campaign_provider_baseline_freeze_receipt_missing"})
    elif campaign_freeze_receipt:
        if campaign_freeze_receipt.get("schema") != "axio_fusion_api.provider_baseline_freeze_receipt.v1":
            missing.append({"kind": "campaign_provider_baseline_freeze_receipt_schema_unrecognized"})
        if not _looks_like_sha256(campaign_receipt_digest):
            missing.append({"kind": "campaign_provider_baseline_freeze_receipt_digest_missing"})
        elif _looks_like_sha256(computed_digest) and campaign_receipt_digest != computed_digest:
            missing.append({"kind": "campaign_provider_baseline_freeze_receipt_digest_mismatch"})
        if campaign_freeze_receipt.get("freeze_digest_matches") is not True:
            missing.append({"kind": "campaign_provider_baseline_freeze_receipt_not_bound"})
    if manifest and available_count is not None and selected_count is not None and selected_count > available_count:
        missing.append({"kind": "provider_baseline_freeze_selected_count_exceeds_available"})
    if manifest and selected_count is not None and selected_count < int(expected_provider_baseline_count):
        missing.append({"kind": "provider_baseline_freeze_selected_count_too_small"})
    if manifest and selected_live_count is not None and selected_live_count < int(expected_provider_baseline_count):
        missing.append({"kind": "provider_baseline_freeze_live_probe_evidence_too_small"})
    if manifest and selection_mode != EXTERNAL_PROVIDER_RANKING_SELECTION_MODE:
        missing.append({"kind": "provider_baseline_freeze_not_externally_ranked_top_three"})
    if manifest and selected_all_available:
        missing.append({"kind": "provider_baseline_freeze_unexpected_all_available_selection"})
    if manifest and selected_count != len(EXTERNAL_PROVIDER_RANKING_REQUIRED_RANKS):
        missing.append({"kind": "provider_baseline_freeze_selected_count_not_top_three"})
    if manifest and external_ranking_receipt.get("schema") != EXTERNAL_PROVIDER_RANKING_RECEIPT_SCHEMA:
        missing.append({"kind": "provider_baseline_freeze_external_ranking_receipt_missing"})
    if manifest and external_ranking_receipt.get("ready") is not True:
        missing.append({"kind": "provider_baseline_freeze_external_ranking_not_ready"})
    if manifest and external_ranking_receipt.get("pre_registered_before_campaign") is not True:
        missing.append({"kind": "provider_baseline_freeze_external_ranking_not_pre_registered"})
    if manifest and external_ranking_receipt.get("registry_file_matches_current_registry") is not True:
        missing.append({"kind": "provider_baseline_freeze_external_ranking_registry_mismatch"})
    if manifest and external_ranking_receipt.get("target_benchmark_material_detected") is True:
        missing.append({"kind": "provider_baseline_freeze_external_ranking_contains_target_benchmark_material"})
    for reason in external_ranking_validation_errors:
        missing.append({"kind": f"provider_baseline_freeze_{reason}"})
    if manifest and sorted(external_rank_values) != list(EXTERNAL_PROVIDER_RANKING_REQUIRED_RANKS):
        missing.append({"kind": "provider_baseline_freeze_external_ranking_top_three_incomplete"})
    if manifest and sorted(frozen_external_ranks) != list(EXTERNAL_PROVIDER_RANKING_REQUIRED_RANKS):
        missing.append({"kind": "provider_baseline_freeze_frozen_rank_mapping_invalid"})
    if manifest and registry_receipt:
        registry_profile_set = str(registry_receipt.get("provider_baseline_profile_set_sha256") or "")
        available_set = str(manifest.get("available_provider_profile_set_sha256") or "")
        if registry_receipt.get("schema") != "axio_fusion_api.provider_registry_receipt.v1":
            missing.append({"kind": "provider_baseline_freeze_registry_receipt_schema_unrecognized"})
        if registry_profile_set and available_set and registry_profile_set != available_set:
            missing.append({"kind": "provider_baseline_freeze_registry_profile_set_mismatch"})
    if manifest and not probe_evidence_receipt:
        missing.append({"kind": "provider_baseline_freeze_probe_evidence_receipt_missing"})
    elif probe_evidence_receipt:
        if probe_evidence_receipt.get("schema") != "axio_fusion_api.provider_probe_evidence_audit_freeze_receipt.v1":
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_receipt_schema_unrecognized"})
        if probe_evidence_receipt.get("ready_for_baseline_freeze") is not True:
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_receipt_not_ready"})
        if probe_evidence_receipt.get("audit_digest_matches") is not True:
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_audit_digest_mismatch"})
        if probe_evidence_receipt.get("registry_file_matches_current_registry") is not True:
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_registry_file_mismatch"})
        if not _looks_like_sha256(probe_evidence_receipt.get("audit_digest_sha256")):
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_audit_digest_missing"})
        if probe_available_count < probe_min_live_count:
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_available_count_too_small"})
        if probe_live_available_count < probe_min_live_count:
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_live_available_count_too_small"})
        if probe_live_mode_count < probe_min_live_count:
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_live_mode_count_too_small"})
        if not _looks_like_sha256(probe_live_profile_set_sha256):
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_live_profile_set_digest_missing"})
        if probe_evidence_receipt.get("private_registry_live_probe_proven") is not True:
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_registry_live_probe_not_proven"})
        if probe_evidence_receipt.get("private_registry_final_claim_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_probe_evidence_registry_not_final_claim_ready"})
    if manifest and not provider_portfolio_summary:
        missing.append({"kind": "provider_baseline_freeze_provider_portfolio_summary_missing"})
    elif provider_portfolio_summary:
        if provider_portfolio_summary.get("schema") != "axio_fusion_api.provider_portfolio_freeze_summary.v1":
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_summary_schema_unrecognized"})
        if provider_portfolio_summary.get("available") is not True:
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_summary_unavailable"})
        if provider_portfolio_summary.get("final_claim_portfolio_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_not_ready"})
        if provider_portfolio_capacity.get("final_claim_independent_verification_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_independent_verification_not_ready"})
        if provider_portfolio_capacity.get("cross_provider_verifier_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_cross_provider_verifier_missing"})
        if not _looks_like_sha256(provider_portfolio_capacity.get("top_verifier_profile_set_sha256")):
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_verifier_set_digest_missing"})
    if freeze_receipt:
        if freeze_receipt.get("provider_probe_evidence_audit_digest_matches") is not True:
            missing.append({"kind": "provider_baseline_freeze_receipt_probe_evidence_audit_digest_mismatch"})
        if (
            _optional_int(freeze_receipt.get("provider_probe_evidence_private_probe_live_available_count"))
            or 0
        ) < probe_min_live_count:
            missing.append({"kind": "provider_baseline_freeze_receipt_probe_evidence_live_available_count_too_small"})
        if freeze_receipt.get("provider_probe_evidence_private_registry_live_probe_proven") is not True:
            missing.append({"kind": "provider_baseline_freeze_receipt_probe_evidence_registry_live_probe_not_proven"})
        if freeze_receipt.get("provider_probe_evidence_private_registry_final_claim_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_receipt_probe_evidence_registry_not_final_claim_ready"})
        if (
            freeze_receipt.get("provider_probe_evidence_private_probe_mode_counts")
            != probe_mode_counts
        ):
            missing.append({"kind": "provider_baseline_freeze_receipt_probe_evidence_mode_counts_mismatch"})
        if (
            str(
                freeze_receipt.get(
                    "provider_probe_evidence_private_probe_live_available_profile_set_sha256"
                )
                or ""
            )
            != probe_live_profile_set_sha256
        ):
            missing.append({"kind": "provider_baseline_freeze_receipt_probe_evidence_live_profile_set_mismatch"})
        if freeze_receipt.get("provider_portfolio_summary_bound") is not True:
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_receipt_not_bound"})
        if freeze_receipt.get("provider_portfolio_final_claim_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_receipt_not_final_ready"})
        if freeze_receipt.get("provider_portfolio_independent_verification_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_receipt_independent_verification_not_ready"})
        if freeze_receipt.get("provider_portfolio_cross_provider_verifier_ready") is not True:
            missing.append({"kind": "provider_baseline_freeze_provider_portfolio_receipt_cross_provider_verifier_missing"})
    if campaign_freeze_receipt:
        if campaign_freeze_receipt.get("provider_probe_evidence_audit_digest_matches") is not True:
            missing.append({"kind": "campaign_provider_baseline_freeze_probe_evidence_audit_digest_mismatch"})
        if (
            _optional_int(
                campaign_freeze_receipt.get(
                    "provider_probe_evidence_private_probe_live_available_count"
                )
            )
            or 0
        ) < probe_min_live_count:
            missing.append({"kind": "campaign_provider_baseline_freeze_probe_evidence_live_available_count_too_small"})
        if campaign_freeze_receipt.get("provider_probe_evidence_private_registry_live_probe_proven") is not True:
            missing.append({"kind": "campaign_provider_baseline_freeze_probe_evidence_registry_live_probe_not_proven"})
        if campaign_freeze_receipt.get("provider_probe_evidence_private_registry_final_claim_ready") is not True:
            missing.append({"kind": "campaign_provider_baseline_freeze_probe_evidence_registry_not_final_claim_ready"})
        if (
            campaign_freeze_receipt.get("provider_probe_evidence_private_probe_mode_counts")
            != probe_mode_counts
        ):
            missing.append({"kind": "campaign_provider_baseline_freeze_probe_evidence_mode_counts_mismatch"})
        if (
            str(
                campaign_freeze_receipt.get(
                    "provider_probe_evidence_private_probe_live_available_profile_set_sha256"
                )
                or ""
            )
            != probe_live_profile_set_sha256
        ):
            missing.append({"kind": "campaign_provider_baseline_freeze_probe_evidence_live_profile_set_mismatch"})
        if campaign_freeze_receipt.get("provider_portfolio_summary_bound") is not True:
            missing.append({"kind": "campaign_provider_baseline_freeze_provider_portfolio_receipt_not_bound"})
        if campaign_freeze_receipt.get("provider_portfolio_cross_provider_verifier_ready") is not True:
            missing.append({"kind": "campaign_provider_baseline_freeze_provider_portfolio_cross_provider_verifier_missing"})
    if manifest and campaign_set != selected_set:
        missing.append(
            {
                "kind": "provider_baseline_freeze_campaign_candidate_set_mismatch",
                "campaign_hash_count": len(campaign_set),
                "freeze_hash_count": len(selected_set),
            }
        )
    if manifest and run_set != selected_set:
        missing.append(
            {
                "kind": "provider_baseline_freeze_run_candidate_set_mismatch",
                "run_hash_count": len(run_set),
                "freeze_hash_count": len(selected_set),
            }
        )
    if manifest and scorecard_set != selected_set:
        missing.append(
            {
                "kind": "provider_baseline_freeze_scorecard_candidate_set_mismatch",
                "scorecard_hash_count": len(scorecard_set),
                "freeze_hash_count": len(selected_set),
            }
        )
    if manifest and claim_set and not claim_set.issubset(selected_set):
        missing.append(
            {
                "kind": "provider_baseline_freeze_claim_candidate_set_mismatch",
                "claim_hash_count": len(claim_set),
                "freeze_hash_count": len(selected_set),
            }
        )
    if manifest and str(claim_freeze_binding.get("freeze_digest_sha256") or "") != computed_digest:
        missing.append({"kind": "claim_audit_provider_baseline_freeze_digest_mismatch"})
    if manifest and str(claim_freeze_binding.get("external_ranking_receipt_digest_sha256") or "") != str(
        external_ranking_receipt.get("receipt_digest_sha256") or ""
    ):
        missing.append({"kind": "claim_audit_external_ranking_receipt_digest_mismatch"})
    if manifest and claim_freeze_binding.get("ready") is not True:
        missing.append({"kind": "claim_audit_provider_baseline_freeze_binding_not_ready"})
    return (
        {
            "available": bool(manifest),
            "schema": str(manifest.get("schema") or "") if manifest else "",
            "freeze_digest_sha256": declared_digest,
            "freeze_receipt_digest_sha256": receipt_digest,
            "computed_freeze_digest_sha256": computed_digest,
            "freeze_receipt_matches_computed": bool(receipt_digest) and receipt_digest == computed_digest,
            "campaign_freeze_receipt_digest_sha256": campaign_receipt_digest,
            "campaign_freeze_receipt_matches_computed": bool(campaign_receipt_digest) and campaign_receipt_digest == computed_digest,
            "provider_baseline_selection": str(manifest.get("provider_baseline_selection") or "") if manifest else "",
            "selected_all_available_provider_baselines": selected_all_available,
            "external_ranking_pre_registered": external_ranking_receipt.get("pre_registered_before_campaign") is True,
            "external_ranking_ready": external_ranking_receipt.get("ready") is True,
            "external_ranking_receipt_digest_sha256": str(external_ranking_receipt.get("receipt_digest_sha256") or ""),
            "external_ranking_validation_error_count": len(external_ranking_validation_errors),
            "external_ranking_validation_errors": external_ranking_validation_errors,
            "external_ranking_rank_values": external_rank_values,
            "frozen_external_rank_values": frozen_external_ranks,
            "available_provider_baseline_count": available_count,
            "selected_provider_baseline_count": selected_count,
            "selected_live_probe_evidence_count": selected_live_count,
            "registry_profile_set_sha256": str(registry_receipt.get("provider_baseline_profile_set_sha256") or "") if registry_receipt else "",
            "probe_evidence_audit_digest_sha256": str(probe_evidence_receipt.get("audit_digest_sha256") or "") if probe_evidence_receipt else "",
            "probe_evidence_registry_file_sha256": str(probe_evidence_receipt.get("private_registry_content_sha256") or "") if probe_evidence_receipt else "",
            "probe_evidence_receipt_ready_for_baseline_freeze": probe_evidence_receipt.get("ready_for_baseline_freeze") is True if probe_evidence_receipt else False,
            "probe_evidence_audit_digest_matches": probe_evidence_receipt.get("audit_digest_matches") is True if probe_evidence_receipt else False,
            "probe_evidence_receipt_registry_file_matches": probe_evidence_receipt.get("registry_file_matches_current_registry") is True if probe_evidence_receipt else False,
            "probe_evidence_min_live_available_models": probe_min_live_count,
            "probe_evidence_private_probe_available_count": probe_available_count,
            "probe_evidence_private_probe_live_available_count": probe_live_available_count,
            "probe_evidence_private_probe_live_mode_count": probe_live_mode_count,
            "probe_evidence_private_probe_mode_counts": probe_mode_counts,
            "probe_evidence_private_probe_live_available_profile_set_sha256": probe_live_profile_set_sha256,
            "probe_evidence_private_registry_live_probe_proven": probe_evidence_receipt.get("private_registry_live_probe_proven") is True if probe_evidence_receipt else False,
            "probe_evidence_private_registry_final_claim_ready": probe_evidence_receipt.get("private_registry_final_claim_ready") is True if probe_evidence_receipt else False,
            "provider_portfolio_summary_available": provider_portfolio_summary.get("available") is True if provider_portfolio_summary else False,
            "provider_portfolio_final_claim_ready": provider_portfolio_summary.get("final_claim_portfolio_ready") is True if provider_portfolio_summary else False,
            "provider_portfolio_independent_verification_ready": provider_portfolio_capacity.get("final_claim_independent_verification_ready") is True if provider_portfolio_capacity else False,
            "provider_portfolio_cross_provider_verifier_ready": provider_portfolio_capacity.get("cross_provider_verifier_ready") is True if provider_portfolio_capacity else False,
            "provider_portfolio_ready_verifier_count": _optional_int(provider_portfolio_capacity.get("ready_verifier_count")) if provider_portfolio_capacity else None,
            "provider_portfolio_ready_provider_hash_count": _optional_int(provider_portfolio_capacity.get("ready_provider_hash_count")) if provider_portfolio_capacity else None,
            "provider_portfolio_top_verifier_profile_set_sha256": str(provider_portfolio_capacity.get("top_verifier_profile_set_sha256") or "") if provider_portfolio_capacity else "",
            "freeze_receipt_provider_portfolio_bound": freeze_receipt.get("provider_portfolio_summary_bound") is True if freeze_receipt else False,
            "campaign_freeze_receipt_provider_portfolio_bound": campaign_freeze_receipt.get("provider_portfolio_summary_bound") is True if campaign_freeze_receipt else False,
            "available_provider_profile_set_sha256": str(manifest.get("available_provider_profile_set_sha256") or "") if manifest else "",
            "selected_provider_profile_set_sha256": str(manifest.get("selected_provider_profile_set_sha256") or "") if manifest else "",
            "selected_provider_candidate_id_set_sha256": str(manifest.get("selected_provider_candidate_id_set_sha256") or "") if manifest else "",
            "campaign_candidate_hash_count": len(campaign_set),
            "run_candidate_hash_count": len(run_set),
            "scorecard_candidate_hash_count": len(scorecard_set),
            "claim_candidate_hash_count": len(claim_set),
            "campaign_set_matches_freeze": bool(manifest) and campaign_set == selected_set,
            "run_set_matches_freeze": bool(manifest) and run_set == selected_set,
            "scorecard_set_matches_freeze": bool(manifest) and scorecard_set == selected_set,
            "claim_set_subset_of_freeze": bool(manifest) and (not claim_set or claim_set.issubset(selected_set)),
            "claim_freeze_binding_ready": claim_freeze_binding.get("ready") is True,
            "claim_freeze_binding_matches_freeze": str(claim_freeze_binding.get("freeze_digest_sha256") or "") == computed_digest,
            "ready": not missing,
            "raw_provider_model_ids_persisted": False,
            "raw_provider_urls_persisted": False,
            "raw_api_keys_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _final_provider_probe_evidence_summary(
    *,
    audit: Mapping[str, Any],
    campaign: Mapping[str, Any],
    provider_baseline_freeze: Mapping[str, Any],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing: list[dict[str, Any]] = []
    payload = audit if isinstance(audit, Mapping) else {}
    checked = payload.get("checked_artifacts") if isinstance(payload.get("checked_artifacts"), Mapping) else {}
    private_registry = checked.get("private_registry") if isinstance(checked.get("private_registry"), Mapping) else {}
    binding = payload.get("cross_artifact_binding") if isinstance(payload.get("cross_artifact_binding"), Mapping) else {}
    leakage = payload.get("anti_leakage_audit") if isinstance(payload.get("anti_leakage_audit"), Mapping) else {}
    artifact_summaries = (
        payload.get("artifact_summaries")
        if isinstance(payload.get("artifact_summaries"), Mapping)
        else {}
    )
    private_probe_summary = (
        artifact_summaries.get("private_probe")
        if isinstance(artifact_summaries.get("private_probe"), Mapping)
        else {}
    )
    private_registry_summary = (
        artifact_summaries.get("private_registry")
        if isinstance(artifact_summaries.get("private_registry"), Mapping)
        else {}
    )
    private_registry_readiness = (
        private_registry_summary.get("readiness")
        if isinstance(private_registry_summary.get("readiness"), Mapping)
        else {}
    )
    blockers = payload.get("blockers") if isinstance(payload.get("blockers"), list) else []
    campaign_registry_receipt = (
        campaign.get("provider_registry_receipt")
        if isinstance(campaign.get("provider_registry_receipt"), Mapping)
        else {}
    )
    freeze_registry_receipt = (
        provider_baseline_freeze.get("provider_registry_receipt")
        if isinstance(provider_baseline_freeze.get("provider_registry_receipt"), Mapping)
        else {}
    )
    freeze_probe_evidence_receipt = (
        provider_baseline_freeze.get("provider_probe_evidence_audit_receipt")
        if isinstance(provider_baseline_freeze.get("provider_probe_evidence_audit_receipt"), Mapping)
        else {}
    )
    audit_registry_file_sha = str(private_registry.get("content_sha256") or "")
    campaign_registry_file_sha = str(campaign_registry_receipt.get("registry_file_sha256") or "")
    freeze_registry_file_sha = str(freeze_registry_receipt.get("registry_file_sha256") or "")
    audit_digest = str(payload.get("audit_digest_sha256") or "") if payload else ""
    computed_audit_digest = (
        sha256_text(stable_json(_provider_probe_evidence_audit_digest_input(payload)))
        if payload
        else ""
    )
    audit_digest_matches = bool(
        _looks_like_sha256(audit_digest)
        and computed_audit_digest
        and audit_digest == computed_audit_digest
    )
    freeze_probe_audit_digest = str(freeze_probe_evidence_receipt.get("audit_digest_sha256") or "") if freeze_probe_evidence_receipt else ""
    min_live_available_models = max(
        3,
        _optional_int(payload.get("min_available_models")) or 3,
        _optional_int(freeze_probe_evidence_receipt.get("min_live_available_models")) or 3,
    )
    private_probe_available_count = _optional_int(private_probe_summary.get("available_count")) or 0
    private_probe_live_available_count = (
        _optional_int(private_probe_summary.get("live_available_count")) or 0
    )
    private_probe_mode_counts = (
        dict(private_probe_summary.get("mode_counts") or {})
        if isinstance(private_probe_summary.get("mode_counts"), Mapping)
        else {}
    )
    private_probe_live_mode_count = _optional_int(private_probe_mode_counts.get("live")) or 0
    private_probe_available_profile_set_sha256 = str(
        private_probe_summary.get("available_profile_set_sha256") or ""
    )
    private_probe_live_available_profile_set_sha256 = str(
        private_probe_summary.get("live_available_profile_set_sha256") or ""
    )
    if not payload:
        missing.append({"kind": "provider_probe_evidence_audit_missing"})
    elif str(payload.get("schema") or "") != "axio_fusion_api.provider_probe_evidence_audit.v1":
        missing.append(
            {
                "kind": "provider_probe_evidence_audit_schema_unrecognized",
                "schema": str(payload.get("schema") or ""),
            }
        )
    if payload and payload.get("ready") is not True:
        missing.append({"kind": "provider_probe_evidence_audit_not_ready"})
    if payload and str(payload.get("status") or "") != "ready":
        missing.append({"kind": "provider_probe_evidence_audit_status_not_ready"})
    if payload and not _looks_like_sha256(audit_digest):
        missing.append({"kind": "provider_probe_evidence_audit_digest_missing"})
    elif payload and not audit_digest_matches:
        missing.append({"kind": "provider_probe_evidence_audit_digest_mismatch"})
    if blockers:
        missing.append(
            {
                "kind": "provider_probe_evidence_audit_has_blockers",
                "blocker_count": len(blockers),
                "blocker_kind_hashes": [
                    sha256_text(str(row.get("kind") or ""))
                    for row in blockers[:12]
                    if isinstance(row, Mapping)
                ],
            }
        )
    if payload and binding.get("all_bindings_ready") is not True:
        missing.append({"kind": "provider_probe_evidence_audit_binding_not_ready"})
    leakage_flags = {
        "safe_artifacts_do_not_contain_private_identifiers": leakage.get("safe_artifacts_do_not_contain_private_identifiers") is True,
        "safe_artifacts_have_no_true_raw_persistence_flags": leakage.get("safe_artifacts_have_no_true_raw_persistence_flags") is True,
        "safe_artifacts_have_no_true_secret_persistence_flags": leakage.get("safe_artifacts_have_no_true_secret_persistence_flags") is True,
        "safe_artifacts_have_no_raw_urls": leakage.get("safe_artifacts_have_no_raw_urls") is True,
        "safe_artifacts_have_no_api_key_like_values": leakage.get("safe_artifacts_have_no_api_key_like_values") is True,
    }
    if payload and not all(leakage_flags.values()):
        missing.append({"kind": "provider_probe_evidence_audit_leakage_not_clean"})
    if payload and not audit_registry_file_sha:
        missing.append({"kind": "provider_probe_evidence_private_registry_content_hash_missing"})
    if payload and private_probe_available_count < min_live_available_models:
        missing.append({"kind": "provider_probe_evidence_private_probe_available_count_too_small"})
    if payload and private_probe_live_available_count < min_live_available_models:
        missing.append({"kind": "provider_probe_evidence_private_probe_live_available_count_too_small"})
    if payload and private_probe_live_mode_count < min_live_available_models:
        missing.append({"kind": "provider_probe_evidence_private_probe_live_mode_count_too_small"})
    if payload and not _looks_like_sha256(private_probe_available_profile_set_sha256):
        missing.append({"kind": "provider_probe_evidence_private_probe_available_profile_set_digest_missing"})
    if payload and not _looks_like_sha256(private_probe_live_available_profile_set_sha256):
        missing.append({"kind": "provider_probe_evidence_private_probe_live_profile_set_digest_missing"})
    if payload and private_registry_readiness.get("live_probe_proven") is not True:
        missing.append({"kind": "provider_probe_evidence_private_registry_live_probe_not_proven"})
    if payload and private_registry_readiness.get("final_claim_registry_ready") is not True:
        missing.append({"kind": "provider_probe_evidence_private_registry_not_final_claim_ready"})
    if payload and campaign_registry_file_sha and audit_registry_file_sha and audit_registry_file_sha != campaign_registry_file_sha:
        missing.append({"kind": "provider_probe_evidence_campaign_registry_file_mismatch"})
    if payload and freeze_registry_file_sha and audit_registry_file_sha and audit_registry_file_sha != freeze_registry_file_sha:
        missing.append({"kind": "provider_probe_evidence_freeze_registry_file_mismatch"})
    if payload and not freeze_probe_evidence_receipt:
        missing.append({"kind": "provider_probe_evidence_freeze_receipt_missing"})
    elif freeze_probe_evidence_receipt:
        if freeze_probe_evidence_receipt.get("ready_for_baseline_freeze") is not True:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_not_ready"})
        if freeze_probe_evidence_receipt.get("audit_digest_matches") is not True:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_audit_digest_mismatch"})
        if audit_digest and freeze_probe_audit_digest and audit_digest != freeze_probe_audit_digest:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_digest_mismatch"})
        if audit_registry_file_sha and str(freeze_probe_evidence_receipt.get("private_registry_content_sha256") or "") != audit_registry_file_sha:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_registry_file_mismatch"})
        if (
            _optional_int(freeze_probe_evidence_receipt.get("private_probe_available_count"))
            or 0
        ) != private_probe_available_count:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_available_count_mismatch"})
        if (
            _optional_int(freeze_probe_evidence_receipt.get("private_probe_live_available_count"))
            or 0
        ) != private_probe_live_available_count:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_live_available_count_mismatch"})
        if (
            dict(freeze_probe_evidence_receipt.get("private_probe_mode_counts") or {})
            if isinstance(freeze_probe_evidence_receipt.get("private_probe_mode_counts"), Mapping)
            else {}
        ) != private_probe_mode_counts:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_mode_counts_mismatch"})
        if (
            str(
                freeze_probe_evidence_receipt.get(
                    "private_probe_live_available_profile_set_sha256"
                )
                or ""
            )
            != private_probe_live_available_profile_set_sha256
        ):
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_live_profile_set_mismatch"})
        if freeze_probe_evidence_receipt.get("private_registry_live_probe_proven") is not True:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_registry_live_probe_not_proven"})
        if freeze_probe_evidence_receipt.get("private_registry_final_claim_ready") is not True:
            missing.append({"kind": "provider_probe_evidence_freeze_receipt_registry_not_final_claim_ready"})
    if payload and _contains_forbidden_persistence_flag(payload):
        missing.append({"kind": "provider_probe_evidence_forbidden_persistence_flag_detected"})
    return (
        {
            "available": bool(payload),
            "schema": str(payload.get("schema") or "") if payload else "",
            "status": str(payload.get("status") or "") if payload else "",
            "ready": not missing,
            "audit_ready": payload.get("ready") is True if payload else False,
            "audit_digest_sha256": audit_digest,
            "computed_audit_digest_sha256": computed_audit_digest,
            "audit_digest_matches": audit_digest_matches,
            "freeze_receipt_audit_digest_sha256": freeze_probe_audit_digest,
            "min_live_available_models": min_live_available_models,
            "private_probe_available_count": private_probe_available_count,
            "private_probe_live_available_count": private_probe_live_available_count,
            "private_probe_live_mode_count": private_probe_live_mode_count,
            "private_probe_mode_counts": private_probe_mode_counts,
            "private_probe_available_profile_set_sha256": private_probe_available_profile_set_sha256,
            "private_probe_live_available_profile_set_sha256": private_probe_live_available_profile_set_sha256,
            "private_registry_live_probe_proven": private_registry_readiness.get("live_probe_proven") is True,
            "private_registry_final_claim_ready": private_registry_readiness.get("final_claim_registry_ready") is True,
            "private_registry_content_sha256": audit_registry_file_sha,
            "campaign_registry_file_sha256": campaign_registry_file_sha,
            "freeze_registry_file_sha256": freeze_registry_file_sha,
            "campaign_registry_file_matches_probe_evidence": bool(audit_registry_file_sha and campaign_registry_file_sha)
            and audit_registry_file_sha == campaign_registry_file_sha,
            "freeze_registry_file_matches_probe_evidence": bool(audit_registry_file_sha and freeze_registry_file_sha)
            and audit_registry_file_sha == freeze_registry_file_sha,
            "freeze_probe_evidence_receipt_present": bool(freeze_probe_evidence_receipt),
            "freeze_probe_evidence_receipt_ready": freeze_probe_evidence_receipt.get("ready_for_baseline_freeze") is True if freeze_probe_evidence_receipt else False,
            "freeze_probe_evidence_receipt_digest_matches_audit": bool(audit_digest and freeze_probe_audit_digest) and audit_digest == freeze_probe_audit_digest,
            "all_bindings_ready": binding.get("all_bindings_ready") is True,
            "safe_artifacts_do_not_contain_private_identifiers": leakage_flags["safe_artifacts_do_not_contain_private_identifiers"],
            "safe_artifacts_have_no_true_raw_persistence_flags": leakage_flags["safe_artifacts_have_no_true_raw_persistence_flags"],
            "safe_artifacts_have_no_true_secret_persistence_flags": leakage_flags["safe_artifacts_have_no_true_secret_persistence_flags"],
            "safe_artifacts_have_no_raw_urls": leakage_flags["safe_artifacts_have_no_raw_urls"],
            "safe_artifacts_have_no_api_key_like_values": leakage_flags["safe_artifacts_have_no_api_key_like_values"],
            "blocker_count": len(blockers),
            "raw_registry_path_persisted": False,
            "raw_probe_paths_persisted": False,
            "raw_provider_names_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_provider_urls_persisted": False,
            "raw_api_keys_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _final_official_import_audit_summary(
    *,
    audit: Mapping[str, Any],
    runs: Sequence[Mapping[str, Any]],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing: list[dict[str, Any]] = []
    payload = audit if isinstance(audit, Mapping) else {}
    official_suites = [
        suite
        for suite in BENCHMARK_SUITES
        if _suite_requires_official_harness(suite.suite_id, suite.task_format)
    ]
    official_suite_ids = {suite.suite_id for suite in official_suites}
    official_runs = [
        run
        for run in runs
        if isinstance(run, Mapping)
        and _suite_requires_official_harness(
            str(run.get("suite_id") or ""),
            str(run.get("task_format") or _suite_task_format(str(run.get("suite_id") or ""))),
        )
    ]
    campaign_receipt = _benchmark_run_set_receipt(official_runs)
    alignment = (
        payload.get("run_alignment_summary")
        if isinstance(payload.get("run_alignment_summary"), Mapping)
        else {}
    )
    audit_receipt = (
        alignment.get("run_set_receipt")
        if isinstance(alignment.get("run_set_receipt"), Mapping)
        else {}
    )
    audit_digest = str(audit_receipt.get("run_set_digest_sha256") or "")
    campaign_digest = str(campaign_receipt.get("run_set_digest_sha256") or "")
    audit_official_suite_count = _optional_int(payload.get("official_suite_count")) or 0
    audit_ready_suite_count = _optional_int(payload.get("ready_official_suite_count")) or 0
    audit_blocked_suite_count = _optional_int(payload.get("blocked_official_suite_count")) or 0
    blocking_reason_counts = (
        dict(payload.get("blocking_reason_counts"))
        if isinstance(payload.get("blocking_reason_counts"), Mapping)
        else {}
    )
    campaign_official_suite_count = len(
        {
            str(run.get("suite_id") or "")
            for run in official_runs
            if str(run.get("suite_id") or "") in official_suite_ids
        }
    )
    forbidden_persistence = bool(payload) and _contains_forbidden_persistence_flag(payload)
    raw_persistence = bool(payload) and _contains_true_raw_persisted_flag(payload)
    run_set_digest_matches = bool(audit_digest and campaign_digest) and audit_digest == campaign_digest

    if not payload:
        missing.append({"kind": "official_import_audit_missing"})
    elif str(payload.get("schema") or "") != "axio_fusion_api.official_import_audit.v1":
        missing.append(
            {
                "kind": "official_import_audit_schema_unrecognized",
                "schema": str(payload.get("schema") or ""),
            }
        )
    if payload and payload.get("ready_for_campaign_import_stage") is not True:
        missing.append({"kind": "official_import_audit_not_ready"})
    if payload and audit_official_suite_count != len(official_suites):
        missing.append(
            {
                "kind": "official_import_audit_suite_count_mismatch",
                "expected_official_suite_count": len(official_suites),
                "audit_official_suite_count": audit_official_suite_count,
            }
        )
    if payload and audit_ready_suite_count != audit_official_suite_count:
        missing.append({"kind": "official_import_audit_ready_suite_count_incomplete"})
    if payload and audit_blocked_suite_count:
        missing.append(
            {
                "kind": "official_import_audit_has_blocked_suites",
                "blocked_official_suite_count": audit_blocked_suite_count,
            }
        )
    if payload and blocking_reason_counts:
        missing.append(
            {
                "kind": "official_import_audit_has_blocking_reasons",
                "blocking_reason_kind_hashes": [
                    sha256_text(str(reason))
                    for reason in sorted(blocking_reason_counts.keys())[:12]
                ],
            }
        )
    if payload and not audit_receipt:
        missing.append({"kind": "official_import_audit_run_set_receipt_missing"})
    elif payload and not audit_digest:
        missing.append({"kind": "official_import_audit_run_set_digest_missing"})
    if not official_runs:
        missing.append({"kind": "campaign_official_runs_missing"})
    if payload and audit_digest and campaign_digest and audit_digest != campaign_digest:
        missing.append(
            {
                "kind": "official_import_audit_run_set_digest_mismatch",
                "audit_run_count": _optional_int(audit_receipt.get("run_count")) or 0,
                "campaign_official_run_count": campaign_receipt.get("run_count", 0),
            }
        )
    if payload and forbidden_persistence:
        missing.append({"kind": "official_import_audit_forbidden_persistence_flag_detected"})
    return (
        {
            "available": bool(payload),
            "schema": str(payload.get("schema") or "") if payload else "",
            "ready": not missing,
            "ready_for_campaign_import_stage": payload.get("ready_for_campaign_import_stage") is True if payload else False,
            "official_suite_count": audit_official_suite_count,
            "expected_official_suite_count": len(official_suites),
            "ready_official_suite_count": audit_ready_suite_count,
            "blocked_official_suite_count": audit_blocked_suite_count,
            "campaign_official_suite_count": campaign_official_suite_count,
            "audit_run_count": _optional_int(audit_receipt.get("run_count")) or 0,
            "campaign_official_run_count": campaign_receipt.get("run_count", 0),
            "audit_run_set_digest_sha256": audit_digest,
            "campaign_official_run_set_digest_sha256": campaign_digest,
            "run_set_digest_matches_campaign": run_set_digest_matches,
            "blocking_reason_counts": blocking_reason_counts,
            "safe_artifacts_have_no_true_raw_persistence_flags": not raw_persistence,
            "safe_artifacts_have_no_forbidden_persistence_flags": not forbidden_persistence,
            "raw_candidate_ids_persisted": False,
            "raw_import_paths_persisted": False,
            "raw_case_hashes_persisted": False,
            "raw_dataset_content_persisted": False,
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _run_efficiency_reason_codes(run: Mapping[str, Any]) -> list[str]:
    reasons = []
    if _optional_float(run.get("estimated_cost_usd")) is None:
        reasons.append("missing_estimated_cost_usd")
    if _optional_int(run.get("pricing_known_case_count")) is None:
        reasons.append("missing_pricing_known_case_count")
    if _optional_int(run.get("provider_call_count")) is None:
        reasons.append("missing_provider_call_count")
    if _optional_float(run.get("average_case_latency_ms")) is None:
        reasons.append("missing_average_case_latency_ms")
    if _optional_float(run.get("p50_case_latency_ms")) is None:
        reasons.append("missing_p50_case_latency_ms")
    if _optional_float(run.get("p95_case_latency_ms")) is None:
        reasons.append("missing_p95_case_latency_ms")
    if not isinstance(run.get("cost_contract"), Mapping):
        reasons.append("missing_cost_contract")
    return reasons


def _final_run_summary(
    runs: Sequence[Mapping[str, Any]],
    *,
    min_cases_per_suite: int,
    expected_provider_baseline_count: int,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    required = [suite.suite_id for suite in BENCHMARK_SUITES]
    by_suite: dict[str, list[Mapping[str, Any]]] = {suite_id: [] for suite_id in required}
    anti_leakage_by_suite: dict[str, list[dict[str, Any]]] = {suite_id: [] for suite_id in required}
    anti_leakage_receipts: list[dict[str, Any]] = []
    dry_run_count = 0
    non_live_count = 0
    run_efficiency_issue_count = 0
    for run in runs:
        suite_id = str(run.get("suite_id") or "")
        if suite_id in by_suite:
            by_suite[suite_id].append(run)
        anti_leakage_receipt = _final_run_anti_leakage_receipt(run)
        anti_leakage_receipts.append(anti_leakage_receipt)
        if suite_id in anti_leakage_by_suite:
            anti_leakage_by_suite[suite_id].append(anti_leakage_receipt)
        mode = str(run.get("mode") or "")
        task_format = str(run.get("task_format") or _suite_task_format(suite_id))
        if mode == "dry_run":
            dry_run_count += 1
        if not _is_live_or_imported_run(mode, task_format):
            non_live_count += 1
        if _run_efficiency_reason_codes(run):
            run_efficiency_issue_count += 1
    run_anti_leakage_issue_count = sum(1 for receipt in anti_leakage_receipts if receipt["clean"] is not True)
    run_anti_leakage_reason_counts = _anti_leakage_receipt_reason_counts(anti_leakage_receipts)
    rows = []
    missing = []
    for suite_id in required:
        suite_runs = by_suite.get(suite_id, [])
        effective_min_cases = _effective_min_cases_for_suite(suite_id, min_cases_per_suite)
        suite_anti_leakage_receipts = anti_leakage_by_suite.get(suite_id, [])
        anti_leakage_issue_count = sum(1 for receipt in suite_anti_leakage_receipts if receipt["clean"] is not True)
        provider_count = sum(1 for run in suite_runs if str(run.get("candidate_id") or "").startswith("provider::"))
        candidate_ids = {str(run.get("candidate_id") or "") for run in suite_runs}
        axio_missing = [
            model for model in ("axio-fast", "axio-terra", "axio-pro") if model not in candidate_ids
        ]
        axio_surface_audit = build_benchmark_api_surface_audit(
            suite_runs,
            require_http_gateway=True,
        )
        axio_surface_rows = axio_surface_audit.get("suite_model_rows") if isinstance(axio_surface_audit.get("suite_model_rows"), list) else []
        axio_surface_ready = all(
            row.get("ready") is True
            for row in axio_surface_rows
            if isinstance(row, Mapping) and row.get("suite_id") == suite_id
        )
        axio_surface_run_count = sum(1 for run in suite_runs if _is_axio_public_candidate(str(run.get("candidate_id") or "")))
        task_format = _suite_task_format(suite_id)
        requires_official_harness = _suite_requires_official_harness(suite_id, task_format)
        harness_issue_count = 0
        if requires_official_harness:
            for run in suite_runs:
                receipt = run.get("harness_receipt") if isinstance(run.get("harness_receipt"), Mapping) else {}
                if _harness_receipt_reasons(receipt, suite_id=suite_id, task_format=task_format):
                    harness_issue_count += 1
        min_case_count = min((_optional_int(run.get("case_count")) or 0 for run in suite_runs), default=0)
        efficiency_issue_count = sum(1 for run in suite_runs if _run_efficiency_reason_codes(run))
        ready = (
            bool(suite_runs)
            and provider_count >= expected_provider_baseline_count
            and not axio_missing
            and axio_surface_ready
            and min_case_count >= effective_min_cases
            and harness_issue_count == 0
            and efficiency_issue_count == 0
            and anti_leakage_issue_count == 0
        )
        reasons = []
        if not suite_runs:
            reasons.append("missing_suite_runs")
        if provider_count < 3:
            reasons.append("fewer_than_three_provider_baselines")
        if provider_count < expected_provider_baseline_count:
            reasons.append("suite_provider_baseline_count_below_available")
        if axio_missing:
            reasons.append("missing_axio_candidate_runs")
        if not axio_surface_ready:
            reasons.append("missing_or_unstable_axio_api_surface_runs")
        if suite_runs and min_case_count < effective_min_cases:
            reasons.append("insufficient_min_case_count")
        if harness_issue_count:
            reasons.append("official_harness_receipts_incomplete")
        if efficiency_issue_count:
            reasons.append("missing_cost_latency_or_call_metrics")
        if anti_leakage_issue_count:
            reasons.append("run_anti_leakage_contract_failed")
        if reasons:
            missing.append({"kind": "suite_run_coverage_incomplete", "suite_id": suite_id, "reason_codes": reasons})
        rows.append(
            {
                "suite_id": suite_id,
                "run_count": len(suite_runs),
                "provider_baseline_count": provider_count,
                "expected_provider_baseline_count": expected_provider_baseline_count,
                "axio_candidate_count": 3 - len(axio_missing),
                "axio_surface_run_count": axio_surface_run_count,
                "expected_axio_surface_run_count": len(AXIO_BENCHMARK_PUBLIC_MODELS) * len(AXIO_BENCHMARK_API_FORMATS),
                "axio_api_surface_ready": axio_surface_ready,
                "min_case_count": min_case_count,
                "effective_min_cases": effective_min_cases,
                "suite_min_case_policy": _suite_min_case_policy(suite_id, min_cases_per_suite),
                "requires_official_harness": requires_official_harness,
                "official_harness_issue_count": harness_issue_count,
                "efficiency_issue_count": efficiency_issue_count,
                "anti_leakage_issue_count": anti_leakage_issue_count,
                "ready": ready,
                "reason_codes": reasons,
            }
        )
    expected_axio_run_units = len(AXIO_BENCHMARK_PUBLIC_MODELS) * len(AXIO_BENCHMARK_API_FORMATS)
    expected_min_runs = len(required) * (expected_axio_run_units + max(3, int(expected_provider_baseline_count)))
    if len(runs) < expected_min_runs:
        missing.append(
            {
                "kind": "insufficient_run_count_for_available_provider_baselines",
                "run_count": len(runs),
                "expected_min_run_count": expected_min_runs,
            }
        )
    if dry_run_count:
        missing.append({"kind": "dry_run_artifacts_present", "dry_run_count": dry_run_count})
    if non_live_count:
        missing.append({"kind": "non_live_or_non_imported_run_artifacts_present", "count": non_live_count})
    if run_efficiency_issue_count:
        missing.append({"kind": "run_cost_latency_metrics_incomplete", "run_issue_count": run_efficiency_issue_count})
    if run_anti_leakage_issue_count:
        missing.append(
            {
                "kind": "run_anti_leakage_contract_failed",
                "run_issue_count": run_anti_leakage_issue_count,
                "suite_issue_count": sum(1 for row in rows if row["anti_leakage_issue_count"]),
                "reason_counts": run_anti_leakage_reason_counts,
            }
        )
    return (
        {
            "run_count": len(runs),
            "expected_min_run_count": expected_min_runs,
            "expected_axio_surface_run_units_per_suite": expected_axio_run_units,
            "required_suite_count": len(required),
            "expected_provider_baseline_count": expected_provider_baseline_count,
            "covered_required_suite_count": sum(1 for row in rows if row["run_count"] > 0),
            "suite_rows": rows,
            "dry_run_count": dry_run_count,
            "non_live_or_non_imported_run_count": non_live_count,
            "run_efficiency_issue_count": run_efficiency_issue_count,
            "run_anti_leakage_receipt_count": len(anti_leakage_receipts),
            "run_anti_leakage_issue_count": run_anti_leakage_issue_count,
            "run_anti_leakage_reason_counts": run_anti_leakage_reason_counts,
            "all_runs_anti_leakage_clean": run_anti_leakage_issue_count == 0,
            "run_anti_leakage_receipts": anti_leakage_receipts,
        },
        missing,
    )


def _final_run_case_alignment_summary(
    runs: Sequence[Mapping[str, Any]],
    *,
    min_cases_per_suite: int,
    source_manifest_path: str | Path | None = None,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    required = [suite.suite_id for suite in BENCHMARK_SUITES]
    by_suite: dict[str, list[Mapping[str, Any]]] = {suite_id: [] for suite_id in required}
    for run in runs:
        suite_id = str(run.get("suite_id") or "")
        if suite_id in by_suite:
            by_suite[suite_id].append(run)
    source_prompt_summary = _source_manifest_prompt_protocol_summary(source_manifest_path)
    source_prompt_hashes = (
        source_prompt_summary.get("hashes_by_suite")
        if isinstance(source_prompt_summary.get("hashes_by_suite"), Mapping)
        else {}
    )
    source_decoding_summary = _source_manifest_decoding_config_summary(source_manifest_path)
    source_decoding_hashes = (
        source_decoding_summary.get("hashes_by_suite")
        if isinstance(source_decoding_summary.get("hashes_by_suite"), Mapping)
        else {}
    )
    source_harness_summary = _source_manifest_official_harness_summary(source_manifest_path)
    source_harness_hashes = (
        source_harness_summary.get("hashes_by_suite")
        if isinstance(source_harness_summary.get("hashes_by_suite"), Mapping)
        else {}
    )
    rows = []
    missing = []
    for suite_id in required:
        effective_min_cases = _effective_min_cases_for_suite(suite_id, min_cases_per_suite)
        suite_task_format = _suite_task_format(suite_id)
        requires_official_harness = _suite_requires_official_harness(suite_id, suite_task_format)
        suite_runs = by_suite.get(suite_id, [])
        candidate_receipts = []
        case_sets: list[set[str]] = []
        prompt_protocol_hashes: list[str] = []
        decoding_config_hashes: list[str] = []
        official_harness_field_hashes: dict[str, list[str]] = {
            field: []
            for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS
        }
        missing_official_harness_field_run_counts: dict[str, int] = {
            field: 0
            for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS
        }
        missing_hash_run_count = 0
        duplicate_case_hash_run_count = 0
        missing_prompt_protocol_hash_run_count = 0
        prompt_protocol_hash_conflict_run_count = 0
        missing_decoding_config_hash_run_count = 0
        decoding_config_hash_conflict_run_count = 0
        official_harness_receipt_missing_run_count = 0
        official_harness_receipt_invalid_run_count = 0
        for run in suite_runs:
            case_receipt = _run_case_hash_receipt(run)
            prompt_receipt = _run_prompt_protocol_receipt(run)
            decoding_receipt = _run_decoding_config_receipt(run)
            official_harness_receipt = _run_official_harness_binding_receipt(
                run,
                suite_id=suite_id,
                task_format=suite_task_format,
            )
            candidate_receipts.append(
                {
                    **case_receipt,
                    **prompt_receipt,
                    **decoding_receipt,
                    **official_harness_receipt,
                }
            )
            case_hashes = set(case_receipt["case_hashes"])
            case_sets.append(case_hashes)
            if not case_hashes or case_receipt["missing_case_hash_count"]:
                missing_hash_run_count += 1
            if case_receipt["duplicate_case_hash_count"]:
                duplicate_case_hash_run_count += 1
            prompt_hash = str(prompt_receipt.get("prompt_protocol_sha256") or "")
            if prompt_hash:
                prompt_protocol_hashes.append(prompt_hash)
            else:
                missing_prompt_protocol_hash_run_count += 1
            if prompt_receipt.get("prompt_protocol_hash_conflict") is True:
                prompt_protocol_hash_conflict_run_count += 1
            decoding_hash = str(decoding_receipt.get("decoding_config_sha256") or "")
            if decoding_hash:
                decoding_config_hashes.append(decoding_hash)
            else:
                missing_decoding_config_hash_run_count += 1
            if decoding_receipt.get("decoding_config_hash_conflict") is True:
                decoding_config_hash_conflict_run_count += 1
            if requires_official_harness:
                if official_harness_receipt.get("harness_receipt_present") is not True:
                    official_harness_receipt_missing_run_count += 1
                if official_harness_receipt.get("harness_receipt_valid") is not True:
                    official_harness_receipt_invalid_run_count += 1
                field_hashes = (
                    official_harness_receipt.get("official_harness_binding_hashes")
                    if isinstance(official_harness_receipt.get("official_harness_binding_hashes"), Mapping)
                    else {}
                )
                for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS:
                    value = str(field_hashes.get(field) or "")
                    if value:
                        official_harness_field_hashes[field].append(value)
                    else:
                        missing_official_harness_field_run_counts[field] += 1
        if case_sets:
            reference = set(case_sets[0])
            union = set().union(*case_sets)
            common = set.intersection(*case_sets)
            identical = (
                bool(reference)
                and missing_hash_run_count == 0
                and duplicate_case_hash_run_count == 0
                and all(case_set == reference for case_set in case_sets)
            )
        else:
            reference = set()
            union = set()
            common = set()
            identical = False
        prompt_protocol_unique_hashes = sorted(set(prompt_protocol_hashes))
        reference_prompt_protocol_hash = prompt_protocol_unique_hashes[0] if len(prompt_protocol_unique_hashes) == 1 else ""
        prompt_protocol_identical = (
            bool(suite_runs)
            and missing_prompt_protocol_hash_run_count == 0
            and prompt_protocol_hash_conflict_run_count == 0
            and len(prompt_protocol_hashes) == len(suite_runs)
            and len(prompt_protocol_unique_hashes) == 1
        )
        decoding_config_unique_hashes = sorted(set(decoding_config_hashes))
        reference_decoding_config_hash = decoding_config_unique_hashes[0] if len(decoding_config_unique_hashes) == 1 else ""
        decoding_config_identical = (
            bool(suite_runs)
            and missing_decoding_config_hash_run_count == 0
            and decoding_config_hash_conflict_run_count == 0
            and len(decoding_config_hashes) == len(suite_runs)
            and len(decoding_config_unique_hashes) == 1
        )
        case_reasons = []
        prompt_reasons = []
        decoding_reasons = []
        source_prompt_protocol_hash = str(source_prompt_hashes.get(suite_id) or "")
        source_prompt_protocol_hash_present = _looks_like_sha256(source_prompt_protocol_hash)
        source_prompt_protocol_matches = (
            source_prompt_protocol_hash_present
            and prompt_protocol_identical
            and reference_prompt_protocol_hash == source_prompt_protocol_hash
        )
        source_decoding_config_hash = str(source_decoding_hashes.get(suite_id) or "")
        source_decoding_config_hash_present = _looks_like_sha256(source_decoding_config_hash)
        source_decoding_config_matches = (
            source_decoding_config_hash_present
            and decoding_config_identical
            and reference_decoding_config_hash == source_decoding_config_hash
        )
        source_official_harness_hashes = (
            source_harness_hashes.get(suite_id)
            if isinstance(source_harness_hashes.get(suite_id), Mapping)
            else {}
        )
        official_harness_binding_field_rows = []
        official_harness_field_matches: dict[str, bool] = {}
        official_harness_source_reasons = []
        for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS:
            run_hashes = official_harness_field_hashes[field]
            unique_hashes = sorted(set(run_hashes))
            reference_hash = unique_hashes[0] if len(unique_hashes) == 1 else ""
            missing_run_count = missing_official_harness_field_run_counts[field]
            hashes_identical = (
                bool(suite_runs)
                and missing_run_count == 0
                and len(run_hashes) == len(suite_runs)
                and len(unique_hashes) == 1
            )
            source_hash = str(source_official_harness_hashes.get(field) or "").strip().lower()
            source_hash_present = _looks_like_sha256(source_hash)
            source_matches = (
                not requires_official_harness
                or (
                    source_hash_present
                    and hashes_identical
                    and reference_hash == source_hash
                )
            )
            official_harness_field_matches[field] = source_matches
            official_harness_binding_field_rows.append(
                {
                    "field": field,
                    "run_hashes_identical": hashes_identical,
                    "run_hash_count": len(unique_hashes),
                    "missing_run_hash_count": missing_run_count,
                    "source_hash_present": source_hash_present,
                    "source_matches": source_matches,
                    "reference_hash_sha256": reference_hash,
                    "source_hash_sha256": source_hash,
                    "run_hash_preview": unique_hashes[:5],
                }
            )
            if not requires_official_harness or not suite_runs:
                continue
            if missing_run_count:
                official_harness_source_reasons.append("run_harness_receipt_hashes_missing")
            if len(unique_hashes) > 1:
                official_harness_source_reasons.append("run_harness_receipt_hashes_conflicting")
            if source_harness_summary.get("available") is True and not source_hash_present:
                if field in {"official_harness_name_sha256", "official_harness_version_sha256"}:
                    official_harness_source_reasons.append("source_harness_hash_missing")
                elif field == "dataset_snapshot_sha256":
                    official_harness_source_reasons.append("source_dataset_snapshot_hash_missing")
                elif field == "evaluator_config_sha256":
                    official_harness_source_reasons.append("source_evaluator_config_hash_missing")
            if source_hash_present and run_hashes and any(value != source_hash for value in run_hashes):
                if field in {"official_harness_name_sha256", "official_harness_version_sha256"}:
                    official_harness_source_reasons.append("run_harness_source_manifest_mismatch")
                elif field == "dataset_snapshot_sha256":
                    official_harness_source_reasons.append("run_dataset_snapshot_source_manifest_mismatch")
                elif field == "evaluator_config_sha256":
                    official_harness_source_reasons.append("run_evaluator_config_source_manifest_mismatch")
        official_harness_identity_matches = (
            not requires_official_harness
            or (
                official_harness_field_matches.get("official_harness_name_sha256") is True
                and official_harness_field_matches.get("official_harness_version_sha256") is True
            )
        )
        dataset_snapshot_matches = (
            not requires_official_harness
            or official_harness_field_matches.get("dataset_snapshot_sha256") is True
        )
        evaluator_config_matches = (
            not requires_official_harness
            or official_harness_field_matches.get("evaluator_config_sha256") is True
        )
        official_harness_source_binding_ready = (
            not requires_official_harness
            or (
                bool(suite_runs)
                and official_harness_receipt_missing_run_count == 0
                and official_harness_receipt_invalid_run_count == 0
                and official_harness_identity_matches
                and dataset_snapshot_matches
                and evaluator_config_matches
            )
        )
        if requires_official_harness and suite_runs and official_harness_receipt_missing_run_count:
            official_harness_source_reasons.append("run_official_harness_receipts_missing")
        if requires_official_harness and suite_runs and official_harness_receipt_invalid_run_count:
            official_harness_source_reasons.append("run_official_harness_receipts_invalid")
        official_harness_source_reasons = sorted(set(official_harness_source_reasons))
        if not suite_runs:
            case_reasons.append("missing_suite_runs")
        if suite_runs and missing_hash_run_count:
            case_reasons.append("run_case_hashes_missing")
        if suite_runs and duplicate_case_hash_run_count:
            case_reasons.append("duplicate_case_hashes_in_run")
        if suite_runs and not identical:
            case_reasons.append("run_case_hash_sets_misaligned")
        if suite_runs and len(common) < effective_min_cases:
            case_reasons.append("common_case_hash_count_below_min")
        if suite_runs and missing_prompt_protocol_hash_run_count:
            prompt_reasons.append("run_prompt_protocol_hashes_missing")
        if suite_runs and prompt_protocol_hash_conflict_run_count:
            prompt_reasons.append("run_prompt_protocol_hashes_conflicting")
        if suite_runs and not prompt_protocol_identical:
            prompt_reasons.append("run_prompt_protocol_hashes_misaligned")
        if suite_runs and source_prompt_summary.get("available") is True and not source_prompt_protocol_hash_present:
            prompt_reasons.append("source_prompt_protocol_hash_missing")
        if (
            suite_runs
            and source_prompt_protocol_hash_present
            and prompt_protocol_identical
            and not source_prompt_protocol_matches
        ):
            prompt_reasons.append("run_prompt_protocol_source_manifest_mismatch")
        if suite_runs and missing_decoding_config_hash_run_count:
            decoding_reasons.append("run_decoding_config_hashes_missing")
        if suite_runs and decoding_config_hash_conflict_run_count:
            decoding_reasons.append("run_decoding_config_hashes_conflicting")
        if suite_runs and not decoding_config_identical:
            decoding_reasons.append("run_decoding_config_hashes_misaligned")
        if suite_runs and source_decoding_summary.get("available") is True and not source_decoding_config_hash_present:
            decoding_reasons.append("source_decoding_config_hash_missing")
        if (
            suite_runs
            and source_decoding_config_hash_present
            and decoding_config_identical
            and not source_decoding_config_matches
        ):
            decoding_reasons.append("run_decoding_config_source_manifest_mismatch")
        ready = (
            bool(suite_runs)
            and identical
            and len(common) >= effective_min_cases
            and prompt_protocol_identical
            and source_prompt_protocol_matches
            and decoding_config_identical
            and source_decoding_config_matches
            and official_harness_source_binding_ready
        )
        if case_reasons:
            missing.append(
                {
                    "kind": "run_case_alignment_incomplete",
                    "suite_id": suite_id,
                    "reason_codes": case_reasons,
                }
            )
        if prompt_reasons:
            missing.append(
                {
                    "kind": "run_prompt_protocol_alignment_incomplete",
                    "suite_id": suite_id,
                    "reason_codes": prompt_reasons,
                }
            )
        if decoding_reasons:
            missing.append(
                {
                    "kind": "run_decoding_config_alignment_incomplete",
                    "suite_id": suite_id,
                    "reason_codes": decoding_reasons,
                }
            )
        if official_harness_source_reasons:
            missing.append(
                {
                    "kind": "run_official_harness_source_binding_incomplete",
                    "suite_id": suite_id,
                    "reason_codes": official_harness_source_reasons,
                }
            )
        reasons = case_reasons + prompt_reasons + decoding_reasons + official_harness_source_reasons
        rows.append(
            {
                "suite_id": suite_id,
                "task_format": suite_task_format,
                "run_count": len(suite_runs),
                "requires_official_harness": requires_official_harness,
                "case_hash_sets_identical": identical,
                "reference_case_hash_count": len(reference),
                "min_case_hash_count": min((len(case_set) for case_set in case_sets), default=0),
                "max_case_hash_count": max((len(case_set) for case_set in case_sets), default=0),
                "common_case_hash_count": len(common),
                "effective_min_cases": effective_min_cases,
                "suite_min_case_policy": _suite_min_case_policy(suite_id, min_cases_per_suite),
                "union_case_hash_count": len(union),
                "missing_hash_run_count": missing_hash_run_count,
                "duplicate_case_hash_run_count": duplicate_case_hash_run_count,
                "common_case_hash_preview": sorted(common)[:5],
                "prompt_protocol_hashes_identical": prompt_protocol_identical,
                "reference_prompt_protocol_sha256": reference_prompt_protocol_hash,
                "prompt_protocol_hash_count": len(prompt_protocol_unique_hashes),
                "prompt_protocol_hash_preview": prompt_protocol_unique_hashes[:5],
                "missing_prompt_protocol_hash_run_count": missing_prompt_protocol_hash_run_count,
                "prompt_protocol_hash_conflict_run_count": prompt_protocol_hash_conflict_run_count,
                "source_prompt_protocol_sha256": source_prompt_protocol_hash,
                "source_prompt_protocol_hash_present": source_prompt_protocol_hash_present,
                "source_prompt_protocol_matches": source_prompt_protocol_matches,
                "decoding_config_hashes_identical": decoding_config_identical,
                "reference_decoding_config_sha256": reference_decoding_config_hash,
                "decoding_config_hash_count": len(decoding_config_unique_hashes),
                "decoding_config_hash_preview": decoding_config_unique_hashes[:5],
                "missing_decoding_config_hash_run_count": missing_decoding_config_hash_run_count,
                "decoding_config_hash_conflict_run_count": decoding_config_hash_conflict_run_count,
                "source_decoding_config_sha256": source_decoding_config_hash,
                "source_decoding_config_hash_present": source_decoding_config_hash_present,
                "source_decoding_config_matches": source_decoding_config_matches,
                "official_harness_source_binding_ready": official_harness_source_binding_ready,
                "official_harness_identity_bound_to_source_manifest": official_harness_identity_matches,
                "dataset_snapshot_bound_to_source_manifest": dataset_snapshot_matches,
                "evaluator_config_bound_to_source_manifest": evaluator_config_matches,
                "official_harness_receipt_missing_run_count": official_harness_receipt_missing_run_count,
                "official_harness_receipt_invalid_run_count": official_harness_receipt_invalid_run_count,
                "official_harness_binding_field_rows": official_harness_binding_field_rows,
                "candidate_receipts": [
                    {
                        key: value
                        for key, value in receipt.items()
                        if key != "case_hashes"
                    }
                    for receipt in candidate_receipts[:40]
                ],
                "ready": ready,
                "reason_codes": reasons,
                "raw_candidate_ids_persisted": False,
                "raw_dataset_content_persisted": False,
                "raw_prompts_persisted": False,
                "raw_labels_persisted": False,
                "raw_provider_outputs_persisted": False,
            }
        )
    issue_rows = [row for row in rows if row["ready"] is not True]
    case_prompt_decoding_issue_rows = [
        row
        for row in rows
        if not (
            row["case_hash_sets_identical"] is True
            and row["common_case_hash_count"] >= int(row.get("effective_min_cases") or min_cases_per_suite)
            and row["prompt_protocol_hashes_identical"] is True
            and row["source_prompt_protocol_matches"] is True
            and row["decoding_config_hashes_identical"] is True
            and row["source_decoding_config_matches"] is True
        )
    ]
    official_harness_rows = [row for row in rows if row["requires_official_harness"] is True]
    return (
        {
            "schema": "axio_fusion_api.final_run_case_alignment.v1",
            "required_suite_count": len(required),
            "aligned_suite_count": sum(1 for row in rows if row["ready"] is True),
            "official_harness_required_suite_count": len(official_harness_rows),
            "case_aligned_suite_count": sum(
                1
                for row in rows
                if row["case_hash_sets_identical"] is True
                and row["common_case_hash_count"] >= int(row.get("effective_min_cases") or min_cases_per_suite)
            ),
            "prompt_protocol_aligned_suite_count": sum(
                1 for row in rows if row["prompt_protocol_hashes_identical"] is True
            ),
            "source_prompt_protocol_bound_suite_count": sum(
                1 for row in rows if row["source_prompt_protocol_matches"] is True
            ),
            "decoding_config_aligned_suite_count": sum(
                1 for row in rows if row["decoding_config_hashes_identical"] is True
            ),
            "source_decoding_config_bound_suite_count": sum(
                1 for row in rows if row["source_decoding_config_matches"] is True
            ),
            "official_harness_source_bound_suite_count": sum(
                1 for row in official_harness_rows if row["official_harness_source_binding_ready"] is True
            ),
            "official_harness_identity_bound_suite_count": sum(
                1
                for row in official_harness_rows
                if row["official_harness_identity_bound_to_source_manifest"] is True
            ),
            "dataset_snapshot_bound_suite_count": sum(
                1
                for row in official_harness_rows
                if row["dataset_snapshot_bound_to_source_manifest"] is True
            ),
            "evaluator_config_bound_suite_count": sum(
                1
                for row in official_harness_rows
                if row["evaluator_config_bound_to_source_manifest"] is True
            ),
            "misaligned_suite_count": len(issue_rows),
            "case_prompt_decoding_misaligned_suite_count": len(case_prompt_decoding_issue_rows),
            "all_required_suites_case_aligned": all(
                row["case_hash_sets_identical"] is True
                and row["common_case_hash_count"] >= int(row.get("effective_min_cases") or min_cases_per_suite)
                for row in rows
            ),
            "all_required_suites_prompt_protocol_aligned": all(
                row["prompt_protocol_hashes_identical"] is True for row in rows
            ),
            "all_required_suites_prompt_protocol_bound_to_source_manifest": all(
                row["source_prompt_protocol_matches"] is True for row in rows
            ),
            "all_required_suites_decoding_config_aligned": all(
                row["decoding_config_hashes_identical"] is True for row in rows
            ),
            "all_required_suites_decoding_config_bound_to_source_manifest": all(
                row["source_decoding_config_matches"] is True for row in rows
            ),
            "all_official_harness_required_suites_bound_to_source_manifest": all(
                row["official_harness_source_binding_ready"] is True
                for row in official_harness_rows
            ),
            "all_official_harness_identities_bound_to_source_manifest": all(
                row["official_harness_identity_bound_to_source_manifest"] is True
                for row in official_harness_rows
            ),
            "all_required_dataset_snapshots_bound_to_source_manifest": all(
                row["dataset_snapshot_bound_to_source_manifest"] is True
                for row in official_harness_rows
            ),
            "all_required_evaluator_configs_bound_to_source_manifest": all(
                row["evaluator_config_bound_to_source_manifest"] is True
                for row in official_harness_rows
            ),
            "all_required_suites_case_and_prompt_aligned": all(
                row["case_hash_sets_identical"] is True
                and row["common_case_hash_count"] >= int(row.get("effective_min_cases") or min_cases_per_suite)
                and row["prompt_protocol_hashes_identical"] is True
                and row["source_prompt_protocol_matches"] is True
                for row in rows
            ),
            "all_required_suites_case_prompt_and_decoding_aligned": not case_prompt_decoding_issue_rows,
            "all_required_suites_case_prompt_decoding_and_harness_aligned": not issue_rows,
            "min_cases_per_suite": int(min_cases_per_suite),
            "source_prompt_protocol_summary": source_prompt_summary,
            "source_decoding_config_summary": source_decoding_summary,
            "source_official_harness_summary": source_harness_summary,
            "suite_rows": rows,
            "raw_candidate_ids_persisted": False,
            "raw_dataset_content_persisted": False,
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _final_api_surface_summary(
    runs: Sequence[Mapping[str, Any]],
    *,
    scorecard: Mapping[str, Any],
    claim_audit: Mapping[str, Any],
    parity_report: Mapping[str, Any],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    recomputed = build_benchmark_api_surface_audit(
        runs,
        require_http_gateway=True,
    )
    run_set_receipt = _benchmark_run_set_receipt(runs)
    recomputed_surface_digest = sha256_text(stable_json(recomputed))
    report = parity_report if isinstance(parity_report, Mapping) else {}
    report_receipt = (
        report.get("run_set_receipt")
        if isinstance(report.get("run_set_receipt"), Mapping)
        else {}
    )
    report_run_set_digest = str(
        report.get("source_run_set_digest_sha256")
        or report_receipt.get("run_set_digest_sha256")
        or ""
    ).strip().lower()
    campaign_run_set_digest = str(run_set_receipt.get("run_set_digest_sha256") or "")
    report_surface_digest = str(report.get("surface_audit_digest_sha256") or "").strip().lower()
    report_blocking_reasons = (
        dict(report.get("blocking_reason_counts"))
        if isinstance(report.get("blocking_reason_counts"), Mapping)
        else {}
    )
    scorecard_surface = (
        scorecard.get("api_surface_summary")
        if isinstance(scorecard.get("api_surface_summary"), Mapping)
        else {}
    )
    claim_surface = (
        claim_audit.get("api_surface_audit")
        if isinstance(claim_audit.get("api_surface_audit"), Mapping)
        else {}
    )
    scorecard_matches = bool(scorecard_surface) and stable_json(scorecard_surface) == stable_json(recomputed)
    claim_matches = bool(claim_surface) and stable_json(claim_surface) == stable_json(recomputed)
    missing = []
    if recomputed.get("all_required_api_surfaces_ready") is not True:
        missing.append(
            {
                "kind": "api_surface_audit_not_ready",
                "blocking_reason_counts": dict(recomputed.get("blocking_reason_counts") or {}),
            }
        )
    if not report:
        missing.append({"kind": "api_surface_parity_report_missing"})
    elif str(report.get("schema") or "") != "axio_fusion_api.benchmark_api_surface_parity_report.v1":
        missing.append(
            {
                "kind": "api_surface_parity_report_schema_unrecognized",
                "schema": str(report.get("schema") or ""),
            }
        )
    if report and report.get("all_required_api_surfaces_ready") is not True:
        missing.append(
            {
                "kind": "api_surface_parity_report_not_ready",
                "blocking_reason_counts": report_blocking_reasons,
            }
        )
    if report and (_optional_int(report.get("failed_surface_row_count")) or 0) != 0:
        missing.append(
            {
                "kind": "api_surface_parity_report_has_failed_rows",
                "failed_surface_row_count": _optional_int(report.get("failed_surface_row_count")) or 0,
            }
        )
    if report and report_blocking_reasons:
        missing.append(
            {
                "kind": "api_surface_parity_report_has_blocking_reasons",
                "blocking_reason_kind_hashes": [
                    sha256_text(str(reason))
                    for reason in sorted(report_blocking_reasons.keys())[:12]
                ],
            }
        )
    if report and not _looks_like_sha256(report_run_set_digest):
        missing.append({"kind": "api_surface_parity_report_run_set_digest_missing"})
    if report and _looks_like_sha256(report_run_set_digest) and report_run_set_digest != campaign_run_set_digest:
        missing.append({"kind": "api_surface_parity_report_run_set_digest_mismatch"})
    if report and not _looks_like_sha256(report_surface_digest):
        missing.append({"kind": "api_surface_parity_report_surface_audit_digest_missing"})
    if report and _looks_like_sha256(report_surface_digest) and report_surface_digest != recomputed_surface_digest:
        missing.append({"kind": "api_surface_parity_report_surface_audit_digest_mismatch"})
    if report and _contains_forbidden_persistence_flag(report):
        missing.append({"kind": "api_surface_parity_report_forbidden_persistence_flag_detected"})
    if scorecard and not scorecard_surface:
        missing.append({"kind": "scorecard_api_surface_summary_missing"})
    elif scorecard_surface and not scorecard_matches:
        missing.append({"kind": "scorecard_api_surface_summary_mismatch"})
    if claim_audit and not claim_surface:
        missing.append({"kind": "claim_audit_api_surface_summary_missing"})
    elif claim_surface and not claim_matches:
        missing.append({"kind": "claim_audit_api_surface_summary_mismatch"})
    return (
        {
            "schema": "axio_fusion_api.final_api_surface_summary.v1",
            "all_required_api_surfaces_ready": recomputed.get("all_required_api_surfaces_ready") is True,
            "required_surface_row_count": _optional_int(recomputed.get("required_surface_row_count")) or 0,
            "ready_surface_row_count": _optional_int(recomputed.get("ready_surface_row_count")) or 0,
            "score_tolerance": _optional_float(recomputed.get("score_tolerance")),
            "http_gateway_required": True,
            "blocking_reason_counts": dict(recomputed.get("blocking_reason_counts") or {}),
            "parity_report_present": bool(report),
            "parity_report_schema": str(report.get("schema") or "") if report else "",
            "parity_report_ready": report.get("all_required_api_surfaces_ready") is True if report else False,
            "parity_report_failed_surface_row_count": _optional_int(report.get("failed_surface_row_count")) or 0,
            "parity_report_run_set_digest_sha256": report_run_set_digest,
            "campaign_run_set_digest_sha256": campaign_run_set_digest,
            "parity_report_run_set_digest_matches_campaign": _looks_like_sha256(report_run_set_digest)
            and report_run_set_digest == campaign_run_set_digest,
            "parity_report_surface_audit_digest_sha256": report_surface_digest,
            "recomputed_surface_audit_digest_sha256": recomputed_surface_digest,
            "parity_report_surface_audit_digest_matches_recomputed": _looks_like_sha256(report_surface_digest)
            and report_surface_digest == recomputed_surface_digest,
            "parity_report_blocking_reason_counts": report_blocking_reasons,
            "scorecard_surface_summary_present": bool(scorecard_surface),
            "claim_audit_surface_summary_present": bool(claim_surface),
            "scorecard_surface_summary_matches_recomputed": scorecard_matches,
            "claim_audit_surface_summary_matches_recomputed": claim_matches,
            "api_surface_contract": _api_surface_contract(),
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _run_case_hash_receipt(run: Mapping[str, Any]) -> dict[str, Any]:
    rows = run.get("case_results") if isinstance(run.get("case_results"), list) else []
    hashes = []
    missing_hash_count = 0
    for row in rows:
        if not isinstance(row, Mapping):
            missing_hash_count += 1
            continue
        case_hash = _case_hash_from_result(row)
        if case_hash:
            hashes.append(case_hash)
        else:
            missing_hash_count += 1
    unique_hashes = sorted(set(hashes))
    duplicate_count = max(0, len(hashes) - len(unique_hashes))
    return {
        "candidate_id_hash": sha256_text(str(run.get("candidate_id") or "")),
        "mode": str(run.get("mode") or ""),
        "case_result_count": len(rows),
        "case_hash_count": len(unique_hashes),
        "duplicate_case_hash_count": duplicate_count,
        "missing_case_hash_count": missing_hash_count,
        "case_hash_preview": unique_hashes[:5],
        "case_hashes": unique_hashes,
        "raw_candidate_id_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_prompt_persisted": False,
        "raw_label_persisted": False,
        "raw_provider_output_persisted": False,
        "secrets_persisted": False,
    }


def _source_manifest_prompt_protocol_summary(source_manifest_path: str | Path | None) -> dict[str, Any]:
    if source_manifest_path is None:
        return {
            "available": False,
            "reason": "missing_source_manifest_path",
            "hashes_by_suite": {},
            "suite_count": 0,
            "prompt_protocol_hash_present_suite_count": 0,
            "missing_prompt_protocol_hash_suite_count": len(BENCHMARK_SUITES),
            "raw_source_manifest_path_persisted": False,
            "raw_prompts_persisted": False,
            "raw_provider_outputs_persisted": False,
        }
    try:
        payload = json.loads(Path(source_manifest_path).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {
            "available": False,
            "reason": "source_manifest_unreadable",
            "hashes_by_suite": {},
            "suite_count": 0,
            "prompt_protocol_hash_present_suite_count": 0,
            "missing_prompt_protocol_hash_suite_count": len(BENCHMARK_SUITES),
            "raw_source_manifest_path_persisted": False,
            "raw_prompts_persisted": False,
            "raw_provider_outputs_persisted": False,
        }
    source_rows = payload.get("suites") if isinstance(payload, Mapping) and isinstance(payload.get("suites"), list) else []
    source_by_suite = {
        str(row.get("suite_id") or ""): row
        for row in source_rows
        if isinstance(row, Mapping)
    }
    hashes_by_suite: dict[str, str] = {}
    rows = []
    for suite in BENCHMARK_SUITES:
        source_row = source_by_suite.get(suite.suite_id)
        source_record = (
            source_row.get("source_record")
            if isinstance(source_row, Mapping) and isinstance(source_row.get("source_record"), Mapping)
            else {}
        )
        prompt_hash = str(source_record.get("prompt_protocol_sha256") or "").strip().lower()
        hash_present = _looks_like_sha256(prompt_hash)
        if hash_present:
            hashes_by_suite[suite.suite_id] = prompt_hash
        rows.append(
            {
                "suite_id": suite.suite_id,
                "prompt_protocol_hash_present": hash_present,
            }
        )
    present_count = len(hashes_by_suite)
    return {
        "available": True,
        "source_manifest_schema": str(payload.get("schema") or "") if isinstance(payload, Mapping) else "",
        "hashes_by_suite": hashes_by_suite,
        "suite_count": len(source_rows),
        "prompt_protocol_hash_present_suite_count": present_count,
        "missing_prompt_protocol_hash_suite_count": len(BENCHMARK_SUITES) - present_count,
        "suite_rows": rows[:24],
        "raw_source_manifest_path_persisted": False,
        "raw_prompts_persisted": False,
        "raw_prompt_templates_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


