def _source_manifest_official_harness_summary(source_manifest_path: str | Path | None) -> dict[str, Any]:
    official_required = [
        suite
        for suite in BENCHMARK_SUITES
        if _suite_requires_official_harness(suite.suite_id, suite.task_format)
    ]
    if source_manifest_path is None:
        return {
            "available": False,
            "reason": "missing_source_manifest_path",
            "hashes_by_suite": {},
            "official_harness_required_suite_count": len(official_required),
            "field_present_counts": {field: 0 for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS},
            "field_missing_counts": {
                field: len(official_required)
                for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS
            },
            "raw_source_manifest_path_persisted": False,
            "raw_harness_output_paths_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        }
    try:
        payload = json.loads(Path(source_manifest_path).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {
            "available": False,
            "reason": "source_manifest_unreadable",
            "hashes_by_suite": {},
            "official_harness_required_suite_count": len(official_required),
            "field_present_counts": {field: 0 for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS},
            "field_missing_counts": {
                field: len(official_required)
                for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS
            },
            "raw_source_manifest_path_persisted": False,
            "raw_harness_output_paths_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        }
    source_rows = payload.get("suites") if isinstance(payload, Mapping) and isinstance(payload.get("suites"), list) else []
    source_by_suite = {
        str(row.get("suite_id") or ""): row
        for row in source_rows
        if isinstance(row, Mapping)
    }
    hashes_by_suite: dict[str, dict[str, str]] = {}
    field_present_counts = {field: 0 for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS}
    suite_rows = []
    for suite in official_required:
        source_row = source_by_suite.get(suite.suite_id)
        source_record = (
            source_row.get("source_record")
            if isinstance(source_row, Mapping) and isinstance(source_row.get("source_record"), Mapping)
            else {}
        )
        field_hashes: dict[str, str] = {}
        field_present = {}
        for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS:
            value = str(source_record.get(field) or "").strip().lower()
            present = _looks_like_sha256(value)
            field_present[field] = present
            if present:
                field_hashes[field] = value
                field_present_counts[field] += 1
        if field_hashes:
            hashes_by_suite[suite.suite_id] = field_hashes
        suite_rows.append(
            {
                "suite_id": suite.suite_id,
                "field_present": field_present,
            }
        )
    field_missing_counts = {
        field: len(official_required) - count
        for field, count in field_present_counts.items()
    }
    return {
        "available": True,
        "source_manifest_schema": str(payload.get("schema") or "") if isinstance(payload, Mapping) else "",
        "hashes_by_suite": hashes_by_suite,
        "suite_count": len(source_rows),
        "official_harness_required_suite_count": len(official_required),
        "field_present_counts": field_present_counts,
        "field_missing_counts": field_missing_counts,
        "suite_rows": suite_rows[:24],
        "raw_source_manifest_path_persisted": False,
        "raw_harness_output_paths_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _run_prompt_protocol_receipt(run: Mapping[str, Any]) -> dict[str, Any]:
    hashes = []
    sources = []
    for source_name, source in (
        ("run", run),
        ("harness_receipt", run.get("harness_receipt") if isinstance(run.get("harness_receipt"), Mapping) else {}),
    ):
        if not isinstance(source, Mapping):
            continue
        for field in (
            "prompt_protocol_sha256",
            "prompt_template_sha256",
            "prompt_template_hash",
            "prompt_protocol_hash",
        ):
            value = source.get(field)
            if _looks_like_sha256(value):
                hashes.append(str(value).strip().lower())
                sources.append(f"{source_name}.{field}")
    unique_hashes = sorted(set(hashes))
    return {
        "prompt_protocol_sha256": unique_hashes[0] if len(unique_hashes) == 1 else "",
        "prompt_protocol_hash_count": len(unique_hashes),
        "prompt_protocol_hash_sources": sources[:8],
        "prompt_protocol_hash_conflict": len(unique_hashes) > 1,
        "raw_prompt_persisted": False,
        "raw_prompt_template_persisted": False,
        "raw_provider_output_persisted": False,
        "secrets_persisted": False,
    }


