def _run_official_harness_binding_receipt(
    run: Mapping[str, Any],
    *,
    suite_id: str,
    task_format: str,
) -> dict[str, Any]:
    requires_official_harness = _suite_requires_official_harness(suite_id, task_format)
    receipt = run.get("harness_receipt") if isinstance(run.get("harness_receipt"), Mapping) else {}
    reason_codes = (
        _harness_receipt_reasons(receipt, suite_id=suite_id, task_format=task_format)
        if requires_official_harness
        else []
    )
    field_hashes = {}
    missing_fields = []
    if requires_official_harness:
        for field in OFFICIAL_HARNESS_SOURCE_BINDING_FIELDS:
            receipt_field = OFFICIAL_HARNESS_RECEIPT_BINDING_FIELDS.get(field, field)
            value = str(receipt.get(receipt_field) or "").strip().lower()
            if _looks_like_sha256(value):
                field_hashes[field] = value
            else:
                missing_fields.append(field)
    return {
        "harness_receipt_required": requires_official_harness,
        "harness_receipt_present": bool(receipt),
        "harness_receipt_valid": (not requires_official_harness) or not reason_codes,
        "harness_receipt_reason_codes": reason_codes,
        "official_harness_binding_hashes": field_hashes,
        "official_harness_binding_missing_fields": missing_fields,
        "raw_harness_output_path_persisted": False,
        "raw_harness_output_content_persisted": False,
        "raw_provider_output_persisted": False,
        "secrets_persisted": False,
    }


def _case_hash_from_result(row: Mapping[str, Any]) -> str:
    for key in (
        "case_id",
        "case_hash",
        "question_sha256",
        "input_sha256",
        "prompt_sha256",
        "reference_sha256",
    ):
        value = row.get(key)
        if _looks_like_sha256(value):
            return str(value).strip().lower()
    return ""


def _final_scorecard_summary(
    scorecard: Mapping[str, Any],
    *,
    expected_provider_baseline_count: int,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    candidates = scorecard.get("candidates") if isinstance(scorecard.get("candidates"), list) else []
    per_suite = scorecard.get("per_suite") if isinstance(scorecard.get("per_suite"), list) else []
    comparison_summary = scorecard.get("comparison") if isinstance(scorecard.get("comparison"), Mapping) else {}
    tier_target_summary = (
        comparison_summary.get("tier_target_summary")
        if isinstance(comparison_summary.get("tier_target_summary"), Mapping)
        else {}
    )
    per_suite_by_id = {
        str(row.get("suite_id") or ""): row
        for row in per_suite
        if isinstance(row, Mapping)
    }
    provider_count = sum(
        1
        for row in candidates
        if isinstance(row, Mapping) and str(row.get("candidate_id") or "").startswith("provider::")
    )
    axio_count = sum(
        1
        for row in candidates
        if isinstance(row, Mapping) and str(row.get("candidate_id") or "").startswith("axio-")
    )
    candidate_efficiency_issue_count = sum(
        1
        for row in candidates
        if isinstance(row, Mapping) and _scorecard_candidate_efficiency_reason_codes(row)
    )
    missing = []
    if not scorecard:
        missing.append({"kind": "scorecard_artifact_unavailable"})
    if provider_count < 3:
        missing.append(
            {
                "kind": "scorecard_missing_provider_baselines",
                "provider_baseline_count": provider_count,
            }
        )
    if provider_count < expected_provider_baseline_count:
        missing.append(
            {
                "kind": "scorecard_provider_baseline_count_below_available",
                "provider_baseline_count": provider_count,
                "expected_provider_baseline_count": expected_provider_baseline_count,
            }
        )
    if axio_count < 3:
        missing.append({"kind": "scorecard_missing_axio_models", "axio_candidate_count": axio_count})
    if candidate_efficiency_issue_count:
        missing.append(
            {
                "kind": "scorecard_candidate_cost_latency_metrics_incomplete",
                "candidate_issue_count": candidate_efficiency_issue_count,
            }
        )
    missing_tier_target_models = []
    for axio_model, target_tier, _ in _AXIO_TIER_TARGETS:
        model_summary = tier_target_summary.get(axio_model) if isinstance(tier_target_summary, Mapping) else None
        if not isinstance(model_summary, Mapping):
            missing_tier_target_models.append(
                {
                    "axio_model": axio_model,
                    "target_tier": target_tier,
                    "reason_codes": ["missing_tier_target_summary"],
                }
            )
            continue
        reason_codes = []
        if str(model_summary.get("target_tier") or "") != target_tier:
            reason_codes.append("target_tier_mismatch")
        if model_summary.get("all_required_suites_present") is not True:
            reason_codes.append("required_suite_comparisons_incomplete")
        if model_summary.get("all_required_suites_passed") is not True:
            reason_codes.append("required_suite_targets_not_all_beaten")
        if reason_codes:
            missing_tier_target_models.append(
                {
                    "axio_model": axio_model,
                    "target_tier": target_tier,
                    "reason_codes": reason_codes,
                    "passed_suite_count": _optional_int(model_summary.get("passed_suite_count")),
                    "required_suite_count": _optional_int(model_summary.get("required_suite_count")),
                }
            )
    if missing_tier_target_models:
        missing.append(
            {
                "kind": "scorecard_tier_target_summary_not_proven",
                "model_issue_count": len(missing_tier_target_models),
            }
        )
    missing_suite_ids = [suite.suite_id for suite in BENCHMARK_SUITES if suite.suite_id not in per_suite_by_id]
    if scorecard and missing_suite_ids:
        missing.append(
            {
                "kind": "scorecard_incomplete_suite_coverage",
                "covered_required_suite_count": len(BENCHMARK_SUITES) - len(missing_suite_ids),
            }
        )
    tier_issue_rows = []
    for suite in BENCHMARK_SUITES:
        row = per_suite_by_id.get(suite.suite_id)
        if not isinstance(row, Mapping):
            continue
        tiers = row.get("provider_baseline_tiers") if isinstance(row.get("provider_baseline_tiers"), list) else []
        comparisons = row.get("axio_target_comparisons") if isinstance(row.get("axio_target_comparisons"), list) else []
        reason_codes = []
        if len(tiers) < 3:
            reason_codes.append("fewer_than_three_provider_tiers")
        if len(tiers) < expected_provider_baseline_count:
            reason_codes.append("provider_tier_count_below_available")
        if _optional_int(row.get("provider_baseline_count")) is not None and _optional_int(row.get("provider_baseline_count")) < expected_provider_baseline_count:
            reason_codes.append("provider_run_count_below_available")
        comparison_models = {str(item.get("axio_model") or "") for item in comparisons if isinstance(item, Mapping)}
        if not {"axio-fast", "axio-terra", "axio-pro"}.issubset(comparison_models):
            reason_codes.append("missing_axio_tier_target_comparisons")
        comparison_by_model = {
            str(item.get("axio_model") or ""): item
            for item in comparisons
            if isinstance(item, Mapping)
        }
        for axio_model, target_tier, _ in _AXIO_TIER_TARGETS:
            comparison = comparison_by_model.get(axio_model)
            if not isinstance(comparison, Mapping):
                continue
            if str(comparison.get("target_tier") or "") != target_tier:
                reason_codes.append("axio_tier_target_mismatch")
            if comparison.get("beats_target") is not True:
                reason_codes.append("axio_tier_target_not_beaten")
        if any(_scorecard_provider_tier_efficiency_reason_codes(tier) for tier in tiers if isinstance(tier, Mapping)):
            reason_codes.append("provider_tier_cost_latency_metrics_incomplete")
        if any(_scorecard_comparison_efficiency_reason_codes(item) for item in comparisons if isinstance(item, Mapping)):
            reason_codes.append("axio_comparison_cost_latency_metrics_incomplete")
        if reason_codes:
            tier_issue_rows.append({"suite_id": suite.suite_id, "reason_codes": reason_codes})
    if tier_issue_rows:
        missing.append(
            {
                "kind": "scorecard_provider_tiers_incomplete",
                "suite_issue_count": len(tier_issue_rows),
            }
        )
    return (
        {
            "candidate_count": len(candidates),
            "provider_baseline_count": provider_count,
            "expected_provider_baseline_count": expected_provider_baseline_count,
            "axio_candidate_count": axio_count,
            "covered_required_suite_count": len(BENCHMARK_SUITES) - len(missing_suite_ids),
            "required_suite_count": len(BENCHMARK_SUITES),
            "provider_tier_issue_count": len(tier_issue_rows),
            "candidate_efficiency_issue_count": candidate_efficiency_issue_count,
            "provider_tier_issues": tier_issue_rows[:20],
            "tier_target_summary_issue_count": len(missing_tier_target_models),
            "tier_target_summary_issues": missing_tier_target_models[:20],
            "all_tier_target_summaries_proven": not missing_tier_target_models,
            "leader_candidate_id": str(scorecard.get("leader", {}).get("candidate_id") or "") if isinstance(scorecard.get("leader"), Mapping) else "",
        },
        missing,
    )


def _scorecard_candidate_efficiency_reason_codes(row: Mapping[str, Any]) -> list[str]:
    reasons = []
    if _optional_float(row.get("total_estimated_cost_usd")) is None:
        reasons.append("missing_total_estimated_cost_usd")
    if _optional_float(row.get("cost_per_case_usd")) is None:
        reasons.append("missing_cost_per_case_usd")
    if _optional_int(row.get("provider_call_count")) is None:
        reasons.append("missing_provider_call_count")
    if _optional_float(row.get("average_latency_ms")) is None:
        reasons.append("missing_average_latency_ms")
    if _optional_float(row.get("p50_latency_ms")) is None:
        reasons.append("missing_p50_latency_ms")
    if _optional_float(row.get("p95_latency_ms")) is None:
        reasons.append("missing_p95_latency_ms")
    return reasons


def _scorecard_provider_tier_efficiency_reason_codes(row: Mapping[str, Any]) -> list[str]:
    reasons = []
    if _optional_float(row.get("estimated_cost_usd")) is None:
        reasons.append("missing_estimated_cost_usd")
    if _optional_float(row.get("cost_per_case_usd")) is None:
        reasons.append("missing_cost_per_case_usd")
    if _optional_int(row.get("provider_call_count")) is None:
        reasons.append("missing_provider_call_count")
    if _optional_float(row.get("p50_case_latency_ms")) is None:
        reasons.append("missing_p50_case_latency_ms")
    if _optional_float(row.get("p95_case_latency_ms")) is None:
        reasons.append("missing_p95_case_latency_ms")
    return reasons


def _scorecard_comparison_efficiency_reason_codes(row: Mapping[str, Any]) -> list[str]:
    reasons = []
    for field in (
        "axio_estimated_cost_usd",
        "baseline_estimated_cost_usd",
        "axio_cost_per_case_usd",
        "baseline_cost_per_case_usd",
        "axio_p50_latency_ms",
        "baseline_p50_latency_ms",
        "axio_p95_latency_ms",
        "baseline_p95_latency_ms",
    ):
        if _optional_float(row.get(field)) is None:
            reasons.append(f"missing_{field}")
    return reasons


def _final_claim_summary(
    claim_audit: Mapping[str, Any],
    *,
    min_cases_per_suite: int,
    alpha: float,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing = []
    comparisons = claim_audit.get("comparisons") if isinstance(claim_audit.get("comparisons"), list) else []
    final_claims = claim_audit.get("final_claims") if isinstance(claim_audit.get("final_claims"), Mapping) else {}
    statistical = claim_audit.get("statistical_contract") if isinstance(claim_audit.get("statistical_contract"), Mapping) else {}
    correction = (
        claim_audit.get("multiple_comparison_correction")
        if isinstance(claim_audit.get("multiple_comparison_correction"), Mapping)
        else {}
    )
    category_coverage = claim_audit.get("category_coverage") if isinstance(claim_audit.get("category_coverage"), Mapping) else {}
    freeze_binding = (
        claim_audit.get("provider_baseline_freeze_binding")
        if isinstance(claim_audit.get("provider_baseline_freeze_binding"), Mapping)
        else {}
    )
    failed_comparisons = [
        row
        for row in comparisons
        if isinstance(row, Mapping) and row.get("claim_allowed") is not True
    ]
    if not claim_audit:
        missing.append({"kind": "claim_audit_artifact_unavailable"})
    if claim_audit.get("schema") != "axio_fusion_api.benchmark_claim_audit.v1":
        missing.append({"kind": "claim_audit_schema_unrecognized"})
    if claim_audit.get("all_final_claims_allowed") is not True:
        missing.append({"kind": "claim_audit_not_approved"})
    if claim_audit.get("all_required_suites_present") is not True:
        missing.append({"kind": "claim_audit_missing_required_suites"})
    if _optional_int(claim_audit.get("covered_required_suite_count")) != len(BENCHMARK_SUITES):
        missing.append(
            {
                "kind": "claim_audit_incomplete_suite_coverage",
                "covered_required_suite_count": _optional_int(claim_audit.get("covered_required_suite_count")),
            }
        )
    if len(comparisons) < len(BENCHMARK_SUITES) * 3:
        missing.append(
            {
                "kind": "claim_audit_incomplete_comparison_count",
                "comparison_count": len(comparisons),
            }
        )
    if str(freeze_binding.get("selection_mode") or "") != EXTERNAL_PROVIDER_RANKING_SELECTION_MODE:
        missing.append({"kind": "claim_audit_not_bound_to_pre_registered_top_three"})
    if freeze_binding.get("ready") is not True:
        missing.append({"kind": "claim_audit_pre_registered_baseline_binding_not_ready"})
    if failed_comparisons:
        missing.append({"kind": "claim_audit_failed_comparisons_present", "failed_comparison_count": len(failed_comparisons)})
    for claim_key in (
        "axio_pro_beats_strongest_single_model_on_all_required_benchmarks",
        "axio_terra_beats_second_strongest_single_model_on_all_required_benchmarks",
        "axio_fast_beats_third_strongest_single_model_on_all_required_benchmarks",
    ):
        if final_claims.get(claim_key) is not True:
            missing.append({"kind": "final_claim_not_proven", "claim": claim_key})
    if statistical.get("paired_case_comparison_required") is not True:
        missing.append({"kind": "paired_case_comparison_not_required_by_artifact"})
    if statistical.get("one_sided_exact_sign_test") is not True:
        missing.append({"kind": "sign_test_not_required_by_artifact"})
    if statistical.get("multiple_comparison_correction_required") is not True:
        missing.append({"kind": "multiple_comparison_correction_not_required_by_artifact"})
    if statistical.get("multiple_comparison_correction_method") != CLAIM_MULTIPLE_COMPARISON_METHOD:
        missing.append({"kind": "multiple_comparison_correction_method_unrecognized"})
    if statistical.get("familywise_error_rate_control") is not True:
        missing.append({"kind": "familywise_error_rate_control_not_required_by_artifact"})
    if str(statistical.get("correction_family") or "") != CLAIM_MULTIPLE_COMPARISON_FAMILY:
        missing.append({"kind": "multiple_comparison_correction_family_unrecognized"})
    if (_optional_int(statistical.get("correction_family_size")) or 0) < len(BENCHMARK_SUITES) * 3:
        missing.append({"kind": "multiple_comparison_correction_family_too_small"})
    if not correction:
        missing.append({"kind": "multiple_comparison_correction_artifact_unavailable"})
    elif correction.get("method") != CLAIM_MULTIPLE_COMPARISON_METHOD:
        missing.append({"kind": "multiple_comparison_correction_artifact_method_unrecognized"})
    if correction and str(correction.get("family") or "") != CLAIM_MULTIPLE_COMPARISON_FAMILY:
        missing.append({"kind": "multiple_comparison_correction_artifact_family_unrecognized"})
    if correction and (_optional_int(correction.get("family_size")) or 0) < len(BENCHMARK_SUITES) * 3:
        missing.append({"kind": "multiple_comparison_correction_artifact_family_too_small"})
    if correction and correction.get("all_comparisons_corrected") is not True:
        missing.append({"kind": "multiple_comparison_correction_incomplete"})
    if statistical.get("aggregate_only_scores_can_not_support_claim") is not True:
        missing.append({"kind": "aggregate_only_scores_not_forbidden_by_artifact"})
    if (_optional_int(statistical.get("min_cases_per_suite")) or 0) < min_cases_per_suite:
        missing.append({"kind": "claim_audit_min_cases_too_low"})
    if (_optional_float(statistical.get("alpha")) or 1.0) > alpha:
        missing.append({"kind": "claim_audit_alpha_too_weak"})
    for category, row in category_coverage.items():
        if isinstance(row, Mapping) and row.get("all_model_claims_passed_for_category") is not True:
            missing.append({"kind": "category_claim_not_proven", "category": str(category)})
    weak_pairs = []
    weak_provider_rows = []
    weak_p_value_rows = []
    weak_corrected_p_value_rows = []
    pre_registration_mismatch_rows = []
    for row in comparisons:
        if not isinstance(row, Mapping):
            continue
        paired = row.get("paired_case_stats") if isinstance(row.get("paired_case_stats"), Mapping) else {}
        effective_min_cases = _effective_min_cases_for_suite(
            str(row.get("suite_id") or ""),
            min_cases_per_suite,
        )
        if (_optional_int(paired.get("common_case_count")) or 0) < effective_min_cases:
            weak_pairs.append(str(row.get("suite_id") or ""))
        if (_optional_int(row.get("provider_baseline_count")) or 0) < 3:
            weak_provider_rows.append(str(row.get("suite_id") or ""))
        expected_baseline_hash = str(row.get("expected_baseline_candidate_id_sha256") or "")
        actual_baseline_id = str(row.get("baseline_candidate_id") or "")
        if (
            row.get("baseline_pre_registered") is not True
            or not _looks_like_sha256(expected_baseline_hash)
            or not actual_baseline_id
            or sha256_text(actual_baseline_id) != expected_baseline_hash
        ):
            pre_registration_mismatch_rows.append(str(row.get("suite_id") or ""))
        p_value = _optional_float(paired.get("p_value_one_sided"))
        if p_value is None or p_value > alpha:
            weak_p_value_rows.append(str(row.get("suite_id") or ""))
        row_correction = row.get("multiple_comparison_correction") if isinstance(row.get("multiple_comparison_correction"), Mapping) else {}
        if row.get("multiple_comparison_passed") is not True or row_correction.get("passed") is not True:
            weak_corrected_p_value_rows.append(str(row.get("suite_id") or ""))
    if weak_pairs:
        missing.append({"kind": "paired_case_overlap_too_small", "comparison_count": len(weak_pairs)})
    if weak_provider_rows:
        missing.append({"kind": "comparison_provider_baseline_count_too_small", "comparison_count": len(weak_provider_rows)})
    if weak_p_value_rows:
        missing.append({"kind": "comparison_sign_test_not_significant", "comparison_count": len(weak_p_value_rows)})
    if weak_corrected_p_value_rows:
        missing.append(
            {
                "kind": "comparison_multiple_comparison_correction_not_significant",
                "comparison_count": len(weak_corrected_p_value_rows),
            }
        )
    if pre_registration_mismatch_rows:
        missing.append(
            {
                "kind": "claim_audit_pre_registered_baseline_pairing_mismatch",
                "comparison_count": len(pre_registration_mismatch_rows),
            }
        )
    return (
        {
            "all_final_claims_allowed": claim_audit.get("all_final_claims_allowed"),
            "all_required_suites_present": claim_audit.get("all_required_suites_present"),
            "required_suite_count": _optional_int(claim_audit.get("required_suite_count")),
            "covered_required_suite_count": _optional_int(claim_audit.get("covered_required_suite_count")),
            "comparison_count": len(comparisons),
            "failed_comparison_count": len(failed_comparisons),
            "final_claims": dict(final_claims),
            "statistical_contract": dict(statistical),
            "multiple_comparison_correction": dict(correction),
            "provider_baseline_freeze_binding": dict(freeze_binding),
        },
        missing,
    )


def _final_cross_artifact_summary(
    *,
    campaign: Mapping[str, Any],
    runs_payload: Mapping[str, Any],
    scorecard: Mapping[str, Any],
    claim_audit: Mapping[str, Any],
    methodology: Mapping[str, Any],
    actual_run_count: int,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing = []
    runs_declared = _optional_int(runs_payload.get("run_count")) if runs_payload else None
    campaign_expected = _optional_int(campaign.get("expected_run_count")) if campaign else None
    campaign_completed = _optional_int(campaign.get("completed_or_resumed_run_count")) if campaign else None
    campaign_suite_count = _optional_int(campaign.get("suite_spec_count")) if campaign else None
    campaign_candidate_count = _optional_int(campaign.get("candidate_count")) if campaign else None
    campaign_run_unit_count = _optional_int(campaign.get("run_unit_count")) if campaign else None
    scorecard_run_count = _optional_int(scorecard.get("run_count")) if scorecard else None
    claim_run_count = _optional_int(claim_audit.get("run_count")) if claim_audit else None
    campaign_claim = campaign.get("claim_summary") if isinstance(campaign.get("claim_summary"), Mapping) else {}
    run_rows = runs_payload.get("runs") if isinstance(runs_payload.get("runs"), list) else []
    run_set_receipt = _benchmark_run_set_receipt(
        [row for row in run_rows if isinstance(row, Mapping)]
    )
    computed_run_set_digest = run_set_receipt["run_set_digest_sha256"]
    runs_digest, runs_receipt_digest = _artifact_run_set_digests(
        runs_payload,
        digest_key="run_set_digest_sha256",
        receipt_key="run_set_receipt",
    )
    scorecard_digest, scorecard_receipt_digest = _artifact_run_set_digests(
        scorecard,
        digest_key="source_run_set_digest_sha256",
        receipt_key="source_run_set_receipt",
    )
    claim_digest, claim_receipt_digest = _artifact_run_set_digests(
        claim_audit,
        digest_key="source_run_set_digest_sha256",
        receipt_key="source_run_set_receipt",
    )
    computed_methodology_receipt = _benchmark_methodology_receipt(methodology) if methodology else {}
    campaign_methodology_receipt = (
        campaign.get("methodology_receipt")
        if isinstance(campaign.get("methodology_receipt"), Mapping)
        else {}
    )
    computed_methodology_digest = str(computed_methodology_receipt.get("methodology_digest_sha256") or "")
    campaign_methodology_digest = str(campaign_methodology_receipt.get("methodology_digest_sha256") or "")
    methodology_receipt_schema = str(campaign_methodology_receipt.get("schema") or "")

    if runs_payload and runs_declared is not None and runs_declared != actual_run_count:
        missing.append(
            {
                "kind": "runs_payload_run_count_mismatch",
                "declared_run_count": runs_declared,
                "actual_run_count": actual_run_count,
            }
        )
    if campaign and campaign_completed is not None and campaign_completed != actual_run_count:
        missing.append(
            {
                "kind": "campaign_completed_run_count_mismatch",
                "completed_or_resumed_run_count": campaign_completed,
                "actual_run_count": actual_run_count,
            }
        )
    if campaign and campaign_expected is not None and campaign_expected != actual_run_count:
        missing.append(
            {
                "kind": "campaign_expected_run_count_mismatch",
                "expected_run_count": campaign_expected,
                "actual_run_count": actual_run_count,
            }
        )
    if campaign and campaign_suite_count is not None and campaign_expected is not None:
        multiplier = campaign_run_unit_count if campaign_run_unit_count is not None else campaign_candidate_count
        product = campaign_suite_count * multiplier if multiplier is not None else None
        if product is None:
            missing.append({"kind": "campaign_expected_run_count_formula_inputs_missing"})
        elif product != campaign_expected:
            missing.append(
                {
                    "kind": "campaign_expected_run_count_formula_mismatch",
                    "suite_spec_count": campaign_suite_count,
                    "candidate_count": campaign_candidate_count,
                    "run_unit_count": campaign_run_unit_count,
                    "expected_run_count": campaign_expected,
                }
            )
    if scorecard and scorecard_run_count is not None and scorecard_run_count != actual_run_count:
        missing.append(
            {
                "kind": "scorecard_run_count_mismatch",
                "scorecard_run_count": scorecard_run_count,
                "actual_run_count": actual_run_count,
            }
        )
    if claim_audit and claim_run_count is not None and claim_run_count != actual_run_count:
        missing.append(
            {
                "kind": "claim_audit_run_count_mismatch",
                "claim_audit_run_count": claim_run_count,
                "actual_run_count": actual_run_count,
            }
        )
    if campaign_claim and claim_audit:
        for key in ("all_required_suites_present", "all_final_claims_allowed"):
            if campaign_claim.get(key) != claim_audit.get(key):
                missing.append(
                    {
                        "kind": "campaign_claim_summary_mismatch",
                        "field": key,
                    }
                )
    for artifact, digest, receipt_digest in (
        ("runs", runs_digest, runs_receipt_digest),
        ("scorecard", scorecard_digest, scorecard_receipt_digest),
        ("claim_audit", claim_digest, claim_receipt_digest),
    ):
        if not _looks_like_sha256(digest):
            missing.append(
                {
                    "kind": "run_set_digest_missing",
                    "artifact": artifact,
                }
            )
            continue
        if _looks_like_sha256(receipt_digest) and receipt_digest != digest:
            missing.append(
                {
                    "kind": "run_set_receipt_digest_mismatch",
                    "artifact": artifact,
                }
            )
    if _looks_like_sha256(runs_digest) and runs_digest != computed_run_set_digest:
        missing.append(
            {
                "kind": "runs_payload_run_set_digest_mismatch",
                "artifact": "runs",
            }
        )
    if _looks_like_sha256(scorecard_digest) and scorecard_digest != computed_run_set_digest:
        missing.append(
            {
                "kind": "scorecard_run_set_digest_mismatch",
                "artifact": "scorecard",
            }
        )
    if _looks_like_sha256(claim_digest) and claim_digest != computed_run_set_digest:
        missing.append(
            {
                "kind": "claim_audit_run_set_digest_mismatch",
                "artifact": "claim_audit",
            }
        )
    if campaign and not campaign_methodology_receipt:
        missing.append({"kind": "methodology_receipt_missing"})
    elif campaign_methodology_receipt:
        if methodology_receipt_schema != "axio_fusion_api.benchmark_methodology_receipt.v1":
            missing.append(
                {
                    "kind": "methodology_receipt_schema_unrecognized",
                    "schema": methodology_receipt_schema,
                }
            )
        if not _looks_like_sha256(campaign_methodology_digest):
            missing.append({"kind": "methodology_receipt_digest_missing"})
        elif campaign_methodology_digest != computed_methodology_digest:
            missing.append({"kind": "methodology_receipt_digest_mismatch"})
        campaign_suite_count = _optional_int(campaign_methodology_receipt.get("suite_count"))
        computed_suite_count = _optional_int(computed_methodology_receipt.get("suite_count"))
        if campaign_suite_count is not None and computed_suite_count is not None and campaign_suite_count != computed_suite_count:
            missing.append(
                {
                    "kind": "methodology_receipt_suite_count_mismatch",
                    "campaign_suite_count": campaign_suite_count,
                    "computed_suite_count": computed_suite_count,
                }
            )
    return (
        {
            "actual_run_count": actual_run_count,
            "runs_payload_run_count": runs_declared,
            "campaign_expected_run_count": campaign_expected,
            "campaign_completed_or_resumed_run_count": campaign_completed,
            "campaign_suite_spec_count": campaign_suite_count,
            "campaign_candidate_count": campaign_candidate_count,
            "campaign_run_unit_count": campaign_run_unit_count,
            "scorecard_run_count": scorecard_run_count,
            "claim_audit_run_count": claim_run_count,
            "computed_run_set_digest_sha256": computed_run_set_digest,
            "runs_payload_run_set_digest_sha256": runs_digest,
            "scorecard_source_run_set_digest_sha256": scorecard_digest,
            "claim_audit_source_run_set_digest_sha256": claim_digest,
            "runs_payload_run_set_digest_matches": _looks_like_sha256(runs_digest)
            and runs_digest == computed_run_set_digest,
            "scorecard_run_set_digest_matches": _looks_like_sha256(scorecard_digest)
            and scorecard_digest == computed_run_set_digest,
            "claim_audit_run_set_digest_matches": _looks_like_sha256(claim_digest)
            and claim_digest == computed_run_set_digest,
            "computed_methodology_digest_sha256": computed_methodology_digest,
            "campaign_methodology_digest_sha256": campaign_methodology_digest,
            "methodology_receipt_digest_matches": _looks_like_sha256(campaign_methodology_digest)
            and campaign_methodology_digest == computed_methodology_digest,
            "methodology_artifact_bound_to_campaign": (
                methodology_receipt_schema == "axio_fusion_api.benchmark_methodology_receipt.v1"
                and _looks_like_sha256(campaign_methodology_digest)
                and campaign_methodology_digest == computed_methodology_digest
            ),
            "scorecard_and_claim_audit_bound_to_run_set": (
                _looks_like_sha256(runs_digest)
                and _looks_like_sha256(scorecard_digest)
                and _looks_like_sha256(claim_digest)
                and runs_digest == computed_run_set_digest
                and scorecard_digest == computed_run_set_digest
                and claim_digest == computed_run_set_digest
            ),
            "mismatch_count": len(missing),
            "raw_dataset_content_persisted": False,
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _final_deterministic_replay_summary(
    runs: Sequence[Mapping[str, Any]],
    *,
    scorecard: Mapping[str, Any],
    claim_audit: Mapping[str, Any],
    provider_baseline_freeze: Mapping[str, Any],
    min_cases_per_suite: int,
    alpha: float,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Recompute scorecard/claim signatures from runs and compare safely."""

    missing = []
    normalized_runs = [_normalize_safe_run_candidate_alias(run) for run in runs if isinstance(run, Mapping)]
    scorecard_signature = _scorecard_replay_signature(scorecard)
    claim_signature = _claim_audit_replay_signature(claim_audit)
    recomputed_scorecard = (
        build_benchmark_scorecard(
            normalized_runs,
            provider_baseline_freeze=provider_baseline_freeze,
            require_http_gateway=True,
        )
        if normalized_runs
        else {}
    )
    recomputed_claim = (
        build_benchmark_claim_audit(
            normalized_runs,
            min_cases_per_suite=min_cases_per_suite,
            alpha=alpha,
            provider_baseline_freeze=provider_baseline_freeze,
            require_http_gateway=True,
        )
        if normalized_runs
        else {}
    )
    recomputed_scorecard_signature = _scorecard_replay_signature(recomputed_scorecard)
    recomputed_claim_signature = _claim_audit_replay_signature(recomputed_claim)
    scorecard_digest = _safe_signature_digest(scorecard_signature)
    recomputed_scorecard_digest = _safe_signature_digest(recomputed_scorecard_signature)
    claim_digest = _safe_signature_digest(claim_signature)
    recomputed_claim_digest = _safe_signature_digest(recomputed_claim_signature)
    scorecard_matches = bool(scorecard_signature) and scorecard_digest == recomputed_scorecard_digest
    claim_matches = bool(claim_signature) and claim_digest == recomputed_claim_digest
    if not normalized_runs:
        missing.append({"kind": "deterministic_replay_run_artifacts_unavailable"})
    if scorecard and not scorecard_matches:
        missing.append(
            {
                "kind": "scorecard_deterministic_replay_mismatch",
                "scorecard_signature_sha256": scorecard_digest,
                "recomputed_signature_sha256": recomputed_scorecard_digest,
            }
        )
    elif not scorecard:
        missing.append({"kind": "scorecard_deterministic_replay_unavailable"})
    if claim_audit and not claim_matches:
        missing.append(
            {
                "kind": "claim_audit_deterministic_replay_mismatch",
                "claim_audit_signature_sha256": claim_digest,
                "recomputed_signature_sha256": recomputed_claim_digest,
            }
        )
    elif not claim_audit:
        missing.append({"kind": "claim_audit_deterministic_replay_unavailable"})
    return (
        {
            "schema": "axio_fusion_api.final_deterministic_replay.v1",
            "run_count": len(normalized_runs),
            "min_cases_per_suite": int(min_cases_per_suite),
            "alpha": float(alpha),
            "scorecard_signature_sha256": scorecard_digest,
            "recomputed_scorecard_signature_sha256": recomputed_scorecard_digest,
            "scorecard_matches_recomputed": scorecard_matches,
            "claim_audit_signature_sha256": claim_digest,
            "recomputed_claim_audit_signature_sha256": recomputed_claim_digest,
            "claim_audit_matches_recomputed": claim_matches,
            "scorecard_candidate_count": _optional_int(scorecard.get("candidate_count")) if scorecard else None,
            "recomputed_scorecard_candidate_count": _optional_int(recomputed_scorecard.get("candidate_count")) if recomputed_scorecard else None,
            "claim_comparison_count": len(claim_audit.get("comparisons", [])) if isinstance(claim_audit.get("comparisons"), list) else None,
            "recomputed_claim_comparison_count": len(recomputed_claim.get("comparisons", [])) if isinstance(recomputed_claim.get("comparisons"), list) else None,
            "claim_all_final_claims_allowed": claim_audit.get("all_final_claims_allowed") if claim_audit else None,
            "recomputed_claim_all_final_claims_allowed": recomputed_claim.get("all_final_claims_allowed") if recomputed_claim else None,
            "replay_missing_count": len(missing),
            "raw_candidate_ids_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_dataset_content_persisted": False,
            "raw_prompts_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _safe_signature_digest(signature: Mapping[str, Any]) -> str:
    return sha256_text(stable_json(signature)) if signature else ""


def _pre_registered_provider_binding_replay_signature(value: Any) -> dict[str, Any]:
    binding = value if isinstance(value, Mapping) else {}
    rank_map = (
        binding.get("rank_to_candidate_id_sha256")
        if isinstance(binding.get("rank_to_candidate_id_sha256"), Mapping)
        else {}
    )
    return {
        "selection_mode": str(binding.get("selection_mode") or ""),
        "freeze_digest_sha256": str(binding.get("freeze_digest_sha256") or ""),
        "freeze_receipt_digest_sha256": str(binding.get("freeze_receipt_digest_sha256") or ""),
        "external_ranking_receipt_digest_sha256": str(
            binding.get("external_ranking_receipt_digest_sha256") or ""
        ),
        "rank_to_candidate_id_sha256": {
            str(rank): str(candidate_hash)
            for rank, candidate_hash in sorted(rank_map.items(), key=lambda item: str(item[0]))
        },
        "ready": binding.get("ready") is True,
        "validation_errors": sorted(
            str(reason)
            for reason in binding.get("external_ranking_validation_errors", [])
            if reason
        ),
    }


def _scorecard_replay_signature(scorecard: Mapping[str, Any]) -> dict[str, Any]:
    if not scorecard:
        return {}
    candidates = scorecard.get("candidates") if isinstance(scorecard.get("candidates"), list) else []
    per_suite = scorecard.get("per_suite") if isinstance(scorecard.get("per_suite"), list) else []
    comparison = scorecard.get("comparison") if isinstance(scorecard.get("comparison"), Mapping) else {}
    tier_target_summary = (
        comparison.get("tier_target_summary")
        if isinstance(comparison.get("tier_target_summary"), Mapping)
        else {}
    )
    candidate_rows = []
    for row in candidates:
        if not isinstance(row, Mapping):
            continue
        candidate_id = str(row.get("candidate_id") or "")
        candidate_rows.append(
            {
                "candidate_id_sha256": sha256_text(candidate_id),
                "run_count": _optional_int(row.get("run_count")),
                "case_count": _optional_int(row.get("case_count")),
                "attempted_count": _optional_int(row.get("attempted_count")),
                "correct_count": _optional_int(row.get("correct_count")),
                "accuracy": _optional_float(row.get("accuracy")),
                "mean_primary_score": _optional_float(row.get("mean_primary_score")),
                "total_estimated_cost_usd": _optional_float(row.get("total_estimated_cost_usd")),
                "cost_per_case_usd": _optional_float(row.get("cost_per_case_usd")),
                "provider_call_count": _optional_int(row.get("provider_call_count")),
                "p50_latency_ms": _optional_float(row.get("p50_latency_ms")),
                "p95_latency_ms": _optional_float(row.get("p95_latency_ms")),
            }
        )
    suite_rows = []
    for row in per_suite:
        if not isinstance(row, Mapping):
            continue
        provider_tiers = row.get("provider_baseline_tiers") if isinstance(row.get("provider_baseline_tiers"), list) else []
        comparisons = row.get("axio_target_comparisons") if isinstance(row.get("axio_target_comparisons"), list) else []
        suite_rows.append(
            {
                "suite_id": str(row.get("suite_id") or ""),
                "category": str(row.get("category") or ""),
                "task_format": str(row.get("task_format") or ""),
                "primary_metric": str(row.get("primary_metric") or ""),
                "run_count": _optional_int(row.get("run_count")),
                "candidate_count": _optional_int(row.get("candidate_count")),
                "provider_baseline_count": _optional_int(row.get("provider_baseline_count")),
                "provider_baseline_tiers": sorted(
                    [
                        _scorecard_tier_replay_signature(item)
                        for item in provider_tiers
                        if isinstance(item, Mapping)
                    ],
                    key=lambda item: (item["rank"] or 0, item["tier"], item["candidate_id_sha256"]),
                ),
                "axio_target_comparisons": sorted(
                    [
                        _scorecard_comparison_replay_signature(item)
                        for item in comparisons
                        if isinstance(item, Mapping)
                    ],
                    key=lambda item: (item["axio_model"], item["target_tier"]),
                ),
            }
        )
    return {
        "schema": "axio_fusion_api.scorecard_replay_signature.v1",
        "scorecard_schema": str(scorecard.get("schema") or ""),
        "run_count": _optional_int(scorecard.get("run_count")),
        "candidate_count": _optional_int(scorecard.get("candidate_count")),
        "candidates": sorted(candidate_rows, key=lambda item: item["candidate_id_sha256"]),
        "per_suite": sorted(suite_rows, key=lambda item: item["suite_id"]),
        "tier_target_summary": {
            axio_model: _scorecard_tier_target_replay_signature(
                tier_target_summary.get(axio_model) if isinstance(tier_target_summary, Mapping) else {}
            )
            for axio_model, _, _ in _AXIO_TIER_TARGETS
        },
        "provider_baseline_freeze_binding": _pre_registered_provider_binding_replay_signature(
            scorecard.get("provider_baseline_freeze_binding")
        ),
        "raw_candidate_ids_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _scorecard_tier_target_replay_signature(row: Any) -> dict[str, Any]:
    if not isinstance(row, Mapping):
        row = {}
    failed_or_missing = row.get("failed_or_missing_suites") if isinstance(row.get("failed_or_missing_suites"), list) else []
    return {
        "target_tier": str(row.get("target_tier") or ""),
        "required_suite_count": _optional_int(row.get("required_suite_count")),
        "suite_comparison_count": _optional_int(row.get("suite_comparison_count")),
        "required_suite_comparison_count": _optional_int(row.get("required_suite_comparison_count")),
        "scored_suite_count": _optional_int(row.get("scored_suite_count")),
        "passed_suite_count": _optional_int(row.get("passed_suite_count")),
        "all_required_suites_present": row.get("all_required_suites_present") if isinstance(row.get("all_required_suites_present"), bool) else None,
        "all_required_suites_passed": row.get("all_required_suites_passed") if isinstance(row.get("all_required_suites_passed"), bool) else None,
        "all_scored_suites_passed": row.get("all_scored_suites_passed") if isinstance(row.get("all_scored_suites_passed"), bool) else None,
        "missing_required_suite_count": _optional_int(row.get("missing_required_suite_count")),
        "failed_or_missing_suites": sorted(
            [
                {
                    "suite_id": str(item.get("suite_id") or ""),
                    "reason_codes": sorted(str(reason) for reason in item.get("reason_codes", []) if reason),
                }
                for item in failed_or_missing
                if isinstance(item, Mapping)
            ],
            key=lambda item: item["suite_id"],
        ),
    }


def _scorecard_tier_replay_signature(row: Mapping[str, Any]) -> dict[str, Any]:
    candidate_id = str(row.get("candidate_id") or "")
    return {
        "tier": str(row.get("tier") or ""),
        "rank": _optional_int(row.get("rank")),
        "candidate_id_sha256": str(row.get("candidate_id_sha256") or sha256_text(candidate_id)),
        "primary_metric": str(row.get("primary_metric") or ""),
        "primary_score": _optional_float(row.get("primary_score")),
        "case_count": _optional_int(row.get("case_count")),
        "correct_count": _optional_int(row.get("correct_count")),
        "estimated_cost_usd": _optional_float(row.get("estimated_cost_usd")),
        "cost_per_case_usd": _optional_float(row.get("cost_per_case_usd")),
        "provider_call_count": _optional_int(row.get("provider_call_count")),
        "p50_case_latency_ms": _optional_float(row.get("p50_case_latency_ms")),
        "p95_case_latency_ms": _optional_float(row.get("p95_case_latency_ms")),
    }


def _scorecard_comparison_replay_signature(row: Mapping[str, Any]) -> dict[str, Any]:
    baseline_candidate_id = str(row.get("baseline_candidate_id") or "")
    return {
        "suite_id": str(row.get("suite_id") or ""),
        "axio_model": str(row.get("axio_model") or ""),
        "target_tier": str(row.get("target_tier") or ""),
        "baseline_candidate_id_sha256": str(row.get("baseline_candidate_id_sha256") or sha256_text(baseline_candidate_id)),
        "primary_metric": str(row.get("primary_metric") or ""),
        "axio_primary_score": _optional_float(row.get("axio_primary_score")),
        "baseline_primary_score": _optional_float(row.get("baseline_primary_score")),
        "primary_score_delta": _optional_float(row.get("primary_score_delta")),
        "axio_estimated_cost_usd": _optional_float(row.get("axio_estimated_cost_usd")),
        "baseline_estimated_cost_usd": _optional_float(row.get("baseline_estimated_cost_usd")),
        "axio_cost_per_case_usd": _optional_float(row.get("axio_cost_per_case_usd")),
        "baseline_cost_per_case_usd": _optional_float(row.get("baseline_cost_per_case_usd")),
        "axio_p50_latency_ms": _optional_float(row.get("axio_p50_latency_ms")),
        "baseline_p50_latency_ms": _optional_float(row.get("baseline_p50_latency_ms")),
        "axio_p95_latency_ms": _optional_float(row.get("axio_p95_latency_ms")),
        "baseline_p95_latency_ms": _optional_float(row.get("baseline_p95_latency_ms")),
        "latency_multiplier_vs_baseline": _optional_float(row.get("latency_multiplier_vs_baseline")),
        "paired_case_overlap_count": _optional_int(row.get("paired_case_overlap_count")),
        "beats_target": row.get("beats_target") if isinstance(row.get("beats_target"), bool) else None,
        "reason_codes": sorted(str(reason) for reason in row.get("reason_codes", []) if reason),
    }


def _claim_audit_replay_signature(claim_audit: Mapping[str, Any]) -> dict[str, Any]:
    if not claim_audit:
        return {}
    comparisons = claim_audit.get("comparisons") if isinstance(claim_audit.get("comparisons"), list) else []
    final_claims = claim_audit.get("final_claims") if isinstance(claim_audit.get("final_claims"), Mapping) else {}
    correction = (
        claim_audit.get("multiple_comparison_correction")
        if isinstance(claim_audit.get("multiple_comparison_correction"), Mapping)
        else {}
    )
    return {
        "schema": "axio_fusion_api.claim_audit_replay_signature.v1",
        "claim_audit_schema": str(claim_audit.get("schema") or ""),
        "run_count": _optional_int(claim_audit.get("run_count")),
        "required_suite_count": _optional_int(claim_audit.get("required_suite_count")),
        "covered_required_suite_count": _optional_int(claim_audit.get("covered_required_suite_count")),
        "all_required_suites_present": claim_audit.get("all_required_suites_present") if isinstance(claim_audit.get("all_required_suites_present"), bool) else None,
        "all_final_claims_allowed": claim_audit.get("all_final_claims_allowed") if isinstance(claim_audit.get("all_final_claims_allowed"), bool) else None,
        "final_claims": {str(key): value for key, value in sorted(final_claims.items())},
        "multiple_comparison_correction": _multiple_comparison_replay_signature(correction),
        "provider_baseline_freeze_binding": _pre_registered_provider_binding_replay_signature(
            claim_audit.get("provider_baseline_freeze_binding")
        ),
        "comparisons": sorted(
            [
                _claim_comparison_replay_signature(row)
                for row in comparisons
                if isinstance(row, Mapping)
            ],
            key=lambda item: (item["suite_id"], item["axio_model"], item["baseline_tier"]),
        ),
        "missing_requirements": _missing_requirement_replay_signature(claim_audit.get("missing_requirements")),
        "raw_candidate_ids_persisted": False,
        "raw_provider_model_ids_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _claim_comparison_replay_signature(row: Mapping[str, Any]) -> dict[str, Any]:
    paired = row.get("paired_case_stats") if isinstance(row.get("paired_case_stats"), Mapping) else {}
    correction = (
        row.get("multiple_comparison_correction")
        if isinstance(row.get("multiple_comparison_correction"), Mapping)
        else {}
    )
    baseline_candidate_id = str(row.get("baseline_candidate_id") or "")
    return {
        "suite_id": str(row.get("suite_id") or ""),
        "category": str(row.get("category") or ""),
        "axio_model": str(row.get("axio_model") or ""),
        "baseline_tier": str(row.get("baseline_tier") or ""),
        "baseline_rank": _optional_int(row.get("baseline_rank")),
        "baseline_pre_registered": row.get("baseline_pre_registered") is True,
        "expected_baseline_candidate_id_sha256": str(
            row.get("expected_baseline_candidate_id_sha256") or ""
        ),
        "baseline_candidate_id_sha256": sha256_text(baseline_candidate_id) if baseline_candidate_id else "",
        "provider_baseline_count": _optional_int(row.get("provider_baseline_count")),
        "axio_primary_score": _optional_float(row.get("axio_primary_score")),
        "baseline_primary_score": _optional_float(row.get("baseline_primary_score")),
        "primary_score_delta": _optional_float(row.get("primary_score_delta")),
        "latency_multiplier_vs_baseline": _optional_float(row.get("latency_multiplier_vs_baseline")),
        "paired_case_stats": _paired_case_replay_signature(paired),
        "raw_significance_passed": row.get("raw_significance_passed") if isinstance(row.get("raw_significance_passed"), bool) else None,
        "uncorrected_claim_allowed": row.get("uncorrected_claim_allowed") if isinstance(row.get("uncorrected_claim_allowed"), bool) else None,
        "multiple_comparison_passed": row.get("multiple_comparison_passed") if isinstance(row.get("multiple_comparison_passed"), bool) else None,
        "multiple_comparison_correction": _multiple_comparison_replay_signature(correction),
        "claim_allowed": row.get("claim_allowed") if isinstance(row.get("claim_allowed"), bool) else None,
        "reason_codes": sorted(str(reason) for reason in row.get("reason_codes", []) if reason),
    }


def _paired_case_replay_signature(row: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "common_case_count": _optional_int(row.get("common_case_count")),
        "both_correct_count": _optional_int(row.get("both_correct_count")),
        "both_wrong_count": _optional_int(row.get("both_wrong_count")),
        "axio_unique_correct_count": _optional_int(row.get("axio_unique_correct_count")),
        "baseline_unique_correct_count": _optional_int(row.get("baseline_unique_correct_count")),
        "discordant_pair_count": _optional_int(row.get("discordant_pair_count")),
        "win_rate_on_discordant_pairs": _optional_float(row.get("win_rate_on_discordant_pairs")),
        "p_value_one_sided": _optional_float(row.get("p_value_one_sided")),
        "paired_score_comparison_count": _optional_int(row.get("paired_score_comparison_count")),
        "case_ids_are_hashes": row.get("case_ids_are_hashes") if isinstance(row.get("case_ids_are_hashes"), bool) else None,
    }


def _multiple_comparison_replay_signature(row: Mapping[str, Any]) -> dict[str, Any]:
    if not row:
        return {}
    return {
        "method": str(row.get("method") or ""),
        "family": str(row.get("family") or ""),
        "family_size": _optional_int(row.get("family_size")),
        "alpha": _optional_float(row.get("alpha")),
        "rank": _optional_int(row.get("rank")),
        "remaining_hypotheses": _optional_int(row.get("remaining_hypotheses")),
        "valid_p_value_count": _optional_int(row.get("valid_p_value_count")),
        "missing_p_value_count": _optional_int(row.get("missing_p_value_count")),
        "raw_significant_count": _optional_int(row.get("raw_significant_count")),
        "corrected_significant_count": _optional_int(row.get("corrected_significant_count")),
        "raw_p_value": _optional_float(row.get("raw_p_value")),
        "adjusted_alpha": _optional_float(row.get("adjusted_alpha")),
        "adjusted_p_value": _optional_float(row.get("adjusted_p_value")),
        "passed": row.get("passed") if isinstance(row.get("passed"), bool) else None,
        "all_comparisons_corrected": row.get("all_comparisons_corrected") if isinstance(row.get("all_comparisons_corrected"), bool) else None,
        "all_comparisons_significant_after_correction": row.get("all_comparisons_significant_after_correction") if isinstance(row.get("all_comparisons_significant_after_correction"), bool) else None,
    }


def _missing_requirement_replay_signature(value: Any) -> list[dict[str, Any]]:
    rows = value if isinstance(value, list) else []
    signatures = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        signatures.append(
            {
                "kind": str(row.get("kind") or ""),
                "suite_id": str(row.get("suite_id") or ""),
                "category": str(row.get("category") or ""),
                "candidate_id": str(row.get("candidate_id") or "") if str(row.get("candidate_id") or "").startswith("axio-") else "",
                "claim": str(row.get("claim") or ""),
                "comparison_count": _optional_int(row.get("comparison_count")),
                "failed_comparison_count": _optional_int(row.get("failed_comparison_count")),
            }
        )
    return sorted(signatures, key=lambda item: stable_json(item))


def _artifact_run_set_digests(
    artifact: Mapping[str, Any],
    *,
    digest_key: str,
    receipt_key: str,
) -> tuple[str, str]:
    digest = str(artifact.get(digest_key) or "").strip().lower() if artifact else ""
    receipt = artifact.get(receipt_key) if isinstance(artifact.get(receipt_key), Mapping) else {}
    receipt_digest = str(receipt.get("run_set_digest_sha256") or "").strip().lower() if receipt else ""
    if not _looks_like_sha256(digest) and _looks_like_sha256(receipt_digest):
        digest = receipt_digest
    return digest, receipt_digest


def _final_methodology_summary(methodology: Mapping[str, Any]) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing = []
    suites = methodology.get("suites") if isinstance(methodology.get("suites"), list) else []
    controls = methodology.get("global_controls") if isinstance(methodology.get("global_controls"), Mapping) else {}
    by_suite = {
        str(row.get("suite_id") or ""): row
        for row in suites
        if isinstance(row, Mapping)
    }
    required_suite_ids = [suite.suite_id for suite in BENCHMARK_SUITES]
    missing_suite_ids = [suite_id for suite_id in required_suite_ids if suite_id not in by_suite]
    if not methodology:
        missing.append({"kind": "methodology_artifact_unavailable"})
    if methodology.get("schema") != "axio_fusion_api.benchmark_methodology_manifest.v1":
        missing.append({"kind": "methodology_schema_unrecognized"})
    if _optional_int(methodology.get("suite_count")) != len(BENCHMARK_SUITES):
        missing.append(
            {
                "kind": "methodology_suite_count_mismatch",
                "suite_count": _optional_int(methodology.get("suite_count")),
            }
        )
    if missing_suite_ids:
        missing.append({"kind": "methodology_missing_required_suites", "missing_suite_count": len(missing_suite_ids)})
    required_controls = (
        "fixed_dataset_snapshot_required",
        "train_eval_isolation_required",
        "same_cases_for_all_candidates",
        "same_prompt_template_per_suite_for_all_candidates",
        "temperature_zero_or_official_default",
        "paired_case_hashes_required_for_claims",
        "multiple_comparison_correction_required_for_claims",
        "familywise_error_rate_control_required",
        "practical_significance_required_for_claims",
        "provider_baselines_ranked_within_each_suite",
        "external_judge_position_balancing_required",
        "official_harness_identity_bound_to_source_manifest_required",
        "dataset_snapshot_bound_to_source_manifest_required",
        "evaluator_config_bound_to_source_manifest_required",
    )
    disabled_controls = [key for key in required_controls if controls.get(key) is not True]
    if disabled_controls:
        missing.append({"kind": "methodology_required_controls_disabled", "controls": disabled_controls})
    if controls.get("multiple_comparison_correction_method") != CLAIM_MULTIPLE_COMPARISON_METHOD:
        missing.append({"kind": "methodology_multiple_comparison_correction_method_unrecognized"})
    per_suite_issues = []
    for suite in BENCHMARK_SUITES:
        row = by_suite.get(suite.suite_id)
        if not isinstance(row, Mapping):
            continue
        row_issues = []
        if str(row.get("task_format") or "") != suite.task_format:
            row_issues.append("task_format_mismatch")
        for key in ("source_type", "source_url", "snapshot_policy", "prompt_protocol", "scoring_protocol", "leakage_policy"):
            if not row.get(key):
                row_issues.append(f"missing_{key}")
        if suite.task_format == "external_pairwise_judge" and row.get("external_import_required") is not True:
            row_issues.append("external_import_not_required")
        if suite.task_format in {"python_code", "tool_call_ast", "external_pairwise_judge"} and row.get("official_harness_required") is not True:
            row_issues.append("official_harness_not_required")
        if row_issues:
            per_suite_issues.append({"suite_id": suite.suite_id, "reason_codes": row_issues})
    if per_suite_issues:
        missing.append({"kind": "methodology_suite_contract_incomplete", "suite_issue_count": len(per_suite_issues)})
    return (
        {
            "suite_count": len(suites),
            "covered_required_suite_count": len(required_suite_ids) - len(missing_suite_ids),
            "required_control_count": len(required_controls),
            "disabled_required_controls": disabled_controls,
            "multiple_comparison_correction_method": str(controls.get("multiple_comparison_correction_method") or ""),
            "suite_issue_count": len(per_suite_issues),
            "suite_issues": per_suite_issues[:20],
            "raw_dataset_content_persisted": False,
            "raw_labels_persisted": False,
            "raw_provider_outputs_persisted": False,
        },
        missing,
    )


def _final_source_manifest_summary(
    *,
    source_manifest_path: str | Path | None,
    min_cases_per_suite: int,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    summary = _evidence_source_manifest_summary(
        source_manifest_path=source_manifest_path,
        min_cases_per_suite=min_cases_per_suite,
    )
    missing = []
    reason_counts = dict(summary.get("blocking_reason_counts") or {})
    if source_manifest_path is None:
        missing.append(
            {
                "kind": "source_manifest_artifact_unavailable",
                "reason": "missing_source_manifest_path",
            }
        )
        missing.append({"kind": "source_manifest_not_validated"})
    elif summary.get("available") is not True:
        missing.append(
            {
                "kind": "source_manifest_artifact_unavailable",
                "reason_counts": reason_counts,
            }
        )
        missing.append({"kind": "source_manifest_not_validated"})
    else:
        if summary.get("source_manifest_schema") != "axio_fusion_api.benchmark_source_manifest.v1":
            missing.append(
                {
                    "kind": "source_manifest_schema_unrecognized",
                    "source_manifest_schema": str(summary.get("source_manifest_schema") or ""),
                }
            )
        if summary.get("all_required_sources_ready") is not True:
            missing.append(
                {
                    "kind": "source_manifest_sources_not_ready",
                    "ready_suite_count": _optional_int(summary.get("ready_suite_count")) or 0,
                    "required_suite_count": _optional_int(summary.get("required_suite_count")) or len(BENCHMARK_SUITES),
                }
            )
        if any(str(reason).startswith("missing_") for reason in reason_counts):
            missing.append(
                {
                    "kind": "source_manifest_required_hashes_missing",
                    "reason_counts": {
                        str(reason): int(count)
                        for reason, count in reason_counts.items()
                        if str(reason).startswith("missing_")
                    },
                }
            )
    final_summary = {
        **summary,
        "validation_required_for_final_claims": True,
        "final_claim_eligible": not missing,
        "source_manifest_path_provided": source_manifest_path is not None,
        "raw_source_manifest_path_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_dataset_paths_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }
    return final_summary, missing


def _final_case_hash_manifest_summary(
    *,
    case_hash_manifest_path: str | Path | None,
    source_manifest_path: str | Path | None,
    min_cases_per_suite: int,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing = []
    if case_hash_manifest_path is None:
        return (
            {
                "available": False,
                "all_required_case_manifests_ready": False,
                "ready_suite_count": 0,
                "required_suite_count": len(BENCHMARK_SUITES),
                "source_digest_match": False,
                "blocking_reason_counts": {"missing_case_hash_manifest_path": 1},
                "raw_case_hash_manifest_path_persisted": False,
                "raw_case_hashes_persisted": False,
                "raw_dataset_content_persisted": False,
                "raw_provider_outputs_persisted": False,
                "secrets_persisted": False,
            },
            [
                {
                    "kind": "case_hash_manifest_artifact_unavailable",
                    "reason": "missing_case_hash_manifest_path",
                },
                {"kind": "case_hash_manifest_not_validated"},
            ],
        )
    receipt = _load_json_artifact(Path(case_hash_manifest_path))
    if not receipt["exists"] or not receipt["valid_json_object"]:
        reason = "case_hash_manifest_path_not_found" if not receipt["exists"] else "case_hash_manifest_invalid_json"
        return (
            {
                "available": False,
                "path_sha256": receipt["path_sha256"],
                "all_required_case_manifests_ready": False,
                "ready_suite_count": 0,
                "required_suite_count": len(BENCHMARK_SUITES),
                "source_digest_match": False,
                "blocking_reason_counts": {reason: 1},
                "raw_case_hash_manifest_path_persisted": False,
                "raw_case_hashes_persisted": False,
                "raw_dataset_content_persisted": False,
                "raw_provider_outputs_persisted": False,
                "secrets_persisted": False,
            },
            [
                {
                    "kind": "case_hash_manifest_artifact_unavailable",
                    "reason": reason,
                },
                {"kind": "case_hash_manifest_not_validated"},
            ],
        )
    payload = receipt["payload"]
    rows = payload.get("suite_rows") if isinstance(payload.get("suite_rows"), list) else []
    by_suite = {
        str(row.get("suite_id") or ""): row
        for row in rows
        if isinstance(row, Mapping)
    }
    required_suite_ids = [suite.suite_id for suite in BENCHMARK_SUITES]
    missing_suite_ids = [suite_id for suite_id in required_suite_ids if suite_id not in by_suite]
    not_ready_rows = [
        row for row in by_suite.values()
        if isinstance(row, Mapping) and row.get("ready") is not True
    ]
    too_small_rows = [
        row
        for row in by_suite.values()
        if isinstance(row, Mapping)
        and (_optional_int(row.get("case_hash_count")) or 0)
        < _effective_min_cases_for_suite(str(row.get("suite_id") or ""), min_cases_per_suite)
    ]
    reason_counts = dict(payload.get("blocking_reason_counts") or {})
    if receipt["schema"] != "axio_fusion_api.benchmark_case_hash_manifest.v1":
        missing.append(
            {
                "kind": "case_hash_manifest_schema_unrecognized",
                "schema": receipt["schema"],
            }
        )
    if missing_suite_ids:
        missing.append(
            {
                "kind": "case_hash_manifest_missing_required_suites",
                "missing_suite_count": len(missing_suite_ids),
            }
        )
    if payload.get("all_required_case_manifests_ready") is not True or not_ready_rows:
        missing.append(
            {
                "kind": "case_hash_manifest_not_ready",
                "not_ready_suite_count": len(not_ready_rows),
                "reason_counts": reason_counts,
            }
        )
    if too_small_rows:
        missing.append(
            {
                "kind": "case_hash_manifest_case_count_below_minimum",
                "suite_count": len(too_small_rows),
                "min_cases_per_suite": int(min_cases_per_suite),
            }
        )
    source_match = _case_hash_manifest_source_digest_match(
        case_hash_manifest=payload,
        source_manifest_path=source_manifest_path,
    )
    binding_summary = _case_hash_binding_receipt_summary(
        source_manifest_path=source_manifest_path,
        case_hash_manifest_path=case_hash_manifest_path,
    )
    if source_manifest_path is not None and source_match.get("all_digests_match") is not True:
        missing.append(
            {
                "kind": "source_manifest_case_hash_digest_mismatch",
                "mismatch_count": _optional_int(source_match.get("mismatch_count")) or 0,
                "missing_source_digest_count": _optional_int(source_match.get("missing_source_digest_count")) or 0,
            }
        )
    if binding_summary.get("binding_receipt_valid_for_current_inputs") is not True:
        missing.append(
            {
                "kind": "source_manifest_case_hash_binding_receipt_invalid",
                "reason_codes": list(binding_summary.get("reason_codes") or []),
            }
        )
    return (
        {
            "available": True,
            "schema": receipt["schema"],
            "path_sha256": receipt["path_sha256"],
            "required_suite_count": len(BENCHMARK_SUITES),
            "suite_count": _optional_int(payload.get("suite_count")) or len(rows),
            "ready_suite_count": _optional_int(payload.get("ready_suite_count")) or 0,
            "all_required_case_manifests_ready": bool(payload.get("all_required_case_manifests_ready")),
            "manifest_digest_sha256": str(payload.get("manifest_digest_sha256") or ""),
            "missing_suite_count": len(missing_suite_ids),
            "not_ready_suite_count": len(not_ready_rows),
            "case_count_below_minimum_suite_count": len(too_small_rows),
            "blocking_reason_counts": reason_counts,
            "source_digest_match": bool(source_match.get("all_digests_match")),
            "source_digest_match_summary": source_match,
            "binding_receipt_summary": binding_summary,
            "raw_case_hash_manifest_path_persisted": False,
            "raw_case_hashes_persisted": False,
            "raw_dataset_content_persisted": False,
            "raw_dataset_paths_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _case_hash_binding_receipt_summary(
    *,
    source_manifest_path: str | Path | None,
    case_hash_manifest_path: str | Path | None,
) -> dict[str, Any]:
    reasons = []
    if source_manifest_path is None:
        reasons.append("missing_source_manifest_path")
        source = {}
    else:
        try:
            source = json.loads(Path(source_manifest_path).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            source = {}
            reasons.append("source_manifest_unreadable")
    receipt = source.get("case_hash_binding_receipt") if isinstance(source, Mapping) and isinstance(source.get("case_hash_binding_receipt"), Mapping) else {}
    if not receipt:
        reasons.append("case_hash_binding_receipt_missing")
    elif receipt.get("schema") != "axio_fusion_api.source_manifest_case_hash_binding.v1":
        reasons.append("case_hash_binding_receipt_schema_unrecognized")
    if receipt and receipt.get("all_required_case_hashes_bound") is not True:
        reasons.append("case_hash_binding_receipt_not_complete")
    if receipt and (_optional_int(receipt.get("bound_suite_count")) or 0) != len(BENCHMARK_SUITES):
        reasons.append("case_hash_binding_receipt_bound_suite_count_mismatch")
    if receipt and _optional_int(receipt.get("not_ready_suite_count")) not in (0, None):
        reasons.append("case_hash_binding_receipt_not_ready_suites_present")
    blocking = receipt.get("blocking_reason_counts") if isinstance(receipt.get("blocking_reason_counts"), Mapping) else {}
    if blocking:
        reasons.append("case_hash_binding_receipt_blocking_reasons_present")
    case_hash_manifest_sha256 = ""
    if case_hash_manifest_path is None:
        reasons.append("missing_case_hash_manifest_path")
    else:
        try:
            case_hash_manifest_sha256 = sha256_text(Path(case_hash_manifest_path).read_text(encoding="utf-8"))
        except OSError:
            reasons.append("case_hash_manifest_unreadable")
    receipt_case_hash = str(receipt.get("case_hash_manifest_sha256") or "") if receipt else ""
    if case_hash_manifest_sha256 and receipt_case_hash != case_hash_manifest_sha256:
        reasons.append("case_hash_binding_receipt_case_manifest_hash_mismatch")
    return {
        "provided": bool(receipt),
        "schema": str(receipt.get("schema") or "") if receipt else "",
        "all_required_case_hashes_bound": receipt.get("all_required_case_hashes_bound") if receipt else None,
        "bound_suite_count": _optional_int(receipt.get("bound_suite_count")) if receipt else None,
        "not_ready_suite_count": _optional_int(receipt.get("not_ready_suite_count")) if receipt else None,
        "blocking_reason_count": len(blocking),
        "case_hash_manifest_sha256_matches_current": bool(case_hash_manifest_sha256 and receipt_case_hash == case_hash_manifest_sha256),
        "binding_receipt_valid_for_current_inputs": not reasons,
        "reason_codes": sorted(set(reasons)),
        "raw_source_manifest_path_persisted": False,
        "raw_case_hash_manifest_path_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _case_hash_manifest_source_digest_match(
    *,
    case_hash_manifest: Mapping[str, Any],
    source_manifest_path: str | Path | None,
) -> dict[str, Any]:
    if source_manifest_path is None:
        return {
            "checked": False,
            "all_digests_match": False,
            "reason": "missing_source_manifest_path",
            "raw_source_manifest_path_persisted": False,
            "raw_case_hashes_persisted": False,
        }
    try:
        source = json.loads(Path(source_manifest_path).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {
            "checked": False,
            "all_digests_match": False,
            "reason": "source_manifest_unreadable",
            "raw_source_manifest_path_persisted": False,
            "raw_case_hashes_persisted": False,
        }
    source_rows = source.get("suites") if isinstance(source, Mapping) and isinstance(source.get("suites"), list) else []
    source_by_suite = {
        str(row.get("suite_id") or ""): row
        for row in source_rows
        if isinstance(row, Mapping)
    }
    case_rows = case_hash_manifest.get("suite_rows") if isinstance(case_hash_manifest.get("suite_rows"), list) else []
    case_by_suite = {
        str(row.get("suite_id") or ""): row
        for row in case_rows
        if isinstance(row, Mapping)
    }
    rows = []
    for suite in BENCHMARK_SUITES:
        source_row = source_by_suite.get(suite.suite_id)
        case_row = case_by_suite.get(suite.suite_id)
        source_record = source_row.get("source_record") if isinstance(source_row, Mapping) and isinstance(source_row.get("source_record"), Mapping) else {}
        source_digest = str(source_record.get("materialized_case_hash_manifest_sha256") or "")
        case_digest = str(case_row.get("materialized_case_hash_manifest_sha256") or "") if isinstance(case_row, Mapping) else ""
        match = bool(source_digest and case_digest and source_digest == case_digest)
        rows.append(
            {
                "suite_id": suite.suite_id,
                "source_digest_present": _looks_like_sha256(source_digest),
                "case_digest_present": _looks_like_sha256(case_digest),
                "digests_match": match,
            }
        )
    mismatch_count = sum(1 for row in rows if row["digests_match"] is not True)
    missing_source_digest_count = sum(1 for row in rows if row["source_digest_present"] is not True)
    missing_case_digest_count = sum(1 for row in rows if row["case_digest_present"] is not True)
    return {
        "checked": True,
        "all_digests_match": mismatch_count == 0,
        "suite_count": len(rows),
        "mismatch_count": mismatch_count,
        "missing_source_digest_count": missing_source_digest_count,
        "missing_case_digest_count": missing_case_digest_count,
        "suite_rows": rows[:24],
        "raw_source_manifest_path_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _is_live_or_imported_run(mode: str, task_format: str) -> bool:
    normalized = str(mode or "").strip().lower()
    if normalized == "live":
        return True
    if str(task_format or "") in OFFICIAL_HARNESS_REQUIRED_FORMATS and normalized in IMPORTED_RUN_MODES:
        return True
    return False


def _final_training_contamination_summary(audit: Mapping[str, Any]) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    missing = []
    findings = audit.get("findings") if isinstance(audit.get("findings"), list) else []
    blocker_count = _optional_int(audit.get("blocker_count"))
    warning_count = _optional_int(audit.get("warning_count"))
    final_clean = audit.get("final_claim_training_clean")
    if not audit:
        missing.append({"kind": "training_contamination_audit_artifact_unavailable"})
    elif str(audit.get("schema") or "") != "axio_fusion_api.training_contamination_audit.v1":
        missing.append({"kind": "training_contamination_audit_schema_unrecognized"})
    if audit and final_clean is not True:
        missing.append({"kind": "training_contamination_not_clean", "final_claim_training_clean": final_clean})
    if audit and (blocker_count is None or blocker_count != 0):
        missing.append({"kind": "training_contamination_blockers_present", "blocker_count": blocker_count})
    if audit and warning_count is None:
        missing.append({"kind": "training_contamination_warning_count_missing"})
    if audit and _contains_forbidden_persistence_flag(audit):
        missing.append({"kind": "training_contamination_audit_forbidden_persistence_flag_detected"})
    finding_kinds: dict[str, int] = {}
    for finding in findings:
        if not isinstance(finding, Mapping):
            continue
        kind = str(finding.get("kind") or "unknown")
        finding_kinds[kind] = finding_kinds.get(kind, 0) + 1
    return (
        {
            "schema": str(audit.get("schema") or ""),
            "final_claim_training_clean": final_clean,
            "final_claim_eligible_after_training_audit": audit.get("final_claim_eligible_after_training_audit"),
            "blocker_count": blocker_count,
            "warning_count": warning_count,
            "finding_count": len(findings),
            "finding_kinds": dict(sorted(finding_kinds.items())),
            "raw_benchmark_content_persisted": False,
            "raw_training_prompts_persisted": False,
            "raw_provider_outputs_persisted": False,
        },
        missing,
    )


def _contains_forbidden_persistence_flag(value: Any) -> bool:
    if isinstance(value, Mapping):
        for key, raw in value.items():
            key_text = str(key)
            if key_text.endswith("_persisted") and _truthy_flag(raw):
                return True
            if key_text == "benchmark_labels_used_for_training" and _truthy_flag(raw):
                return True
            if _contains_forbidden_persistence_flag(raw):
                return True
    elif isinstance(value, list):
        return any(_contains_forbidden_persistence_flag(item) for item in value)
    return False


def _final_run_anti_leakage_receipt(run: Mapping[str, Any]) -> dict[str, Any]:
    case_results = run.get("case_results") if isinstance(run.get("case_results"), list) else []
    run_without_cases = {
        str(key): value
        for key, value in run.items()
        if str(key) != "case_results"
    }
    top_level_reason_counts = _anti_leakage_reason_counts(run_without_cases)
    case_result_reason_counts: dict[str, int] = {}
    case_result_issue_count = 0
    anti_leakage_contract = (
        run.get("anti_leakage_contract")
        if isinstance(run.get("anti_leakage_contract"), Mapping)
        else {}
    )
    prompt_contract_required = anti_leakage_contract.get("prompt_contract_required_for_final_claim") is True
    prompt_contract_issue_count = 0
    for row in case_results:
        if not isinstance(row, Mapping):
            case_result_issue_count += 1
            _increment_count(case_result_reason_counts, "case_result_not_object")
            continue
        row_reason_counts = _anti_leakage_reason_counts(row)
        if prompt_contract_required and not _benchmark_prompt_contract_is_clean(row.get("prompt_contract")):
            prompt_contract_issue_count += 1
            _increment_count(row_reason_counts, "prompt_contract_missing_or_failed")
        if row_reason_counts:
            case_result_issue_count += 1
            _merge_counts(case_result_reason_counts, row_reason_counts)
    reason_counts: dict[str, int] = {}
    _merge_counts(reason_counts, top_level_reason_counts)
    _merge_counts(reason_counts, case_result_reason_counts)
    if case_result_issue_count:
        reason_counts["case_result_level_anti_leakage_failed"] = case_result_issue_count
    reason_counts = dict(sorted(reason_counts.items()))
    return {
        "schema": "axio_fusion_api.run_anti_leakage_receipt.v1",
        "suite_id_hash": sha256_text(str(run.get("suite_id") or "")),
        "candidate_id_hash": sha256_text(str(run.get("candidate_id") or "")),
        "case_result_count": len(case_results),
        "case_result_issue_count": case_result_issue_count,
        "prompt_contract_required_for_final_claim": prompt_contract_required,
        "prompt_contract_case_count": len(case_results) if prompt_contract_required else 0,
        "prompt_contract_issue_count": prompt_contract_issue_count,
        "top_level_reason_counts": dict(sorted(top_level_reason_counts.items())),
        "case_result_reason_counts": dict(sorted(case_result_reason_counts.items())),
        "reason_counts": reason_counts,
        "reason_codes": sorted(reason_counts),
        "clean": not reason_counts,
        "raw_candidate_id_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _anti_leakage_reason_counts(value: Any) -> dict[str, int]:
    counts: dict[str, int] = {}
    _collect_anti_leakage_reason_counts(value, counts)
    return dict(sorted(counts.items()))


def _collect_anti_leakage_reason_counts(value: Any, counts: dict[str, int]) -> None:
    if isinstance(value, Mapping):
        for key, raw in value.items():
            key_text = str(key)
            lowered = key_text.lower()
            if key_text == "benchmark_labels_used_for_training" and _truthy_flag(raw):
                _increment_count(counts, "benchmark_labels_used_for_training")
                _increment_count(counts, "training_eval_isolation_failed")
            if key_text.endswith("_persisted") and _truthy_flag(raw):
                _increment_count(counts, "forbidden_persistence_flag_true")
                if lowered.startswith("raw_"):
                    _increment_count(counts, "raw_persistence_flag_true")
                if any(token in lowered for token in ("prompt", "question", "input", "option")):
                    _increment_count(counts, "raw_prompt_or_question_persisted")
                if any(token in lowered for token in ("label", "answer", "reference")):
                    _increment_count(counts, "raw_label_or_reference_persisted")
                if "output" in lowered or "provider_response" in lowered:
                    _increment_count(counts, "raw_provider_output_persisted")
                if any(token in lowered for token in ("secret", "api_key", "apikey", "provider_url", "endpoint")):
                    _increment_count(counts, "secret_or_provider_endpoint_persisted")
                if any(token in lowered for token in ("dataset", "source_content")):
                    _increment_count(counts, "raw_dataset_content_or_path_persisted")
            _collect_anti_leakage_reason_counts(raw, counts)
    elif isinstance(value, list):
        for item in value:
            _collect_anti_leakage_reason_counts(item, counts)


def _anti_leakage_receipt_reason_counts(receipts: Sequence[Mapping[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for receipt in receipts:
        reason_counts = receipt.get("reason_counts") if isinstance(receipt.get("reason_counts"), Mapping) else {}
        _merge_counts(counts, reason_counts)
    return dict(sorted(counts.items()))


def _increment_count(counts: dict[str, int], key: str, amount: int = 1) -> None:
    if not key:
        return
    counts[key] = counts.get(key, 0) + int(amount)


def _merge_counts(target: dict[str, int], source: Mapping[str, Any]) -> None:
    for key, raw in source.items():
        amount = _optional_int(raw)
        if amount is None:
            continue
        _increment_count(target, str(key), amount)


def _provider_candidate_alias_artifact_audit(
    artifacts: Mapping[str, Mapping[str, Any]],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    rows = []
    missing = []
    total_raw_hint_count = 0
    for name, receipt in artifacts.items():
        if not isinstance(receipt, Mapping) or receipt.get("valid_json_object") is not True:
            continue
        findings: list[dict[str, Any]] = []
        count = _collect_raw_provider_candidate_id_findings(
            receipt.get("payload"),
            path="$",
            findings=findings,
            limit=12,
        )
        total_raw_hint_count += count
        rows.append(
            {
                "artifact": str(name),
                "raw_provider_candidate_id_count": count,
                "finding_preview": findings,
                "raw_provider_candidate_ids_persisted": False,
                "raw_provider_model_ids_persisted": False,
            }
        )
        if count:
            missing.append(
                {
                    "kind": "raw_provider_candidate_id_detected",
                    "artifact": str(name),
                    "finding_count": count,
                }
            )
    return (
        {
            "schema": "axio_fusion_api.provider_candidate_alias_audit.v1",
            "provider_candidate_hash_alias_required": True,
            "checked_artifact_count": len(rows),
            "artifact_with_raw_provider_candidate_id_count": sum(1 for row in rows if row["raw_provider_candidate_id_count"]),
            "raw_provider_candidate_id_count": total_raw_hint_count,
            "all_provider_candidate_ids_are_hash_aliases_or_public_synthetic_ids": total_raw_hint_count == 0,
            "artifact_rows": rows,
            "raw_provider_candidate_ids_persisted": False,
            "raw_provider_model_ids_persisted": False,
            "raw_provider_outputs_persisted": False,
            "secrets_persisted": False,
        },
        missing,
    )


def _collect_raw_provider_candidate_id_findings(
    value: Any,
    *,
    path: str,
    findings: list[dict[str, Any]],
    limit: int,
) -> int:
    count = 0
    if isinstance(value, Mapping):
        for key, raw in value.items():
            key_text = str(key)
            key_path = f"{path}{_safe_scan_key_segment(key_text)}"
            if _provider_candidate_has_raw_model_hint(key_text):
                count += 1
                _append_raw_provider_candidate_finding(
                    findings,
                    value=key_text,
                    path=key_path,
                    location="object_key",
                    limit=limit,
                )
            count += _collect_raw_provider_candidate_id_findings(
                raw,
                path=key_path,
                findings=findings,
                limit=limit,
            )
    elif isinstance(value, list):
        for index, item in enumerate(value):
            count += _collect_raw_provider_candidate_id_findings(
                item,
                path=f"{path}[{index}]",
                findings=findings,
                limit=limit,
            )
    elif isinstance(value, str) and _provider_candidate_has_raw_model_hint(value):
        count += 1
        _append_raw_provider_candidate_finding(
            findings,
            value=value,
            path=path,
            location="string_value",
            limit=limit,
        )
    return count


def _append_raw_provider_candidate_finding(
    findings: list[dict[str, Any]],
    *,
    value: str,
    path: str,
    location: str,
    limit: int,
) -> None:
    if len(findings) >= max(0, int(limit)):
        return
    text = str(value or "")
    suffix = text[len("provider::") :] if text.startswith("provider::") else text
    findings.append(
        {
            "path": path,
            "location": location,
            "value_sha256": sha256_text(text),
            "provider_suffix_sha256": sha256_text(suffix),
            "reason": "provider_candidate_id_suffix_contains_raw_model_separator",
            "raw_value_persisted": False,
        }
    )


def _safe_scan_key_segment(key: str) -> str:
    text = str(key or "")
    if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,64}", text):
        return f".{text}"
    return f".key_sha256_{sha256_text(text)[:12]}"


def _truthy_flag(value: Any) -> bool:
    if value is True:
        return True
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes"}
    return False


def write_json(path: str | Path, payload: Mapping[str, Any]) -> Path:
    output = Path(path)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    return output


def _load_official_import_batch(path: str | Path) -> dict[str, Any] | list[Any]:
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    if isinstance(payload, (dict, list)):
        return payload
    raise ValueError("official import batch must be a JSON object or list")


def _official_import_batch_entries(batch: Mapping[str, Any] | list[Any]) -> list[dict[str, Any]]:
    if isinstance(batch, list):
        return [dict(row) for row in batch if isinstance(row, Mapping)]
    for key in ("imports", "runs", "items", "entries"):
        rows = batch.get(key)
        if isinstance(rows, list):
            return [dict(row) for row in rows if isinstance(row, Mapping)]
    return []


def _official_import_batch_defaults(
    batch: Mapping[str, Any] | list[Any],
    *,
    default_harness_name: str,
    default_harness_version: str,
    default_dataset_snapshot: str,
    default_evaluator_config: str,
    default_prompt_protocol: str,
    default_decoding_config: str,
) -> dict[str, Any]:
    manifest_defaults = batch.get("defaults") if isinstance(batch, Mapping) and isinstance(batch.get("defaults"), Mapping) else {}
    return {
        "harness_name": str(manifest_defaults.get("harness_name") or default_harness_name or ""),
        "harness_version": str(manifest_defaults.get("harness_version") or default_harness_version or ""),
        "dataset_snapshot": str(manifest_defaults.get("dataset_snapshot") or default_dataset_snapshot or ""),
        "evaluator_config": str(manifest_defaults.get("evaluator_config") or default_evaluator_config or ""),
        "prompt_protocol": str(
            manifest_defaults.get("prompt_protocol")
            or manifest_defaults.get("prompt_protocol_sha256")
            or default_prompt_protocol
            or ""
        ),
        "decoding_config": str(
            manifest_defaults.get("decoding_config")
            or manifest_defaults.get("decoding_config_sha256")
            or default_decoding_config
            or ""
        ),
        "position_balanced": _batch_bool(manifest_defaults.get("position_balanced")),
    }


def _import_official_batch_entry(
    entry: Mapping[str, Any],
    *,
    index: int,
    output_root: Path,
    defaults: Mapping[str, Any],
) -> dict[str, Any]:
    suite_id = str(entry.get("suite_id") or "").strip()
    candidate_id = str(entry.get("candidate_id") or "").strip()
    source_path = str(entry.get("source") or entry.get("source_path") or "").strip()
    task_format = str(entry.get("task_format") or "auto").strip() or "auto"
    api_format = str(entry.get("api_format") or "").strip()
    harness_name = str(entry.get("harness_name") or defaults.get("harness_name") or "").strip()
    harness_version = str(entry.get("harness_version") or defaults.get("harness_version") or "").strip()
    dataset_snapshot = str(entry.get("dataset_snapshot") or defaults.get("dataset_snapshot") or "").strip()
    evaluator_config = str(entry.get("evaluator_config") or defaults.get("evaluator_config") or "").strip()
    prompt_protocol = str(
        entry.get("prompt_protocol")
        or entry.get("prompt_protocol_sha256")
        or defaults.get("prompt_protocol")
        or ""
    ).strip()
    decoding_config = str(
        entry.get("decoding_config")
        or entry.get("decoding_config_sha256")
        or defaults.get("decoding_config")
        or ""
    ).strip()
    position_balanced = _batch_bool(entry.get("position_balanced"))
    if position_balanced is None:
        position_balanced = bool(defaults.get("position_balanced"))
    missing = [
        field
        for field, value in (
            ("suite_id", suite_id),
            ("candidate_id", candidate_id),
            ("source", source_path),
            ("harness_name", harness_name),
            ("harness_version", harness_version),
            ("dataset_snapshot", dataset_snapshot),
            ("evaluator_config", evaluator_config),
        )
        if not value
    ]
    safe_candidate_id = _canonical_safe_candidate_id(candidate_id) if candidate_id else ""
    candidate_hash = sha256_text(safe_candidate_id) if safe_candidate_id else ""
    base_receipt = {
        "entry_index": int(index),
        "suite_id": suite_id,
        "task_format": task_format,
        "api_format": api_format,
        "candidate_id_hash": candidate_hash if candidate_id else "",
        "candidate_id_policy": _candidate_id_alias_policy(candidate_id, safe_candidate_id) if candidate_id else {},
        "source_path_sha256": sha256_text(source_path) if source_path else "",
        "position_balanced": bool(position_balanced),
        "raw_candidate_id_persisted": False,
        "raw_provider_model_id_persisted": False,
        "raw_source_path_persisted": False,
        "raw_source_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }
    if missing:
        return {
            **base_receipt,
            "status": "failed",
            "reason_codes": [f"missing_{field}" for field in missing],
            "output_path_sha256": "",
            "error_type": "validation_error",
        }
    try:
        run = import_official_benchmark_run(
            suite_id=suite_id,
            candidate_id=candidate_id,
            source_path=source_path,
            task_format=task_format,
            harness_name=harness_name,
            harness_version=harness_version,
            dataset_snapshot=dataset_snapshot,
            evaluator_config=evaluator_config,
            position_balanced=bool(position_balanced),
            prompt_protocol=prompt_protocol,
            decoding_config=decoding_config,
            api_format=api_format,
        )
        run_surface_id = str(run.get("api_surface_id") or safe_candidate_id)
        output_path = output_root / _safe_filename(suite_id) / f"{sha256_text(run_surface_id)[:16]}.safe.json"
        write_json(output_path, run)
        receipt = run.get("harness_receipt") if isinstance(run.get("harness_receipt"), Mapping) else {}
        return {
            **base_receipt,
            "status": "imported",
            "reason_codes": [],
            "output_path_sha256": sha256_text(str(output_path)),
            "case_count": _optional_int(run.get("case_count")) or 0,
            "attempted_count": _optional_int(run.get("attempted_count")) or 0,
            "accuracy": run.get("accuracy"),
            "mean_score": run.get("mean_score"),
            "harness_receipt_valid": not _harness_receipt_reasons(
                receipt,
                suite_id=suite_id,
                task_format=str(run.get("task_format") or task_format),
            ),
            "raw_output_path_persisted": False,
        }
    except Exception as exc:  # noqa: BLE001 - summary must never persist raw exception text.
        return {
            **base_receipt,
            "status": "failed",
            "reason_codes": ["import_failed"],
            "output_path_sha256": "",
            "error_type": type(exc).__name__,
            "raw_error_message_persisted": False,
        }


def _official_import_batch_summary_by_suite(receipts: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    by_suite: dict[str, dict[str, Any]] = {}
    for receipt in receipts:
        suite_id = str(receipt.get("suite_id") or "unknown")
        row = by_suite.setdefault(
            suite_id,
            {
                "suite_id": suite_id,
                "entry_count": 0,
                "imported_count": 0,
                "failed_count": 0,
                "position_balanced_import_count": 0,
                "candidate_hashes": [],
            },
        )
        row["entry_count"] += 1
        if receipt.get("status") == "imported":
            row["imported_count"] += 1
        else:
            row["failed_count"] += 1
        if receipt.get("position_balanced") is True and receipt.get("status") == "imported":
            row["position_balanced_import_count"] += 1
        candidate_hash = str(receipt.get("candidate_id_hash") or "")
        if candidate_hash and candidate_hash not in row["candidate_hashes"]:
            row["candidate_hashes"].append(candidate_hash)
    return [
        {
            **row,
            "candidate_hash_count": len(row["candidate_hashes"]),
            "candidate_hashes": row["candidate_hashes"][:24],
            "raw_candidate_ids_persisted": False,
        }
        for row in sorted(by_suite.values(), key=lambda item: str(item["suite_id"]))
    ]


def _batch_bool(value: Any) -> bool | None:
    if isinstance(value, bool):
        return value
    if value in (None, ""):
        return None
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "y", "position_balanced"}:
        return True
    if text in {"0", "false", "no", "n"}:
        return False
    return None


def _template_suite_spec(template: Mapping[str, Any], suite_id: str) -> Mapping[str, Any]:
    for row in template.get("suites", []) if isinstance(template.get("suites"), list) else []:
        if isinstance(row, Mapping) and str(row.get("suite_id") or "") == suite_id:
            return row
    return {}


def _acquisition_candidate_receipt(candidate: Mapping[str, Any], *, index: int) -> dict[str, Any]:
    candidate_id = str(candidate.get("candidate_id") or "")
    run_unit_id = str(candidate.get("run_unit_id") or candidate_id)
    api_format = str(candidate.get("api_format") or ("provider_native" if str(candidate_id).startswith("provider::") else "internal"))
    api_surface_id = str(candidate.get("api_surface_id") or run_unit_id)
    candidate_type = str(candidate.get("candidate_type") or "unknown")
    algorithm = str(candidate.get("algorithm") or "")
    candidate_hash = sha256_text(candidate_id)
    run_unit_hash = sha256_text(run_unit_id)
    is_provider = candidate_type == "provider" or candidate_id.startswith("provider::")
    is_axio = candidate_id.startswith("axio-")
    return {
        "candidate_index": int(index),
        "candidate_id_hash": candidate_hash,
        "run_unit_id_hash": run_unit_hash,
        "candidate_placeholder": f"<RUN_UNIT_{index + 1:03d}_{run_unit_hash[:12]}>",
        "candidate_type": candidate_type,
        "algorithm": algorithm,
        "public_axio_model": candidate_id if is_axio else "",
        "api_format": api_format,
        "api_surface_id_hash": sha256_text(api_surface_id),
        "api_surface_role": str(candidate.get("api_surface_role") or ""),
        "api_surface_is_primary_claim": candidate.get("api_surface_is_primary_claim") is True,
        "baseline_algorithm": algorithm if candidate_type == "baseline" else "",
        "provider_profile_hash": str(candidate.get("provider_profile_hash") or sha256_text(candidate_id)) if is_provider else "",
        "raw_candidate_id_persisted": False,
        "raw_run_unit_id_persisted": False,
        "raw_provider_model_id_persisted": False,
        "raw_provider_url_persisted": False,
        "secrets_persisted": False,
    }


def _acquisition_candidate_counts(receipts: Sequence[Mapping[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for receipt in receipts:
        candidate_type = str(receipt.get("candidate_type") or "unknown")
        counts[candidate_type] = counts.get(candidate_type, 0) + 1
    return dict(sorted(counts.items()))


def _benchmark_download_statuses(download_manifest_path: str | Path | None) -> dict[str, dict[str, Any]]:
    if not download_manifest_path:
        return {}
    path = Path(download_manifest_path)
    if not path.exists():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    rows = payload.get("suites") if isinstance(payload, Mapping) and isinstance(payload.get("suites"), list) else []
    return {
        str(row.get("suite_id") or ""): {
            "status": str(row.get("status") or ""),
            "status_sha256": sha256_text(str(row.get("status") or "")),
            "_manifest_row": dict(row),
        }
        for row in rows
        if isinstance(row, Mapping) and str(row.get("suite_id") or "")
    }


def _materialization_adapter_id(suite_id: str) -> str:
    return {
        "gpqa_diamond": "gpqa_diamond_csv_fixed_per_case_option_order_v1",
        "mmmu_text_science": "mmmu_science_text_validation_v1",
        "global_mmlu_lite": "global_mmlu_multilingual_test_v1",
        "flores_translation_instruction": "flores200_devtest_fixed_10_directions_v1",
        "math_500": "math_500_test_exact_v1",
        "aime_recent": "aime_2024_exact_v1",
        "bbh": "bbh_official_json_exact_v1",
        "arc_challenge": "arc_challenge_parquet_mcq_v1",
        "truthfulqa": "truthfulqa_mc1_v1",
        "halueval": "halueval_qa_factual_choice_v1",
        "medqa_usmle": "medqa_us_test_mcq_v1",
        "financebench": "financebench_open_source_oracle_context_v1",
        "legalbench": "legalbench_tsv_exact_v1",
        "bizbench": "bizbench_test_exact_v1",
        "policyllm_policybench": "policyllm_multilevel_mcq_v1",
    }.get(suite_id, "")


def _materialization_status_row(
    suite: BenchmarkSuite,
    *,
    raw_root: Path,
    output_dir: Path,
    download_status: Mapping[str, Mapping[str, Any]],
    min_cases_per_suite: int,
) -> dict[str, Any]:
    adapter_id = _materialization_adapter_id(suite.suite_id)
    effective_min_cases = _effective_min_cases_for_suite(suite.suite_id, min_cases_per_suite)
    output_path = output_dir / f"{suite.suite_id}.jsonl"
    output_count = _safe_count_jsonl_rows(output_path) if output_path.exists() else 0
    validation = {}
    if output_path.exists():
        validation = validate_benchmark_dataset(
            suite_id=suite.suite_id,
            dataset_path=output_path,
            task_format=suite.task_format,
        )
    reasons = []
    status = "ready" if output_count >= effective_min_cases and validation.get("ready_for_scoring") is True else "materialization_required"
    download = download_status.get(suite.suite_id, {})
    gpqa_integrity: dict[str, Any] = {}
    if suite.suite_id == "gpqa_diamond" and str(download.get("status") or "") == "downloaded":
        gpqa_integrity = audit_gpqa_authorized_artifact(
            artifact_path=raw_root / "gpqa/gpqa_diamond.csv",
            manifest_row=(
                download.get("_manifest_row")
                if isinstance(download.get("_manifest_row"), Mapping)
                else {}
            ),
        )
    if str(download.get("status") or "").startswith("blocked"):
        status = "blocked_gated"
        reasons.append("source_blocked_gated")
    elif suite.suite_id == "gpqa_diamond" and str(download.get("status") or "") != "downloaded":
        # GPQA's upstream terms require an explicit operator acceptance.  Do
        # not infer authorization merely from the presence of a local CSV.
        status = "blocked_gated"
        reasons.append("gpqa_authorized_download_status_required")
    elif suite.suite_id == "gpqa_diamond" and gpqa_integrity.get("valid") is not True:
        status = "blocked_gated"
        reasons.append("gpqa_authorized_artifact_integrity_required")
        reasons.extend(
            f"gpqa_integrity_{reason}"
            for reason in gpqa_integrity.get("reason_codes", [])
            if str(reason)
        )
    elif _suite_requires_official_harness(suite.suite_id, suite.task_format):
        status = "blocked_official_or_audited_harness_required"
        reasons.append("official_or_audited_harness_required")
    elif not adapter_id:
        status = "blocked_materialization_adapter_not_implemented"
        reasons.append("materialization_adapter_not_implemented")
    elif not _materialization_raw_sources_available(suite.suite_id, raw_root):
        status = "blocked_raw_source_missing"
        reasons.append("raw_source_missing")
    elif not output_path.exists():
        reasons.append("standardized_dataset_missing")
    elif validation and validation.get("ready_for_scoring") is not True:
        reasons.append("standardized_dataset_invalid")
    elif output_count < effective_min_cases:
        reasons.append("insufficient_materialized_cases")
    ready = status == "ready" and not reasons
    return {
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": suite.task_format,
        "adapter_id": adapter_id,
        "status": "ready" if ready else status,
        "ready": ready,
        "reason_codes": sorted(set(reasons)),
        "download_status": str(download.get("status") or "unknown"),
        "gpqa_artifact_integrity": (
            gpqa_integrity
            if suite.suite_id == "gpqa_diamond"
            else {}
        ),
        "standardized_dataset_exists": output_path.exists(),
        "standardized_dataset_path_sha256": sha256_text(str(output_path)),
        "standardized_dataset_relative_path": f"{suite.suite_id}.jsonl",
        "materialized_case_count": output_count,
        "min_cases_per_suite": int(min_cases_per_suite),
        "effective_min_cases": effective_min_cases,
        "suite_min_case_policy": _suite_min_case_policy(suite.suite_id, min_cases_per_suite),
        "validation": _safe_materialization_validation_summary(validation),
        "requires_official_harness": _suite_requires_official_harness(suite.suite_id, suite.task_format),
        "raw_dataset_paths_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_labels_persisted": False,
        "secrets_persisted": False,
    }


def _materialize_one_benchmark_suite(
    suite: BenchmarkSuite,
    *,
    raw_root: Path,
    output_dir: Path,
    download_status: Mapping[str, Mapping[str, Any]],
    limit_per_suite: int | None,
    min_cases_per_suite: int,
    overwrite: bool,
) -> dict[str, Any]:
    preflight = _materialization_status_row(
        suite,
        raw_root=raw_root,
        output_dir=output_dir,
        download_status=download_status,
        min_cases_per_suite=min_cases_per_suite,
    )
    if preflight["ready"] is True and not overwrite:
        row = dict(preflight)
        row["status"] = "already_materialized"
        return row
    if str(preflight.get("status") or "").startswith("blocked"):
        return preflight
    adapter_id = str(preflight.get("adapter_id") or "")
    if not adapter_id:
        return preflight
    output_path = output_dir / f"{suite.suite_id}.jsonl"
    try:
        cases = _materialized_cases_for_suite(
            suite.suite_id,
            raw_root=raw_root,
            limit=limit_per_suite,
        )
        output_path.parent.mkdir(parents=True, exist_ok=True)
        with output_path.open("w", encoding="utf-8") as handle:
            for case in cases:
                handle.write(json.dumps(case, ensure_ascii=False, sort_keys=True) + "\n")
    except Exception as exc:  # noqa: PERF203 - data adapter boundary
        row = dict(preflight)
        row.update(
            {
                "status": "failed",
                "ready": False,
                "reason_codes": sorted(set([*list(row.get("reason_codes") or []), type(exc).__name__])),
                "error_type": type(exc).__name__,
                "raw_dataset_paths_persisted": False,
                "raw_dataset_content_persisted": False,
                "raw_labels_persisted": False,
            }
        )
        return row
    post = _materialization_status_row(
        suite,
        raw_root=raw_root,
        output_dir=output_dir,
        download_status=download_status,
        min_cases_per_suite=min_cases_per_suite,
    )
    post["status"] = "materialized" if post["ready"] is True else "materialized_but_not_ready"
    return post


def _safe_materialization_validation_summary(validation: Mapping[str, Any]) -> dict[str, Any]:
    if not validation:
        return {
            "available": False,
            "raw_dataset_path_persisted": False,
            "raw_dataset_content_persisted": False,
        }
    return {
        "available": True,
        "ready_for_scoring": bool(validation.get("ready_for_scoring")),
        "row_count": _optional_int(validation.get("row_count")) or 0,
        "valid_case_count": _optional_int(validation.get("valid_case_count")) or 0,
        "invalid_case_count": _optional_int(validation.get("invalid_case_count")) or 0,
        "duplicate_case_hash_count": _optional_int(validation.get("duplicate_case_hash_count")) or 0,
        "label_leakage_suspected_count": _optional_int(validation.get("label_leakage_suspected_count")) or 0,
        "invalid_reason_counts": dict(validation.get("invalid_reason_counts") or {}),
        "raw_dataset_path_persisted": False,
        "raw_dataset_content_persisted": False,
    }


def _materialization_raw_sources_available(suite_id: str, raw_root: Path) -> bool:
    checks = {
        "gpqa_diamond": lambda: (raw_root / "gpqa/gpqa_diamond.csv").exists(),
        "mmmu_text_science": lambda: any((raw_root / "mmmu_science").glob("*/validation-*.parquet")),
        "global_mmlu_lite": lambda: any((raw_root / "global_mmlu").glob("*/test.parquet")),
        "flores_translation_instruction": lambda: all(
            (
                raw_root
                / "flores200_official"
                / "flores200_dataset"
                / "devtest"
                / f"{language_code}.devtest"
            ).exists()
            for language_code in FLORES_LANGUAGE_NAMES
        ),
        "math_500": lambda: (raw_root / "math_500/test.jsonl").exists(),
        "aime_recent": lambda: (raw_root / "aime_recent/aime_2024_problems.parquet").exists(),
        "bbh": lambda: any((raw_root / "BIG-Bench-Hard/bbh").glob("*.json")),
        "arc_challenge": lambda: (raw_root / "arc_hf/arc_challenge_test.parquet").exists()
        or (raw_root / "arc_hf/arc_challenge_validation.parquet").exists(),
        "truthfulqa": lambda: (raw_root / "truthfulqa/data/mc_task.json").exists(),
        "halueval": lambda: (raw_root / "HaluEval/data/qa_data.json").exists(),
        "medqa_usmle": lambda: (raw_root / "medqa_official_drive/extracted/data_clean/questions/US/test.jsonl").exists(),
        "financebench": lambda: (raw_root / "financebench/data/financebench_open_source.jsonl").exists(),
        "legalbench": lambda: any((raw_root / "legalbench/tasks").glob("*/test.tsv"))
        or any((raw_root / "legalbench/tasks").glob("*/train.tsv")),
        "bizbench": lambda: any((raw_root / "bizbench/data").glob("test-*.parquet")),
        "policyllm_policybench": lambda: any((raw_root / "policyllm").glob("level_*_with_id.json")),
    }
    check = checks.get(suite_id)
    return bool(check and check())


def _materialized_cases_for_suite(
    suite_id: str,
    *,
    raw_root: Path,
    limit: int | None,
) -> list[dict[str, Any]]:
    adapters = {
        "gpqa_diamond": _materialize_gpqa_diamond,
        "mmmu_text_science": _materialize_mmmu_science,
        "global_mmlu_lite": _materialize_global_mmlu,
        "flores_translation_instruction": _materialize_flores_translation,
        "math_500": _materialize_math_500,
        "aime_recent": _materialize_aime_recent,
        "bbh": _materialize_bbh,
        "arc_challenge": _materialize_arc_challenge,
        "truthfulqa": _materialize_truthfulqa,
        "halueval": _materialize_halueval,
        "medqa_usmle": _materialize_medqa_usmle,
        "financebench": _materialize_financebench,
        "legalbench": _materialize_legalbench,
        "bizbench": _materialize_bizbench,
        "policyllm_policybench": _materialize_policyllm,
    }
    adapter = adapters.get(suite_id)
    if adapter is None:
        return []
    rows = adapter(raw_root)
    bounded = list(rows if limit is None else rows[: max(0, int(limit))])
    return [_with_materialized_case_id(row, suite_id=suite_id, index=index) for index, row in enumerate(bounded)]


def _with_materialized_case_id(row: Mapping[str, Any], *, suite_id: str, index: int) -> dict[str, Any]:
    result = dict(row)
    if "id" not in result or not str(result.get("id") or ""):
        identity = {
            "suite_id": suite_id,
            "index": index,
            "prompt": result.get("prompt") or result.get("question") or result.get("input") or result.get("source") or "",
            "answer": result.get("answer") or result.get("target") or result.get("reference") or "",
        }
        result["id"] = sha256_text(stable_json(identity))[:32]
    result["source_suite_id"] = suite_id
    return result


def _materialize_flores_translation(raw_root: Path) -> list[dict[str, Any]]:
    devtest_dir = raw_root / "flores200_official" / "flores200_dataset" / "devtest"
    language_lines = {
        language_code: (devtest_dir / f"{language_code}.devtest").read_text(encoding="utf-8").splitlines()
        for language_code in FLORES_LANGUAGE_NAMES
    }
    rows = []
    for source_code, target_code in FLORES_TRANSLATION_DIRECTIONS:
        source_lines = language_lines[source_code]
        target_lines = language_lines[target_code]
        if len(source_lines) < FLORES_CASES_PER_DIRECTION or len(target_lines) < FLORES_CASES_PER_DIRECTION:
            raise ValueError("flores_devtest_direction_has_insufficient_aligned_rows")
        for index in range(FLORES_CASES_PER_DIRECTION):
            rows.append(
                {
                    "id": f"flores200-devtest::{source_code}->{target_code}::{index:04d}",
                    "source": source_lines[index],
                    "reference": target_lines[index],
                    "source_language": FLORES_LANGUAGE_NAMES[source_code],
                    "source_language_code": source_code,
                    "target_language": FLORES_LANGUAGE_NAMES[target_code],
                    "target_language_code": target_code,
                }
            )
    return _valid_materialized_rows(rows)


