def _materialize_bbh(raw_root: Path) -> list[dict[str, Any]]:
    rows = []
    for path in sorted((raw_root / "BIG-Bench-Hard/bbh").glob("*.json")):
        payload = json.loads(path.read_text(encoding="utf-8"))
        examples = payload.get("examples") if isinstance(payload, Mapping) and isinstance(payload.get("examples"), list) else []
        for index, example in enumerate(examples):
            if not isinstance(example, Mapping):
                continue
            rows.append(
                _exact_case(
                    prompt=example.get("input"),
                    answer=example.get("target"),
                    case_id=f"{path.stem}:{index}",
                    category=path.stem,
                )
            )
    return _valid_materialized_rows(rows)


def _materialize_arc_challenge(raw_root: Path) -> list[dict[str, Any]]:
    path = raw_root / "arc_hf/arc_challenge_test.parquet"
    if not path.exists():
        path = raw_root / "arc_hf/arc_challenge_validation.parquet"
    rows = []
    for raw in _read_parquet_rows(path):
        choices = raw.get("choices") if isinstance(raw.get("choices"), Mapping) else {}
        labels = choices.get("label") if isinstance(choices.get("label"), list) else []
        texts = choices.get("text") if isinstance(choices.get("text"), list) else []
        rows.append(
            _mcq_case(
                question=raw.get("question"),
                options=dict(zip(labels, texts)) if labels and texts else texts,
                answer=raw.get("answerKey"),
                case_id=raw.get("id"),
                category="arc_challenge",
            )
        )
    return _valid_materialized_rows(rows)


