def _materialize_gpqa_diamond(raw_root: Path) -> list[dict[str, Any]]:
    """Materialize an operator-authorized GPQA Diamond CSV without answer-position bias.

    The official source stores the correct answer separately from three
    distractors.  Keeping that source order would put the correct choice in a
    predictable position.  A fixed per-case SHA-256 ordering creates one
    reproducible option map before any candidate is run; every Axio surface and
    every provider baseline then receives that identical map.
    """

    path = raw_root / "gpqa/gpqa_diamond.csv"
    required_fields = {
        "Question",
        "Correct Answer",
        "Incorrect Answer 1",
        "Incorrect Answer 2",
        "Incorrect Answer 3",
    }
    rows = []
    with path.open(encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle)
        fieldnames = {str(field or "").strip() for field in (reader.fieldnames or [])}
        if not required_fields.issubset(fieldnames):
            raise ValueError("gpqa_diamond_csv_schema_missing")
        for raw in reader:
            question = str(raw.get("Question") or "").strip()
            correct = str(raw.get("Correct Answer") or "").strip()
            options = [
                str(raw.get("Incorrect Answer 1") or "").strip(),
                str(raw.get("Incorrect Answer 2") or "").strip(),
                str(raw.get("Incorrect Answer 3") or "").strip(),
                correct,
            ]
            normalized_options = [_normalize_freeform_answer(option) for option in options]
            if not question or not correct or any(not option for option in options):
                raise ValueError("gpqa_diamond_csv_row_missing_required_value")
            if len(set(normalized_options)) != 4:
                raise ValueError("gpqa_diamond_csv_row_duplicate_option")
            case_identity = {
                "suite_id": "gpqa_diamond",
                "question": question,
                "correct": correct,
                "incorrect": options[:3],
            }
            case_id = "gpqa_diamond::" + sha256_text(stable_json(case_identity))[:32]
            ordered_options = sorted(
                options,
                key=lambda option: sha256_text(
                    stable_json(
                        {
                            "adapter": "gpqa_diamond_csv_fixed_per_case_option_order_v1",
                            "case_id": case_id,
                            "option": option,
                        }
                    )
                ),
            )
            option_map = {
                chr(ord("A") + option_index): option
                for option_index, option in enumerate(ordered_options)
            }
            correct_label = next(
                label
                for label, option in option_map.items()
                if _normalize_freeform_answer(option) == _normalize_freeform_answer(correct)
            )
            domain = str(raw.get("High-level domain") or "").strip()
            subdomain = str(raw.get("Subdomain") or "").strip()
            category = ":".join(part for part in (domain, subdomain) if part) or "gpqa_diamond"
            rows.append(
                _mcq_case(
                    question=question,
                    options=option_map,
                    answer=correct_label,
                    case_id=case_id,
                    category=category,
                )
            )
    return _valid_materialized_rows(rows)


def _materialize_truthfulqa(raw_root: Path) -> list[dict[str, Any]]:
    payload = json.loads((raw_root / "truthfulqa/data/mc_task.json").read_text(encoding="utf-8"))
    examples = payload if isinstance(payload, list) else [payload]
    rows = []
    for index, raw in enumerate(examples):
        if not isinstance(raw, Mapping):
            continue
        targets = raw.get("mc1_targets") if isinstance(raw.get("mc1_targets"), Mapping) else raw.get("mc0_targets")
        options = list(targets.keys()) if isinstance(targets, Mapping) else []
        correct_index = next((i for i, option in enumerate(options) if _truthy_label(targets.get(option))), None) if isinstance(targets, Mapping) else None
        answer = chr(ord("A") + correct_index) if correct_index is not None else ""
        rows.append(_mcq_case(question=raw.get("question"), options=options, answer=answer, case_id=f"truthfulqa:{index}", category="truthfulqa"))
    return _valid_materialized_rows(rows)


def _materialize_halueval(raw_root: Path) -> list[dict[str, Any]]:
    rows = []
    for index, raw in enumerate(_read_json_or_jsonl_rows(raw_root / "HaluEval/data/qa_data.json")):
        question = "\n".join(
            part
            for part in (
                f"Knowledge: {raw.get('knowledge')}" if raw.get("knowledge") else "",
                f"Question: {raw.get('question')}" if raw.get("question") else "",
                "Choose the factual answer.",
            )
            if part
        )
        rows.append(
            _mcq_case(
                question=question,
                options=[raw.get("right_answer"), raw.get("hallucinated_answer")],
                answer="A",
                case_id=f"halueval_qa:{index}",
                category="halueval_qa",
            )
        )
    return _valid_materialized_rows(rows)


