def _materialize_bizbench(raw_root: Path) -> list[dict[str, Any]]:
    paths = sorted((raw_root / "bizbench/data").glob("test-*.parquet"))
    rows = []
    for index, raw in enumerate(_read_parquet_rows(paths[0]) if paths else []):
        context = str(raw.get("context") or "").strip()
        question = str(raw.get("question") or "").strip()
        prompt = "\n\n".join(part for part in (f"Context:\n{context}" if context else "", question) if part)
        case_identity = {
            "index": index,
            "task": raw.get("task"),
            "question": raw.get("question"),
            "context": raw.get("context"),
            "context_type": raw.get("context_type"),
            "options": raw.get("options"),
        }
        rows.append(
            _exact_case(
                prompt=prompt,
                answer=raw.get("answer"),
                case_id=sha256_text(stable_json(case_identity))[:32],
                category=raw.get("task"),
            )
        )
    return _valid_materialized_rows(rows)


def _materialize_legalbench(raw_root: Path) -> list[dict[str, Any]]:
    rows = []
    tasks_root = raw_root / "legalbench/tasks"
    for task_dir in sorted(path for path in tasks_root.iterdir() if path.is_dir()):
        data_path = task_dir / "test.tsv"
        if not data_path.exists():
            data_path = task_dir / "train.tsv"
        if not data_path.exists():
            continue
        prompt_prefix = _safe_read_text(task_dir / "base_prompt.txt")
        task_rows = _read_tsv_rows(data_path)
        answer_values = sorted(
            {
                str(raw.get("answer") or raw.get("label") or raw.get("target") or "").strip()
                for raw in task_rows
                if str(raw.get("answer") or raw.get("label") or raw.get("target") or "").strip()
            }
        )
        if len(answer_values) < 2 or len(answer_values) > 26:
            continue
        option_map = {chr(ord("A") + index): answer for index, answer in enumerate(answer_values)}
        answer_to_label = {answer: label for label, answer in option_map.items()}
        for raw in task_rows:
            text = raw.get("text") or raw.get("input") or raw.get("question") or raw.get("prompt") or ""
            answer = raw.get("answer") or raw.get("label") or raw.get("target") or ""
            prompt = "\n\n".join(part for part in (prompt_prefix.strip(), str(text).strip()) if part)
            rows.append(
                _mcq_case(
                    question=prompt,
                    options=option_map,
                    answer=answer_to_label.get(str(answer).strip(), ""),
                    case_id=f"{task_dir.name}:{raw.get('index') or len(rows)}",
                    category=task_dir.name,
                )
            )
    return _valid_materialized_rows(rows)


def _read_jsonl_rows(path: Path) -> list[dict[str, Any]]:
    rows = []
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            if not line.strip():
                continue
            payload = json.loads(line)
            if isinstance(payload, Mapping):
                rows.append(dict(payload))
    return rows


def _read_json_or_jsonl_rows(path: Path) -> list[dict[str, Any]]:
    text = path.read_text(encoding="utf-8").strip()
    if not text:
        return []
    try:
        payload = json.loads(text)
        if isinstance(payload, list):
            return [dict(row) for row in payload if isinstance(row, Mapping)]
        if isinstance(payload, Mapping):
            return [dict(payload)]
    except json.JSONDecodeError:
        pass
    return _read_jsonl_rows(path)


def _read_parquet_rows(path: Path) -> list[dict[str, Any]]:
    try:
        import pyarrow.parquet as pq  # type: ignore[import-not-found]
    except Exception as exc:  # noqa: PERF203 - optional dependency boundary
        raise RuntimeError("optional_pyarrow_missing") from exc
    if not path.exists():
        return []
    return [dict(row) for row in pq.read_table(path).to_pylist() if isinstance(row, Mapping)]


def _read_tsv_rows(path: Path) -> list[dict[str, Any]]:
    with path.open(encoding="utf-8", newline="") as handle:
        return [dict(row) for row in csv.DictReader(handle, delimiter="\t")]


def _safe_read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except OSError:
        return ""


def _exact_case(*, prompt: Any, answer: Any, case_id: Any = "", category: Any = "") -> dict[str, Any]:
    return {
        "id": str(case_id or ""),
        "prompt": str(prompt or ""),
        "answer": str(answer or ""),
        "category": str(category or ""),
    }


def _mcq_case(*, question: Any, options: Any, answer: Any, case_id: Any = "", category: Any = "") -> dict[str, Any]:
    option_map = _coerce_option_map(options)
    normalized_answer = _normalize_materialized_answer(answer, option_map)
    return {
        "id": str(case_id or ""),
        "question": str(question or ""),
        "options": option_map,
        "answer": normalized_answer,
        "category": str(category or ""),
    }


def _valid_materialized_rows(rows: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    result = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        prompt = row.get("prompt") or row.get("question") or row.get("input") or row.get("source")
        answer = row.get("answer") or row.get("target") or row.get("reference")
        options = row.get("options")
        if not str(prompt or "").strip() or not str(answer or "").strip():
            continue
        if options is not None and not _coerce_option_map(options):
            continue
        result.append(dict(row))
    return result


def _coerce_options(value: Any) -> Any:
    if isinstance(value, str):
        text = value.strip()
        if text.startswith("[") or text.startswith("{"):
            try:
                return ast.literal_eval(text)
            except (SyntaxError, ValueError):
                return text
    return value


def _coerce_option_map(value: Any) -> dict[str, str]:
    value = _coerce_options(value)
    if isinstance(value, Mapping):
        return {str(key).upper(): str(option) for key, option in value.items() if str(option).strip()}
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        return {
            chr(ord("A") + index): str(option)
            for index, option in enumerate(value)
            if str(option).strip()
        }
    return {}


def _normalize_materialized_answer(value: Any, option_map: Mapping[str, str]) -> str:
    text = str(value or "").strip()
    upper = text.upper()
    if upper in option_map:
        return upper
    if len(upper) == 1 and "A" <= upper <= "Z":
        return upper
    normalized_text = _normalize_freeform_answer(text)
    for label, option in option_map.items():
        if normalized_text and normalized_text == _normalize_freeform_answer(option):
            return str(label).upper()
    return _normalize_answer(text)


def _truthy_label(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return float(value) > 0
    return str(value).strip().lower() in {"1", "true", "yes", "correct"}


def _financebench_context(value: Any) -> str:
    if not isinstance(value, list):
        return ""
    snippets = []
    for item in value[:6]:
        if isinstance(item, Mapping):
            for key in ("evidence_text", "text", "excerpt", "content", "quote"):
                if str(item.get(key) or "").strip():
                    snippets.append(str(item.get(key)).strip())
                    break
        elif str(item).strip():
            snippets.append(str(item).strip())
    if not snippets:
        return ""
    return "Evidence context:\n" + "\n".join(f"- {snippet}" for snippet in snippets)


def _candidate_count_by_type_from_matrix(matrix: Mapping[str, Any]) -> dict[str, int]:
    candidates = matrix.get("candidates") if isinstance(matrix.get("candidates"), list) else []
    counts: dict[str, int] = {}
    for candidate in candidates:
        if not isinstance(candidate, Mapping):
            continue
        candidate_type = str(candidate.get("candidate_type") or "unknown")
        counts[candidate_type] = counts.get(candidate_type, 0) + 1
    return dict(sorted(counts.items()))


def _candidate_count_by_type_from_ids(candidate_ids: Sequence[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for candidate_id in candidate_ids:
        text = str(candidate_id or "")
        if text.startswith("axio-"):
            candidate_type = "axio"
        elif text.startswith("provider::"):
            candidate_type = "provider"
        else:
            candidate_type = "baseline"
        counts[candidate_type] = counts.get(candidate_type, 0) + 1
    return dict(sorted(counts.items()))


def _source_materialization_template(
    suite: BenchmarkSuite,
    *,
    base_dir: str,
    import_dir: str,
    min_cases_per_suite: int,
) -> dict[str, Any]:
    requires_official_harness = _suite_requires_official_harness(suite.suite_id, suite.task_format)
    effective_min_cases = _effective_min_cases_for_suite(suite.suite_id, min_cases_per_suite)
    if requires_official_harness:
        command = (
            "axio-fusion-api-standalone benchmark-import-official-batch "
            "--batch-file <FILLED_OFFICIAL_IMPORT_BATCH_JSON> "
            "--output-dir <SAFE_OFFICIAL_IMPORT_DIR> "
            "--output <WORK_DIR>/official_import_batch_receipt.json"
        )
        output_placeholder = f"<SAFE_OFFICIAL_IMPORT_DIR>/{suite.suite_id}/"
    else:
        command = (
            "axio-fusion-api-standalone benchmark-validate-dataset "
            f"--suite-id {suite.suite_id} "
            f"--dataset <PINNED_DATASET_DIR>/{suite.suite_id}.jsonl "
            f"--task-format {suite.task_format} "
            "--output <WORK_DIR>/validation/"
            f"{suite.suite_id}.json"
        )
        output_placeholder = f"<PINNED_DATASET_DIR>/{suite.suite_id}.jsonl"
    return {
        "input_mode": "official_or_audited_import" if requires_official_harness else "local_jsonl",
        "min_cases": effective_min_cases,
        "suite_min_case_policy": _suite_min_case_policy(suite.suite_id, min_cases_per_suite),
        "local_dataset_path_sha256": sha256_text(f"{base_dir.rstrip('/')}/{suite.suite_id}.jsonl")
        if not requires_official_harness
        else "",
        "safe_import_dir_sha256": sha256_text(f"{import_dir.rstrip('/')}/{suite.suite_id}")
        if requires_official_harness
        else "",
        "output_placeholder": output_placeholder,
        "adapter_command_template": command,
        "requires_same_case_hashes_for_all_candidates": True,
        "case_hash_manifest_required": True,
        "raw_dataset_path_persisted": False,
        "raw_import_path_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _validate_source_manifest_suite(
    row: Mapping[str, Any],
    *,
    suite: BenchmarkSuite,
    min_cases_per_suite: int,
) -> dict[str, Any]:
    reasons = []
    source_record = row.get("source_record") if isinstance(row.get("source_record"), Mapping) else {}
    materialization = row.get("materialization") if isinstance(row.get("materialization"), Mapping) else {}
    requires_official_harness = _suite_requires_official_harness(suite.suite_id, suite.task_format)
    effective_min_cases = _effective_min_cases_for_suite(suite.suite_id, min_cases_per_suite)
    if str(row.get("task_format") or "") != suite.task_format:
        reasons.append("task_format_mismatch")
    if str(row.get("category") or "") != suite.category:
        reasons.append("category_mismatch")
    if (_optional_int(row.get("min_cases")) or 0) < effective_min_cases:
        reasons.append("min_cases_below_required")
    if row.get("official_harness_required") is not requires_official_harness:
        reasons.append("official_harness_requirement_mismatch")
    for field in _source_manifest_required_sha_fields(requires_official_harness):
        if not _looks_like_sha256(source_record.get(field)):
            reasons.append(f"missing_{field}")
    license_policy_id = str(source_record.get("license_policy_id") or "").strip()
    if _unfilled_placeholder(license_policy_id):
        reasons.append("missing_license_policy_id")
    if not materialization:
        reasons.append("missing_materialization")
    elif materialization.get("case_hash_manifest_required") is not True:
        reasons.append("case_hash_manifest_not_required")
    if _contains_forbidden_persistence_flag(row):
        reasons.append("forbidden_persistence_flag_detected")
    return {
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": suite.task_format,
        "input_mode": str(row.get("input_mode") or ""),
        "official_harness_required": requires_official_harness,
        "effective_min_cases": effective_min_cases,
        "suite_min_case_policy": _suite_min_case_policy(suite.suite_id, min_cases_per_suite),
        "ready": not reasons,
        "reason_codes": reasons,
        "required_hash_field_count": len(_source_manifest_required_sha_fields(requires_official_harness)),
        "hash_field_pass_count": sum(
            1
            for field in _source_manifest_required_sha_fields(requires_official_harness)
            if _looks_like_sha256(source_record.get(field))
        ),
        "license_policy_id_present": not _unfilled_placeholder(license_policy_id),
        "case_hash_manifest_required": bool(materialization.get("case_hash_manifest_required"))
        if materialization
        else False,
        "raw_dataset_content_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _source_manifest_required_sha_fields(requires_official_harness: bool) -> tuple[str, ...]:
    fields = (
        "dataset_snapshot_sha256",
        "source_revision_sha256",
        "case_selection_sha256",
        "prompt_protocol_sha256",
        "decoding_config_sha256",
        "adapter_version_sha256",
        "materialized_case_hash_manifest_sha256",
        "data_usage_review_id_sha256",
        "evaluator_config_sha256",
    )
    if requires_official_harness:
        fields = (
            *fields,
            "official_harness_name_sha256",
            "official_harness_version_sha256",
        )
    return fields


def _case_hash_manifest_missing_suite_row(suite: BenchmarkSuite) -> dict[str, Any]:
    return {
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": suite.task_format,
        "input_mode": "missing",
        "ready": False,
        "reason_codes": ["dataset_manifest_suite_missing"],
        "case_hash_count": 0,
        "duplicate_case_hash_count": 0,
        "materialized_case_hash_manifest_sha256": "",
        "raw_dataset_path_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_import_path_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _case_hash_manifest_local_suite_row(
    spec: Mapping[str, Any],
    *,
    suite: BenchmarkSuite,
    min_cases_per_suite: int,
) -> dict[str, Any]:
    dataset_path = _suite_dataset_path(spec)
    effective_min_cases = _effective_min_cases_for_suite(suite.suite_id, min_cases_per_suite)
    reasons = []
    hashes: list[str] = []
    invalid_json_count = 0
    validation: Mapping[str, Any] = {}
    if not dataset_path:
        reasons.append("dataset_path_missing")
    elif not Path(dataset_path).exists():
        reasons.append("dataset_path_not_found")
    else:
        hashes, invalid_json_count = _dataset_case_hashes_from_jsonl(dataset_path, suite_id=suite.suite_id)
        validation = validate_benchmark_dataset(
            suite_id=suite.suite_id,
            dataset_path=dataset_path,
            task_format=suite.task_format,
        )
        if validation.get("ready_for_scoring") is not True:
            if validation.get("invalid_case_count"):
                reasons.append("invalid_dataset_rows")
            if validation.get("duplicate_case_hash_count"):
                reasons.append("duplicate_dataset_cases")
            if validation.get("label_leakage_suspected_count"):
                reasons.append("possible_label_leakage")
        if invalid_json_count:
            reasons.append("invalid_jsonl_rows")
    unique_hashes = sorted(set(hashes))
    duplicate_count = max(0, len(hashes) - len(unique_hashes))
    if duplicate_count:
        reasons.append("duplicate_materialized_case_hashes")
    if len(unique_hashes) < effective_min_cases:
        reasons.append("insufficient_case_hash_count")
    digest = _case_hash_set_digest(suite.suite_id, unique_hashes) if unique_hashes else ""
    return {
        "suite_id": suite.suite_id,
        "benchmark_slot_id": suite.suite_id,
        "benchmark_dataset_id": str(spec.get("benchmark_dataset_id") or suite.suite_id),
        "benchmark_identity": str(spec.get("benchmark_identity") or suite.title),
        "replacement_active": spec.get("replacement_active") is True,
        "replacement_disclosure": (
            "This is an explicit replacement dataset and is not the original benchmark."
            if spec.get("replacement_active") is True
            else ""
        ),
        "category": suite.category,
        "task_format": suite.task_format,
        "input_mode": "local_jsonl",
        "ready": not reasons,
        "reason_codes": sorted(set(reasons)),
        "case_hash_count": len(unique_hashes),
        "effective_min_cases": effective_min_cases,
        "suite_min_case_policy": _suite_min_case_policy(suite.suite_id, min_cases_per_suite),
        "duplicate_case_hash_count": duplicate_count,
        "invalid_jsonl_row_count": invalid_json_count,
        "valid_case_count": _optional_int(validation.get("valid_case_count")) if validation else None,
        "materialized_case_hash_manifest_sha256": digest,
        "dataset_path_sha256": sha256_text(dataset_path) if dataset_path else "",
        "raw_dataset_path_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
    }


def _official_case_source_path(
    spec: Mapping[str, Any],
    *,
    suite_id: str,
    overrides: Mapping[str, str],
) -> str:
    override = str(overrides.get(suite_id) or "").strip()
    if override:
        return override
    for key in ("official_case_source", "official_case_source_path", "case_source"):
        value = str(spec.get(key) or "").strip()
        if value:
            return value
    return ""


def _case_hash_manifest_official_source_suite_row(
    source_path: str,
    *,
    suite: BenchmarkSuite,
    min_cases_per_suite: int,
) -> dict[str, Any]:
    """Build a pre-generation case-set receipt from an official source file.

    Only stable public case identifiers are consumed. Prompts, tests,
    references, labels, and model output remain private and are never returned
    in this safe manifest.
    """

    effective_min_cases = _effective_min_cases_for_suite(suite.suite_id, min_cases_per_suite)
    path = Path(source_path)
    reasons: list[str] = []
    hashes: list[str] = []
    invalid_row_count = 0
    parser = _official_case_source_parser_id(suite.suite_id)
    if not parser:
        reasons.append("official_case_source_parser_not_supported")
    elif not path.exists():
        reasons.append("official_case_source_not_found")
    else:
        try:
            hashes, invalid_row_count = _official_source_case_hashes(
                path,
                suite_id=suite.suite_id,
                parser=parser,
            )
        except _OfficialCaseSourceError as exc:
            reasons.append(exc.reason_code)
        if invalid_row_count:
            reasons.append("official_case_source_invalid_rows")
    unique_hashes = sorted(set(hashes))
    duplicate_count = max(0, len(hashes) - len(unique_hashes))
    if duplicate_count:
        reasons.append("duplicate_official_case_identifiers")
    if len(unique_hashes) < effective_min_cases:
        reasons.append("insufficient_case_hash_count")
    digest = _case_hash_set_digest(suite.suite_id, unique_hashes) if unique_hashes else ""
    return {
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": suite.task_format,
        "input_mode": "official_source_identifier_manifest",
        "case_source_parser": parser,
        "ready": not reasons,
        "reason_codes": sorted(set(reasons)),
        "case_hash_count": len(unique_hashes),
        "effective_min_cases": effective_min_cases,
        "suite_min_case_policy": _suite_min_case_policy(suite.suite_id, min_cases_per_suite),
        "duplicate_case_hash_count": duplicate_count,
        "invalid_source_row_count": invalid_row_count,
        "materialized_case_hash_manifest_sha256": digest,
        "official_case_source_path_sha256": sha256_text(str(path)),
        "official_harness_outputs_required_for_scoring": True,
        "official_harness_outputs_available": False,
        "raw_candidate_ids_persisted": False,
        "raw_dataset_path_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _official_case_source_parser_id(suite_id: str) -> str:
    return {
        "livecodebench": "livecodebench_parquet_question_id_v1",
        "humaneval": "humaneval_task_id_v1",
        "bfcl": "bfcl_v3_category_id_v1",
        "tau_bench": "tau_bench_tasks_ast_index_v1",
        "ifeval": "ifeval_key_v1",
        "mt_bench_work": "mt_bench_question_id_v1",
    }.get(suite_id, "")


class _OfficialCaseSourceError(ValueError):
    """Safe source-parser failure that can be surfaced as a reason code."""

    def __init__(self, reason_code: str) -> None:
        super().__init__(reason_code)
        self.reason_code = reason_code


def _official_source_case_hashes(
    path: Path,
    *,
    suite_id: str,
    parser: str,
) -> tuple[list[str], int]:
    if parser == "livecodebench_parquet_question_id_v1":
        return _livecodebench_source_case_hashes(path, suite_id=suite_id)
    if parser == "bfcl_v3_category_id_v1":
        return _bfcl_source_case_hashes(path, suite_id=suite_id)
    if parser == "tau_bench_tasks_ast_index_v1":
        return _tau_bench_source_case_hashes(path, suite_id=suite_id)
    if parser not in {
        "humaneval_task_id_v1",
        "ifeval_key_v1",
        "mt_bench_question_id_v1",
    }:
        raise _OfficialCaseSourceError("official_case_source_parser_not_supported")

    open_file = gzip.open if path.suffix.lower() == ".gz" else open
    hashes: list[str] = []
    invalid_rows = 0
    try:
        handle = open_file(path, "rt", encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise _OfficialCaseSourceError("official_case_source_unreadable") from exc
    with handle:
        for line in handle:
            text = line.strip()
            if not text:
                continue
            try:
                row = json.loads(text)
            except json.JSONDecodeError:
                invalid_rows += 1
                continue
            if not isinstance(row, Mapping):
                invalid_rows += 1
                continue
            case_identifier = _official_jsonl_case_identifier(row, parser=parser)
            if case_identifier in (None, ""):
                invalid_rows += 1
                continue
            hashes.append(_official_source_case_hash(suite_id, case_identifier))
    return hashes, invalid_rows


def _official_jsonl_case_identifier(row: Mapping[str, Any], *, parser: str) -> Any:
    if parser == "humaneval_task_id_v1":
        return row.get("task_id")
    if parser == "ifeval_key_v1":
        return row.get("key")
    if parser == "mt_bench_question_id_v1":
        return row.get("question_id")
    return None


def _official_source_case_hash(suite_id: str, case_identifier: Any) -> str:
    return sha256_text(
        json.dumps(
            {"suite_id": suite_id, "id": case_identifier},
            ensure_ascii=False,
            sort_keys=True,
        )
    )


def _livecodebench_source_case_hashes(path: Path, *, suite_id: str) -> tuple[list[str], int]:
    source = _livecodebench_generation_parquet(path)
    identifiers = _livecodebench_question_ids(source)
    invalid_rows = sum(1 for identifier in identifiers if identifier in (None, ""))
    # LiveCodeBench has multiple hidden tests per code-generation problem. The
    # question id, rather than a question/test pair, is the benchmark case.
    unique_identifiers = sorted({str(identifier) for identifier in identifiers if identifier not in (None, "")})
    return [_official_source_case_hash(suite_id, identifier) for identifier in unique_identifiers], invalid_rows


def _livecodebench_generation_parquet(path: Path) -> Path:
    source = path / "test_generation.parquet" if path.is_dir() else path
    if source.name != "test_generation.parquet" or not source.is_file():
        raise _OfficialCaseSourceError("official_case_source_livecodebench_generation_parquet_missing")
    return source


def _livecodebench_question_ids(path: Path) -> list[Any]:
    try:
        import pyarrow.parquet as parquet
    except ImportError as exc:
        raise _OfficialCaseSourceError("official_case_source_parquet_dependency_missing") from exc
    try:
        parquet_file = parquet.ParquetFile(path)
        if "question_id" not in parquet_file.schema.names:
            raise _OfficialCaseSourceError("official_case_source_livecodebench_question_id_missing")
        return parquet_file.read(columns=["question_id"])["question_id"].to_pylist()
    except _OfficialCaseSourceError:
        raise
    except (OSError, ValueError, TypeError) as exc:
        raise _OfficialCaseSourceError("official_case_source_livecodebench_parquet_unreadable") from exc


_BFCL_V3_CASESET_FILENAMES = (
    "BFCL_v3_simple.json",
    "BFCL_v3_multiple.json",
    "BFCL_v3_parallel.json",
    "BFCL_v3_parallel_multiple.json",
    "BFCL_v3_live_simple.json",
    "BFCL_v3_live_multiple.json",
)


def _bfcl_source_case_hashes(path: Path, *, suite_id: str) -> tuple[list[str], int]:
    if not path.is_dir():
        raise _OfficialCaseSourceError("official_case_source_bfcl_directory_required")
    source_files = [path / name for name in _BFCL_V3_CASESET_FILENAMES]
    if any(not source.is_file() for source in source_files):
        raise _OfficialCaseSourceError("official_case_source_bfcl_category_files_missing")

    hashes: list[str] = []
    invalid_rows = 0
    for source in source_files:
        try:
            handle = source.open("r", encoding="utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            raise _OfficialCaseSourceError("official_case_source_unreadable") from exc
        with handle:
            for line in handle:
                text = line.strip()
                if not text:
                    continue
                try:
                    row = json.loads(text)
                except json.JSONDecodeError:
                    invalid_rows += 1
                    continue
                if not isinstance(row, Mapping) or row.get("id") in (None, ""):
                    invalid_rows += 1
                    continue
                # BFCL ids are scoped by category file. Keeping the file stem
                # in the identity prevents collisions across task categories.
                identifier = {"category": source.stem, "id": str(row["id"])}
                hashes.append(_official_source_case_hash(suite_id, identifier))
    return hashes, invalid_rows


_TAU_BENCH_TASK_SOURCES = (
    ("retail", "retail/tasks_test.py", "TASKS_TEST"),
    ("airline", "airline/tasks_test.py", "TASKS"),
)


def _tau_bench_source_case_hashes(path: Path, *, suite_id: str) -> tuple[list[str], int]:
    env_root = _tau_bench_env_root(path)
    hashes: list[str] = []
    invalid_rows = 0
    for domain, relative_path, target_name in _TAU_BENCH_TASK_SOURCES:
        source = env_root / relative_path
        if not source.is_file():
            raise _OfficialCaseSourceError("official_case_source_tau_bench_task_file_missing")
        try:
            tree = ast.parse(source.read_text(encoding="utf-8"), filename=source.name)
        except (OSError, UnicodeDecodeError, SyntaxError) as exc:
            raise _OfficialCaseSourceError("official_case_source_tau_bench_ast_unreadable") from exc
        task_list = _top_level_static_task_list(tree, target_name=target_name)
        if task_list is None:
            raise _OfficialCaseSourceError("official_case_source_tau_bench_static_task_list_missing")
        if not all(isinstance(node, ast.Call) for node in task_list.elts):
            invalid_rows += 1
            continue
        for index in range(len(task_list.elts)):
            hashes.append(_official_source_case_hash(suite_id, f"{domain}:{index}"))
    return hashes, invalid_rows


def _tau_bench_env_root(path: Path) -> Path:
    if not path.is_dir():
        raise _OfficialCaseSourceError("official_case_source_tau_bench_directory_required")
    candidates = (path / "tau_bench" / "envs", path / "envs", path)
    for candidate in candidates:
        if all((candidate / relative_path).is_file() for _, relative_path, _ in _TAU_BENCH_TASK_SOURCES):
            return candidate
    raise _OfficialCaseSourceError("official_case_source_tau_bench_task_file_missing")


def _top_level_static_task_list(tree: ast.Module, *, target_name: str) -> ast.List | None:
    for node in tree.body:
        if isinstance(node, ast.Assign):
            targets = node.targets
            value = node.value
        elif isinstance(node, ast.AnnAssign):
            targets = [node.target]
            value = node.value
        else:
            continue
        if any(isinstance(target, ast.Name) and target.id == target_name for target in targets):
            return value if isinstance(value, ast.List) else None
    return None


def _case_hash_manifest_imported_suite_row(
    spec: Mapping[str, Any],
    *,
    suite: BenchmarkSuite,
    candidate_ids: Sequence[str],
    min_cases_per_suite: int,
) -> dict[str, Any]:
    effective_min_cases = _effective_min_cases_for_suite(suite.suite_id, min_cases_per_suite)
    imported = spec.get("imported_runs") if isinstance(spec.get("imported_runs"), Mapping) else {}
    candidates = [str(candidate).strip() for candidate in candidate_ids if str(candidate).strip()]
    if not candidates:
        candidates = sorted(str(candidate) for candidate in imported.keys() if str(candidate))
    task_format = str(spec.get("task_format") or suite.task_format)
    validation = _validate_imported_runs(
        spec,
        candidates,
        suite_id=suite.suite_id,
        task_format=task_format,
    )
    alignment = _imported_case_alignment(
        spec,
        candidates,
        suite_id=suite.suite_id,
        task_format=task_format,
    )
    reasons = []
    if not candidates:
        reasons.append("missing_imported_run_candidates")
    if validation.get("missing_import_count"):
        reasons.append("official_import_receipts_missing")
    if validation.get("invalid_import_count"):
        reasons.append("official_import_receipts_invalid")
    if candidates and alignment.get("case_hash_sets_identical") is not True:
        reasons.append("official_import_case_hashes_misaligned")
    case_hashes = _first_imported_case_hash_set(spec, candidates)
    if len(case_hashes) < effective_min_cases:
        reasons.append("insufficient_case_hash_count")
    digest = _case_hash_set_digest(suite.suite_id, sorted(case_hashes)) if case_hashes else ""
    return {
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": task_format,
        "input_mode": "official_or_audited_import",
        "ready": not reasons,
        "reason_codes": sorted(set(reasons)),
        "candidate_count": len(candidates),
        "candidate_hashes_sha256": [sha256_text(candidate) for candidate in candidates[:64]],
        "valid_import_count": _optional_int(validation.get("valid_import_count")) or 0,
        "missing_import_count": _optional_int(validation.get("missing_import_count")) or 0,
        "invalid_import_count": _optional_int(validation.get("invalid_import_count")) or 0,
        "case_hash_sets_identical": bool(alignment.get("case_hash_sets_identical")),
        "case_hash_count": len(case_hashes),
        "effective_min_cases": effective_min_cases,
        "suite_min_case_policy": _suite_min_case_policy(suite.suite_id, min_cases_per_suite),
        "duplicate_case_hash_count": 0,
        "materialized_case_hash_manifest_sha256": digest,
        "raw_candidate_ids_persisted": False,
        "raw_import_paths_persisted": False,
        "raw_case_hashes_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _dataset_case_hashes_from_jsonl(path: str | Path, *, suite_id: str) -> tuple[list[str], int]:
    hashes: list[str] = []
    invalid = 0
    with Path(path).open("r", encoding="utf-8") as handle:
        for index, line in enumerate(handle):
            text = line.strip()
            if not text:
                continue
            try:
                payload = json.loads(text)
            except json.JSONDecodeError:
                invalid += 1
                continue
            if not isinstance(payload, Mapping):
                invalid += 1
                continue
            hashes.append(_dataset_case_hash(payload, suite_id=suite_id, index=index))
    return hashes, invalid


def _first_imported_case_hash_set(spec: Mapping[str, Any], candidates: Sequence[str]) -> set[str]:
    for candidate_id in candidates:
        path = _imported_run_path(spec, candidate_id)
        if not path or not Path(path).exists():
            continue
        try:
            payload = json.loads(Path(path).read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            continue
        if isinstance(payload, Mapping):
            return _run_case_hash_set(payload)
    return set()


def _case_hash_set_digest(suite_id: str, case_hashes: Sequence[str]) -> str:
    clean = sorted({str(case_hash).strip().lower() for case_hash in case_hashes if _looks_like_sha256(case_hash)})
    if not clean:
        return ""
    return sha256_text(stable_json({"suite_id": suite_id, "case_hashes": clean}))


def _unfilled_placeholder(value: Any) -> bool:
    text = str(value or "").strip()
    return not text or (text.startswith("<") and text.endswith(">"))


def _local_dataset_requirement(
    *,
    suite: BenchmarkSuite,
    base_dir: str,
    min_cases_per_suite: int,
) -> dict[str, Any]:
    dataset_path = f"{base_dir.rstrip('/')}/{suite.suite_id}.jsonl"
    effective_min_cases = _effective_min_cases_for_suite(suite.suite_id, min_cases_per_suite)
    return {
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": suite.task_format,
        "min_cases": effective_min_cases,
        "suite_min_case_policy": _suite_min_case_policy(suite.suite_id, min_cases_per_suite),
        "dataset_path_sha256": sha256_text(dataset_path),
        "dataset_placeholder": f"<PINNED_DATASET_DIR>/{suite.suite_id}.jsonl",
        "required_jsonl_fields": _dataset_schema_for_format(suite.task_format)["required_fields"],
        "validate_command_template": (
            "axio-fusion-api-standalone benchmark-validate-dataset "
            f"--suite-id {suite.suite_id} "
            f"--dataset <PINNED_DATASET_DIR>/{suite.suite_id}.jsonl "
            f"--task-format {suite.task_format} "
            "--output <WORK_DIR>/validation/"
            f"{suite.suite_id}.json"
        ),
        "raw_dataset_path_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_labels_persisted": False,
    }


def _official_import_requirement(
    *,
    suite: BenchmarkSuite,
    candidate_receipt: Mapping[str, Any],
    import_dir: str,
) -> dict[str, Any]:
    candidate_hash = str(candidate_receipt.get("candidate_id_hash") or "")
    run_unit_hash = str(candidate_receipt.get("run_unit_id_hash") or candidate_hash)
    candidate_placeholder = str(candidate_receipt.get("candidate_placeholder") or "<CANDIDATE_ID>")
    api_format = str(candidate_receipt.get("api_format") or "")
    api_surface_id_hash = str(candidate_receipt.get("api_surface_id_hash") or "")
    output_path = f"{import_dir.rstrip('/')}/{suite.suite_id}/{run_unit_hash[:16]}.safe.json"
    position_balanced = suite.task_format == "external_pairwise_judge"
    position_flag = "--position-balanced " if position_balanced else ""
    api_format_flag = f"--api-format {api_format} " if api_format in AXIO_BENCHMARK_API_FORMATS else ""
    return {
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": suite.task_format,
        "candidate_id_hash": candidate_hash,
        "run_unit_id_hash": run_unit_hash,
        "candidate_placeholder": candidate_placeholder,
        "candidate_type": str(candidate_receipt.get("candidate_type") or "unknown"),
        "algorithm": str(candidate_receipt.get("algorithm") or ""),
        "api_format": api_format,
        "api_surface_id_hash": api_surface_id_hash,
        "api_surface_role": str(candidate_receipt.get("api_surface_role") or ""),
        "api_surface_is_primary_claim": candidate_receipt.get("api_surface_is_primary_claim") is True,
        "provider_profile_hash": str(candidate_receipt.get("provider_profile_hash") or ""),
        "position_balanced_required": position_balanced,
        "harness_receipt_required": True,
        "required_harness_hash_fields": [
            "harness_name_sha256",
            "harness_version_sha256",
            "dataset_snapshot_sha256",
            "evaluator_config_sha256",
        ],
        "import_output_path_sha256": sha256_text(output_path),
        "import_output_placeholder": f"<SAFE_OFFICIAL_IMPORT_DIR>/{suite.suite_id}/{candidate_placeholder}.safe.json",
        "import_command_template": (
            "axio-fusion-api-standalone benchmark-import-official-run "
            f"--suite-id {suite.suite_id} "
            f"--candidate-id {candidate_placeholder} "
            "--source <OFFICIAL_HARNESS_OUTPUT_JSON_OR_JSONL> "
            f"--task-format {suite.task_format} "
            f"{api_format_flag}"
            "--harness-name <OFFICIAL_OR_AUDITED_HARNESS_NAME> "
            "--harness-version <PINNED_VERSION_OR_COMMIT> "
            "--dataset-snapshot <PINNED_DATASET_SNAPSHOT> "
            "--evaluator-config <DETERMINISTIC_EVALUATOR_CONFIG> "
            f"{position_flag}"
            f"--output <SAFE_OFFICIAL_IMPORT_DIR>/{suite.suite_id}/{candidate_placeholder}.safe.json"
        ),
        "raw_candidate_id_persisted": False,
        "raw_import_path_persisted": False,
        "raw_source_path_persisted": False,
        "raw_source_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _acquisition_readiness_snapshot(
    *,
    dataset_manifest_path: str | Path | None,
    registry_path: str | Path | None,
    candidate_ids: Sequence[str],
    min_cases_per_suite: int,
) -> dict[str, Any]:
    if not dataset_manifest_path:
        return {
            "available": False,
            "reason_codes": ["missing_dataset_manifest_path"],
            "candidate_source": "run_matrix",
            "candidate_count": len(candidate_ids),
            "raw_candidate_ids_persisted": False,
            "raw_dataset_paths_persisted": False,
            "secrets_persisted": False,
        }
    selected = Path(dataset_manifest_path)
    if not selected.exists():
        return {
            "available": False,
            "reason_codes": ["dataset_manifest_path_not_found"],
            "candidate_source": "run_matrix",
            "candidate_count": len(candidate_ids),
            "dataset_manifest_path_sha256": sha256_text(str(dataset_manifest_path)),
            "raw_candidate_ids_persisted": False,
            "raw_dataset_paths_persisted": False,
            "secrets_persisted": False,
        }
    readiness = audit_benchmark_campaign_readiness(
        dataset_manifest_path=selected,
        registry_path=registry_path,
        candidate_ids=candidate_ids,
        include_provider_baselines=False,
        max_provider_baselines=0,
        min_cases_per_suite=min_cases_per_suite,
    )
    rows = readiness.get("rows") if isinstance(readiness.get("rows"), list) else []
    return {
        "available": True,
        "schema": str(readiness.get("schema") or ""),
        "candidate_source": "run_matrix",
        "candidate_count": _optional_int(readiness.get("candidate_count")) or len(candidate_ids),
        "ready_suite_count": _optional_int(readiness.get("ready_suite_count")) or 0,
        "all_required_suites_ready": bool(readiness.get("all_required_suites_ready")),
        "will_claim_audit_be_possible": bool(readiness.get("will_claim_audit_be_possible")),
        "official_import_expected_count": sum(_optional_int(row.get("expected_imported_run_count")) or 0 for row in rows if isinstance(row, Mapping) and row.get("requires_official_harness") is True),
        "official_import_valid_count": sum(_optional_int(row.get("valid_imported_run_count")) or 0 for row in rows if isinstance(row, Mapping) and row.get("requires_official_harness") is True),
        "official_import_missing_count": sum(_optional_int(row.get("missing_imported_run_count")) or 0 for row in rows if isinstance(row, Mapping) and row.get("requires_official_harness") is True),
        "blocking_reason_counts": _count_reason_codes(_evidence_readiness_missing(readiness)),
        "raw_candidate_ids_persisted": False,
        "raw_dataset_paths_persisted": False,
        "raw_dataset_content_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _candidate_row(candidate_id: str, candidate_type: str, algorithm: str) -> dict[str, Any]:
    return {
        "candidate_id": candidate_id,
        "candidate_type": candidate_type,
        "algorithm": algorithm,
        "raw_prompt_persisted": False,
        "secrets_persisted": False,
    }


def _candidate_row_from_id(profiles: Sequence[ModelProfile], candidate_id: str) -> dict[str, Any]:
    if candidate_id.startswith("provider::"):
        return _provider_candidate_row(_provider_profile_from_candidate_id(profiles, candidate_id))
    surface = _split_axio_api_surface_id(candidate_id)
    logical_id = surface[0] if surface else candidate_id
    if _is_axio_public_candidate(logical_id):
        return _candidate_row(logical_id, "axio", _axio_algorithm_for_candidate(logical_id))
    return _candidate_row(candidate_id, "baseline", candidate_id)


def _provider_candidate_row(profile: ModelProfile) -> dict[str, Any]:
    return {
        "candidate_id": _provider_candidate_id(profile),
        "candidate_type": "provider",
        "algorithm": "single_provider_model",
        "provider_profile_hash": sha256_text(profile.profile_id),
        "raw_provider_name_persisted": False,
        "raw_provider_model_id_persisted": False,
        "raw_prompt_persisted": False,
        "secrets_persisted": False,
    }


def _dataset_schema_for_format(task_format: str) -> dict[str, Any]:
    schemas = {
        "multiple_choice": {
            "required_fields": ["question", "options", "answer"],
            "optional_fields": ["id", "category", "subject"],
            "example_schema": {
                "question": "string",
                "options": ["string", "string"],
                "answer": "A",
                "category": "optional string",
            },
        },
        "exact_match": {
            "required_fields": ["prompt", "answer"],
            "optional_fields": ["id", "category", "subject"],
            "example_schema": {
                "prompt": "string",
                "answer": "normalized final answer",
                "category": "optional string",
            },
        },
        "translation_chrf": {
            "required_fields": ["source", "reference"],
            "optional_fields": ["source_language", "target_language", "pass_threshold", "id"],
            "example_schema": {
                "source": "source sentence",
                "reference": "target-language reference",
                "source_language": "en",
                "target_language": "fr",
            },
        },
        "python_code": {
            "required_fields": ["prompt", "tests"],
            "optional_fields": ["entry_point", "id", "category"],
            "example_schema": {
                "prompt": "programming problem statement",
                "entry_point": "function_name",
                "tests": "python assertions executed by the benchmark harness",
            },
        },
        "tool_call_ast": {
            "required_fields": ["prompt", "tools", "expected_tool_call"],
            "optional_fields": ["id", "category"],
            "example_schema": {
                "prompt": "user request requiring a tool call",
                "tools": [{"name": "tool_name", "parameters": {"field": "type"}}],
                "expected_tool_call": {"name": "tool_name", "arguments": {"field": "value"}},
            },
        },
        "instruction_checks": {
            "required_fields": ["prompt", "checks"],
            "optional_fields": ["id", "category"],
            "example_schema": {
                "prompt": "instruction-following prompt",
                "checks": {
                    "contains": ["required substring"],
                    "not_contains": ["forbidden substring"],
                    "regex": ["pattern"],
                    "json_required": False,
                    "max_words": 100,
                },
            },
        },
        "external_pairwise_judge": {
            "required_fields": [],
            "optional_fields": ["imported_runs"],
            "example_schema": {
                "imported_runs": {
                    "axio-pro": "path/to/prompt_free_official_judge_run.json",
                    "provider::<profile-hash-alias>": "path/to/prompt_free_official_judge_run.json",
                }
            },
        },
    }
    return schemas.get(task_format, schemas["multiple_choice"])


def _dataset_acquisition_plan_for_suite(
    suite: BenchmarkSuite,
    *,
    base_dir: str,
    min_cases_per_suite: int,
) -> dict[str, Any]:
    methodology = _methodology_contract_for_suite(suite)
    requires_official_harness = _suite_requires_official_harness(suite.suite_id, suite.task_format)
    effective_min_cases = _effective_min_cases_for_suite(suite.suite_id, min_cases_per_suite)
    local_dataset_path = (
        f"{base_dir.rstrip('/')}/{suite.suite_id}.jsonl"
        if suite.task_format != "external_pairwise_judge"
        else ""
    )
    if requires_official_harness:
        action = "import_official_or_audited_run_receipts_for_every_candidate"
        input_mode = "official_or_audited_import"
    else:
        action = "prepare_local_schema_jsonl_and_validate"
        input_mode = "local_jsonl"
    return {
        "schema": "axio_fusion_api.dataset_acquisition_suite_plan.v1",
        "suite_id": suite.suite_id,
        "category": suite.category,
        "task_format": suite.task_format,
        "input_mode": input_mode,
        "required_action": action,
        "source_type": str(methodology.get("source_type") or ""),
        "source_url": str(methodology.get("source_url") or suite.reference),
        "dataset_slice": str(methodology.get("dataset_slice") or ""),
        "case_selection": str(methodology.get("case_selection") or ""),
        "snapshot_policy": str(methodology.get("snapshot_policy") or ""),
        "min_cases": effective_min_cases,
        "suite_min_case_policy": _suite_min_case_policy(suite.suite_id, min_cases_per_suite),
        "local_dataset_template_path": local_dataset_path,
        "validate_command_template": (
            "axio-fusion-api-standalone benchmark-validate-dataset "
            f"--suite-id {suite.suite_id} "
            f"--dataset <PINNED_DATASET_DIR>/{suite.suite_id}.jsonl "
            f"--task-format {suite.task_format} "
            "--output <WORK_DIR>/validation/"
            f"{suite.suite_id}.json"
        )
        if not requires_official_harness
        else "",
        "import_command_template": (
            "axio-fusion-api-standalone benchmark-import-official-run "
            f"--suite-id {suite.suite_id} "
            "--candidate-id <CANDIDATE_ID> "
            "--source <OFFICIAL_HARNESS_OUTPUT_JSON_OR_JSONL> "
            f"--task-format {suite.task_format} "
            "--harness-name <OFFICIAL_OR_AUDITED_HARNESS_NAME> "
            "--harness-version <PINNED_VERSION_OR_COMMIT> "
            "--dataset-snapshot <PINNED_DATASET_SNAPSHOT> "
            "--evaluator-config <DETERMINISTIC_EVALUATOR_CONFIG> "
            f"{'--position-balanced ' if suite.task_format == 'external_pairwise_judge' else ''}"
            "--output <SAFE_OFFICIAL_IMPORT_DIR>/"
            f"{suite.suite_id}__<CANDIDATE_ID>.safe.json"
        )
        if requires_official_harness
        else "",
        "import_receipt_required_for_each_candidate": requires_official_harness,
        "position_balanced_import_required": suite.task_format == "external_pairwise_judge",
        "final_claim_eligible_only_after_readiness": True,
        "raw_dataset_content_persisted": False,
        "raw_labels_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _harness_receipt_schema() -> dict[str, Any]:
    return {
        "schema": "axio_fusion_api.harness_receipt.v1",
        "suite_id": "benchmark suite id",
        "task_format": "suite task format",
        "official_harness_required": True,
        "official_or_audited_harness": True,
        "harness_name_sha256": "sha256 of official or audited harness name",
        "harness_version_sha256": "sha256 of pinned version, commit, release, or container digest",
        "dataset_snapshot_sha256": "sha256 of pinned official dataset snapshot identity",
        "evaluator_config_sha256": "sha256 of deterministic evaluator configuration",
        "prompt_protocol_sha256": "sha256 of the per-suite prompt protocol/template used for every candidate",
        "decoding_config_sha256": "sha256 of the per-suite deterministic decoding configuration used for every candidate",
        "position_balanced": "required for pairwise judge suites",
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _prompt_protocol_sha256_for_suite(
    suite_id: str,
    task_format: str,
    *,
    prompt_protocol: str = "",
) -> str:
    explicit = str(prompt_protocol or "").strip()
    if _looks_like_sha256(explicit):
        return explicit.lower()
    protocol = explicit
    if not protocol:
        for suite in BENCHMARK_SUITES:
            if suite.suite_id == suite_id:
                protocol = str(_methodology_contract_for_suite(suite).get("prompt_protocol") or "").strip()
                break
    if not protocol:
        return ""
    return sha256_text(
        stable_json(
            {
                "schema": "axio_fusion_api.prompt_protocol.v1",
                "suite_id": str(suite_id or ""),
                "task_format": str(task_format or ""),
                "prompt_protocol": protocol,
            }
        )
    )


def _decoding_config_sha256_for_suite(
    suite_id: str,
    task_format: str,
    *,
    decoding_config: str = "",
) -> str:
    explicit = str(decoding_config or "").strip()
    if _looks_like_sha256(explicit):
        return explicit.lower()
    if explicit:
        payload: Mapping[str, Any] = {
            "schema": "axio_fusion_api.decoding_config.v1",
            "suite_id": str(suite_id or ""),
            "task_format": str(task_format or ""),
            "decoding_config": explicit,
        }
    else:
        payload = {
            "schema": "axio_fusion_api.decoding_config.v1",
            "suite_id": str(suite_id or ""),
            "task_format": str(task_format or ""),
            "temperature": 0.0,
            "top_p": None,
            "seed": "official_or_not_applicable",
            "official_default_allowed": _suite_requires_official_harness(suite_id, task_format),
            "deterministic_decoding_required": True,
        }
    return sha256_text(stable_json(payload))


def _local_harness_receipt(suite_id: str, task_format: str) -> dict[str, Any]:
    official_required = _suite_requires_official_harness(suite_id, task_format)
    return {
        "schema": "axio_fusion_api.harness_receipt.v1",
        "suite_id": suite_id,
        "task_format": task_format,
        "harness_kind": "built_in_local_runner",
        "official_harness_required": official_required,
        "official_or_audited_harness": not official_required,
        "final_claim_eligible": not official_required,
        "pilot_only": official_required,
        "harness_name_sha256": sha256_text("axio_fusion_api.local_runner"),
        "harness_version_sha256": sha256_text("0.1"),
        "dataset_snapshot_sha256": "",
        "evaluator_config_sha256": sha256_text(task_format),
        "prompt_protocol_sha256": _prompt_protocol_sha256_for_suite(suite_id, task_format),
        "decoding_config_sha256": _decoding_config_sha256_for_suite(suite_id, task_format),
        "position_balanced": False,
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _official_harness_receipt(
    *,
    suite_id: str,
    task_format: str,
    harness_name: str,
    harness_version: str,
    dataset_snapshot: str,
    evaluator_config: str,
    position_balanced: bool,
    prompt_protocol_sha256: str = "",
    decoding_config_sha256: str = "",
) -> dict[str, Any]:
    prompt_hash = prompt_protocol_sha256 or _prompt_protocol_sha256_for_suite(suite_id, task_format)
    decoding_hash = decoding_config_sha256 or _decoding_config_sha256_for_suite(suite_id, task_format)
    return {
        "schema": "axio_fusion_api.harness_receipt.v1",
        "suite_id": suite_id,
        "task_format": task_format,
        "harness_kind": "official_or_audited_import",
        "official_harness_required": _suite_requires_official_harness(suite_id, task_format),
        "official_or_audited_harness": True,
        "final_claim_eligible": True,
        "pilot_only": False,
        "harness_name_sha256": _hash_or_keep_sha256(harness_name),
        "harness_version_sha256": _hash_or_keep_sha256(harness_version),
        "dataset_snapshot_sha256": _hash_or_keep_sha256(dataset_snapshot),
        "evaluator_config_sha256": _hash_or_keep_sha256(evaluator_config),
        "prompt_protocol_sha256": prompt_hash,
        "decoding_config_sha256": decoding_hash,
        "position_balanced": bool(position_balanced),
        "raw_dataset_content_persisted": False,
        "raw_prompts_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }


def _load_official_import_source(path: str | Path) -> dict[str, Any]:
    selected = Path(path)
    if selected.suffix.lower() == ".jsonl":
        rows = []
        with selected.open("r", encoding="utf-8") as handle:
            for line in handle:
                text = line.strip()
                if not text:
                    continue
                payload = json.loads(text)
                if isinstance(payload, Mapping):
                    rows.append(dict(payload))
        return {"kind": "jsonl_rows", "rows": rows, "input_row_count": len(rows)}
    payload = json.loads(selected.read_text(encoding="utf-8"))
    if isinstance(payload, list):
        rows = [dict(row) for row in payload if isinstance(row, Mapping)]
        return {"kind": "json_list", "rows": rows, "input_row_count": len(rows)}
    if not isinstance(payload, Mapping):
        raise ValueError("official benchmark import source must be a JSON object, JSON list, or JSONL rows")
    for key in ("case_results", "results", "cases", "rows", "samples"):
        value = payload.get(key)
        if isinstance(value, list):
            rows = [dict(row) for row in value if isinstance(row, Mapping)]
            return {"kind": f"json_object_{key}", "rows": rows, "input_row_count": len(rows)}
    raise ValueError("official benchmark import source must contain case_results, results, cases, rows, or samples")


def _official_import_case_result(
    row: Mapping[str, Any],
    *,
    suite_id: str,
    task_format: str,
    index: int,
) -> dict[str, Any]:
    correct = _import_correct_value(row)
    score = _import_score_value(row, correct=correct)
    status = str(row.get("status") or row.get("state") or "").strip().lower()
    if not status:
        status = "completed" if correct is not None or score is not None else "unscored"
    prediction_text = _first_text(row, ("prediction", "pred", "completion", "response", "output", "model_output", "answer"))
    reference_text = _first_text(row, ("reference", "gold", "target", "label", "expected", "ground_truth"))
    error_text = _first_text(row, ("error", "error_type", "exception"))
    imported_cost = _first_optional_float(
        row.get("estimated_cost_usd"),
        row.get("cost_usd"),
        row.get("total_cost_usd"),
    )
    provider_call_count = _optional_int(row.get("provider_call_count")) or _optional_int(row.get("model_call_count")) or 0
    public_api_invocation = _safe_imported_public_api_invocation(row.get("public_api_invocation"))
    return {
        "case_index": index,
        "case_id": _official_case_id(row, suite_id=suite_id, index=index),
        "category": str(row.get("category") or row.get("subject") or row.get("task") or ""),
        "metric": str(row.get("metric") or _primary_metric_for_format(task_format)),
        "score": score,
        "correct": correct,
        "status": status,
        "latency_ms": round(_first_optional_float(row.get("latency_ms"), row.get("latency"), row.get("duration_ms")) or 0.0, 3),
        "estimated_cost_usd": round(max(0.0, imported_cost or 0.0), 8),
        "pricing_known": imported_cost is not None,
        "input_tokens": _optional_int(row.get("input_tokens")) or 0,
        "output_tokens": _optional_int(row.get("output_tokens")) or 0,
        "provider_call_count": provider_call_count,
        "prediction_sha256": _imported_text_hash(row.get("prediction_sha256"), prediction_text),
        "reference_sha256": _imported_text_hash(row.get("reference_sha256"), reference_text),
        "output_sha256": _imported_text_hash(row.get("output_sha256"), prediction_text),
        "instruction_level_score": _first_optional_float(
            row.get("instruction_level_score"),
            row.get("instruction_accuracy"),
        ),
        "instruction_count": _optional_int(row.get("instruction_count")),
        "compile_passed": (
            row.get("compile_passed")
            if isinstance(row.get("compile_passed"), bool)
            else None
        ),
        "tool_action_count": (
            _optional_int(row.get("tool_action_count"))
            if "tool_action_count" in row
            else None
        ),
        "tool_error_count": (
            _optional_int(row.get("tool_error_count"))
            if "tool_error_count" in row
            else None
        ),
        "candidate_call_count": (
            _optional_int(row.get("candidate_call_count"))
            if "candidate_call_count" in row
            else None
        ),
        "position_balanced": row.get("position_balanced") if isinstance(row.get("position_balanced"), bool) else None,
        "judge_disagreement": row.get("judge_disagreement") if isinstance(row.get("judge_disagreement"), bool) else None,
        "judge_call_count": (
            _optional_int(row.get("judge_call_count"))
            if "judge_call_count" in row
            else None
        ),
        "judge_output_sha256": _imported_text_hash(row.get("judge_output_sha256"), ""),
        "error_type": error_text[:120],
        "public_api_invocation": public_api_invocation,
        "raw_input_persisted": False,
        "raw_reference_persisted": False,
        "raw_label_persisted": False,
        "raw_model_output_persisted": False,
        "secrets_persisted": False,
    }


def _safe_imported_public_api_invocation(value: Any) -> dict[str, Any]:
    """Retain only safe, auditable public-API transport facts from an import."""

    source = value if isinstance(value, Mapping) else {}
    safe = {
        "schema": str(source.get("schema") or ""),
        "public_api_surface_used": source.get("public_api_surface_used") is True,
        "candidate_kind": str(source.get("candidate_kind") or ""),
        "api_format": str(source.get("api_format") or ""),
        "transport": str(source.get("transport") or ""),
        "network_calls_performed": source.get("network_calls_performed") is True,
        "status_code": _optional_int(source.get("status_code")) or 0,
        "response_shape_valid": source.get("response_shape_valid") is True,
        "response_model_matches_request": source.get("response_model_matches_request") is True,
        "dialogue_turn_count": _optional_int(source.get("dialogue_turn_count")) or 0,
        "agent_turn_count": _optional_int(source.get("agent_turn_count")) or 0,
        "http_gateway_call_count": _optional_int(source.get("http_gateway_call_count")) or 0,
        "network_call_count": _optional_int(source.get("network_call_count")) or 0,
        "raw_gateway_url_persisted": False,
        "raw_prompt_persisted": False,
        "raw_response_text_persisted": False,
        "raw_provider_outputs_persisted": False,
        "secrets_persisted": False,
    }
    gateway_hash = str(source.get("gateway_url_sha256") or "").strip().lower()
    if _looks_like_sha256(gateway_hash):
        safe["gateway_url_sha256"] = gateway_hash
    return safe


def _official_case_id(row: Mapping[str, Any], *, suite_id: str, index: int) -> str:
    for key in ("case_id", "case_hash", "id_hash", "question_hash", "prompt_hash"):
        value = row.get(key)
        if _looks_like_sha256(value):
            return str(value).strip().lower()
    explicit = row.get("id") or row.get("question_id") or row.get("sample_id") or row.get("task_id")
    if explicit not in (None, ""):
        return sha256_text(json.dumps({"suite_id": suite_id, "id": str(explicit)}, ensure_ascii=False, sort_keys=True))
    text = _first_text(row, ("prompt", "question", "input", "source", "instruction"))
    if text:
        return sha256_text(json.dumps({"suite_id": suite_id, "text": text}, ensure_ascii=False, sort_keys=True))
    return sha256_text(json.dumps({"suite_id": suite_id, "index": index}, ensure_ascii=False, sort_keys=True))


def _import_correct_value(row: Mapping[str, Any]) -> bool | None:
    for key in ("correct", "passed", "success", "is_correct", "match", "exact_match"):
        if key not in row:
            continue
        value = row.get(key)
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return bool(value)
        if isinstance(value, str):
            normalized = value.strip().lower()
            if normalized in {"1", "true", "yes", "pass", "passed", "correct", "success"}:
                return True
            if normalized in {"0", "false", "no", "fail", "failed", "incorrect"}:
                return False
    score = _first_optional_float(row.get("score"), row.get("metric_score"), row.get("judge_score"))
    threshold = _first_optional_float(row.get("pass_threshold"), row.get("threshold"))
    if score is not None and threshold is not None:
        return score >= threshold
    return None


def _import_score_value(row: Mapping[str, Any], *, correct: bool | None) -> float | None:
    score = _first_optional_float(row.get("score"), row.get("metric_score"), row.get("judge_score"), row.get("value"))
    if score is not None:
        return round(score, 6)
    if correct is not None:
        return 1.0 if correct else 0.0
    return None


def _imported_text_hash(value: Any, fallback_text: str) -> str:
    if _looks_like_sha256(value):
        return str(value).strip().lower()
    return sha256_text(fallback_text) if fallback_text else ""


def _official_import_secondary_metrics(case_results: Sequence[Mapping[str, Any]]) -> dict[str, float]:
    metrics: dict[str, float] = {}
    instruction_scores = [
        float(row["instruction_level_score"])
        for row in case_results
        if isinstance(row.get("instruction_level_score"), (int, float))
    ]
    if instruction_scores:
        metrics["instruction_level_accuracy"] = round(
            sum(instruction_scores) / len(instruction_scores),
            6,
        )
    compile_scores = [
        1.0 if row.get("compile_passed") is True else 0.0
        for row in case_results
        if isinstance(row.get("compile_passed"), bool)
    ]
    if compile_scores:
        metrics["compile_rate"] = round(sum(compile_scores) / len(compile_scores), 6)
    tool_rows = [
        row
        for row in case_results
        if isinstance(row.get("tool_action_count"), int)
        and not isinstance(row.get("tool_action_count"), bool)
        and isinstance(row.get("tool_error_count"), int)
        and not isinstance(row.get("tool_error_count"), bool)
    ]
    tool_action_count = sum(max(0, int(row["tool_action_count"])) for row in tool_rows)
    tool_error_count = sum(max(0, int(row["tool_error_count"])) for row in tool_rows)
    if tool_rows:
        metrics["tool_error_rate"] = round(tool_error_count / tool_action_count, 6) if tool_action_count else 0.0
    judge_rows = [
        row
        for row in case_results
        if isinstance(row.get("judge_disagreement"), bool)
        and isinstance(row.get("judge_call_count"), int)
        and not isinstance(row.get("judge_call_count"), bool)
    ]
    if judge_rows:
        metrics["judge_disagreement_rate"] = round(
            sum(1 for row in judge_rows if row.get("judge_disagreement") is True) / len(judge_rows),
            6,
        )
        metrics["judge_call_count"] = float(sum(max(0, int(row["judge_call_count"])) for row in judge_rows))
    return metrics


def _primary_metric_for_official_import(suite_id: str, task_format: str) -> str:
    if suite_id == "mt_bench_work" and task_format == "external_pairwise_judge":
        return "win_rate"
    if suite_id == "tau_bench" and task_format == "tool_call_ast":
        return "task_success_rate"
    if suite_id == "ifeval" and task_format == "instruction_checks":
        return "prompt_level_strict_accuracy"
    return _primary_metric_for_format(task_format)


def _hash_or_keep_sha256(value: str) -> str:
    text = str(value or "").strip()
    if _looks_like_sha256(text):
        return text.lower()
    return sha256_text(text)


